module rtcl_p3s7_blinking_led
        #(
            parameter   int COUNT_LIMIT = 50_000_000
        )
        (
            input   var logic           clk50   ,
            input   var logic           clk72   ,
            output  var logic   [1:0]   led     ,
            output  var logic   [7:0]   pmod    
        );
    reg [31:0] counter50;
    reg [31:0] counter72;
    reg [1:0] led_reg;
    reg [7:0] pmod_reg;

    always_ff @(posedge clk50) begin
        if (counter50 < COUNT_LIMIT) begin
            counter50 <= counter50 + 1;
        end
    end

    always_ff @(posedge clk72) begin
        if (counter72 < COUNT_LIMIT) begin
            counter72 <= counter72 + 1;
        end
    end

    always_ff @(posedge clk50) begin
        if (counter50 >= COUNT_LIMIT) begin
            led_reg <= ~led_reg;
        end
    end

    always_ff @(posedge clk72) begin
        if (counter72 >= COUNT_LIMIT) begin
            pmod_reg <= counter72[7:0];
        end
    end

    assign led = led_reg;
    assign pmod = pmod_reg;

endmodule

module alu(
    input var [32:0] in_a,
    input var [32:0] in_b,
    input var [4:0] alu_op,

    output reg [31:0] rd_val_out,
    output reg lt,
    output reg ltu,
    output reg eq
);

// Internal wires
reg [32:0] temp_a, temp_b, result;
reg [32:0] two_complement_b;
reg [32:0] two_complement_a;
reg [32:0] two_complement_result;

// Function to convert a 32-bit number to its two's complement form
always_comb begin
    two_complement_b = ~in_b + 1;
    two_complement_a = ~in_a + 1;
end

// Function to perform two's complement addition
always_comb begin
    two_complement_result = two_complement_a + two_complement_b;
end

// Main ALU logic
always_comb begin
    case (alu_op)
        5'b00000: // ADD
            result = in_a + in_b;
        5'b00001: // SUB
            result = in_a - in_b;
        5'b00010: // SLT
            lt = (in_a < in_b) ? 1'b1 : 1'b0;
        5'b00011: // SLTU
            ltu = (in_a < in_b) ? 1'b1 : 1'b0;
        5'b00100: // XOR
            result = in_a ^ in_b;
        5'b00101: // OR
            result = in_a | in_b;
        5'b00110: // AND
            result = in_a & in_b;
        5'b01000: // LUI
            result = {in_b[31:10], 20'b0};
        default: // Invalid operation
            result = 32'b0;
    endcase
end

// Assign the result to rd_val_out
assign rd_val_out = result;

// Assign the status flags
assign lt = (result < in_b) ? 1'b1 : 1'b0;
assign ltu = (result < in_b) ? 1'b1 : 1'b0;
assign eq = (result == in_b) ? 1'b1 : 1'b0;

endmodule

module addmuladd_2_stage_signed_16_bit(
	input signed [15:0] a,
	input signed [15:0] b,
	input signed [15:0] c,
	input signed [15:0] d,
	output [15:0] out,
	input clk);

reg [15:0] stage0;
reg [15:0] stage1;

always @(posedge clk) begin
	// Stage 1: Compute ((d + a) * b) + c
	stage1 <= ((d + a) * b) + c;
end

// Stage 0: Store the result of stage1 in stage0
always @(posedge clk) begin
	stage0 <= stage1;
end

// Output the result from stage1
assign out = stage1;

endmodule

