module mulsub_3_stage_signed_18_bit(
	input signed [17:0] a,
	input signed [17:0] b,
	input signed [17:0] c,
	output [17:0] out,
	input clk);

	// Intermediate result register
	reg [35:0] stage0;
	reg [35:0] stage1;
	reg [35:0] stage2;

	// Initial multiplication and subtraction
	always @(posedge clk) begin
		stage0 <= a * b - c;
	end

	// Pipeline stages
	always @(posedge clk) begin
		stage1 <= stage0;
	end

	always @(posedge clk) begin
		stage2 <= stage1;
	end

	// Output is the result after three clock cycles
	assign out = stage2;

endmodule

module mulsubsub_1_stage_signed_13_bit(
    input signed [12:0] a,
    input signed [12:0] b,
    input signed [12:0] c,
    input signed [12:0] d,
    output [12:0] out,
    input clk);

    // Internal 26-bit register to hold intermediate result
    reg [25:0] stage0;

    // Sequential block to perform operations on each rising clock edge
    always @(posedge clk) begin
        // Multiply a and b
        stage0 <= a * b;

        // Subtract the difference of c and d
        stage0 <= stage0 - (c - d);
    end

    // Output the result from the internal register
    assign out = stage0[25:13];

endmodule

module addmulxor_2_stage_signed_12_bit(
    input signed [11:0] a,
    input signed [11:0] b,
    input signed [11:0] c,
    input signed [11:0] d,
    output reg [11:0] out,
    input clk);

    // Internal 24-bit registers to handle overflow
    reg [23:0] stage1_result;
    reg [23:0] stage2_result;

    // Stage 1: Addition and Multiplication
    always @(posedge clk) begin
        stage1_result <= a + b + c * d;
    end

    // Stage 2: XOR Operation
    always @(posedge clk) begin
        stage2_result <= stage1_result ^ d;
    end

    // Output the final result after two clock cycles
    always @(posedge clk) begin
        out <= stage2_result[11:0];
    end

endmodule

module muland_2_stage_signed_13_bit(
    input signed [12:0] a,
    input signed [12:0] b,
    input signed [12:0] c,
    output [12:0] out,
    input clk);

    // Intermediate result from the first stage
    reg [25:0] stage0;

    // First stage: Multiply a and b
    always @(posedge clk) begin
        stage0 <= a * b;
    end

    // Second stage: Bitwise AND with c
    always @(posedge clk) begin
        out <= stage0 & c;
    end

endmodule

