module addmuladd_2_stage_unsigned_16_bit(
    input  [15:0] a,
    input  [15:0] b,
    input  [15:0] c,
    input  [15:0] d,
    output [15:0] out,
    input clk);

    // Internal 32-bit registers to hold intermediate results
    reg [31:0] stage0;
    reg [31:0] stage1;

    // First stage: compute (d + a)
    always @(posedge clk) begin
        stage0 <= {d, a};
    end

    // Second stage: compute ((d + a) * b) + c
    always @(posedge clk) begin
        stage1 <= (stage0 * b) + c;
    end

    // Output the result from the second stage
    assign out = stage1[15:0];

endmodule

module presubmul_2_stage_unsigned_8_bit(
