    output [7:0] out,
    input clk);

    // Internal registers to store intermediate results
    reg [15:0] stage0;
    reg [15:0] stage1;

    // Calculate the intermediate result of (d - a) * b
    always @(posedge clk) begin
        stage0 <= (d - a) * b;
    end

    // Shift the result through two registers to create a delay
    always @(posedge clk) begin
        stage1 <= stage0;
    end

    // Output the delayed result
    assign out = stage1;

endmodule

