module std_mem_d3_32_16_16_16_4_4_4 #(
    parameter WIDTH = 32,
    parameter D0_SIZE = 16,
    parameter D1_SIZE = 16,
    parameter D2_SIZE = 16,
    parameter D0_IDX_SIZE = 4,
    parameter D1_IDX_SIZE = 4,
    parameter D2_IDX_SIZE = 4
) (
   input wire                logic [D0_IDX_SIZE-1:0] addr0,
   input wire                logic [D1_IDX_SIZE-1:0] addr1,
   input wire                logic [D2_IDX_SIZE-1:0] addr2,
   input wire                logic [ WIDTH-1:0] write_data,
   input wire                logic write_en,
   input wire                logic clk,
   output logic [ WIDTH-1:0] read_data,
   output logic              done
);

// 3D array to store data
logic [WIDTH-1:0] mem[D0_SIZE][D1_SIZE][D2_SIZE];

// Read operation
always_comb begin
    read_data = mem[addr0][addr1][addr2];
end

// Write operation
always_ff @(posedge clk) begin
    if (write_en) begin
        mem[addr0][addr1][addr2] <= write_data;
        done <= 1'b1;
    end else begin
        done <= 1'b0;
    end
end

// Error checking for simulation
initial begin
    if (addr0 >= D0_SIZE || addr1 >= D1_SIZE || addr2 >= D2_SIZE) begin
        $error("Error: Out-of-bounds access detected.");
    end
end

endmodule

module mulsub_2_stage_unsigned_18_bit_xor_reduction(
    input  [17:0] a,
    input  [17:0] b,
    input  [17:0] c,
    output [17:0] out,
    input clk);

    // First stage: Multiply a and b, then subtract c
    reg [35:0] stage0;
    always @(posedge clk) begin
        stage0 <= a * b - c;
    end

    // Second stage: Hold the result from stage0
    reg [35:0] stage1;
    always @(posedge clk) begin
        stage1 <= stage0;
    end

    // XOR reduction of the 36-bit result
    reg [17:0] xor_result;
    always @(posedge clk) begin
        xor_result <= stage1[35:18] ^ stage1[17:0];
    end

    // Output the result
    assign out = xor_result;

endmodule

module muladd_1_stage_signed_14_bit(
