	// Internal 28-bit register to hold the result of the multiplication
	reg [27:0] stage0;

	// Calculate the product of a and b
	always @(posedge clk) begin
		stage0 <= a * b;
	end

	// Add c to the product and store the result in the output
	always @(posedge clk) begin
		out <= stage0 + c;
	end

endmodule

module addmulor_1_stage_unsigned_11_bit(
    input  [10:0] a,
    input  [10:0] b,
    input  [10:0] c,
    input  [10:0] d,
    output [10:0] out,
    input clk);

    // Intermediate result of addition and multiplication
    reg [21:0] intermediate_result;

    // Sequential process to perform the operations
    always @(posedge clk) begin
        // Add d and a
        intermediate_result <= d + a;

        // Multiply the result by b
        intermediate_result <= intermediate_result * b;

        // Perform bitwise OR with c
        intermediate_result <= intermediate_result | c;
    end

    // Assign the lower 11 bits of the intermediate result to the output
    assign out = intermediate_result[21:11];

endmodule

