// Define the FAIL macro to control the timing relationship between write and ready
`define FAIL 100 // Adjust this value to change the timing relationship

// Property to check for mutually exclusive read and write conditions
property mutually_exclusive;
    @(posedge clock) (read | write) ##1 ! (read | write);
endproperty

