module addmulsub_1_stage_signed_8_bit(
    input signed [7:0] a,
    input signed [7:0] b,
    input signed [7:0] c,
    input signed [7:0] d,
    output [7:0] out,
    input clk);

    // Internal 16-bit signed register to handle intermediate results
    reg signed [15:0] stage0;

    // Sequential block triggered by the positive edge of the clock
    always @(posedge clk) begin
        // Add a and d
        stage0 <= a + d;

        // Multiply the result by b
        stage0 <= stage0 * b;

        // Subtract c
        stage0 <= stage0 - c;

        // Assign the 8-bit result to out
        out <= stage0[7:0];
    end

endmodule

module mult_1_stage_unsigned_11_bit_xor_reduction(
    input  [10:0] a,
    input  [10:0] b,
    output [10:0] out,
    input clk);

    // Internal register to store the multiplication result
    reg [21:0] stage0;

    // Combinational multiplication operation
    always @(posedge clk) begin
        stage0 <= a * b;
    end

    // XOR reduction of the multiplication result
    assign out = stage0[21] ^ stage0[20] ^ stage0[19] ^ stage0[18] ^ stage0[17] ^ stage0[16] ^ stage0[15] ^ stage0[14] ^ stage0[13] ^ stage0[12] ^ stage0[11] ^ stage0[10] ^ stage0[9] ^ stage0[8] ^ stage0[7] ^ stage0[6] ^ stage0[5] ^ stage0[4] ^ stage0[3] ^ stage0[2] ^ stage0[1] ^ stage0[0];

endmodule

module muland_1_stage_signed_12_bit(
