    // Internal register to store intermediate results
    reg [23:0] stage0;

    // Sequential process to perform multiplication and bitwise AND
    always @(posedge clk) begin
        // Multiply a and b
        stage0 <= a * b;
        // Perform bitwise AND with c
        stage0 <= stage0 & c;
        // Output the lower 12 bits of the result
        out <= stage0[11:0];
    end

endmodule

module mulxor_3_stage_signed_11_bit(
	input signed [10:0] a,
	input signed [10:0] b,
	input signed [10:0] c,
	output [10:0] out,
	input clk);

	// Intermediate registers to store results
	reg [21:0] stage0;
	reg [21:0] stage1;
	reg [21:0] stage2;

	// Temporary variable to hold the result of multiplication
	reg [21:0] temp;

	// Multiplication stage
	always @(posedge clk) begin
		temp = a * b;
	end

	// First stage of XOR operation
	always @(posedge clk) begin
		stage0 = temp ^ c;
	end

	// Second stage of XOR operation
	always @(posedge clk) begin
		stage1 = stage0 ^ c;
	end

	// Third stage of XOR operation
	always @(posedge clk) begin
		stage2 = stage1 ^ c;
	end

	// Output the result after three clock cycles
	always @(posedge clk) begin
		out = stage2;
	end

endmodule

module mulxor_1_stage_unsigned_11_bit(
