    // 22-bit register to store the multiplication result
    reg [21:0] stage0;

    // Always block triggered by the positive edge of clk
    always @(posedge clk) begin
        // Perform multiplication and XOR operation
        stage0 <= (a * b) + c;
    end

    // Output is the lower 11 bits of stage0
    assign out = stage0[10:0];

endmodule

