	// First stage operation: (d - a) * b + c
	always @(posedge clk) begin
		stage0 <= (d - a) * b + c;
	end

	// XOR reduction on the 34-bit intermediate register
	always @(posedge clk) begin
		out <= stage0[33:17];
	end

endmodule

