    output [15:0] out,
    input clk);

    // 32-bit registers to store intermediate results
    reg [31:0] stage0;
    reg [31:0] stage1;

    // First stage: compute (d + a) * b + c
    always @(posedge clk) begin
        stage0 <= (d + a) * b + c;
    end

    // Second stage: store the result in stage1
    always @(posedge clk) begin
        stage1 <= stage0;
    end

