module UART2(
    input wire ipClk,
    input wire ipReset,
    input wire[7:0] ipTxData,
    input wire ipTxSend,
    output reg opTxBusy,
    output reg opTx,
    input wire ipRx,
    output reg [7:0] opRxData,
    output reg opRxValid
);

    // Define states for the FSM
    typedef enum {TxIdle, Sending, TxDone, RxIdle, Receiving, RxDone} UARTState_t;
    UARTState_t TxState, RxState;

    // Baud rate counters
    reg [9:0] TxBdCount, RxBdCount;

    // Internal registers
    reg [7:0] RxData;
    reg [7:0] TxDataReg;
    reg [7:0] TxDataShift;
    reg [7:0] RxDataShift;
    reg [3:0] BitCounter;

    // Reset the FSM and counters
    always @(posedge ipClk or posedge ipReset) begin
        if (ipReset) begin
            TxState <= TxIdle;
            RxState <= RxIdle;
            TxBdCount <= 0;
            RxBdCount <= 0;
            opTxBusy <= 0;
            opTx <= 0;
            opRxValid <= 0;
            opRxData <= 0;
            TxDataReg <= 0;
            TxDataShift <= 0;
            RxDataShift <= 0;
            BitCounter <= 0;
        end else begin
            // Update FSM states
            case (TxState)
                TxIdle: begin
                    if (ipTxSend) begin
                        TxState <= Sending;
                        TxBdCount <= 0;
                        TxDataShift <= ipTxData;
                        opTxBusy <= 1;
                    end
                end
                Sending: begin
                    if (TxBdCount == 433) begin
                        TxState <= TxDone;
                        opTxBusy <= 0;
                    end else begin
                        opTx <= TxDataShift[7];
                        TxDataShift <= {TxDataShift[6:0], 1'b0};
                        TxBdCount <= TxBdCount + 1;
                    end
                end
                TxDone: begin
                    opTx <= 1'b1; // Stop bit
                    TxBdCount <= 0;
                    TxState <= TxIdle;
                end
            endcase

            case (RxState)
                RxIdle: begin
                    if (ipRx == 1'b0) begin
                        RxState <= Receiving;
                        RxBdCount <= 0;
                        RxDataShift <= 0;
                        BitCounter <= 0;
                    end
                end
                Receiving: begin
                    if (RxBdCount == 433) begin
                        RxState <= RxDone;
                        opRxValid <= 1;
                        opRxData <= RxDataShift;
                    end else begin
                        RxDataShift <= {RxDataShift[6:0], ipRx};
                        RxBdCount <= RxBdCount + 1;
                        BitCounter <= BitCounter + 1;
                        if (BitCounter == 8) begin
                            RxState <= RxIdle;
                        end
                    end
                end
                RxDone: begin
                    RxBdCount <= 0;
                    RxState <= RxIdle;
                end
            endcase

            // Update baud rate counters
            if (ipClk) begin
                if (TxState == Sending) begin
                    TxBdCount <= TxBdCount + 1;
                end
                if (RxState == Receiving) begin
                    RxBdCount <= RxBdCount + 1;
                end
            end
        end
    end

endmodule

module submulxor_2_stage_signed_10_bit_xor_reduction(
	input signed [9:0] a,
	input signed [9:0] b,
	input signed [9:0] c,
	input signed [9:0] d,
	output [9:0] out,
	input clk);

	// Intermediate results
	reg [19:0] stage0;
	reg [19:0] stage1;

	// Stage 1: Subtraction and Multiplication
	always @(posedge clk) begin
		stage0 <= a - b;
		stage1 <= stage0 * c + d;
	end

	// Stage 2: XOR Reduction
	always @(posedge clk) begin
		out <= stage1[9:0];
	end

endmodule

module mulsub_3_stage_unsigned_9_bit(
    input  [8:0] a,
    input  [8:0] b,
    input  [8:0] c,
    output [8:0] out,
    input clk);

    // Intermediate registers
    reg [17:0] stage0;
    reg [17:0] stage1;
    reg [17:0] stage2;

    // Multiplication and subtraction
    always @(posedge clk) begin
        stage0 <= a * b - c;
        stage1 <= stage0;
        stage2 <= stage1;
    end

    // Output is the value in the last register after three clock cycles
    assign out = stage2;

endmodule

module submuladd_3_stage_signed_8_bit_xor_reduction(
    input signed [7:0] a,
    input signed [7:0] b,
    input signed [7:0] c,
    input signed [7:0] d,
    output [7:0] out,
    input clk);

    // Intermediate registers for the pipeline
    reg [15:0] stage0;
    reg [15:0] stage1;
    reg [15:0] stage2;

    // First stage: (d - a) * b
    always @(posedge clk) begin
        stage0 <= (d - a) * b;
    end

    // Second stage: stage0 + c
    always @(posedge clk) begin
        stage1 <= stage0 + c;
    end

    // Third stage: stage1 (no additional operation needed)
    always @(posedge clk) begin
        stage2 <= stage1;
    end

    // Final output: XOR reduction of stage2
    assign out = stage2[15];

endmodule

module mulor_2_stage_signed_8_bit(
	input signed [7:0] a,
	input signed [7:0] b,
	input signed [7:0] c,
	output [7:0] out,
	input clk);

reg [15:0] stage0;
reg [15:0] stage1;

always @(posedge clk) begin
	// First stage: Multiply a and b
	stage0 <= a * b;

	// Second stage: Combine the result with c using bitwise OR
	stage1 <= stage0 | c;

	// Output the lower 8 bits of the final result
	out <= stage1[7:0];
end

endmodule

module addmulsub_1_stage_unsigned_11_bit(
