	reg [21:0] stage0;

	// Sequential operation triggered by the rising edge of the clock
	always @(posedge clk) begin
		// Add a and d
		stage0 <= a + d;
		// Multiply the result by b
		stage0 <= stage0 * b;
		// Subtract c
		stage0 <= stage0 - c;
		// Assign the lower 11 bits of the result to the output
		out <= stage0[21:11];
	end

