    input signed [8:0] b,
    input signed [8:0] c,
    input signed [8:0] d,
    output reg [8:0] out,
    input clk);

    // Internal registers to store intermediate results
    reg [17:0] stage0;
    reg [17:0] stage1;

    // First stage computation: (d - a) * b ^ c
    always @(posedge clk) begin
        stage0 <= (d - a) * b ^ c;
    end

    // Second stage computation: store the result from the first stage
    always @(posedge clk) begin
        stage1 <= stage0;
    end

    // Output the result from the second stage
    assign out = stage1[8:0];

