module submulsub_3_stage_unsigned_8_bit_xor_reduction(
    input  [7:0] a,
    input  [7:0] b,
    input  [7:0] c,
    input  [7:0] d,
    output [7:0] out,
    input clk);

    // 16-bit registers to handle overflow
    reg [15:0] stage0;
    reg [15:0] stage1;
    reg [15:0] stage2;

    // Arithmetic operations
    always @(posedge clk) begin
        // Stage 0: a - b
        stage0 <= a - b;

        // Stage 1: c - d
        stage1 <= c - d;

        // Stage 2: stage0 - stage1
        stage2 <= stage0 - stage1;
    end

    // XOR reduction of the final stage's value
    always @(posedge clk) begin
        out <= stage2[15]; // Reduce the 16-bit value to a single bit
    end

endmodule

module submuland_1_stage_signed_13_bit(
