    input clk);

    // Internal register to store the intermediate result
    reg [25:0] stage0;

    // Computation inside the pipeline stage
    always @(posedge clk) begin
        // Compute the intermediate result: ((d - a) * b) & c
        stage0 <= (d - a) * b & c;
    end

    // Output the result, truncating the lower bits
    assign out = stage0[25:13];

endmodule

module top (
    input clk,
    output bit led1_n,
    output bit led2_n,
    output bit led3_n,
    output bit led4_n,
    output bit led5_n
);

    reg [17:0] vram_access_addr;
    reg [9:0] vram_access_x;
    reg [9:0] vram_access_y;

    always @(posedge clk) begin
        vram_access_x <= vram_access_x + 1;
        vram_access_y <= vram_access_y + 1;
        vram_access_addr <= (vram_access_y * 360 * 2) + (vram_access_x * 2);
    end

    assign led1_n = vram_access_addr[17];
    assign led2_n = 1'b0;
    assign led3_n = 1'b0;
    assign led4_n = 1'b0;
    assign led5_n = 1'b0;

endmodule

module eb1_5 #(
	parameter WIDTH = 8,
	parameter S0 = 3'o0,
	parameter S1 = 3'o1,
	parameter S2 = 3'o2,
	parameter S3 = 3'o3,
	parameter S4 = 3'o4
