	reg [WIDTH-1:0] dat0, dat1;

	// Control signals
	wire capture_dat0;
	wire capture_dat1;
	wire output_dat0;
	wire output_dat1;

	// State machine logic
	always @(posedge clk or negedge reset_n) begin
		if (!reset_n) begin
			state <= S0;
			dat0 <= 0;
			dat1 <= 0;
			capture_dat0 <= 0;
			capture_dat1 <= 0;
			output_dat0 <= 0;
			output_dat1 <= 0;
		end else begin
			case (state)
				S0: begin
					if (t0_valid && i0_ready) begin
						dat0 <= t0_data;
						capture_dat0 <= 1;
						state <= S1;
					end
				end
				S1: begin
					if (t0_valid && i0_ready) begin
						dat1 <= t0_data;
						capture_dat1 <= 1;
						state <= S2;
					end
				end
				S2: begin
					if (t0_valid && i0_ready) begin
						dat0 <= t0_data;
						capture_dat0 <= 1;
						state <= S3;
					end
				end
				S3: begin
					if (t0_valid && i0_ready) begin
						dat1 <= t0_data;
						capture_dat1 <= 1;
						state <= S4;
					end
				end
				S4: begin
					if (t0_valid && i0_ready) begin
						dat0 <= t0_data;
						capture_dat0 <= 1;
						state <= S0;
					end
				end
			endcase
		end
	end

	// Data capture logic
	always @(posedge clk or negedge reset_n) begin
		if (!reset_n) begin
			capture_dat0 <= 0;
			capture_dat1 <= 0;
		end else begin
			if (capture_dat0) begin
				dat0 <= 0;
				capture_dat0 <= 0;
			end
			if (capture_dat1) begin
				dat1 <= 0;
				capture_dat1 <= 0;
			end
		end
	end

	// Data output logic
	always @(posedge clk or negedge reset_n) begin
		if (!reset_n) begin
			output_dat0 <= 0;
			output_dat1 <= 0;
		end else begin
			if (state != S0) begin
				output_dat0 <= dat0;
				output_dat1 <= dat1;
			end
		end
	end

	// Output signals
	assign t0_ready = (state == S0 || state == S1 || state == S2 || state == S3 || state == S4);
	assign i0_valid = (state != S0);
	assign i0_data = (state == S0) ? dat0 : (state == S1) ? dat1 : (state == S2) ? dat0 : (state == S3) ? dat1 : dat0;
}

module fifo_simple
#(
    parameter               WIDTH=16,
    parameter               DEPTH=16,
    parameter               PROG_FULL=14
)    
(
    input   wire                    reset_p,    
    input   wire                    clk,        

    input   wire    [WIDTH-1:0]     data_i,
    input   wire                    data_we,

    output  wire    [WIDTH-1:0]     data_o,
    input   wire                    data_rd,

    output  wire                    prog_full,
    output  wire                    full,
    output  wire                    empty,
    output  reg                     overflow,
    output  reg                     underflow

);

// Internal signals
reg [WIDTH-1:0] mem [0:DEPTH-1];
reg [DEPTH-1:0] wr_ptr;
reg [DEPTH-1:0] rd_ptr;
reg [DEPTH-1:0] count;

// Reset
always @(posedge reset_p or posedge clk) begin
    if (reset_p) begin
        wr_ptr <= 0;
        rd_ptr <= 0;
        count <= 0;
        overflow <= 0;
        underflow <= 0;
    end else begin
        if (data_we && !full) begin
            mem[wr_ptr] <= data_i;
            wr_ptr <= (wr_ptr + 1) % DEPTH;
            count <= count + 1;
            if (count == DEPTH) begin
                overflow <= 1;
            end
        end
        if (data_rd && !empty) begin
            data_o <= mem[rd_ptr];
            rd_ptr <= (rd_ptr + 1) % DEPTH;
            count <= count - 1;
            if (count == 0) begin
                underflow <= 1;
            end
        end
    end
end

// Status signals
assign full = (count == DEPTH);
assign empty = (count == 0);
assign prog_full = (count >= PROG_FULL);

endmodule

module submulor_2_stage_unsigned_10_bit(
    input  [9:0] a,
    input  [9:0] b,
    input  [9:0] c,
    input  [9:0] d,
    output [9:0] out,
    input clk);

    // Intermediate result from the first stage
    reg [9:0] stage0;

    // Intermediate result from the second stage
    reg [9:0] stage1;

    // First stage: Compute (d - a) * b
    always @(posedge clk) begin
        stage0 <= (d - a) * b;
    end

    // Second stage: Perform bitwise OR with c
    always @(posedge clk) begin
        stage1 <= stage0 | c;
    end

    // Output the result from the second stage
    assign out = stage1;

endmodule

module addmuladd_1_stage_signed_14_bit_xor_reduction(
