    // Intermediate 28-bit logic signal
    reg [27:0] stage0;

    // Sequential block to update stage0 on each clock edge
    always @(posedge clk) begin
        // Perform the arithmetic operations
        stage0 <= (d + a) * b + c;
    end

    // Apply bitwise XOR reduction to the entire 28-bit signal
    assign out = stage0[27];

endmodule

