        end
    end
}

module vga_ctrl(
    input wire pixel_clk,
    output wire hsync,
    output wire vsync,
    output wire [9:0] pixel_x,
    output wire [9:0] pixel_y,
    output wire visible_region
);

    // Parameters for VGA timing
    parameter TOTAL_PIXELS = 640;
    parameter TOTAL_LINES = 480;
    parameter H_SYNC_PULSE_WIDTH = 9;
    parameter H_BACK_PULSE_WIDTH = 45;
    parameter H_FRONT_PULSE_WIDTH = 16;
    parameter V_SYNC_PULSE_WIDTH = 2;
    parameter V_BACK_PULSE_WIDTH = 10;
    parameter V_FRONT_PULSE_WIDTH = 2;

    // Internal counters
    reg [9:0] h_counter;
    reg [9:0] v_counter;

    // Internal signals
    reg h_sync;
    reg v_sync;
    reg [9:0] pixel_x_reg;
    reg [9:0] pixel_y_reg;
    reg visible_region_reg;

    // Horizontal counter
    always @(posedge pixel_clk) begin
        if (h_counter == (TOTAL_PIXELS - 1)) begin
            h_counter <= 0;
            h_sync <= 1;
        end else begin
            h_counter <= h_counter + 1;
            h_sync <= 0;
        end
    end

    // Vertical counter
    always @(posedge pixel_clk) begin
        if (h_counter == (TOTAL_PIXELS - 1)) begin
            h_counter <= 0;
            v_counter <= v_counter + 1;
        end
    end

    // Horizontal sync generation
    always @(posedge pixel_clk) begin
        if (h_counter == (TOTAL_PIXELS - 1)) begin
            h_sync <= 1;
        end else begin
            h_sync <= 0;
        end
    end

    // Vertical sync generation
    always @(posedge pixel_clk) begin
        if (v_counter == (TOTAL_LINES - 1)) begin
            v_sync <= 1;
        end else begin
            v_sync <= 0;
        end
    end

    // Pixel coordinates
    always @(posedge pixel_clk) begin
        if (h_counter == (TOTAL_PIXELS - 1)) begin
            pixel_x_reg <= 0;
            pixel_y_reg <= pixel_y_reg + 1;
        end else begin
            pixel_x_reg <= pixel_x_reg + 1;
        end
    end

    // Visible region detection
    always @(posedge pixel_clk) begin
        if (h_counter == (TOTAL_PIXELS - 1)) begin
            visible_region_reg <= (pixel_y_reg >= V_FRONT_PULSE_WIDTH) && (pixel_y_reg < (TOTAL_LINES - V_BACK_PULSE_WIDTH));
        end else begin
            visible_region_reg <= visible_region_reg;
        end
    end

    // Output signals
    assign hsync = h_sync;
    assign vsync = v_sync;
    assign pixel_x = pixel_x_reg;
    assign pixel_y = pixel_y_reg;
    assign visible_region = visible_region_reg;

endmodule

