module AXIS_SLAV #( parameter pUSER_PROJECT_SIDEBAND_WIDTH = 5,
          parameter pADDR_WIDTH   = 12,
                    parameter pDATA_WIDTH   = 32
                  )
(
  output wire                        ss_tvalid_0,
  output wire  [(pDATA_WIDTH-1) : 0] ss_tdata,
  output wire                 [1: 0] ss_tuser,
`ifdef USER_PROJECT_SIDEBAND_SUPPORT
  output  wire                 [pUSER_PROJECT_SIDEBAND_WIDTH-1: 0] ss_tupsb,
`endif
  output wire                 [3: 0] ss_tstrb,
  output wire                 [3: 0] ss_tkeep,
  output wire                        ss_tlast,
  output wire                        ss_tvalid_1,
  output wire                        ss_tvalid_2,
  output wire                        ss_tvalid_3,
  input  wire                        ss_tready_0,
  input  wire                        ss_tready_1,
  input  wire                        ss_tready_2,
  input  wire                        ss_tready_3,
  input  wire                        s_tvalid,
  input  wire  [(pDATA_WIDTH-1) : 0] s_tdata,
  input  wire                 [1: 0] s_tuser,
`ifdef USER_PROJECT_SIDEBAND_SUPPORT
  input  wire                 [pUSER_PROJECT_SIDEBAND_WIDTH-1: 0] s_tupsb,
`endif
  input  wire                 [3: 0] s_tstrb,
  input  wire                 [3: 0] s_tkeep,
  input  wire                        s_tlast,
  output wire                        s_tready,
  input  wire                        axis_clk,
  input  wire                        axi_reset_n,
  input  wire                        axis_rst_n,
  input  wire                 [4: 0] user_prj_sel
)
{
  // Local signals for multiplexing
  wire [3:0] valid_mux;
  wire [3:0] ready_mux;

  // Multiplex valid signals
  valid_mux[0] = (user_prj_sel == 0) ? s_tvalid : 1'b0;
  valid_mux[1] = (user_prj_sel == 1) ? s_tvalid : 1'b0;
  valid_mux[2] = (user_prj_sel == 2) ? s_tvalid : 1'b0;
  valid_mux[3] = (user_prj_sel == 3) ? s_tvalid : 1'b0;

  // Multiplex ready signals
  ready_mux[0] = (user_prj_sel == 0) ? ss_tready_0 : 1'b0;
  ready_mux[1] = (user_prj_sel == 1) ? ss_tready_1 : 1'b0;
  ready_mux[2] = (user_prj_sel == 2) ? ss_tready_2 : 1'b0;
  ready_mux[3] = (user_prj_sel == 3) ? ss_tready_3 : 1'b0;

  // Assign outputs based on multiplexed signals
  assign ss_tvalid_0 = valid_mux[0];
  assign ss_tvalid_1 = valid_mux[1];
  assign ss_tvalid_2 = valid_mux[2];
  assign ss_tvalid_3 = valid_mux[3];

  assign ss_tdata = (user_prj_sel == 0) ? s_tdata : 32'b0;
