  assign ss_tkeep = (user_prj_sel == 0) ? s_tkeep : 4'b0;
  assign ss_tlast = (user_prj_sel == 0) ? s_tlast : 1'b0;

  // Assign s_tready based on multiplexed signals
  assign s_tready = ready_mux[user_prj_sel];
}

