module im2_control(
    input wire i_CLK_CPU,
    input wire i_reset,
    input wire i_m1_n,
    input wire i_mreq_n,
    input wire i_iorq_n,
    input wire i_rfsh_n,
    input wire [7:0] i_cpu_d,
    output wire o_reti_decode,
    output wire o_reti_seen
);

    // Define states
    typedef enum {S_0, S_ED_T4, S_4D_T4, S_CB_T4} state_t;
    state_t current_state, next_state;

    // Register to capture fetch status
    reg ifetch_d;

    // Register to capture opcode value
    reg [7:0] cpu_opcode;

    // Wire to determine fetch condition
    wire ifetch;

    // Wire to determine fetch cancel condition
    wire ifetch_cancel;

    // Combinational logic for opcode decoding
    always_comb begin
        case (cpu_opcode)
            8'hED: ifetch = 1'b1; // ED opcode
            8'h4D: ifetch = 1'b1; // 4D opcode
            8'hCB: ifetch = 1'b1; // CB opcode
            default: ifetch = 1'b0; // Other opcodes
        endcase
    end

    // Sequential logic for state management
    always_ff @(posedge i_CLK_CPU or posedge i_reset) begin
        if (i_reset) begin
            current_state <= S_0;
            o_reti_decode <= 1'b0;
            o_reti_seen <= 1'b0;
        end else begin
            current_state <= next_state;

            // Determine next state based on current state and fetch conditions
            case (current_state)
                S_0: begin
                    if (ifetch) begin
                        next_state <= S_ED_T4;
                    end else begin
                        next_state <= S_0;
                    end
                end
                S_ED_T4: begin
                    if (ifetch_cancel) begin
                        next_state <= S_0;
                    end else begin
                        next_state <= S_4D_T4;
                    end
                end
                S_4D_T4: begin
                    if (ifetch_cancel) begin
                        next_state <= S_0;
                    end else begin
                        next_state <= S_CB_T4;
                    end
                end
                S_CB_T4: begin
                    if (ifetch_cancel) begin
                        next_state <= S_0;
                    end else begin
                        next_state <= S_0;
                    end
                end
            endcase

            // Generate outputs based on current state
            if (current_state == S_ED_T4 || current_state == S_4D_T4 || current_state == S_CB_T4) begin
                o_reti_decode <= 1'b1;
            end else begin
                o_reti_decode <= 1'b0;
            end

            if (current_state == S_CB_T4) begin
                o_reti_seen <= 1'b1;
            end else begin
                o_reti_seen <= 1'b0;
            end
        end
    end

endmodule

