module round
  #(parameter bits_in=0,
    parameter bits_out=0,
    parameter round_to_zero=0,       
    parameter round_to_nearest=1,    
    parameter trunc=0)               
    (input [bits_in-1:0] in,
     output [bits_out-1:0] out,
     output [bits_in-bits_out:0] err);

  // Internal signals
  reg [bits_in-1:0] rounded;
  reg [bits_in-bits_out:0] error;

  // Calculate the correction value based on the rounding mode
  reg [bits_in-1:0] correction;
  always @(*) begin
    if (round_to_zero) begin
      correction = {bits_in{1'b0}};
    end else if (round_to_nearest) begin
      correction = {bits_in{1'b0}};
      if (in[bits_in-1]) begin
        correction = {bits_in{1'b1}};
      end
    end else if (trunc) begin
      correction = {bits_in{1'b0}};
    end else begin
      correction = {bits_in{1'b0}};
    end
  end

  // Compute the rounded result
  assign rounded = in + correction;

  // Compute the error signal
  assign error = in - rounded;

  // Output the rounded result and error
  assign out = rounded[bits_in-bits_out:0];
  assign err = error[bits_in-bits_out:0];

endmodule

module add_1_bit(
    input wire clk,
    input wire x,
    input wire y,
    input wire cin,
    output reg sum,
    output reg cout
);

always @(posedge clk) begin
    // Calculate the sum using XOR
    sum <= x ^ y ^ cin;

    // Calculate the carry-out using OR
    cout <= (x & y) | (y & cin) | (cin & x);
end

endmodule

