module pes_elevator (
    input [7:0] request_floor,
    input [7:0] in_current_floor,
    input clk,
    input reset,
    input over_time,
    input over_weight,
    output reg direction,
    output reg complete,
    output reg door_alert,
    output reg weight_alert,
    output reg [7:0] out_current_floor
);

    // Internal registers to maintain state
    reg [7:0] current_floor;
    reg [1:0] state;

    // Initial state
    initial begin
        current_floor = in_current_floor;
        state = 2'b00; // 00: Idle, 01: Moving up, 10: Moving down
    end

    // Always block to handle state transitions
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_floor = in_current_floor;
            state = 2'b00;
            direction = 1'b0; // Default direction is down
            complete = 1'b0;
            door_alert = 1'b0;
            weight_alert = 1'b0;
        end else begin
            case (state)
                2'b00: begin // Idle
                    if (request_floor > current_floor) begin
                        state = 2'b01; // Move up
                        direction = 1'b1;
                    end else if (request_floor < current_floor) begin
                        state = 2'b10; // Move down
                        direction = 1'b0;
                    end
                end
                2'b01: begin // Moving up
                    if (current_floor == request_floor) begin
                        state = 2'b00; // Idle
                        complete = 1'b1;
                    end else if (current_floor == 127) begin // Maximum floor
                        state = 2'b00; // Idle
                        complete = 1'b1;
                    end else begin
                        current_floor = current_floor + 1;
                    end
                end
                2'b10: begin // Moving down
                    if (current_floor == request_floor) begin
                        state = 2'b00; // Idle
                        complete = 1'b1;
                    end else if (current_floor == 0) begin // Minimum floor
                        state = 2'b00; // Idle
                        complete = 1'b1;
                    end else begin
                        current_floor = current_floor - 1;
                    end
                end
            endcase

            // Safety conditions
            if (over_time) begin
                state = 2'b00; // Idle
                complete = 1'b0;
                door_alert = 1'b1;
            end
            if (over_weight) begin
                state = 2'b00; // Idle
                complete = 1'b0;
                weight_alert = 1'b1;
            end
        end
    end

endmodule

