module toe_s_axis_listen_port_req_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);

// State machine states
typedef enum {ZERO, ONE, TWO} state_t;
state_t current_state, next_state;

// Registers for data buffering
reg [N-1:0] data_p1, data_p2;

// Combinational logic to determine next state
always_comb begin
    case (current_state)
        ZERO: begin
            if (s_valid && s_ready) begin
                next_state = ONE;
            end else begin
                next_state = ZERO;
            end
        end
        ONE: begin
            if (m_ready) begin
                next_state = TWO;
            end else begin
                next_state = ONE;
            end
        end
        TWO: begin
            if (s_valid && s_ready) begin
                next_state = ONE;
            end else begin
                next_state = TWO;
            end
        end
        default: next_state = ZERO;
    endcase
end

// Register to hold the current state
always_ff @(posedge clk or posedge reset) begin
    if (reset) begin
        current_state <= ZERO;
    end else begin
        current_state <= next_state;
    end
end

// Data buffering logic
always_ff @(posedge clk or posedge reset) begin
    if (reset) begin
        data_p1 <= 0;
        data_p2 <= 0;
    end else begin
        case (current_state)
            ZERO: begin
                data_p1 <= s_data;
            end
            ONE: begin
                data_p2 <= s_data;
            end
            TWO: begin
                data_p1 <= data_p2;
            end
            default: begin
                data_p1 <= 0;
                data_p2 <= 0;
            end
        endcase
    end
end

// Output signals
assign s_ready = (current_state == ONE) ? m_ready : 1'b1;
assign m_valid = (current_state == TWO) ? s_valid : 1'b0;
assign m_data = (current_state == TWO) ? data_p1 : 0;

endmodule

