module AXI_WRITE_DATA_CHANNEL_model(
    input wire clk,
    input wire resetn,
    input wire [31:0] data,
    input wire go,
    output reg done,
    output wire [31:0] WDATA,
    output reg [3:0] WSTRB,
    output reg WVALID,
    input wire WREADY
);

    // State machine states
    typedef enum {RESET, IDLE, RUNNING, COMPLETE} state_t;
    state_t current_state, next_state;

    // State register
    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            current_state <= RESET;
        end else begin
            current_state <= next_state;
        end
    end

    // State machine logic
    always @(current_state or go or WREADY) begin
        case (current_state)
            RESET: begin
                next_state = IDLE;
            end
            IDLE: begin
                if (go) begin
                    next_state = RUNNING;
                end else begin
                    next_state = IDLE;
                end
            end
            RUNNING: begin
                if (WREADY) begin
                    next_state = COMPLETE;
                end else begin
                    next_state = RUNNING;
                end
            end
            COMPLETE: begin
                next_state = IDLE;
            end
        endcase
    end

    // Output logic
    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            done <= 1'b0;
            WDATA <= 32'b0;
            WSTRB <= 4'b0;
            WVALID <= 1'b0;
        end else begin
            case (current_state)
                IDLE: begin
                    done <= 1'b0;
                    WDATA <= 32'b0;
                    WSTRB <= 4'b0;
                    WVALID <= 1'b0;
                end
                RUNNING: begin
                    done <= 1'b0;
                    WDATA <= data;
                    WSTRB <= 4'b1111; // Assuming 32-bit data
                    WVALID <= 1'b1;
                end
                COMPLETE: begin
                    done <= 1'b1;
                    WDATA <= 32'b0;
                    WSTRB <= 4'b0;
                    WVALID <= 1'b0;
                end
            endcase
        end
    end

endmodule

