module fifo36_demux
  #(parameter match_data = 0,
    parameter match_mask = 0)
   (input clk, input reset, input clear,
    input [35:0] data_i, input src_rdy_i, output dst_rdy_o,
    output [35:0] data0_o, output src0_rdy_o, input dst0_rdy_i,
    output [35:0] data1_o, output src1_rdy_o, input dst1_rdy_i);

  // State machine signals
  reg [1:0] state;
  reg [35:0] data0, data1;

  // Combinational logic
  always @(*) begin
    case (state)
      IDLE: begin
        if (reset || clear) begin
          state <= IDLE;
          data0 <= 36'b0;
          data1 <= 36'b0;
        end else if (src_rdy_i) begin
          state <= DATA0;
          data0 <= data_i;
          data1 <= 36'b0;
        end
      end
      DATA0: begin
        if (dst0_rdy_i) begin
          state <= IDLE;
          data0 <= 36'b0;
          data1 <= 36'b0;
        end else if (src_rdy_i) begin
          state <= DATA1;
          data0 <= 36'b0;
          data1 <= data_i;
        end
      end
      DATA1: begin
        if (dst1_rdy_i) begin
          state <= IDLE;
          data0 <= 36'b0;
          data1 <= 36'b0;
        end else if (src_rdy_i) begin
          state <= DATA0;
          data0 <= data_i;
          data1 <= 36'b0;
        end
      end
    endcase
  end

  // Sequential logic
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      state <= IDLE;
      data0 <= 36'b0;
      data1 <= 36'b0;
    end else if (clear) begin
      state <= IDLE;
      data0 <= 36'b0;
      data1 <= 36'b0;
    end else if (src_rdy_i) begin
      case (state)
        IDLE: begin
          if (match_data == data_i && match_mask == data_i) begin
            state <= DATA0;
          end else begin
            state <= DATA1;
          end
        end
        DATA0: begin
          if (match_data == data_i && match_mask == data_i) begin
            state <= DATA0;
          end else begin
            state <= DATA1;
          end
        end
        DATA1: begin
          if (match_data == data_i && match_mask == data_i) begin
            state <= DATA0;
          end else begin
            state <= DATA1;
          end
        end
      endcase
    end
  end

  // Output assignments
  assign data0_o = (state == DATA0) ? data0 : 36'b0;
  assign src0_rdy_o = (state == DATA0) ? dst0_rdy_i : 1'b0;
  assign data1_o = (state == DATA1) ? data1 : 36'b0;
  assign src1_rdy_o = (state == DATA1) ? dst1_rdy_i : 1'b0;
  assign dst_rdy_o = (state == IDLE) ? 1'b0 : 1'b1;

endmodule

module branch_ctrl(
