    case (funct3)
        3'b000: // EQ (Equal)
            jmpb = (data_rs1 == data_rs2);
        3'b001: // NE (Not Equal)
            jmpb = (data_rs1 != data_rs2);
        3'b100: // LT (Signed Less Than)
            jmpb = (data_rs1 < data_rs2);
        3'b101: // LTU (Unsigned Less Than)
            jmpb = (data_rs1 < data_rs2);
        3'b110: // GT (Signed Greater Than)
            jmpb = (data_rs1 > data_rs2);
        3'b111: // GTU (Unsigned Greater Than)
            jmpb = (data_rs1 > data_rs2);
        default: // Default case, should not occur
            jmpb = 0;
    endcase
end

endmodule

