module full_adder(output wire c_out, output wire s_out, input wire c_in, input wire x_in, input wire y_in);
    // Sum output is the XOR of x_in, y_in, and c_in
    assign s_out = x_in ^ y_in ^ c_in;

    // Carry-out is the OR of the three AND terms
    assign c_out = (x_in & y_in) | (x_in & c_in) | (y_in & c_in);
endmodule

module receiver(
    input wire rx,
    output reg rdy,
    input wire rdy_clr,
    input wire clk_50m,
    input wire rst,
    input wire clken,
    output reg [7:0] data
);

    // Define the states of the state machine
    typedef enum {START, DATA, STOP} state_t;
    state_t current_state, next_state;

    // Internal registers
    reg [7:0] received_data;
    reg [3:0] bit_counter;
    reg [3:0] stop_counter;
    reg [3:0] start_counter;
    reg [3:0] data_counter;

    // Clock enable and reset
    reg [3:0] clock_enable_counter;

    // State machine logic
    always @(posedge clk_50m or posedge rst) begin
        if (rst) begin
            current_state <= START;
            rdy <= 0;
            received_data <= 0;
            bit_counter <= 0;
            stop_counter <= 0;
            start_counter <= 0;
            data_counter <= 0;
            clock_enable_counter <= 0;
        end else if (clken) begin
            current_state <= next_state;

            // Clock enable logic
            if (clock_enable_counter == 4) begin
                clock_enable_counter <= 0;
            end else begin
                clock_enable_counter <= clock_enable_counter + 1;
            end

            // State transitions
            case (current_state)
                START: begin
                    if (rx == 1'b0) begin
                        next_state <= DATA;
                        bit_counter <= 0;
                        start_counter <= 0;
                        data_counter <= 0;
                        stop_counter <= 0;
                    end else begin
                        next_state <= START;
                    end
                end
                DATA: begin
                    if (clock_enable_counter == 1) begin
                        received_data[bit_counter] <= rx;
                        bit_counter <= bit_counter + 1;
                        if (bit_counter == 8) begin
                            next_state <= STOP;
                            data_counter <= 0;
                        end
                    end
                end
                STOP: begin
                    if (rx == 1'b1) begin
                        next_state <= START;
                        stop_counter <= stop_counter + 1;
                        if (stop_counter == 4) begin
                            rdy <= 1;
                            data <= received_data;
                            data_counter <= 0;
                        end
                    end else begin
                        next_state <= STOP;
                    end
                end
            endcase
        end
    end

    // Clear the ready signal
    always @(posedge rdy_clr) begin
        rdy <= 0;
    end

endmodule

