module CLG4(x1, y1, x2, y2, x3, y3, x4, y4, c1,
            s1, s2, s3, s4, c5);
    input x1, y1, x2, y2, x3, y3, x4, y4, c1;
    output s1, s2, s3, s4, c5;

    // Intermediate signals
    wire p1, p2, p3, p4;
    wire g1, g2, g3, g4;
    wire c2, c3, c4;
    wire c5;

    // XOR operations for p1-p4
    assign p1 = x1 ^ y1;
    assign p2 = x2 ^ y2;
    assign p3 = x3 ^ y3;
    assign p4 = x4 ^ y4;

    // AND operations for g1-g4
    assign g1 = x1 & y1;
    assign g2 = x2 & y2;
    assign g3 = x3 & y3;
    assign g4 = x4 & y4;

    // Carry generation for c2-c4
    assign c2 = g1 | (g2 & p1);
    assign c3 = g2 | (g3 & p2) | (c2 & p1);
    assign c4 = g3 | (g4 & p3) | (c3 & p2) | (c2 & p1);

    // Final carry-out c5
    assign c5 = g4 | (c3 & p3) | (c2 & p2) | (c1 & p1);

    // Sum computation for s1-s4
    assign s1 = p1 ^ c1;
    assign s2 = p2 ^ c2;
    assign s3 = p3 ^ c3;
    assign s4 = p4 ^ c4;
endmodule

