module jtframe_romrq #(parameter AW=18, DW=8 )(
    input               rst,
    input               clk,
    input               clr, 
    input [21:0]        offset,
    input [AW-1:0]      addr,
    input               addr_ok,    
    input [31:0]        din,
    input               din_ok,
    input               we,
    output reg          req,
    output reg          data_ok,    
    output     [21:0]   sdram_addr,
    output reg [DW-1:0] dout
) {
    // Internal registers
    reg [AW-1:0] addr_req;
    reg [AW-1:0] cached_addr0;
    reg [AW-1:0] cached_addr1;
    reg [DW-1:0] cached_data0;
    reg [DW-1:0] cached_data1;
    reg [2:0] subaddr;
    reg good;

    // Address translation
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            addr_req <= 0;
            cached_addr0 <= 0;
            cached_addr1 <= 0;
            cached_data0 <= 0;
            cached_data1 <= 0;
            subaddr <= 0;
            good <= 0;
        end else if (clr) begin
            addr_req <= 0;
            cached_addr0 <= 0;
            cached_addr1 <= 0;
            cached_data0 <= 0;
            cached_data1 <= 0;
            subaddr <= 0;
            good <= 0;
        end else if (addr_ok) begin
            addr_req <= {addr, {AW-DW{1'b0}}};
            subaddr <= addr[AW-DW-1:0];
        end
    end

    // Cache management
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            good <= 0;
        end else if (clr) begin
            good <= 0;
        end else if (we && din_ok) begin
            if (subaddr == 0) begin
                cached_addr0 <= addr_req;
                cached_data0 <= din;
            end else if (subaddr == 1) begin
                cached_addr1 <= addr_req;
                cached_data1 <= din;
            end
            good <= 1;
        end
    end

    // Memory request generation
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            req <= 0;
        end else if (clr) begin
            req <= 0;
        end else if (good && !hit0 && !hit1) begin
            req <= 1;
        end
    end

    // Data output selection
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            dout <= 0;
        end else if (clr) begin
            dout <= 0;
        end else if (good && subaddr == 0) begin
            dout <= cached_data0;
        end else if (good && subaddr == 1) begin
            dout <= cached_data1;
        end else if (addr_ok) begin
            dout <= din;
        end
    end

    // SDRAM address generation
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            sdram_addr <= 0;
        end else if (clr) begin
            sdram_addr <= 0;
        end else if (addr_ok) begin
            sdram_addr <= addr_req + offset;
        end
    end

    // Cache hit detection
    reg hit0, hit1;
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            hit0 <= 0;
            hit1 <= 0;
        end else if (clr) begin
            hit0 <= 0;
            hit1 <= 0;
        end else if (addr_ok) begin
            hit0 <= (addr_req == cached_addr0);
            hit1 <= (addr_req == cached_addr1);
        end
    end
}

