module oh_oai32 #(parameter DW = 1 ) 
   (
    input [DW-1:0]  a0,
    input [DW-1:0]  a1,
    input [DW-1:0]  a2,
    input [DW-1:0]  b0,
    input [DW-1:0]  b1, 
    output [DW-1:0] z
    );
    // Compute the OR of the first group of inputs
    wire [DW-1:0] or_a = a0 | a1 | a2;
    // Compute the OR of the second group of inputs
    wire [DW-1:0] or_b = b0 | b1;
    // Compute the AND of the two OR results
    wire [DW-1:0] and_result = or_a & or_b;
    // Compute the logical negation of the AND result
    assign z = ~and_result;
endmodule

