module Counter2(
    input clk,
    input start,
    input reset,
    output reg [3:0] count1,
    output reg [3:0] count2,
    output reg done
    );

    parameter mod = 9;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            count1 <= 4'b0000;
            count2 <= 4'b0000;
            done <= 1'b0;
        end else begin
            if (start) begin
                if (count1 < mod - 1) begin
                    count1 <= count1 + 1;
                end else begin
                    count1 <= 4'b0000;
                    if (count2 < mod - 1) begin
                        count2 <= count2 + 1;
                    end else begin
                        count1 <= 4'b0001;
                        if (count1 < mod - 1) begin
                            count1 <= count1 + 1;
                        end else begin
                            count1 <= 4'b0000;
                            count2 <= 4'b0000;
                            done <= 1'b1;
                        end
                    end
                end
            end else begin
                if (done) begin
                    count1 <= 4'b0000;
                    count2 <= 4'b0000;
                    done <= 1'b0;
                end
            end
        end
    end

endmodule

