module Data_Memory (
    input reset,
    input [31:0] address,
    input [31:0] write_data,
    input memRead,
    input memWrite,
    input [2:0] func3,
    output reg [31:0] read_data
);

    // Memory array to store data
    reg [7:0] memory [0:255];

    // Reset the memory to zero
    always @(posedge reset) begin
        for (int i = 0; i < 256; i++) begin
            memory[i] <= 8'h00;
        end
    end

    // Read operation
    always @(posedge memRead or posedge reset) begin
        if (reset) begin
            read_data <= 32'h00000000;
        end else begin
            case (func3)
                3'b000: // lbu
                    read_data <= {memory[address[7:0]], 8'h00};
                3'b001: // lh
                    read_data <= {memory[address[7:0]], memory[address[7:0] + 1]};
                3'b010: // lw
                    read_data <= {memory[address[7:0]], memory[address[7:0] + 1], memory[address[7:0] + 2], memory[address[7:0] + 3]};
                default: // Other cases, assume sign-extension for other func3 values
                    read_data <= {memory[address[7:0]], memory[address[7:0] + 1], memory[address[7:0] + 2], memory[address[7:0] + 3]};
            endcase
        end
    end

    // Write operation
    always @(posedge memWrite or posedge reset) begin
        if (reset) begin
            // No action needed on reset
        end else begin
            case (func3)
                3'b000: // lbu
                    memory[address[7:0]] <= write_data[7:0];
                3'b001: // lh
                    memory[address[7:0]] <= write_data[7:0];
                    memory[address[7:0] + 1] <= write_data[15:8];
                3'b010: // lw
                    memory[address[7:0]] <= write_data[7:0];
                    memory[address[7:0] + 1] <= write_data[15:8];
                    memory[address[7:0] + 2] <= write_data[23:16];
                    memory[address[7:0] + 3] <= write_data[31:24];
                default: // Other cases, assume sign-extension for other func3 values
                    memory[address[7:0]] <= write_data[7:0];
                    memory[address[7:0] + 1] <= write_data[15:8];
                    memory[address[7:0] + 2] <= write_data[23:16];
                    memory[address[7:0] + 3] <= write_data[31:24];
            endcase
        end
    end

endmodule

module UARTTransmitter(
  input        clock,
               reset,
               io_valid,
  input  [7:0] io_bits,
  input        tick,
  output       io_ready,
               tx
);

  // State definitions
  typedef enum {IDLE, START, DATA, STOP} state_t;
  state_t current_state, next_state;

  // State register
  reg [3:0] state_reg;

  // Data register
  reg [7:0] data_reg;

  // Ready signal
  reg io_ready_reg;

  // Serial output
  reg tx_reg;

  // Initial state
  initial begin
    state_reg <= IDLE;
    io_ready_reg <= 1'b0;
    tx_reg <= 1'b0;
  end

  // State machine
  always @(posedge clock or posedge reset) begin
    if (reset) begin
      state_reg <= IDLE;
      io_ready_reg <= 1'b0;
      tx_reg <= 1'b0;
    end else begin
      current_state <= state_reg;
      next_state <= IDLE;

      case (current_state)
        IDLE: begin
          if (io_valid) begin
            next_state <= START;
            data_reg <= io_bits;
          end
        end
        START: begin
          next_state <= DATA;
          tx_reg <= 1'b0;
        end
        DATA: begin
          if (tick) begin
            tx_reg <= data_reg[0];
            data_reg <= data_reg >> 1;
            if (data_reg == 8'h00) begin
              next_state <= STOP;
            end
          end
        end
        STOP: begin
          next_state <= IDLE;
          tx_reg <= 1'b1;
        end
      endcase

      state_reg <= next_state;
      io_ready_reg <= (current_state == IDLE);
    end
  end

  // Output assignments
  assign io_ready = io_ready_reg;
  assign tx = tx_reg;

endmodule

