module text_pixel #(parameter TEXT_DATA_WIDTH=8, TEXT_COLOUR_WIDTH=8) (
    input wire clk,
    input wire [9:0] x,
    input wire [8:0] y,
    input wire [TEXT_DATA_WIDTH-1:0] text_data,
    input wire [TEXT_COLOUR_WIDTH-1:0] text_colour,
    output reg [((TEXT_COLOUR_WIDTH/2)-1):0] pixel
) {
    // Load character map from external file during initialization
    reg [63:0] character_map [0:255];

    // Initialize character map with data from vga_font.mem
    initial begin
        $readmemh("vga_font.mem", character_map);
    end

    // Clock-triggered always block to update pixel color
    always @(posedge clk) begin
        // Calculate the character index based on the x coordinate
        reg [7:0] char_index = x[7:0];

        // Calculate the pixel index within the character
        reg [3:0] pixel_index = y[3:0];

        // Determine the color based on the character map and text colour
        if (character_map[char_index][pixel_index]) begin
            pixel = text_colour[3:0];
        end else begin
            pixel = text_colour[7:4];
        end
    end
}

