module vga_controller(
    input wire RST,
    input wire CLK,
    output wire H_SYNC,
    output wire V_SYNC,
    output wire [10:0] X,
    output wire [10:0] Y,
    output wire DISP_EN
);

    // Parameters for VGA timing
    parameter H_ACTIVE = 1280;
    parameter H_SYNC_PULSE = 88;
    parameter H_BACK_PORCH = 40;
    parameter H_FRONT_PORCH = 40;
    parameter H_TOTAL = H_ACTIVE + H_SYNC_PULSE + H_BACK_PORCH + H_FRONT_PORCH;

    parameter V_ACTIVE = 720;
    parameter V_SYNC_PULSE = 2;
    parameter V_BACK_PORCH = 33;
    parameter V_FRONT_PORCH = 10;
    parameter V_TOTAL = V_ACTIVE + V_SYNC_PULSE + V_BACK_PORCH + V_FRONT_PORCH;

    // Internal registers
    reg [10:0] x_reg;
    reg [10:0] y_reg;
    reg h_sync_reg;
    reg v_sync_reg;
    reg disp_en_reg;

    // Counter for horizontal position
    reg [10:0] h_counter;
    reg [10:0] h_counter_max;

    // Counter for vertical position
    reg [10:0] v_counter;
    reg [10:0] v_counter_max;

    // Clock sensitivity list
    always @(posedge CLK or posedge RST) begin
        if (RST) begin
            x_reg <= 0;
            y_reg <= 0;
            h_sync_reg <= 0;
            v_sync_reg <= 0;
            disp_en_reg <= 0;
            h_counter <= 0;
            h_counter_max <= H_TOTAL - 1;
            v_counter <= 0;
            v_counter_max <= V_TOTAL - 1;
        end else begin
            // Horizontal position counter
            if (h_counter < H_TOTAL) begin
                h_counter <= h_counter + 1;
            end else begin
                h_counter <= 0;
                v_counter <= v_counter + 1;
            end

            // Horizontal sync generation
            if (h_counter == H_ACTIVE + H_SYNC_PULSE) begin
                h_sync_reg <= 1;
            end else if (h_counter == H_ACTIVE + H_SYNC_PULSE + H_BACK_PORCH) begin
                h_sync_reg <= 0;
            end

            // Vertical sync generation
            if (v_counter == V_ACTIVE + V_SYNC_PULSE) begin
                v_sync_reg <= 1;
            end else if (v_counter == V_ACTIVE + V_SYNC_PULSE + V_BACK_PORCH) begin
                v_sync_reg <= 0;
            end

            // Display enable generation
            if (h_counter >= H_ACTIVE && h_counter < H_ACTIVE + H_SYNC_PULSE + H_BACK_PORCH + H_FRONT_PORCH &&
                v_counter >= V_ACTIVE && v_counter < V_ACTIVE + V_SYNC_PULSE + V_BACK_PORCH + V_FRONT_PORCH) begin
                disp_en_reg <= 1;
            end else begin
                disp_en_reg <= 0;
            end

            // Update X and Y registers
            if (h_counter == H_ACTIVE + H_SYNC_PULSE + H_BACK_PORCH) begin
                x_reg <= x_reg + 1;
            end
            if (v_counter == V_ACTIVE + V_SYNC_PULSE + V_BACK_PORCH) begin
                y_reg <= y_reg + 1;
            end
        end
    end

    // Output assignments
    assign X = x_reg;
    assign Y = y_reg;
    assign H_SYNC = h_sync_reg;
    assign V_SYNC = v_sync_reg;
    assign DISP_EN = disp_en_reg;

endmodule

