module tx_add_preamble(
    input wire clk,
    input wire data_valid_in,
    input wire [7:0] data_in,
    output reg data_valid_out,
    output reg [7:0] data_out
);

    // Registers to store data and its validity
    reg [63:0] delay_data;
    reg [7:0] delay_data_valid;

    // Preamble bytes
    reg [7:0] preamble1 = 8'b11010101;
    reg [7:0] preamble2 = 8'b01010101;

    // Shift the data and validity registers
    always @(posedge clk) begin
        if (data_valid_in) begin
            // Shift data and validity registers
            delay_data <= {delay_data[55:0], data_in};
            delay_data_valid <= {delay_data_valid[6:0], 1'b1};
        end else begin
            // Shift data and validity registers
            delay_data <= {delay_data[55:0], 8'b0};
            delay_data_valid <= {delay_data_valid[6:0], 1'b0};
        end
    end

    // Generate the output based on the delay_data_valid register
    always @(posedge clk) begin
        if (delay_data_valid[7]) begin
            // Transmit the first byte of data
            data_out <= delay_data[55:48];
            data_valid_out <= 1'b1;
        end else if (delay_data_valid[6]) begin
            // Transmit the preamble byte
            data_out <= preamble1;
            data_valid_out <= 1'b1;
        end else if (data_valid_in) begin
            // Transmit the preamble byte and new data
            data_out <= preamble2;
            data_valid_out <= 1'b1;
        end else begin
            // No data to transmit
            data_out <= 8'b0;
            data_valid_out <= 1'b0;
        end
    end

endmodule

