module sqrt_pipelined
  #(
    parameter
    INPUT_BITS   = 16, 
    OUTPUT_BITS  = INPUT_BITS / 2 + INPUT_BITS % 2 
    )
  (
   input                        clk,        
   input                        reset_n,    
   input                        start,      
   input [INPUT_BITS-1:0]       radicand,   
   output reg                   data_valid, 
   output reg [OUTPUT_BITS-1:0] root        
   );

  // Register declarations
  reg [INPUT_BITS-1:0] radicand_gen;
  reg [OUTPUT_BITS-1:0] root_gen;
  reg [OUTPUT_BITS-1:0] mask_gen;

  // Generate block to create pipeline stages
  generate
    for (genvar i = 0; i < OUTPUT_BITS; i++) begin
      // Stage i
      always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
          radicand_gen <= radicand;
          root_gen <= 0;
          mask_gen <= 0;
        end else if (start) begin
          radicand_gen <= radicand;
          root_gen <= 0;
          mask_gen <= 0;
        end else if (i == 0) begin
          // First stage
          mask_gen <= 1 << (OUTPUT_BITS - 1);
          root_gen <= radicand_gen >> (OUTPUT_BITS - 1);
        end else begin
          // Subsequent stages
          mask_gen <= mask_gen >> 1;
          root_gen <= root_gen - (radicand_gen & mask_gen);
        end
      end
    end
  endgenerate

  // Data valid signal
  always @(posedge clk or negedge reset_n) begin
    if (!reset_n) begin
      data_valid <= 0;
    end else if (start) begin
      data_valid <= 0;
    end else if (i == OUTPUT_BITS - 1) begin
      data_valid <= 1;
    end
  end

endmodule

