module ps2controller (
    input reset,
    input i_clock,
    input i_data,
    output scan_ready,
    output [7:0] scan_code
);

    // Define the state machine states
    typedef enum { IDLE, CAPTURING, CHECKING_PARITY, PROCESSING_STOP_BIT } state_t;
    state_t current_state, next_state;

    // Define the register and counter
    reg [7:0] scan_code_reg;
    reg [3:0] counter;

    // Define the parity check
    reg parity;

    // Define the ready signal
    reg scan_ready_reg;

    // State machine process
    always @(posedge i_clock or posedge reset) begin
        if (reset) begin
            current_state <= IDLE;
            scan_code_reg <= 8'b0;
            counter <= 4'b0;
            parity <= 1'b0;
            scan_ready_reg <= 1'b0;
        end else begin
            current_state <= next_state;

            case (current_state)
                IDLE: begin
                    if (i_data) begin
                        next_state <= CAPTURING;
                    end else begin
                        next_state <= IDLE;
                    end
                end

                CAPTURING: begin
                    if (counter < 8) begin
                        scan_code_reg[7 - counter] <= i_data;
                        counter <= counter + 1;
                        next_state <= CAPTURING;
                    end else begin
                        next_state <= CHECKING_PARITY;
                    end
                end

                CHECKING_PARITY: begin
                    parity <= i_data;
                    next_state <= PROCESSING_STOP_BIT;
                end

                PROCESSING_STOP_BIT: begin
                    if (i_data) begin
                        next_state <= IDLE;
                    end else begin
                        next_state <= IDLE;
                    end
                end

                default: begin
                    next_state <= IDLE;
                end
            endcase
        end
    end

    // Output the scan_ready signal
    always @(posedge i_clock or posedge reset) begin
        if (reset) begin
            scan_ready_reg <= 1'b0;
        end else begin
            scan_ready_reg <= (current_state == PROCESSING_STOP_BIT);
        end
    end

    // Output the scan_code signal
    assign scan_code = scan_code_reg;

endmodule

