module radix2(
    input wire [1:0] state,
    input wire signed [23:0] din_a_r,
    input wire signed [23:0] din_a_i,
    input wire signed [23:0] din_b_r,
    input wire signed [23:0] din_b_i,
    input wire signed [23:0] w_r,
    input wire signed [23:0] w_i,
    output reg signed[23:0] op_r,
    output reg signed[23:0] op_i,
    output reg signed[23:0] delay_r,
    output reg signed[23:0] delay_i,
    output reg outvalid
);

    // Internal registers to prevent overflow during complex multiplications
    reg signed[41:0] temp_r;
    reg signed[41:0] temp_i;

    // Combinational logic to process inputs based on the current state
    always_comb begin
        case (state)
            2'b00: begin
                op_r = 0;
                op_i = 0;
                delay_r = 0;
                delay_i = 0;
                outvalid = 0;
            end
            2'b01: begin
                // Addition and subtraction of input pairs
                temp_r = din_a_r + din_b_r;
                temp_i = din_a_i + din_b_i;
                op_r = temp_r;
                op_i = temp_i;
                delay_r = temp_r;
                delay_i = temp_i;
                outvalid = 1;
            end
            2'b10: begin
                // Multiplication by twiddle factors with higher precision
                temp_r = (din_a_r * w_r) - (din_a_i * w_i);
                temp_i = (din_a_r * w_i) + (din_a_i * w_r);
                op_r = temp_r;
                op_i = temp_i;
                delay_r = temp_r;
                delay_i = temp_i;
                outvalid = 1;
            end
            2'b11: begin
                op_r = 0;
                op_i = 0;
                delay_r = 0;
                delay_i = 0;
                outvalid = 0;
            end
            default: begin
                op_r = 0;
                op_i = 0;
                delay_r = 0;
                delay_i = 0;
                outvalid = 0;
            end
        endcase
    end

endmodule

