module toe_m_axis_rxread_cmd_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);

// State machine states
typedef enum {ZERO, ONE, TWO} state_t;
state_t state;

// Internal registers
reg [N-1:0] data_p1;
reg [N-1:0] data_p2;
reg load_p1;
reg load_p2;
reg load_p1_from_p2;

// Control signals
always @(posedge clk or posedge reset) begin
    if (reset) begin
        state <= ZERO;
        data_p1 <= 0;
        data_p2 <= 0;
        load_p1 <= 0;
        load_p2 <= 0;
        load_p1_from_p2 <= 0;
        s_ready <= 0;
        m_valid <= 0;
    end else begin
        case (state)
            ZERO: begin
                if (s_valid && m_ready) begin
                    state <= ONE;
                    load_p1 <= 1;
                end
            end
            ONE: begin
                if (load_p1) begin
                    data_p1 <= s_data;
                    load_p1 <= 0;
                    load_p2 <= 1;
                end
            end
            TWO: begin
                if (load_p2) begin
                    data_p2 <= data_p1;
                    load_p2 <= 0;
                    load_p1_from_p2 <= 1;
                    s_ready <= 1;
                    m_valid <= 1;
                end
            end
        endcase
    end
end

// Output signals
assign m_data = data_p2;
assign s_ready = load_p1_from_p2;

endmodule

