module alu
  (
   alu_src1,
   alu_src2,
   alu_opcode,
   minus_is_zero,
   less_than,
   less_than_unsigned,
   alu_result
   );
input wire [31:0]       alu_src1;
   input wire [31:0]	   alu_src2;
   input wire [3:0]	   alu_opcode;
   output reg [31:0]	   alu_result;
   output reg		   minus_is_zero;
   output reg		   less_than;
   output reg		   less_than_unsigned;

   // Internal register for subtraction
   reg [32:0] internal_result;

   // Function to perform subtraction using a 33-bit register
   function [31:0] subtract;
      input [31:0] a, b;
      begin
         internal_result = {32'b0, a} - b;
         subtract = internal_result[31:0];
      end
   endfunction

   // Case statement to determine the operation
   always @(*) begin
      case (alu_opcode)
         4'b0000: alu_result = alu_src1 + alu_src2; // Addition
         4'b0001: alu_result = alu_src1 - alu_src2; // Subtraction
         4'b0010: alu_result = alu_src1 & alu_src2; // AND
         4'b0011: alu_result = alu_src1 | alu_src2; // OR
         4'b0100: alu_result = alu_src1 ^ alu_src2; // XOR
         4'b0101: alu_result = alu_src1 << 1; // Left shift (unsigned)
         4'b0110: alu_result = alu_src1 >> 1; // Right shift (unsigned)
         4'b0111: alu_result = alu_src1 << 1; // Left shift (signed)
         4'b1000: alu_result = alu_src1 >> 1; // Right shift (signed)
         default: alu_result = 32'b0; // Invalid opcode
      endcase

      // Calculate status flags
      minus_is_zero = (alu_result == 32'b0);
      less_than = (alu_src1 < alu_src2);
      less_than_unsigned = (alu_src1 < alu_src2);
   end

endmodule

module delay_ctrl (
    input clk,
    input reset,

    input faster,
    input slower,
    output [3:0] delay,

    input write,
    input [7:0] writedata
);

    reg [3:0] delay_intern;

    // Initialize delay_intern to 8
    initial begin
        delay_intern = 4'b1000;
    end

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            delay_intern <= 4'b1000;
        end else begin
            if (write) begin
                // Load lower four bits of writedata into delay_intern
                delay_intern <= writedata[3:0];
            end else begin
                // Handle faster and slower inputs
                if (faster) begin
                    // Decrement delay_intern by 1, but not below 1
                    if (delay_intern > 1) begin
                        delay_intern <= delay_intern - 1;
                    end
                end else if (slower) begin
                    // Increment delay_intern by 1, but not above 15
                    if (delay_intern < 15) begin
                        delay_intern <= delay_intern + 1;
                    end
                end
            end
        end
    end

    // Output the current delay value
    assign delay = delay_intern;

endmodule

module clk_div(
    input wire clk,
    output wire clk_hz
);

    // Define the prescaler register
    reg [27:0] prescaler;

    // Define the temporary register
    reg temp;

    // Define the output clock
    assign clk_hz = temp;

    // Clock divider logic
    always @(posedge clk) begin
        // Increment the prescaler
        prescaler <= prescaler + 1'b1;

        // Check if the prescaler has reached the threshold
        if (prescaler == 28'h2FAF080) begin
            // Reset the prescaler
            prescaler <= 28'h0;

            // Set the temporary register high for one cycle
            temp <= 1'b1;
        end else begin
            // Reset the temporary register
            temp <= 1'b0;
        end
    end

endmodule

