                mem[wr_ptr] <= din;
                wr_ptr <= (wr_ptr + 1) % DEPTH;
            end
            if (read && !empty_n) begin
                dout <= mem[rd_ptr];
                rd_ptr <= (rd_ptr + 1) % DEPTH;
            end
            empty_n <= (wr_ptr == rd_ptr);
            full_n <= (wr_ptr + 1) % DEPTH == rd_ptr;
        end
    end

