module ldrw
  (
   input [7:0] 	 cell0,
   input [7:0] 	 cell1,
   input [7:0] 	 cell2,
   input [7:0] 	 cell3,
   output [31:0] argb
   );

  // Calculate the sum of the lower 7 bits of each input cell
  wire [6:0] sum = cell0[6:0] + cell1[6:0] + cell2[6:0] + cell3[6:0];

  // Shift the sum left by 3 bits to create the count value
  wire [11:0] count = sum << 3;

  // Check if any of the 8th bits of the input cells are set to 1
  wire any_8th_bit_set = cell0[7] | cell1[7] | cell2[7] | cell3[7];

  // Determine the final argb value based on the 8th bit check
  assign argb = any_8th_bit_set ? 32'h00000077 : {count, count, count, 8'h00};

endmodule

module pwm(
    input wire clk,
    input wire rst,
    input wire [31:0] duty,
    output reg pwm_out
);

    // Parameters
    parameter PERIOD = 8;

    // Internal registers
    reg [31:0] duty_reg;
    reg [PERIOD-1:0] counter;

    // Reset process
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            duty_reg <= duty;
            counter <= 0;
            pwm_out <= 0;
        end else begin
            if (counter == PERIOD - 1) begin
                counter <= 0;
                duty_reg <= duty;
            end else begin
                counter <= counter + 1;
            end
            pwm_out <= (counter < duty_reg);
        end
    end

endmodule

module KeyEncoder(Columns, Rows, Clock, Reset, OnesDigit, TensDigit, Found);
    input [3:0] Columns;
    input [3:0] Rows;
    input Clock, Reset;
    output reg [3:0] OnesDigit;
    output reg [3:0] TensDigit;
    output reg Found;

    // Define the key mapping
    parameter [7:0] KEY_MAP[0:15] = {
        8'h00, 8'h01, 8'h02, 8'h03,  // 0-3
        8'h04, 8'h05, 8'h06, 8'h07,  // 4-7
        8'h08, 8'h09, 8'h0A, 8'h0B,  // 8-11
        8'h0C, 8'h0D, 8'h0E, 8'h0F   // 12-15
    };

    // Define the found status parameter
    parameter [8:0] FOUND_PARAM = 9'h100; // Example found status

    // Internal signals
    reg [3:0] key_code;
    reg [3:0] key_ones;
    reg [3:0] key_tens;
    reg [7:0] key_map_value;
    reg [8:0] found_status;

    // Reset the module
    always @(posedge Reset) begin
        OnesDigit <= 4'b0000;
        TensDigit <= 4'b0000;
        Found <= 1'b0;
        key_code <= 4'b0000;
        key_ones <= 4'b0000;
        key_tens <= 4'b0000;
        found_status <= 9'b000000000;
    end

    // Decode the key press
    always @(posedge Clock) begin
        if (Reset) begin
            key_code <= 4'b0000;
            key_ones <= 4'b0000;
            key_tens <= 4'b0000;
            found_status <= 9'b000000000;
        end else begin
            key_code <= Columns * 4 + Rows;
            key_map_value <= KEY_MAP[key_code];
            key_ones <= key_map_value[3:0];
            key_tens <= key_map_value[7:4];
            found_status <= FOUND_PARAM;
        end
    end

    // Assign outputs
    assign OnesDigit = key_ones;
    assign TensDigit = key_tens;
    assign Found = (found_status == FOUND_PARAM);
endmodule

module sky130_fd_sc_hs__nand4b (Y, A_N, B, C, D);
    output Y;
    input A_N;
    input B;
    input C;
    input D;

    wire A_N_inv;
    wire NAND_result;

    // Invert A_N using a NOT gate
    not A_N_inv (A_N_inv, A_N);

    // Combine A_N_inv with B, C, and D using a four-input NAND gate
    nand NAND_gate (NAND_result, A_N_inv, B, C, D);

    // Buffer the NAND result to produce the final output Y
    assign Y = NAND_result;
endmodule

