module CLG4_3(
    input x1, y1, x2, y2, x3, y3, x4, y4, c1,
    output s1, s2, s3, s4
);

    // Intermediate signals
    wire p1, p2, p3, p4; // Sum without carry
    wire g1, g2, g3, g4; // Carry generation
    wire c2, c3, c4; // Ripple carry

    // Calculate p1-p4 (sum without carry)
    assign p1 = x1 ^ y1;
    assign p2 = x2 ^ y2;
    assign p3 = x3 ^ y3;
    assign p4 = x4 ^ y4;

    // Calculate g1-g4 (carry generation)
    assign g1 = x1 & y1;
    assign g2 = x2 & y2;
    assign g3 = x3 & y3;
    assign g4 = x4 & y4;

    // Calculate c2-c4 (ripple carry)
    assign c2 = g1 | (g2 & c1);
    assign c3 = g2 | (g3 & c2);
    assign c4 = g3 | (g4 & c3);

    // Calculate s1-s4 (sum with carry)
    assign s1 = p1 ^ c1;
    assign s2 = p2 ^ c2;
    assign s3 = p3 ^ c3;
    assign s4 = p4 ^ c4;

endmodule

