module fir_filter_slice #(
  parameter IN_WIDTH     = 16,
  parameter COEFF_WIDTH  = 16,
  parameter ACCUM_WIDTH  = 32,
  parameter OUT_WIDTH    = 32
)(
  input clk,
  input reset,
  input clear,
  input sample_in_stb,
  input signed [IN_WIDTH-1:0] sample_in_a,       
  input signed [IN_WIDTH-1:0] sample_in_b,       
  output signed [IN_WIDTH-1:0] sample_forward,   
  input signed [COEFF_WIDTH-1:0] coeff_in,       
  output signed [COEFF_WIDTH-1:0] coeff_forward, 
  input coeff_load_stb,                          
  input signed [ACCUM_WIDTH-1:0] sample_accum,   
  output signed [OUT_WIDTH-1:0] sample_out       
);

  // Internal registers
  reg [IN_WIDTH-1:0] a_reg;
  reg [IN_WIDTH-1:0] b_reg;
  reg [ACCUM_WIDTH-1:0] ad_reg;
  reg [ACCUM_WIDTH-1:0] m_reg;
  reg [ACCUM_WIDTH-1:0] p_reg;

  // Reset and clear logic
  always @(posedge clk or posedge reset or posedge clear) begin
    if (reset) begin
      a_reg <= 0;
      b_reg <= 0;
      ad_reg <= 0;
      m_reg <= 0;
      p_reg <= 0;
    end else if (clear) begin
      a_reg <= 0;
      b_reg <= 0;
      ad_reg <= 0;
      m_reg <= 0;
      p_reg <= 0;
    end
  end

  // Sample input logic
  always @(posedge clk or posedge reset or posedge clear) begin
    if (reset) begin
      a_reg <= 0;
    end else if (sample_in_stb) begin
      a_reg <= sample_in_a;
    end
  end

  // Coefficient input logic
  always @(posedge clk or posedge reset or posedge clear) begin
    if (reset) begin
      b_reg <= 0;
    end else if (coeff_load_stb) begin
      b_reg <= coeff_in;
    end
  end

  // Addition and multiplication logic
  always @(posedge clk or posedge reset or posedge clear) begin
    if (reset) begin
      ad_reg <= 0;
      m_reg <= 0;
    end else if (sample_in_stb) begin
      ad_reg <= a_reg + b_reg;
      m_reg <= ad_reg * sample_in_b;
    end
  end

  // Accumulation logic
  always @(posedge clk or posedge reset or posedge clear) begin
    if (reset) begin
      p_reg <= 0;
    end else if (sample_in_stb) begin
      p_reg <= p_reg + m_reg;
    end
  end

  // Output logic
  always @(posedge clk or posedge reset or posedge clear) begin
    if (reset) begin
      sample_out <= 0;
    end else if (sample_in_stb) begin
      sample_out <= p_reg[OUT_WIDTH-1:0];
    end
  end

  // Forwarding logic
  assign sample_forward = a_reg;
  assign coeff_forward = b_reg;

endmodule

