module uds_counter #(
    parameter WIDTH = 8,
    parameter MAX = 255
) (
    input [WIDTH-1:0] in,
    input up, down, set,
    input clk,
    output reg [WIDTH-1:0] out
);

    reg [WIDTH-1:0] count;
    reg [2:0] uds;

    // Initialize the counter to zero
    initial begin
        out = 0;
    end

    // Encode control signals into a single vector
    assign uds = {up, set, down};

    // Synchronous process to handle counter operations
    always @(posedge clk) begin
        case (uds)
            3'b001: begin // Set operation
                if (count < MAX) begin
                    count = in;
                end
            end
            3'b010: begin // Increment operation
                if (count < MAX) begin
                    count = count + 1;
                end
            end
            3'b100: begin // Decrement operation
                if (count > 0) begin
                    count = count - 1;
                end
            end
            default: begin // No operation
                // Hold the current count value
            end
        endcase
    end

    // Assign the current count to the output
    assign out = count;

endmodule

