    reg [size-1 : 0] a_int;
    reg [size-1 : 0] b_int;

    // Array of registers to store intermediate results
    reg [2*size-1 : 0] pdt_int [0:level-1];

    // Register to hold the final product
    reg [2*size-1 : 0] pdt_reg;

    // Clocked block to handle the pipelining process
    always @(posedge clk) begin
        // Capture input values into internal registers
        a_int <= a;
        b_int <= b;

        // Compute the product of a_int and b_int
        pdt_int[0] <= a_int * b_int;

        // Propagate the product through each pipeline stage
        for (int i = 1; i < level; i++) begin
            pdt_int[i] <= pdt_int[i-1];
        end

        // Assign the final product to the output
        pdt_reg <= pdt_int[level-1];
    end

    // Assign the final product to the output port
    assign pdt = pdt_reg;

endmodule

