	for (int i = 0; i < LATENCY; i++) begin
		r_q_P[i] <= 0;
	end
end

// Combinational multiplication
always @(*) begin
	r_a_1P <= a;
	r_b_1P <= b;
end

// Pipeline stages
always @(posedge clk) begin
	if (!arst) begin
		for (int i = 0; i < LATENCY; i++) begin
			if (i == 0) begin
				r_q_P[i] <= r_a_1P * r_b_1P;
			end else begin
				r_q_P[i] <= r_q_P[i-1];
			end
		end
	end
end

// Output delay
always @(posedge clk) begin
	if (!arst) begin
		o <= r_q_P[LATENCY-1];
	end
end

