module QueueCompatibility_14 (
  input        clock,
  input        reset,
  output       io_enq_ready,
  input        io_enq_valid,
  input  [3:0] io_enq_bits_tl_state_size,
  input  [1:0] io_enq_bits_tl_state_source,
  input        io_deq_ready,
  output       io_deq_valid,
  output [3:0] io_deq_bits_tl_state_size,
  output [1:0] io_deq_bits_tl_state_source
);

  // Register to store the queue's state
  reg [3:0] queue_state_size;
  reg [1:0] queue_state_source;

  // Register to track the full state of the queue
  reg maybe_full;

  // Reset the queue state and full state on reset
  always @(posedge reset) begin
    queue_state_size <= 4'b0;
    queue_state_source <= 2'b0;
    maybe_full <= 1'b0;
  end

  // Update the queue state and full state based on enqueue and dequeue operations
  always @(posedge clock) begin
    if (reset) begin
      queue_state_size <= 4'b0;
      queue_state_source <= 2'b0;
      maybe_full <= 1'b0;
    end else begin
      if (io_enq_valid && io_enq_ready) begin
        queue_state_size <= io_enq_bits_tl_state_size;
        queue_state_source <= io_enq_bits_tl_state_source;
      end
      if (io_deq_valid && io_deq_ready) begin
        queue_state_size <= queue_state_size - 1'b1;
      end
      maybe_full <= (queue_state_size == 4'b0);
    end
  end

  // Provide the valid dequeue signals and the corresponding state information
  assign io_deq_valid = (queue_state_size != 4'b0) && io_deq_ready;
  assign io_deq_bits_tl_state_size = queue_state_size;
  assign io_deq_bits_tl_state_source = queue_state_source;

  // Provide the ready signal for enqueue
  assign io_enq_ready = !maybe_full;

endmodule

module ADDFHXL ( S, CO, A, B, CI);
    output reg S, CO;
    input wire A, B, CI;

    // XOR gate for sum calculation
    assign S = A ^ B ^ CI;

    // OR gate for carry-out calculation
    assign CO = (A & B) | (A & CI) | (B & CI);

    // Specify block for timing constraints
    `ifdef SYNTHESIS
        // Ensure consistent propagation delays across all input paths to S and CO
        `define S_DELAY 1
        `define CO_DELAY 1

        // Timing constraints for S
        always @(posedge A or posedge B or posedge CI) begin
            #`S_DELAY S <= A ^ B ^ CI;
        end

        // Timing constraints for CO
        always @(posedge A or posedge B or posedge CI) begin
            #`CO_DELAY CO <= (A & B) | (A & CI) | (B & CI);
        end
    `endif
endmodule

module multpool_rdata_mux #(
  parameter NBITS     = 256,
  parameter NUM_RDATA = 1024) (
  input  wire               hclk,     
  input  wire               hresetn,  
  input  wire [3*NBITS-1:0] rdata [0 :NUM_RDATA-1],
  input  wire               valid_rd,
  output wire [3*NBITS-1:0] hrdata
);

  // Number of groups
  localparam NUM_GROUPS = NUM_RDATA / 4;

  // Intermediate results for each group
  reg [3*NBITS-1:0] group_results[NUM_GROUPS];

  // Temporary register to hold the combined result
  reg [3*NBITS-1:0] temp_result;

  // Process each group of data
  for (genvar i = 0; i < NUM_GROUPS; i++) begin
    always @(posedge hclk or negedge hresetn) begin
      if (!hresetn) begin
        group_results[i] <= 0;
      end else if (valid_rd) begin
        group_results[i] <= rdata[i * 4 + 0] | rdata[i * 4 + 1] | rdata[i * 4 + 2] | rdata[i * 4 + 3];
      end
    end
  end

  // Combine the intermediate results
  always @(posedge hclk or negedge hresetn) begin
    if (!hresetn) begin
      temp_result <= 0;
    end else if (valid_rd) begin
      temp_result <= group_results[0] | group_results[1] | group_results[2] | group_results[3];
    end
  end

  // Output the final result
  assign hrdata = temp_result;

endmodule

module udpLoopback_lbRxMetadataIn_reg_slice
#(
    parameter
        N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);

// Internal registers
reg [N-1:0] data_p1;
reg [N-1:0] data_p2;
reg [2:0] state;

// FSM states
typedef enum {ZERO, ONE, TWO} state_t;
state_t current_state, next_state;

// Combinational logic to determine next state
always_comb begin
    case (current_state)
        ZERO: begin
            if (s_valid && m_ready) begin
                next_state = ONE;
            end else begin
                next_state = ZERO;
            end
        end
        ONE: begin
            if (m_ready) begin
                next_state = TWO;
            end else begin
                next_state = ONE;
            end
        end
        TWO: begin
            if (s_valid) begin
                next_state = ONE;
            end else begin
                next_state = TWO;
            end
        end
    endcase
end

// Sequential logic to update state and registers
always_ff @(posedge clk or posedge reset) begin
    if (reset) begin
        current_state <= ZERO;
        data_p1 <= 0;
        data_p2 <= 0;
        m_data <= 0;
        m_valid <= 0;
        s_ready <= 1;
    end else begin
        current_state <= next_state;
        if (current_state == ONE) begin
            data_p1 <= s_data;
        end
        if (current_state == TWO) begin
            data_p2 <= s_data;
            m_data <= data_p1;
            m_valid <= s_valid;
            s_ready <= m_ready;
        end
    end
end

endmodule

