module m2016_ram(
    input [7:0] data,
    input clk,
    input nOE,
    input nCS,
    input [10:0] addr,
    input nWE,
    output reg [7:0] q
);

    // Declare the memory array
    reg [7:0] memory[0:2047];

    // Sequential logic to handle write and read operations
    always @(posedge clk or negedge nCS) begin
        if (~nCS) begin
            if (~nWE) begin
                // Write operation
                memory[addr] <= data;
            end else if (~nOE) begin
                // Read operation
                q <= memory[addr];
            end else begin
                // Output enable is low, but not writing or reading
                q <= 8'b0;
            end
        end else begin
            // CS is low, reset the memory
            q <= 8'b0;
        end
    end

endmodule

module sbox3 (
    input [6:1] Bin,
    output reg [4:1] BSout
);

    // Define the 6-bit offset by rearranging Bin's bits
    wire [5:0] offset = {Bin[6], Bin[1], Bin[5:2]};

    // Define the 4-bit substitution table
    reg [3:0] sbox_table[63:0] = {
        4'b0000, 4'b0001, 4'b0010, 4'b0011, 4'b0100, 4'b0101, 4'b0110, 4'b0111,
