module serial2parallel(
    input clk,
    input rst_n,
    input din_serial,
    input din_valid,
    output reg [7:0] dout_parallel,
    output reg dout_valid
);

    // Internal counter to track the number of valid serial bits received
    reg [3:0] counter;

    // Shift register to construct the parallel output
    reg [7:0] shift_register;

    // Flag to indicate when a complete byte has been received
    reg byte_received;

    // Reset the module when rst_n is low
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            counter <= 4'b0000;
            shift_register <= 8'b00000000;
            dout_parallel <= 8'b00000000;
            dout_valid <= 1'b0;
            byte_received <= 1'b0;
        end else begin
            // Shift the serial data into the shift register
            if (din_valid) begin
                shift_register <= {din_serial, shift_register[7:1]};
                counter <= counter + 1'b1;
            end

            // Check if a complete byte has been received
            if (counter == 8'b1111) begin
                byte_received <= 1'b1;
                counter <= 4'b0000;
            end else begin
                byte_received <= 1'b0;
            end

            // Set the parallel output when a complete byte is received
            if (byte_received) begin
                dout_parallel <= shift_register;
                dout_valid <= 1'b1;
            end else begin
                dout_valid <= 1'b0;
            end
        end
    end

endmodule

