module blake2_G(
    input wire [63 : 0]  a,
    input wire [63 : 0]  b,
    input wire [63 : 0]  c,
    input wire [63 : 0]  d,
    input wire [63 : 0]  m0,
    input wire [63 : 0]  m1,

    output wire [63 : 0] a_prim,
    output wire [63 : 0] b_prim,
    output wire [63 : 0] c_prim,
    output wire [63 : 0] d_prim
);

    // Intermediate registers to store intermediate results
    reg [63 : 0] a0, a1, b0, b1, b2, b3, c0, c1, d0, d1, d2, d3;

    // Combinational logic to perform the G function
    always @* begin
        // Step 1: a0 = a + m0
        a0 = a + m0;

        // Step 2: b0 = b + m1
        b0 = b + m1;

        // Step 3: c0 = c + a0
        c0 = c + a0;

        // Step 4: d0 = d + b0
        d0 = d + b0;

        // Step 5: a1 = a0 ^ c0
        a1 = a0 ^ c0;

        // Step 6: b1 = b0 ^ d0
        b1 = b0 ^ d0;

        // Step 7: c1 = c0 ^ a1
        c1 = c0 ^ a1;

        // Step 8: d1 = d0 ^ b1
        d1 = d0 ^ b1;

        // Step 9: a2 = a1 + d1
        a2 = a1 + d1;

        // Step 10: b2 = b1 + a2
        b2 = b1 + a2;

        // Step 11: c2 = c1 + b2
        c2 = c1 + b2;

        // Step 12: d2 = d1 + c2
        d2 = d1 + c2;

        // Step 13: a3 = a2 ^ c2
        a3 = a2 ^ c2;

        // Step 14: b3 = b2 ^ d2
        b3 = b2 ^ d2;

        // Step 15: c3 = c2 ^ a3
        c3 = c2 ^ a3;

        // Step 16: d3 = d2 ^ b3
        d3 = d2 ^ b3;

        // Step 17: a_prim = a3 + d3
        a_prim = a3 + d3;

        // Step 18: b_prim = b3 + a_prim
        b_prim = b3 + a_prim;

        // Step 19: c_prim = c3 + b_prim
        c_prim = c3 + b_prim;

        // Step 20: d_prim = d3 + c_prim
        d_prim = d3 + c_prim;
    end

endmodule

module NAND5B4 (O, I0, I1, I2, I3, I4);

    output O;

    input  I0, I1, I2, I3, I4;

    wire I0_inv, I1_inv, I2_inv, I3_inv;

    // Invert the first four inputs
    not #1 I0_inv (I0_inv, I0);
    not #1 I1_inv (I1_inv, I1);
    not #1 I2_inv (I2_inv, I2);
    not #1 I3_inv (I3_inv, I3);

    // Compute the NAND of the inverted inputs and I4
    nand #1 O (O, I0_inv, I1_inv, I2_inv, I3_inv, I4);

endmodule

