module sincf #(parameter win=1, wout=5)
(
	input clk,
	input [win-1:0] din,
	output reg [wout-1:0] dout
)
{
    reg [wout-1:0] mem[win-1:0];

    always @(posedge clk) begin
        // Shift the register to the right
        for (int i = win-1; i > 0; i--) begin
            mem[i] <= mem[i-1];
        end

        // Store the current input in the first position
        mem[0] <= din;

        // Calculate the sum of the last 24 inputs
        dout <= 0;
        for (int i = 0; i < win; i++) begin
            dout <= dout + mem[i];
        end
    end
}

