module bcd(
    input wire clk,
    input wire clr,
    input wire ce,
    output wire [3:0] q
);

    // Internal registers
    reg [3:0] dint;
    reg [3:0] qreg;

    // Sequential logic
    always @(posedge clk or posedge clr) begin
        if (clr) begin
            qreg <= 4'b0000; // Clear the counter
        end else if (ce) begin
            qreg <= dint; // Load the next count value
        end
    end

    // Combinational logic
    always @(*) begin
        if (dint == 4'b0101) begin
            dint <= 4'b0000; // Reset to 0 if the next count is 9
        end else begin
            dint <= dint + 1'b1; // Increment the count
        end
    end

    // Assign the output
    assign q = qreg;

endmodule

