module complexmulttrial (
    input [15:0] a_r,
    input [15:0] a_i,
    input [15:0] b_r,
    input [15:0] b_i,
    input [15:0] w_r,
    input [15:0] w_i,
    output [15:0] x_r,
    output [15:0] x_i,
    output [15:0] y_r,
    output [15:0] y_i
);

    // Intermediate variables to handle larger intermediate values
    wire [31:0] temp1;
    wire [31:0] temp2;
    wire [31:0] temp3;
    wire [31:0] temp4;
    wire [31:0] temp5;
    wire [31:0] temp6;
    wire [31:0] temp7;
    wire [31:0] temp8;
    wire [31:0] temp9;
    wire [31:0] temp10;
    wire [31:0] temp11;
    wire [31:0] temp12;
    wire [31:0] temp13;
    wire [31:0] temp14;
    wire [31:0] temp15;
    wire [31:0] temp16;
    wire [31:0] temp17;
    wire [31:0] temp18;
    wire [31:0] temp19;
    wire [31:0] temp20;
    wire [31:0] temp21;
    wire [31:0] temp22;
    wire [31:0] temp23;
    wire [31:0] temp24;
    wire [31:0] temp25;
    wire [31:0] temp26;
    wire [31:0] temp27;
    wire [31:0] temp28;
    wire [31:0] temp29;
    wire [31:0] temp30;
    wire [31:0] temp31;

    // Addition of two complex numbers
    temp1 = a_r + b_r;
    temp2 = a_i + b_i;

    // Multiplication of two complex numbers
    temp3 = a_r * b_r - a_i * b_i;
    temp4 = a_r * b_i + a_i * b_r;

    // Subtraction of two complex numbers
    temp5 = a_r - b_r;
    temp6 = a_i - b_i;

    // Multiplication of the result of subtraction with another complex number
    temp7 = temp5 * w_r - temp6 * w_i;
    temp8 = temp5 * w_i + temp6 * w_r;

    // Final outputs
    x_r = temp1;
    x_i = temp2;
    y_r = temp7;
    y_i = temp8;

endmodule

module Control (
    input wire clk,
    input wire rst,
    input [7:0] in3, in2, in1, in0,
    output reg [3:0] anodo,
    output reg [7:0] catodo
);

    // Local parameter for the size of the internal counter register
    localparam N = 18;

    // Internal counter register
    reg [N-1:0] q_reg;

    // Counter increment logic
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            q_reg <= 0;
        end else begin
            q_reg <= q_reg + 1;
        end
    end

    // Determine which input signal to display based on the counter's top two bits
    reg [1:0] display_signal;
    assign display_signal = q_reg[17:16];

    // Determine which segments to activate based on the counter's top two bits
    reg [3:0] segment_select;
    assign segment_select = q_reg[15:12];

    // Map the display signal to the appropriate input port
    reg [7:0] current_input;
    always @(display_signal) begin
        case (display_signal)
            2'b00: current_input = in0;
            2'b01: current_input = in1;
            2'b10: current_input = in2;
            2'b11: current_input = in3;
            default: current_input = 8'b00000000; // Default to all segments off
        endcase
    end

    // Map the segment select to the appropriate segment
    reg [7:0] segment_data;
    always @(segment_select) begin
        case (segment_select)
            4'b0000: segment_data = 8'b00000000; // All segments off
            4'b0001: segment_data = 8'b11111110; // Segment A
            4'b0010: segment_data = 8'b11000001; // Segment B
            4'b0011: segment_data = 8'b11100000; // Segment C
            4'b0100: segment_data = 8'b01110000; // Segment D
            4'b0101: segment_data = 8'b10110000; // Segment E
            4'b0110: segment_data = 8'b10111000; // Segment F
            4'b0111: segment_data = 8'b11111000; // Segment G
            4'b1000: segment_data = 8'b11110000; // Segment DP
            default: segment_data = 8'b00000000; // Default to all segments off
        endcase
    end

    // Assign the output signals
    assign anodo = segment_select;
    assign catodo = segment_data;

endmodule

