module uart_send(
  input sys_clk,
  input sys_rst_n,
  input uart_en,
  input [7:0] uart_din,
  output reg uart_txd
);

  // Constants
  parameter CLK_FREQ = 100000000; // System clock frequency in Hz
  parameter UART_BPS = 9600;     // Desired baud rate in bits per second
  parameter BPS_CNT = CLK_FREQ / UART_BPS; // Number of clock cycles per bit

  // Registers
  reg [7:0] tx_data; // Data to be transmitted
  reg tx_flag;      // Flag to indicate data transmission
  reg [15:0] clk_cnt; // Clock cycle counter
  reg [3:0] tx_cnt;  // Data bit counter

  // State machine
  typedef enum logic [3:0] {
    IDLE,
    START_BIT,
    DATA_BITS,
    STOP_BIT
  } state_t;
  state_t state;

  // Reset logic
  always @(posedge sys_clk or negedge sys_rst_n) begin
    if (!sys_rst_n) begin
      tx_data <= 8'b0;
      tx_flag <= 1'b0;
      clk_cnt <= 16'b0;
      tx_cnt <= 4'b0;
      state <= IDLE;
    end else begin
      if (uart_en) begin
        tx_data <= uart_din;
        tx_flag <= 1'b1;
        clk_cnt <= 16'b0;
        tx_cnt <= 4'b0;
        state <= START_BIT;
      end
    end
  end

  // State machine process
  always @(posedge sys_clk) begin
    if (tx_flag) begin
      case (state)
        IDLE: begin
          if (clk_cnt == BPS_CNT) begin
            clk_cnt <= 16'b0;
            tx_cnt <= 4'b0;
            state <= START_BIT;
          end
        end
        START_BIT: begin
          if (clk_cnt == BPS_CNT) begin
            clk_cnt <= 16'b0;
            tx_cnt <= 4'b0;
            state <= DATA_BITS;
          end
        end
        DATA_BITS: begin
          if (tx_cnt == 8) begin
            tx_cnt <= 4'b0;
            state <= STOP_BIT;
          end else begin
            if (clk_cnt == BPS_CNT) begin
              clk_cnt <= 16'b0;
              tx_cnt <= tx_cnt + 1'b1;
              uart_txd <= tx_data[tx_cnt];
            end
          end
        end
        STOP_BIT: begin
          if (clk_cnt == BPS_CNT) begin
            clk_cnt <= 16'b0;
            tx_cnt <= 4'b0;
            state <= IDLE;
          end
        end
      endcase
    end
  end

endmodule

