module shift #(
    parameter DATA_WIDTH = 16,
    parameter DATA_TYPE = "unsigned", 
    parameter SHIFT_VALUE = 1,      
    parameter ASYNC = 0,             
    parameter OVERFLOW_WARNING = 1
) (
    input wire clk,
    input wire [DATA_WIDTH-1:0] din,

    output wire [DATA_WIDTH-1:0] dout,
    output wire [1:0] warning
);

// Define the data type as unsigned or signed
typedef logic [DATA_WIDTH-1:0] data_t;

// Declare variables
data_t shifted_data;
data_t max_value;
data_t min_value;
data_t overflow_flag;

// Generate block to handle different data types and shift directions
generate
    if (DATA_TYPE == "unsigned") begin
        // Calculate the maximum and minimum values for unsigned data
        max_value = (1 << DATA_WIDTH) - 1;
        min_value = 0;

        // Combinational logic for unsigned data
        if (ASYNC == 0) begin
            // Synchronous mode
            always @(posedge clk) begin
                shifted_data = din << SHIFT_VALUE;
                overflow_flag = (shifted_data > max_value) || (shifted_data < min_value);
                dout = shifted_data;
                warning = {overflow_flag, 0};
            end
        end else begin
            // Asynchronous mode
            assign shifted_data = din << SHIFT_VALUE;
            assign overflow_flag = (shifted_data > max_value) || (shifted_data < min_value);
            assign dout = shifted_data;
            assign warning = {overflow_flag, 0};
        end
    end else if (DATA_TYPE == "signed") begin
        // Calculate the maximum and minimum values for signed data
        max_value = (1 << (DATA_WIDTH - 1)) - 1;
        min_value = -(1 << (DATA_WIDTH - 1));

        // Combinational logic for signed data
        if (ASYNC == 0) begin
            // Synchronous mode
            always @(posedge clk) begin
                shifted_data = din << SHIFT_VALUE;
                overflow_flag = (shifted_data > max_value) || (shifted_data < min_value);
                dout = shifted_data;
                warning = {overflow_flag, 0};
            end
        end else begin
            // Asynchronous mode
            assign shifted_data = din << SHIFT_VALUE;
            assign overflow_flag = (shifted_data > max_value) || (shifted_data < min_value);
            assign dout = shifted_data;
            assign warning = {overflow_flag, 0};
        end
    end else begin
        // Handle unsupported data type
        $error("Unsupported data type: %s", DATA_TYPE);
    end
endgenerate

endmodule

