module alu_32 (
  input wire [WORD_SIZE-1:0] input_a,
  input wire [WORD_SIZE-1:0] input_b,
  input wire [CONTROL_SIGNAL_SIZE-1:0] control,
  output wire zero,
  output reg cout,
  output reg err_overflow,
  output reg err_invalid_control,
  output reg [WORD_SIZE-1:0] result
);

parameter WORD_SIZE = 32;
parameter CONTROL_SIGNAL_SIZE = 4;

always @(*) begin
  case (control)
    AND: begin
      result = input_a & input_b;
      zero = (result == 0);
      cout = 0;
      err_overflow = 0;
      err_invalid_control = 0;
    end
    OR: begin
      result = input_a | input_b;
      zero = (result == 0);
      cout = 0;
      err_overflow = 0;
      err_invalid_control = 0;
    end
    ADD: begin
      result = input_a + input_b;
      zero = (result == 0);
      cout = result[WORD_SIZE-1];
      err_overflow = (result[WORD_SIZE-1] != input_a[WORD_SIZE-1] && result[WORD_SIZE-1] != input_b[WORD_SIZE-1]);
      err_invalid_control = 0;
    end
    ADD_UNSIGNED: begin
      result = input_a + input_b;
      zero = (result == 0);
      cout = result[WORD_SIZE-1];
      err_overflow = 0;
      err_invalid_control = 0;
    end
    SUB: begin
      result = input_a - input_b;
      zero = (result == 0);
      cout = result[WORD_SIZE-1];
      err_overflow = (result[WORD_SIZE-1] != input_a[WORD_SIZE-1] && result[WORD_SIZE-1] != input_b[WORD_SIZE-1]);
      err_invalid_control = 0;
    end
    SLT: begin
      result = (input_a < input_b) ? 1'b1 : 1'b0;
      zero = (result == 0);
      cout = 0;
      err_overflow = 0;
      err_invalid_control = 0;
    end
    NOR: begin
      result = ~(input_a | input_b);
      zero = (result == 0);
      cout = 0;
      err_overflow = 0;
      err_invalid_control = 0;
    end
    default: begin
      result = 0;
      zero = 0;
      cout = 0;
      err_overflow = 1'b1;
      err_invalid_control = 1'b1;
    end
  endcase
end

endmodule

