	always @(posedge rdclk) begin
		if (rdreq && !rdempty) begin
			q <= fifo_data[rd_ptr];
			rd_ptr <= (rd_ptr + 1) % 64;
			fifo_depth <= (fifo_depth - 1) % 64;
		end
	end

