module mash(
    input wire [63:0] din,
    output wire [31:0] dout
);

    // Internal wires to store even and odd bits
    wire [31:0] even_bits;
    wire [31:0] odd_bits;

    // Generate loop to split the input into even and odd bits
    generate
        for (genvar i = 0; i < 32; i++) begin
            even_bits[i] = din[2*i];
            odd_bits[i] = din[2*i + 1];
        end
    endgenerate

    // Combine even and odd bits using a bitwise OR operation
    assign dout = even_bits | odd_bits;

endmodule

module mylfsr2(
    input wire [7:0] starting,
    output wire [7:0] lfsr2_out,
    input wire clk,
    input wire rst,
    input wire en
);

    // Internal signal to hold the current state of the LFSR
    reg [7:0] lfsr2_state;

    // Feedback polynomial: x^8 + x^4 + x^3 + x^2 + 1
    // This corresponds to the polynomial x^8 + x^4 + x^3 + x^2 + 1
    // which is a common choice for LFSRs
    // The feedback is applied to the MSB and the 4th bit from the right
    // This is a simple example and can be adjusted based on specific requirements

    // Reset the LFSR when the reset signal is low
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            lfsr2_state <= starting;
        end else if (en) begin
            // Apply feedback logic
            lfsr2_state <= {lfsr2_state[6:0], lfsr2_state[7] ^ lfsr2_state[4]};
        end
    end

    // Output the current state of the LFSR
    assign lfsr2_out = lfsr2_state;

endmodule

