module axi_bram_reader #
(
  parameter integer AXI_DATA_WIDTH = 32,
  parameter integer AXI_ADDR_WIDTH = 16,
  parameter integer BRAM_DATA_WIDTH = 32,
  parameter integer BRAM_ADDR_WIDTH = 10
)
(
  input  wire                       aclk,
  input  wire                       aresetn,

  input  wire [AXI_ADDR_WIDTH-1:0]  s_axi_awaddr,  
  input  wire                       s_axi_awvalid, 
  output wire                       s_axi_awready, 
  input  wire [AXI_DATA_WIDTH-1:0]  s_axi_wdata,   
  input  wire                       s_axi_wvalid,  
  output wire                       s_axi_wready,  
  output wire [1:0]                 s_axi_bresp,   
  output wire                       s_axi_bvalid,  
  input  wire                       s_axi_bready,  
  input  wire [AXI_ADDR_WIDTH-1:0]  s_axi_araddr,  
  input  wire                       s_axi_arvalid, 
  output wire                       s_axi_arready, 
  output wire [AXI_DATA_WIDTH-1:0]  s_axi_rdata,   
  output wire [1:0]                 s_axi_rresp,   
  output wire                       s_axi_rvalid,  
  input  wire                       s_axi_rready,  

  output wire                       bram_porta_clk,
  output wire                       bram_porta_rst,
  output wire [BRAM_ADDR_WIDTH-1:0] bram_porta_addr,
  input  wire [BRAM_DATA_WIDTH-1:0] bram_porta_rddata
)
{
  // Internal signals
  reg [AXI_ADDR_WIDTH-1:0] axi_read_addr;
  reg axi_read_valid;
  reg axi_read_ready;
  reg [AXI_DATA_WIDTH-1:0] axi_read_data;
  reg [1:0] axi_read_resp;
  reg axi_read_valid_out;
  reg axi_read_ready_out;
  reg [AXI_DATA_WIDTH-1:0] axi_read_data_out;
  reg [1:0] axi_read_resp_out;

  // AXI read request handling
  always @(posedge aclk or negedge aresetn) begin
    if (aresetn == 1'b0) begin
      axi_read_addr <= 0;
      axi_read_valid <= 0;
      axi_read_ready <= 0;
      axi_read_data <= 0;
      axi_read_resp <= 2'b0;
      axi_read_valid_out <= 0;
      axi_read_ready_out <= 0;
      axi_read_data_out <= 0;
      axi_read_resp_out <= 2'b0;
    end else begin
      axi_read_addr <= s_axi_araddr;
      axi_read_valid <= s_axi_arvalid;
      axi_read_ready <= s_axi_arready;
      axi_read_data <= 0;
      axi_read_resp <= 2'b0;
      axi_read_valid_out <= axi_read_valid && axi_read_ready;
      axi_read_ready_out <= axi_read_valid;
      axi_read_data_out <= axi_read_data;
      axi_read_resp_out <= axi_read_resp;
    end
  end

  // BRAM address conversion and timing alignment
  reg [BRAM_ADDR_WIDTH-1:0] bram_addr;
  always @(posedge aclk or negedge aresetn) begin
    if (aresetn == 1'b0) begin
      bram_addr <= 0;
    end else begin
      bram_addr <= axi_read_addr[BRAM_ADDR_WIDTH-1:0];
    end
  end

  // BRAM interface
  assign bram_porta_clk = aclk;
  assign bram_porta_rst = ~aresetn;
  assign bram_porta_addr = bram_addr;
  assign s_axi_rdata = axi_read_data_out;
  assign s_axi_rresp = axi_read_resp_out;
  assign s_axi_rvalid = axi_read_valid_out;
  assign s_axi_rready = s_axi_rready;

  // AXI write channel is inactive
  assign s_axi_awready = 1'b0;
  assign s_axi_wready = 1'b0;
  assign s_axi_bvalid = 1'b0;
  assign s_axi_bresp = 2'b0;
}

module sky130_fd_sc_hd__or4bb (
    X  ,
    A  ,
    B  ,
    C_N,
    D_N
);

    output X  ;
    input  A  ;
    input  B  ;
    input  C_N;
    input  D_N;

    wire nand0_out;
    wire or0_out_X;

    // NAND gate: C_N AND D_N
    nand #(.N(1)) nand0 (
        .A(C_N),
        .B(D_N),
        .Y(nand0_out)
    );

    // OR gate: A OR B OR nand0_out
    or #(.N(1)) or0 (
        .A(A),
        .B(B),
        .C(nand0_out),
        .Y(or0_out_X)
    );

    // Buffer: or0_out_X to X
    buf #(.N(1)) buf (
        .I(or0_out_X),
        .O(X)
    );

endmodule

