module pwm#(
    parameter WAVE_WEIGHT = 1024,
    parameter WAVE_LEN_WIDTH = 11
)(
    input wire clk,
    input wire reset,

    input wire update,
    input wire [WAVE_LEN_WIDTH-1:0] wave_length,
    input wire [WAVE_LEN_WIDTH-1:0] pulse_width,
    input wire active_high,

    output wire [WAVE_LEN_WIDTH-1:0] wave_length_out,
    output wire [WAVE_LEN_WIDTH-1:0] pulse_width_out,
    output wire active_high_out,

    input wire enable,
    output wire pwm_out
);

    // Internal registers to store the current parameters
    reg [WAVE_LEN_WIDTH-1:0] current_wave_length;
    reg [WAVE_LEN_WIDTH-1:0] current_pulse_width;
    reg active_high_reg;

    // Internal counters
    reg [WAVE_LEN_WIDTH-1:0] weight_counter;
    reg [WAVE_LEN_WIDTH-1:0] wave_length_counter;

    // Reset logic
    always @(posedge reset) begin
        current_wave_length <= 0;
        current_pulse_width <= 0;
        active_high_reg <= 0;
        weight_counter <= 0;
        wave_length_counter <= 0;
    end

    // Update logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_wave_length <= 0;
            current_pulse_width <= 0;
            active_high_reg <= 0;
            weight_counter <= 0;
            wave_length_counter <= 0;
        end else if (update) begin
            current_wave_length <= wave_length;
            current_pulse_width <= pulse_width;
            active_high_reg <= active_high;
        end
    end

    // PWM generation logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            weight_counter <= 0;
            wave_length_counter <= 0;
        end else if (enable) begin
            weight_counter <= weight_counter + 1;
            wave_length_counter <= wave_length_counter + 1;

            if (weight_counter == current_pulse_width) begin
                weight_counter <= 0;
                if (wave_length_counter == current_wave_length) begin
                    wave_length_counter <= 0;
                end else begin
                    wave_length_counter <= wave_length_counter + 1;
                end
            end

            pwm_out <= (active_high_reg && (weight_counter < current_pulse_width)) || (!active_high_reg && (weight_counter >= current_pulse_width));
        end
    end

    // Output assignments
    assign wave_length_out = current_wave_length;
    assign pulse_width_out = current_pulse_width;
    assign active_high_out = active_high_reg;

endmodule

module scan_hex_led_disp(
    input clk, reset,
    input [3:0] hex3, hex2, hex1, hex0,
    input [3:0] dp,
    output reg[3:0] en, 
    output reg[7:0] sseg
    );

    // Internal counter to cycle through digits
    reg [3:0] digit_counter;

    // Register to hold the current digit
    reg [3:0] current_digit;

    // Register to hold the current segment pattern
    reg [7:0] current_sseg;

    // Register to hold the current decimal point state
    reg [3:0] current_dp;

    // State machine for digit selection
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            digit_counter <= 0;
            current_digit <= 0;
            current_sseg <= 0;
            current_dp <= 0;
        end else begin
            digit_counter <= digit_counter + 1;
            if (digit_counter == 4) begin
                digit_counter <= 0;
            end
            current_digit <= digit_counter;
        end
    end

    // Combinational logic to map hex values to segment patterns
    always @(*) begin
        case (current_digit)
            0: begin
                current_sseg = 8'h3F; // 0
                current_dp = dp[0];
            end
            1: begin
                current_sseg = 8'h06; // 1
                current_dp = dp[1];
            end
            2: begin
                current_sseg = 8'h5B; // 2
                current_dp = dp[2];
            end
            3: begin
                current_sseg = 8'h4F; // 3
                current_dp = dp[3];
            end
            4: begin
                current_sseg = 8'h66; // 4
                current_dp = dp[0];
            end
            5: begin
                current_sseg = 8'h6D; // 5
                current_dp = dp[1];
            end
            6: begin
                current_sseg = 8'h7D; // 6
                current_dp = dp[2];
            end
            7: begin
                current_sseg = 8'h07; // 7
                current_dp = dp[3];
            end
            8: begin
                current_sseg = 8'h7F; // 8
                current_dp = dp[0];
            end
            9: begin
                current_sseg = 8'h6F; // 9
                current_dp = dp[1];
            end
            default: begin
                current_sseg = 8'h00; // 0
                current_dp = dp[0];
            end
        endcase
    end

    // Assign outputs based on current digit
    assign en = (current_digit == digit_counter);
    assign sseg = current_sseg;

endmodule

