);

    // Define rotation patterns
    localparam R0 = 16; // Rotation for o0
    localparam R1 = 32; // Rotation for o1
    localparam R2 = 48; // Rotation for o2
    localparam R3 = 64; // Rotation for o3
    localparam R4 = 80; // Rotation for o4

    // Compute o0
    assign o0 = x0 ^ (x1 << R0) ^ (x2 >> R1) ^ (x3 << R2) ^ (x4 >> R3);

    // Compute o1
    assign o1 = x1 ^ (x2 << R1) ^ (x3 >> R2) ^ (x4 << R3) ^ (x0 >> R4);

    // Compute o2
    assign o2 = x2 ^ (x3 << R2) ^ (x4 >> R3) ^ (x0 << R4) ^ (x1 >> R0);

    // Compute o3
    assign o3 = x3 ^ (x4 << R3) ^ (x0 << R4) ^ (x1 >> R0) ^ (x2 >> R1);

    // Compute o4
    assign o4 = x4 ^ (x0 << R4) ^ (x1 >> R0) ^ (x2 >> R1) ^ (x3 >> R2);

endmodule

module Barrel15L_16(
    input [13:0] data_i,
    input [1:0] shift_i,
    output reg [16:0] data_o
    );

    // Sign-extend the input data to 17 bits
    wire [16:0] tmp;
    assign tmp = {data_i[13], data_i[13:0]};

    // Combinational logic to shift the data based on the shift control
    always @(*) begin
        case (shift_i)
            2'b00: data_o = tmp;
            2'b01: data_o = tmp << 1;
            2'b10: data_o = tmp << 2;
            2'b11: data_o = tmp << 3;
            default: data_o = tmp; // Default case to handle invalid shift values
        endcase
    end

endmodule

module Data_Memory(
    input clk,
    input rst,
    input MemWrite,
    input MemRead,
    input [31:0] addr,
    input [31:0] write_data,
    output [31:0] read_data
);

    // Memory array with 32 registers, each holding 32 bits
    reg [31:0] memory [0:31];

    // Initial block to set all registers to zero on power-up
    initial begin
        for (int i = 0; i < 32; i++) begin
            memory[i] = 32'b0;
        end
    end

    // Always block to handle write operations
    always @(posedge clk) begin
        if (MemWrite) begin
            memory[addr] = write_data;
        end
    end

    // Combinational block to handle read operations
    assign read_data = MemRead ? memory[addr] : 32'b0;

endmodule

module binary_updown_counter #(parameter BITS = 1)
        (input wire clk, input wire rst, input wire ena,
         input wire updown, output wire [BITS - 1:0] out, output wire ovf);

    // Internal register to store the current count
    reg [BITS - 1:0] cnt;

    // Generate statement to create logic for each bit
    generate
        for (genvar i = 0; i < BITS; i = i + 1) begin
            // Wire to propagate the enable signal through each bit
            wire enable_wires;

            // Control logic for each bit
            always @(posedge clk or posedge rst) begin
                if (rst) begin
                    // Initialize the counter to zero on reset
                    cnt <= 0;
                end else if (ena) begin
                    // Update the count based on the direction control
                    if (updown) begin
                        // Increment the count
                        cnt <= cnt + 1;
                    end else begin
                        // Decrement the count
                        cnt <= cnt - 1;
                    end
                end
            end

            // Propagate the enable signal through each bit
            assign enable_wires = ena;
        end
    endgenerate

    // Output the current count
    assign out = cnt;

    // Detect overflow and output the overflow indication
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            // Initialize the overflow flag to zero on reset
            ovf <= 0;
        end else if (cnt == (2**BITS - 1) || cnt == 0) begin
            // Set the overflow flag when the count wraps around
            ovf <= 1;
        end else begin
            // Clear the overflow flag otherwise
            ovf <= 0;
        end
    end

endmodule

module BCD (
    input [15:0] binary,
    output wire [3:0] b,
    output wire [3:0] s,
    output wire [3:0] g,
    output wire [3:0] q
);

    reg [31:0] register;

    // Initialize the register with the binary input
    always @(*) begin
        register = binary;
    end

    // Repeat loop to process each nibble
    for (int i = 0; i < 16; i++) begin
        // Extract the current nibble
        reg [3:0] nibble = register[31:28];

        // Adjust the nibble to ensure BCD compliance
        if (nibble > 4) begin
            nibble = nibble + 3;
        end

        // Shift the register right
        register = {register[27:0], nibble};

        // Assign the processed nibble to the output ports
        case (i)
            0: b = nibble;
            1: s = nibble;
            2: g = nibble;
            3: q = nibble;
        endcase
    end

endmodule

module risc_v_32_mem(m_addr, d_f_mem, inst_decode, mem_out);
    input  [31:0] m_addr;                                    
    input  [31:0] d_f_mem;                                   
    input  [36:0] inst_decode;								 
    output reg [31:0] mem_out;

    // Extract the relevant bits from the instruction decode
    wire i_lw = inst_decode[36];
    wire i_lbu = inst_decode[35];
    wire i_lb = inst_decode[34];
    wire i_lhu = inst_decode[33];
    wire i_lh = inst_decode[32];

    // Calculate the aligned address
    wire [31:0] aligned_addr;
    assign aligned_addr = m_addr & ~3; // Align to 4-byte boundary

    // Determine the data to be loaded based on the instruction decode
    always_comb begin
        case ({i_lw, i_lbu, i_lb, i_lhu, i_lh})
            5'b00000: mem_out = d_f_mem[31:0]; // Load word
            5'b00001: mem_out = d_f_mem[31:24]; // Load byte with sign extension
            5'b00010: mem_out = d_f_mem[31:24]; // Load byte without sign extension
            5'b00011: mem_out = d_f_mem[31:16]; // Load half-word with sign extension
            5'b00100: mem_out = d_f_mem[31:16]; // Load half-word without sign extension
            default: mem_out = 32'h0; // Default to zero if invalid instruction
        endcase
    end

endmodule

