module Divider #(parameter Time=20)
(
    input I_CLK,
    output reg O_CLK
)
{
    reg [15:0] counter;

    always @(posedge I_CLK)
    begin
        if (counter < (Time - 1))
        begin
            counter <= counter + 1;
        end
        else
        begin
            counter <= 0;
            O_CLK <= ~O_CLK;
        end
    end

    initial
    begin
        O_CLK <= 0;
    end
}

module expression_00584(
    input [3:0] a0,
    input [4:0] a1,
    input [5:0] a2,
    input signed [3:0] a3,
    input signed [4:0] a4,
    input signed [5:0] a5,
    input [3:0] b0,
    input [4:0] b1,
    input [5:0] b2,
    input signed [3:0] b3,
    input signed [4:0] b4,
    input signed [5:0] b5,
    output [89:0] y
);

    // Local parameters
    localparam p0 = 1;
    localparam p1 = 2;
    localparam p2 = 3;
    localparam p3 = 4;
    localparam p4 = 5;
    localparam p5 = 6;
    localparam p6 = 7;
    localparam p7 = 8;
    localparam p8 = 9;
    localparam p9 = 10;
    localparam p10 = 11;
    localparam p11 = 12;
    localparam p12 = 13;
    localparam p13 = 14;
    localparam p14 = 15;
    localparam p15 = 16;
    localparam p16 = 17;
    localparam p17 = 18;

    // Intermediate results
    wire [17:0] y0;
    wire [17:0] y1;
    wire [17:0] y2;
    wire [17:0] y3;
    wire [17:0] y4;
    wire [17:0] y5;
    wire [17:0] y6;
    wire [17:0] y7;
    wire [17:0] y8;
    wire [17:0] y9;
    wire [17:0] y10;
    wire [17:0] y11;
    wire [17:0] y12;
    wire [17:0] y13;
    wire [17:0] y14;
    wire [17:0] y15;
    wire [17:0] y16;
    wire [17:0] y17;

    // Compute intermediate results
    y0 = (a0 & b0) + (a1 & b1) + (a2 & b2) + (a3 & b3) + (a4 & b4) + (a5 & b5);
    y1 = (a0 | b0) + (a1 | b1) + (a2 | b2) + (a3 | b3) + (a4 | b4) + (a5 | b5);
    y2 = (a0 ^ b0) + (a1 ^ b1) + (a2 ^ b2) + (a3 ^ b3) + (a4 ^ b4) + (a5 ^ b5);
    y3 = (a0 << 1) + (a1 << 1) + (a2 << 1) + (a3 << 1) + (a4 << 1) + (a5 << 1);
    y4 = (a0 >> 1) + (a1 >> 1) + (a2 >> 1) + (a3 >> 1) + (a4 >> 1) + (a5 >> 1);
    y5 = (a0 + b0) + (a1 + b1) + (a2 + b2) + (a3 + b3) + (a4 + b4) + (a5 + b5);
    y6 = (a0 - b0) + (a1 - b1) + (a2 - b2) + (a3 - b3) + (a4 - b4) + (a5 - b5);
    y7 = (a0 * b0) + (a1 * b1) + (a2 * b2) + (a3 * b3) + (a4 * b4) + (a5 * b5);
    y8 = (a0 / b0) + (a1 / b1) + (a2 / b2) + (a3 / b3) + (a4 / b4) + (a5 / b5);
    y9 = (a0 % b0) + (a1 % b1) + (a2 % b2) + (a3 % b3) + (a4 % b4) + (a5 % b5);
    y10 = (a0 & ~b0) + (a1 & ~b1) + (a2 & ~b2) + (a3 & ~b3) + (a4 & ~b4) + (a5 & ~b5);
    y11 = (a0 | ~b0) + (a1 | ~b1) + (a2 | ~b2) + (a3 | ~b3) + (a4 | ~b4) + (a5 | ~b5);
    y12 = (a0 ^ ~b0) + (a1 ^ ~b1) + (a2 ^ ~b2) + (a3 ^ ~b3) + (a4 ^ ~b4) + (a5 ^ ~b5);
    y13 = (a0 << 2) + (a1 << 2) + (a2 << 2) + (a3 << 2) + (a4 << 2) + (a5 << 2);
    y14 = (a0 >> 2) + (a1 >> 2) + (a2 >> 2) + (a3 >> 2) + (a4 >> 2) + (a5 >> 2);
    y15 = (a0 + ~b0) + (a1 + ~b1) + (a2 + ~b2) + (a3 + ~b3) + (a4 + ~b4) + (a5 + ~b5);
    y16 = (a0 - ~b0) + (a1 - ~b1) + (a2 - ~b2) + (a3 - ~b3) + (a4 - ~b4) + (a5 - ~b5);
    y17 = (a0 * ~b0) + (a1 * ~b1) + (a2 * ~b2) + (a3 * ~b3) + (a4 * ~b4) + (a5 * ~b5);

    // Concatenate intermediate results to form the final output
    assign y = {y17, y16, y15, y14, y13, y12, y11, y10, y9, y8, y7, y6, y5, y4, y3, y2, y1, y0};

endmodule

module peridot_ethio_cdb_signal (
	input wire			reset,
	input wire			clk,
	input wire			in_sig,
	output wire			out_sig,
	output wire			riseedge,
	output wire			falledge
);

reg [2:0] shift_reg;

always @(posedge clk or posedge reset) begin
	if (reset) begin
		shift_reg <= 3'b000;
		out_sig <= 1'b0;
		riseedge <= 1'b0;
		falledge <= 1'b0;
	end else begin
		shift_reg <= {in_sig, shift_reg[2:1]};
		out_sig <= shift_reg[2];
		riseedge <= (shift_reg[2] == 1'b1 && shift_reg[1] == 1'b0);
		falledge <= (shift_reg[2] == 1'b0 && shift_reg[1] == 1'b1);
	end
end

endmodule

module IB_ENDPOINT_OP_DONE_BUFFER(
    input wire CLK,
    input wire RESET,
    input wire [15:0] RD_COMPL_TAG,
    input wire RD_COMPL_START,
    input wire RD_COMPL_DONE,
    input wire [15:0] BM_TAG,
    input wire BM_DONE,
    output wire [15:0] OP_TAG,
    output wire OP_DONE
);

    // Internal registers
    reg [15:0] rd_compl_tag_reg;
    reg rd_compl_start_reg;
    reg rd_compl_done_reg;
    reg [15:0] bm_tag_reg;
    reg bm_done_reg;
    reg op_tag_reg;
    reg op_done_reg;

    // Reset logic
    always @(posedge RESET) begin
        rd_compl_tag_reg <= 16'h0;
        rd_compl_start_reg <= 1'b0;
        rd_compl_done_reg <= 1'b0;
        bm_tag_reg <= 16'h0;
        bm_done_reg <= 1'b0;
        op_tag_reg <= 16'h0;
        op_done_reg <= 1'b0;
    end

    // Combinational logic
    always @(posedge CLK or posedge RESET) begin
        if (RESET) begin
            rd_compl_tag_reg <= 16'h0;
            rd_compl_start_reg <= 1'b0;
            rd_compl_done_reg <= 1'b0;
            bm_tag_reg <= 16'h0;
            bm_done_reg <= 1'b0;
            op_tag_reg <= 16'h0;
            op_done_reg <= 1'b0;
        end else begin
            rd_compl_tag_reg <= RD_COMPL_TAG;
            rd_compl_start_reg <= RD_COMPL_START;
            rd_compl_done_reg <= RD_COMPL_DONE;
            bm_tag_reg <= BM_TAG;
            bm_done_reg <= BM_DONE;

            if (rd_compl_start_reg && !rd_compl_done_reg) begin
                op_tag_reg <= rd_compl_tag_reg;
                op_done_reg <= 1'b1;
            end else if (bm_done_reg) begin
                op_tag_reg <= bm_tag_reg;
                op_done_reg <= 1'b1;
            end else begin
                op_tag_reg <= 16'h0;
                op_done_reg <= 1'b0;
            end
        end
    end

    // Output signals
    assign OP_TAG = op_tag_reg;
    assign OP_DONE = op_done_reg;

