input  captnupdt;
output mainclk;
output updateclk;
output capture;
output update;

reg [1:0] temp_state;
reg [1:0] temp_updateclk;
reg [1:0] temp_capture;
reg [1:0] temp_update;

initial begin
    temp_state = 2'b00;
    temp_updateclk = 2'b00;
    temp_capture = 2'b00;
    temp_update = 2'b00;
end

always @(posedge clk or posedge captnupdt or posedge shiftnld) begin
    case ({captnupdt, shiftnld})
        2'b10: begin
            temp_updateclk = 2'b11;
            temp_capture = 2'b11;
        end
        2'b11: begin
            temp_updateclk = 2'b11;
            temp_capture = 2'b11;
        end
        2'b01: begin
            temp_updateclk = 2'b10;
            temp_capture = 2'b00;
        end
        default: begin
            temp_updateclk = 2'b00;
            temp_capture = 2'b00;
            temp_update = 2'b10;
        end
    endcase
end

assign mainclk = temp_state[0] ? clk : 1'b0;
assign updateclk = temp_updateclk[0] ? clk : 1'b0;
assign capture = temp_capture[0];
assign update = temp_update[0];

endmodule

module syn_gen
(
    input              I_pxl_clk   ,
    input              I_rst_n     ,
    input      [15:0]  I_h_total   ,
    input      [15:0]  I_h_sync    ,
    input      [15:0]  I_h_bporch  ,
    input      [15:0]  I_h_res     ,
    input      [15:0]  I_v_total   ,
    input      [15:0]  I_v_sync    ,
    input      [15:0]  I_v_bporch  ,
    input      [15:0]  I_v_res     ,
    input      [15:0]  I_rd_hres   ,
    input      [15:0]  I_rd_vres   ,
    input              I_hs_pol    ,
    input              I_vs_pol    ,
    output reg         O_rden      ,
    output reg         O_de        ,   
    output reg         O_hs        ,
    output reg         O_vs         
);

    // Internal counters
    reg [15:0] V_cnt;
    reg [15:0] H_cnt;

    // Intermediate signals
    reg Pout_de_w;
    reg Pout_hs_w;
    reg Pout_vs_w;
    reg Rden_w;

    // Reset the counters
    always @(posedge I_rst_n or negedge I_pxl_clk) begin
        if (!I_rst_n) begin
            V_cnt <= 0;
            H_cnt <= 0;
        end else begin
            if (I_pxl_clk) begin
                if (H_cnt == I_h_total - 1) begin
                    H_cnt <= 0;
                    if (V_cnt == I_v_total - 1) begin
                        V_cnt <= 0;
                    end else begin
                        V_cnt <= V_cnt + 1;
                    end
                end else begin
                    H_cnt <= H_cnt + 1;
                end
            end
        end
    end

    // Generate intermediate signals
    assign Pout_de_w = (H_cnt >= I_h_bporch) && (H_cnt < I_h_bporch + I_h_res);
    assign Pout_hs_w = (H_cnt == I_h_sync);
    assign Pout_vs_w = (V_cnt == I_v_sync);
    assign Rden_w = (H_cnt >= I_rd_hres) && (H_cnt < I_rd_hres + I_rd_vres);

    // Delay intermediate signals
    reg [15:0] Pout_de_d;
    reg [15:0] Pout_hs_d;
    reg [15:0] Pout_vs_d;
    reg [15:0] Rden_d;

    always @(posedge I_pxl_clk) begin
        Pout_de_d <= Pout_de_w;
        Pout_hs_d <= Pout_hs_w;
        Pout_vs_d <= Pout_vs_w;
        Rden_d <= Rden_w;
    end

    // Assign outputs with optional polarity inversion
    assign O_de = Pout_de_d;
    assign O_hs = (I_hs_pol) ? ~Pout_hs_d : Pout_hs_d;
    assign O_vs = (I_vs_pol) ? ~Pout_vs_d : Pout_vs_d;
    assign O_rden = Rden_d;

endmodule

