module pddm (
    input sdi,
    input signed_data,
    output [31:0] dout,
    input ock,
    input uck,
    input rstn,
    input clk
);

    // Internal signals
    reg [31:0] sigma;
    reg [31:0] undersampled_sigma;
    reg [31:0] delta;
    reg [31:0] deriv;
    reg [31:0] prev_sigma;

    // Reset
    always @(posedge rstn or negedge clk) begin
        if (!rstn) begin
            sigma <= 0;
            undersampled_sigma <= 0;
            delta <= 0;
            deriv <= 0;
            prev_sigma <= 0;
        end
    end

    // Phase accumulation
    always @(posedge clk) begin
        if (ock) begin
            if (sdi) begin
                sigma <= sigma + delta;
            end else begin
                sigma <= sigma - delta;
            end
        end
    end

    // Undersampling
    always @(posedge clk) begin
        if (uck) begin
            undersampled_sigma <= sigma;
        end
    end

    // Derivative calculation
    always @(posedge clk) begin
        if (clk) begin
            deriv <= sigma - prev_sigma;
            prev_sigma <= sigma;
        end
    end

    // Output generation
    always @(posedge clk) begin
        if (clk) begin
            if (signed_data) begin
                dout <= deriv;
            end else begin
                dout <= deriv;
            end
        end
    end

endmodule

