module clk_div(
    input clk,
    input rst,
    input SW2,
    input SW15,
    input keyReady,
    input [3:0] BTN_OK,
    output reg[31:0] clkdiv,
    output reg Clk_CPU,
    output reg readn
);

    // Parameters
    parameter AUTO_CLK_MODE = 24;
    parameter STEP_CLK_MODE = 4;
    parameter MAX_STEPS = 16; // Maximum number of steps for CPU clock

    // Internal registers
    reg [31:0] counter;
    reg [31:0] step;
    reg [31:0] auto_clk;
    reg wasReady;

    // Reset logic
    always @(posedge rst) begin
        counter <= 0;
        step <= 0;
        auto_clk <= 0;
        wasReady <= 0;
        Clk_CPU <= 0;
        readn <= 0;
    end

    // Clock divider logic
    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            step <= 0;
            auto_clk <= 0;
            wasReady <= 0;
            Clk_CPU <= 0;
            readn <= 0;
        end else begin
            if (keyReady && !wasReady) begin
                wasReady <= 1;
                counter <= 0;
                step <= 0;
                auto_clk <= 0;
                Clk_CPU <= 0;
                readn <= 0;
                if (BTN_OK[3]) begin
                    step <= MAX_STEPS;
                end else if (BTN_OK[2]) begin
                    step <= 8;
                end else if (BTN_OK[1]) begin
                    step <= 4;
                end else if (BTN_OK[0]) begin
                    step <= 2;
                end
            end else if (keyReady && wasReady) begin
                if (counter < step) begin
                    counter <= counter + 1;
                end else begin
                    counter <= 0;
                    wasReady <= 0;
                    if (SW2) begin
                        auto_clk <= auto_clk + 1;
                        if (auto_clk == 2**AUTO_CLK_MODE) begin
                            auto_clk <= 0;
                            Clk_CPU <= ~Clk_CPU;
                        end
                    end else begin
                        Clk_CPU <= ~Clk_CPU;
                    end
                end
            end else begin
                if (SW2) begin
                    auto_clk <= auto_clk + 1;
                    if (auto_clk == 2**AUTO_CLK_MODE) begin
                        auto_clk <= 0;
                        Clk_CPU <= ~Clk_CPU;
                    end
                end else begin
                    Clk_CPU <= ~Clk_CPU;
                end
            end
        end
    end

    // Output computation
    always @(posedge clk) begin
        if (rst) begin
            clkdiv <= 0;
        end else begin
            clkdiv <= counter;
        end
    end

    // Readn control
    always @(posedge clk) begin
        if (rst) begin
            readn <= 0;
        end else begin
            readn <= keyReady && !wasReady;
        end
    end

endmodule

