module processing_system7_v5_5_w_atc #
  (
   parameter         C_FAMILY                         = "rtl",

   parameter integer C_AXI_ID_WIDTH                   = 4,


   parameter integer C_AXI_DATA_WIDTH                 = 64,


   parameter integer C_AXI_WUSER_WIDTH                = 1


   )
  (

   input  wire                                  ARESET,
   input  wire                                  ACLK,


   input  wire                                  cmd_w_valid,
   input  wire                                  cmd_w_check,
   input  wire [C_AXI_ID_WIDTH-1:0]             cmd_w_id,
   output wire                                  cmd_w_ready,


   output wire                                  cmd_b_push,
   output wire                                  cmd_b_error,
   output reg  [C_AXI_ID_WIDTH-1:0]             cmd_b_id,
   input  wire                                  cmd_b_full,


   input  wire [C_AXI_ID_WIDTH-1:0]             S_AXI_WID,
   input  wire [C_AXI_DATA_WIDTH-1:0]           S_AXI_WDATA,
   input  wire [C_AXI_DATA_WIDTH/8-1:0]         S_AXI_WSTRB,
   input  wire                                  S_AXI_WLAST,
   input  wire [C_AXI_WUSER_WIDTH-1:0]          S_AXI_WUSER,
   input  wire                                  S_AXI_WVALID,
   output wire                                  S_AXI_WREADY,


   output wire [C_AXI_ID_WIDTH-1:0]             M_AXI_WID,
   output wire [C_AXI_DATA_WIDTH-1:0]           M_AXI_WDATA,
   output wire [C_AXI_DATA_WIDTH/8-1:0]         M_AXI_WSTRB,
   output wire                                  M_AXI_WLAST,
   output wire [C_AXI_WUSER_WIDTH-1:0]          M_AXI_WUSER,
   output wire                                  M_AXI_WVALID,
   input  wire                                  M_AXI_WREADY
   );

   // Internal registers
   reg [C_AXI_ID_WIDTH-1:0] cmd_w_id_reg;
   reg [C_AXI_DATA_WIDTH-1:0] cmd_w_data_reg;
   reg [C_AXI_DATA_WIDTH/8-1:0] cmd_w_strb_reg;
   reg cmd_w_last_reg;
   reg cmd_w_user_reg;
   reg cmd_w_valid_reg;
   reg cmd_w_check_reg;
   reg cmd_b_push_reg;
   reg cmd_b_error_reg;
   reg cmd_b_full_reg;

   // State machine
   enum {IDLE, CMD_VALID, CMD_CHECK, CMD_STROBE, CMD_DATA, CMD_LAST, CMD_USER, CMD_B} state;

   // Control signals
   wire cmd_w_ready_int;
   wire cmd_b_push_int;
   wire cmd_b_error_int;
   wire cmd_b_full_int;

   // AXI signals
   wire [C_AXI_ID_WIDTH-1:0] axi_wid;
   wire [C_AXI_DATA_WIDTH-1:0] axi_wdata;
   wire [C_AXI_DATA_WIDTH/8-1:0] axi_wstrb;
   wire axi_wlast;
   wire [C_AXI_WUSER_WIDTH-1:0] axi_wuser;
   wire axi_wvalid;
   wire axi_wready;

   // AXI interface
   assign axi_wid = cmd_w_id_reg;
   assign axi_wdata = cmd_w_data_reg;
   assign axi_wstrb = cmd_w_strb_reg;
   assign axi_wlast = cmd_w_last_reg;
   assign axi_wuser = cmd_w_user_reg;
   assign axi_wvalid = cmd_w_valid_reg;
   assign cmd_w_ready_int = axi_wready;

   // AXI interface
   assign M_AXI_WID = axi_wid;
   assign M_AXI_WDATA = axi_wdata;
   assign M_AXI_WSTRB = axi_wstrb;
   assign M_AXI_WLAST = axi_wlast;
   assign M_AXI_WUSER = axi_wuser;
   assign M_AXI_WVALID = axi_wvalid;
   assign S_AXI_WREADY = axi_wvalid;

   // State machine
   always @(posedge ACLK or posedge ARESET) begin
      if (ARESET) begin
         state <= IDLE;
         cmd_w_id_reg <= 0;
         cmd_w_data_reg <= 0;
         cmd_w_strb_reg <= 0;
         cmd_w_last_reg <= 0;
         cmd_w_user_reg <= 0;
         cmd_w_valid_reg <= 0;
         cmd_w_check_reg <= 0;
         cmd_b_push_reg <= 0;
         cmd_b_error_reg <= 0;
         cmd_b_full_reg <= 0;
      end else begin
         case (state)
            IDLE: begin
               if (cmd_w_valid && cmd_w_check) begin
                  state <= CMD_VALID;
               end
            end
            CMD_VALID: begin
               cmd_w_id_reg <= cmd_w_id;
               cmd_w_data_reg <= S_AXI_WDATA;
               cmd_w_strb_reg <= S_AXI_WSTRB;
               cmd_w_last_reg <= S_AXI_WLAST;
               cmd_w_user_reg <= S_AXI_WUSER;
               cmd_w_valid_reg <= 1;
               cmd_w_check_reg <= 0;
               state <= CMD_CHECK;
            end
            CMD_CHECK: begin
               if (cmd_w_check) begin
                  state <= CMD_STROBE;
               end else begin
                  state <= IDLE;
               end
            end
            CMD_STROBE: begin
               if (!S_AXI_WSTRB) begin
                  state <= CMD_DATA;
               end else begin
                  state <= CMD_STROBE;
               end
            end
            CMD_DATA: begin
               if (S_AXI_WSTRB) begin
                  state <= CMD_DATA;
               end else begin
                  state <= CMD_LAST;
               end
            end
            CMD_LAST: begin
               if (S_AXI_WLAST) begin
                  state <= CMD_USER;
               end else begin
                  state <= CMD_DATA;
               end
            end
            CMD_USER: begin
               if (S_AXI_WUSER) begin
                  state <= CMD_USER;
               end else begin
                  state <= CMD_B;
               end
            end
            CMD_B: begin
               cmd_b_push_reg <= 1;
               cmd_b_error_reg <= 0;
               cmd_b_full_reg <= 0;
               state <= IDLE;
            end
         endcase
      end
   end

   // AXI interface
   always @(posedge ACLK or posedge ARESET) begin
      if (ARESET) begin
         axi_wready <= 0;
      end else begin
         axi_wready <= cmd_w_ready_int;
      end
   end

   // AXI interface
   always @(posedge ACLK or posedge ARESET) begin
      if (ARESET) begin
         cmd_b_push <= 0;
         cmd_b_error <= 0;
         cmd_b_full <= 0;
      end else begin
         cmd_b_push <= cmd_b_push_reg;
         cmd_b_error <= cmd_b_error_reg;
         cmd_b_full <= cmd_b_full_reg;
      end
   end

endmodule

