module timer_stream_adapter_synchTime_2_fifo
#(
    parameter
        DATA_BITS  = 8,
        DEPTH_BITS = 4
)(
    input  wire                 clk,
    input  wire                 aclr,
    output wire                 empty_n,
    output wire                 full_n,
    input  wire                 read,
    input  wire                 write,
    output wire [DATA_BITS-1:0] dout,
    input  wire [DATA_BITS-1:0] din
);

    // Parameters
    localparam DEPTH = 1 << DEPTH_BITS;

    // Internal registers
    reg [DATA_BITS-1:0] mem[0:DEPTH-1];
    reg [DEPTH_BITS-1:0] index;
    reg empty;
    reg full;

    // Asynchronous reset
    always @(posedge clk or posedge aclr) begin
        if (aclr) begin
            empty <= 1'b1;
            full <= 1'b0;
            index <= 0;
        end else begin
            empty <= 1'b1;
            full <= 1'b0;
        end
    end

    // Sequential logic
    always @(posedge clk) begin
        if (aclr) begin
            empty <= 1'b1;
            full <= 1'b0;
            index <= 0;
        end else begin
            if (write && !full) begin
                mem[index] <= din;
                index <= index + 1'b1;
                if (index == DEPTH - 1) begin
                    index <= 0;
                end
                if (index == 0) begin
                    empty <= 1'b0;
                end
            end
            if (read && !empty) begin
                dout <= mem[index];
                index <= index + 1'b1;
                if (index == DEPTH - 1) begin
                    index <= 0;
                end
                if (index == 0) begin
                    empty <= 1'b1;
                end
            end
            if (write && read && !full && !empty) begin
                mem[index] <= din;
                index <= index + 1'b1;
                if (index == DEPTH - 1) begin
                    index <= 0;
                end
                if (index == 0) begin
                    empty <= 1'b0;
                end
            end
            if (full && !write) begin
                full <= 1'b1;
            end
            if (empty && !read) begin
                empty <= 1'b0;
            end
        end
    end

    // Output signals
    assign empty_n = ~empty;
    assign full_n = ~full;

endmodule

module debounce(
    input clk,
    input btn_input,
    output reg btn_output
);

    // Internal registers
    reg [31:0] timer;
    reg btn_pre;

    // Always block triggered on the positive edge of the clock
    always @(posedge clk) begin
        // Increment the timer
        timer <= timer + 1'b1;

        // Check if the timer has reached the maximum count
        if (timer == 1000000) begin
            // Compare the current button input with the previous state
            if (btn_input == btn_pre) begin
                // Update the debounced output with the current input
                btn_output <= btn_input;
            end
            // Reset the timer and update the previous input state
            timer <= 0;
            btn_pre <= btn_input;
        end
    end

endmodule

