module gray_Nbits #(
    parameter N = 4
) (
    input wire clk,
    input wire reset,
    input wire enable,
    output reg [N-1:0] gray_out
);

parameter SIZE = N + 1;
parameter Zeros = {SIZE{1'b0}};

reg [SIZE-1:0] state;
reg [N-1:0] toggle;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        state <= Zeros;
    end else if (enable) begin
        state <= state ^ toggle;
    end
end

always @(state) begin
    toggle[0] = 1'b1; // Always toggle the least significant bit
    for (int i = 1; i < N; i++) begin
        toggle[i] = state[i-1] ^ state[i];
    end
end

assign gray_out = state[N-1:1];

endmodule

