module BBFACosh(
    input  [63:0] in,
    output reg [63:0] out
);
    always @* begin
        // Convert the input bits to a real number
        real input_real = $bit2real(in);

        // Compute the hyperbolic cosine of the real number
        real result_real = acosh(input_real);

        // Convert the result back to bits
        out = $real2bit(result_real);
    end
