module Fibonacci_Series
(
    input wire CLK_IN,
    input wire RST_N,
    output wire [7:0]SEQUENCE
);

    // Internal registers to store the last two Fibonacci numbers
    reg [7:0] fib0;
    reg [7:0] fib1;

    // Register to store the current Fibonacci number
    reg [7:0] current_fib;

    // Register to store the end value of the Fibonacci sequence
    reg [7:0] end_value;

    // Reset the Fibonacci sequence
    always @(posedge RST_N) begin
        fib0 <= 0;
        fib1 <= 0;
        current_fib <= 0;
        end_value <= 0;
    end

    // Generate the Fibonacci sequence
    always @(posedge CLK_IN) begin
        if (!RST_N) begin
            // Initialize the sequence
            fib0 <= 0;
            fib1 <= 1;
            current_fib <= 0;
            end_value <= 0;
        end else begin
            // Update the Fibonacci sequence
            current_fib <= fib0 + fib1;
            fib0 <= fib1;
            fib1 <= current_fib;

            // Check if the current Fibonacci number is the end value
            if (current_fib == end_value) begin
                // Stop the sequence
                current_fib <= 0;
            end
        end
    end

    // Output the current Fibonacci number
    assign SEQUENCE = current_fib;

endmodule

