module ISOLORX1 (ISO, D, Q);

output  Q;
input   ISO, D;

// Define the functional macro to control timing details
`ifdef FUNCTIONAL
    // Functional model without timing details
    assign Q = ISO | D;
`else
    // Realistic model with timing details
    reg Q;

    // Internal signals to track input transitions
    reg ISO_prev, D_prev;

    // Assignments for the output based on input transitions
    always @(*) begin
        if (ISO != ISO_prev) begin
            if (ISO) begin
                Q <= 1'b1; // ISO goes high
                #47; // Delay for ISO going high
            end else begin
                Q <= 1'b0; // ISO goes low
                #59; // Delay for ISO going low
            end
        end else if (D != D_prev) begin
            if (D) begin
                Q <= 1'b1; // D goes high
                #47; // Delay for D going high
            end else begin
                Q <= 1'b0; // D goes low
                #50; // Delay for D going low
            end
        end else begin
            Q <= Q; // No change in input, no delay
        end
    end

    // Assign initial values to the internal signals
    initial begin
        ISO_prev = 1'b0;
        D_prev = 1'b0;
    end

    // Assign the current input values to the internal signals
    always @(ISO or D) begin
        ISO_prev = ISO;
        D_prev = D;
    end
`endif

endmodule

module adapter_rgb_2_ppfifo #(
  parameter                 DATA_WIDTH = 24
)(
  input                             clk,
  input                             rst,

  input         [23:0]              i_rgb,
  input                             i_h_sync,
  input                             i_h_blank,
  input                             i_v_sync,
  input                             i_v_blank,
  input                             i_data_en,


  output                            o_ppfifo_clk,
  input       [1:0]                 i_ppfifo_rdy,
  output  reg [1:0]                 o_ppfifo_act,
  input       [23:0]                i_ppfifo_size,
  output  reg                       o_ppfifo_stb,
  output  reg [DATA_WIDTH - 1:0]    o_ppfifo_data


);
  // Internal signals
  reg [23:0] r_count;
  reg [1:0] state;
  reg [1:0] fifo_ready;
  reg [1:0] fifo_active;
  reg [23:0] fifo_size;

  // State machine
  always @(posedge clk or posedge rst) begin
    if (rst) begin
      state <= IDLE;
      r_count <= 0;
      fifo_ready <= 0;
      fifo_active <= 0;
      fifo_size <= 0;
    end else begin
      case (state)
        IDLE: begin
          if (i_ppfifo_rdy == 2'b11) begin
            state <= READY;
            fifo_ready <= 1'b1;
          end
        end
        READY: begin
          if (i_h_blank == 1'b0 && i_data_en == 1'b1) begin
            if (r_count < i_ppfifo_size) begin
              o_ppfifo_stb <= 1'b1;
              o_ppfifo_data <= i_rgb;
              r_count <= r_count + 1'b1;
              fifo_active <= 1'b1;
            end else begin
              state <= RELEASE;
            end
          end else begin
            o_ppfifo_stb <= 1'b0;
            fifo_active <= 1'b0;
          end
        end
        RELEASE: begin
          if (i_v_blank == 1'b1) begin
            state <= IDLE;
            fifo_ready <= 1'b0;
            fifo_active <= 1'b0;
          end
        end
      endcase
    end
  end

  // Output signals
  assign o_ppfifo_clk = clk;
  assign o_ppfifo_act = fifo_active;
  assign o_ppfifo_size = fifo_size;
endmodule

