    output [4:0] grant
);

    // State register to track the current priority level
    reg [4:0] current_priority;

    // Reset the current priority to 0 on active-low reset
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            current_priority <= 5'b00000;
        end
    end

    // Combinational logic to determine the grant
    always @(*) begin
        grant = 5'b00000;
        for (int i = 0; i <= 4; i++) begin
            if (req[i] && (current_priority == i || current_priority == 5'b00000)) begin
                grant[i] = 1'b1;
                break;
            end
        end
    end

    // Synchronous logic to update the current priority
    always @(posedge clk) begin
        if (grant[0]) begin
            current_priority <= 5'b00001;
        end else if (grant[1]) begin
            current_priority <= 5'b00010;
        end else if (grant[2]) begin
            current_priority <= 5'b00100;
        end else if (grant[3]) begin
            current_priority <= 5'b01000;
        end else if (grant[4]) begin
            current_priority <= 5'b10000;
        end
    end

endmodule

module routing_buffer(
