module data_deal(
    input  clk,
    input  rst_n,
    input  [6:0] data_in,
    input  data_in_sign,

    output [6:0] data_out,
    output data_out_sign,
    input  data_valid,
    output data_ok
);

    reg [6:0] data_reg;
    reg [3:0] data_regnum;
    reg data_out_sign_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            data_reg <= 7'b0000000;
            data_regnum <= 4'b0000;
            data_out_sign_reg <= 1'b0;
            data_ok <= 1'b0;
        end else begin
            if (data_valid) begin
                if (data_in_sign) begin
                    data_reg <= data_reg + data_in;
                end else begin
                    data_reg <= data_reg - data_in;
                end
                data_regnum <= data_regnum + 1'b1;
            end

            if (data_regnum == 8) begin
                if (data_reg == 28 || data_reg == 36) begin
                    data_ok <= 1'b1;
                end else begin
                    data_ok <= 1'b0;
                end
            end else begin
                data_ok <= 1'b0;
            end

            if (data_valid) begin
                data_out_sign_reg <= 1'b1;
            end else begin
                data_out_sign_reg <= 1'b0;
            end

            if (data_out_sign_reg) begin
                data_out <= data_out + 1'b1;
            end else begin
                data_out <= 7'b0000000;
            end
        end
    end

endmodule

module counter #(
    parameter WIDTH = 8
) (
    input rstn,
    input clk,
    input up,
    input down,
    output reg [WIDTH-1:0] count
);

reg [WIDTH-1:0] count_int;

always @(posedge clk or negedge rstn) begin
    if (!rstn) begin
        count_int <= 0;
    end else begin
        if (up && down) begin
            // If both up and down are high, prioritize up
            count_int <= count_int + 1;
        end else if (up) begin
            count_int <= count_int + 1;
        end else if (down) begin
            count_int <= count_int - 1;
        end
    end
end

assign count = count_int;

endmodule

module clk_div(
