    always @(posedge clk_100MHz or posedge reset) begin
        if (reset) begin
            ticks <= 499999;
            clk_out <= 0;
        end else begin
            if (ticks == 0) begin
                clk_out <= ~clk_out;
                ticks <= 499999;
            end else begin
                ticks <= ticks - 1;
            end
        end
    end

    assign clk_100Hz = clk_out;

endmodule

module iiitb_freqdiv(
    input clkin,
    input [3:0] n,
    input en,
    output clkout
);

    // Define the maximum divisor value
    localparam MAX_DIVISOR = 15;

    // Define the counter width
    localparam COUNTER_WIDTH = 4;

    // Define the counter types
    reg [COUNTER_WIDTH-1:0] pc; // Rising-edge counter
    reg [COUNTER_WIDTH-1:0] nc; // Falling-edge counter

    // Reset logic
    always @(posedge en or negedge clkin) begin
        if (!en) begin
            pc <= 0;
            nc <= 0;
        end
    end

    // Rising-edge counter
    always @(posedge clkin) begin
        if (en) begin
            pc <= pc + 1;
        end
    end

    // Falling-edge counter
    always @(negedge clkin) begin
        if (en) begin
            nc <= nc + 1;
        end
    end

    // Determine the output clock based on the divisor
    always @(posedge clkin or negedge clkin) begin
        if (en) begin
            if (n % 2 == 0) begin
                // Even divisor
                clkout <= (pc >= n / 2) ? 1'b0 : 1'b1;
            end else begin
                // Odd divisor
                clkout <= (nc >= (n / 2) + 1) ? 1'b0 : 1'b1;
            end
        end else begin
            clkout <= 1'b0; // Disable output when not enabled
        end
    end

endmodule

