    parameter Divider = 100000;

    // Combinational logic to set Timeout
    always @(posedge Clock) begin
        if (MR) begin
            counter <= 0;
            Timeout <= 0;
        end else if (counter == Divider) begin
            Timeout <= 1;
        end else begin
            Timeout <= 0;
        end
    end

    // Sequential logic to control counter reset and increment
    always @(posedge Clock) begin
        if (MR) begin
            counter <= 0;
        end else if (counter < Divider) begin
            counter <= counter + 1;
        end
    end
endmodule

