module toe_m_axis_rx_data_rsp_metadata_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);

// Internal registers
reg [N-1:0] data_p1;
reg [N-1:0] data_p2;
reg load_p1;
reg load_p2;
reg load_p1_from_p2;

// State machine
typedef enum {ZERO, ONE, TWO} state_t;
state_t state;

// State machine logic
always @(posedge clk or posedge reset) begin
    if (reset) begin
        state <= ZERO;
        load_p1 <= 1'b0;
        load_p2 <= 1'b0;
        load_p1_from_p2 <= 1'b0;
    end else begin
        case (state)
            ZERO: begin
                if (s_valid && s_ready) begin
                    state <= ONE;
                    load_p1 <= 1'b1;
                end
            end
            ONE: begin
                if (load_p1) begin
                    data_p1 <= s_data;
                    load_p1 <= 1'b0;
                    load_p2 <= 1'b1;
                end
            end
            TWO: begin
                if (load_p2) begin
                    data_p2 <= data_p1;
                    load_p2 <= 1'b0;
                    load_p1_from_p2 <= 1'b1;
                end
            end
        endcase
    end
end

// Output logic
always @(posedge clk or posedge reset) begin
    if (reset) begin
        m_data <= {N{1'b0}};
        m_valid <= 1'b0;
    end else begin
        if (load_p1_from_p2) begin
            m_data <= data_p2;
            m_valid <= 1'b1;
            load_p1_from_p2 <= 1'b0;
        end
    end
end

// s_ready logic
always @(posedge clk or posedge reset) begin
    if (reset) begin
        s_ready <= 1'b1;
    end else begin
        if (m_valid && m_ready) begin
            s_ready <= 1'b1;
        end else begin
            s_ready <= 1'b0;
        end
    end
end

endmodule

module Incer #(
    parameter DATA_WIDTH = 8
)
(clk, arstn, din, dout, mode);

input clk;
input arstn;
input mode;
input [DATA_WIDTH-1:0] din;
output [DATA_WIDTH-1:0] dout;

// Internal registers
reg [DATA_WIDTH-1:0] counter;
reg [1:0] state;

// Initial state
always @(posedge clk or negedge arstn) begin
    if (!arstn) begin
        counter <= 0;
        state <= ADD_STATE;
    end
end

// State machine
always @(posedge clk or negedge arstn) begin
    if (!arstn) begin
        counter <= 0;
        state <= ADD_STATE;
    end else begin
        case (state)
            ADD_STATE: begin
                if (mode) begin
                    counter <= counter + 2;
                end else begin
                    counter <= counter + 1;
                end
                state <= INC_STATE;
            end
            INC_STATE: begin
                if (mode) begin
                    counter <= counter + 1;
                end else begin
                    counter <= 0;
                    state <= ADD_STATE;
                end
            end
        endcase
    end
end

// Output
assign dout = counter;

endmodule

module edge_canny_detector_mul_mul_16s_16s_32_4_1_DSP48_3 (
