    input ce,
    input signed [16 - 1 : 0] a,
    input signed [16 - 1 : 0] b,
    output signed [32 - 1 : 0] p
);

    // Register for the first input
    reg [16 - 1 : 0] a_reg;
    // Register for the second input
    reg [16 - 1 : 0] b_reg;
    // Register for the intermediate result
    reg [32 - 1 : 0] p_reg_tmp;
    // Register for the final output
    reg [32 - 1 : 0] p_reg;

    // Reset the registers
    always @(posedge rst) begin
        a_reg <= 0;
        b_reg <= 0;
        p_reg_tmp <= 0;
        p_reg <= 0;
    end

    // Enable the multiplication and register updates on each positive clock edge
    always @(posedge clk) begin
        if (ce) begin
            // Store the inputs in registers
            a_reg <= a;
            b_reg <= b;
            // Perform the multiplication in the first stage
            p_reg_tmp <= a_reg * b_reg;
            // Store the intermediate result in the second stage
            p_reg <= p_reg_tmp;
        end
    end

    // Assign the final output directly from the register
    assign p = p_reg;

endmodule

