module udpAppMux_txLengthNetwork_fifo
#(
    parameter
        DATA_BITS  = 8,
        DEPTH_BITS = 4
)(
    input  wire                 clk,
    input  wire                 aclr,
    output wire                 empty_n,
    output wire                 full_n,
    input  wire                 read,
    input  wire                 write,
    output wire [DATA_BITS-1:0] dout,
    input  wire [DATA_BITS-1:0] din
);

// Parameters
localparam DEPTH = 1 << DEPTH_BITS;

// Memory array
reg [DATA_BITS-1:0] mem [DEPTH-1:0];

// Index register
reg [DEPTH_BITS-1:0] index;

// Flags
wire [DATA_BITS-1:0] data_in;
wire [DATA_BITS-1:0] data_out;

// Combinational logic
always_comb begin
    empty_n = (index == 0);
    full_n = (index == DEPTH - 1);
    data_in = din;
    data_out = mem[index];
end

// Sequential logic
always_ff @(posedge clk or posedge aclr) begin
    if (aclr) begin
        index <= 0;
        empty_n <= 1'b1;
        full_n <= 1'b0;
    end else begin
        if (write && !full_n) begin
            mem[index] <= data_in;
            index <= index + 1'b1;
        end
        if (read && !empty_n) begin
            index <= index - 1'b1;
        end
    end
end

// Output data
assign dout = data_out;

endmodule

module Counter_Controller #(
    parameter   DWIDTH = 7
)(
    input                   clk,
    input                   rst_n,
    input                   start_i,
    input   [DWIDTH-1:0]    cnt_val_i,
    input   [DWIDTH-1:0]    cnt_i,
    output                  run_o,
    output                  done_o
);

    // State definitions
    typedef enum logic [1:0] {
        S_IDLE,
        S_RUN,
        S_DONE
    } state_t;

    // Internal signals
    state_t state, state_n;
    logic [DWIDTH-1:0] cnt_val, cnt_val_n;
    logic run, done;

    // Register for state management
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= S_IDLE;
            cnt_val <= 0;
            run <= 0;
            done <= 0;
        end else begin
            state <= state_n;
            cnt_val <= cnt_val_n;
            run <= run;
            done <= done;
        end
    end

    // Register for counter value management
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt_val_n <= cnt_val_i;
        end else begin
            cnt_val_n <= cnt_val;
        end
    end

    // FSM logic
    always_comb begin
        state_n = state;
        run_o = run;
        done_o = done;

        case (state)
            S_IDLE: begin
                if (start_i) begin
                    state_n = S_RUN;
                    cnt_val_n = cnt_val_i;
                end
            end
            S_RUN: begin
                if (cnt_val == cnt_i) begin
                    state_n = S_DONE;
                    done_o = 1'b1;
                end else begin
                    run_o = 1'b1;
                end
            end
            S_DONE: begin
                if (!start_i) begin
                    state_n = S_IDLE;
                end
            end
        endcase
    end

endmodule

