module AXIS_WB_WB_Queue (
  input         clock,
  input         reset,
  output        io_enq_ready,
  input         io_enq_valid,
  input  [31:0] io_enq_bits,
  input         io_deq_ready,
  output        io_deq_valid,
  output [31:0] io_deq_bits
);

  // Parameters
  parameter DEPTH = 512;
  parameter WIDTH = 32;

  // RAM for the queue
  reg [WIDTH-1:0] ram [0:DEPTH-1];

  // Pointers
  reg [8:0] value;
  reg [8:0] value_1;

  // Full flag
  reg maybe_full;

  // Reset
  always @(posedge reset) begin
    value <= 0;
    value_1 <= 0;
    maybe_full <= 0;
  end

  // Enqueue operation
  always @(posedge clock) begin
    if (reset) begin
      value <= 0;
    end else if (io_enq_valid && !maybe_full) begin
      ram[value] <= io_enq_bits;
      value <= value + 1;
      if (value == DEPTH - 1) begin
        value <= 0;
      end
      if (value == value_1) begin
        maybe_full <= 1;
      end
    end
  end

  // Dequeue operation
  always @(posedge clock) begin
    if (reset) begin
      value_1 <= 0;
    end else if (io_deq_ready && maybe_full) begin
      io_deq_bits <= ram[value_1];
      value_1 <= value_1 + 1;
      if (value_1 == DEPTH - 1) begin
        value_1 <= 0;
      end
      if (value_1 == value) begin
        maybe_full <= 0;
      end
    end
  end

  // Ready signals
  assign io_enq_ready = !maybe_full;
  assign io_deq_valid = maybe_full;

endmodule

