module Control(
    input clk,
    input start,
    output reg[3:0] direction,
    output reg ready
);

    // Define the states of the finite state machine
    typedef enum {IDLE, STATE1, STATE2, STATE3} state_t;
    state_t current_state, next_state;

    // Initial state
    initial begin
        current_state = IDLE;
    end

    // State transition logic
    always @(posedge clk or posedge start) begin
        if (start) begin
            // Reset the state machine
            current_state = IDLE;
        end else begin
            // Determine the next state based on the current state
            case (current_state)
                IDLE: begin
                    if (start) begin
                        next_state = STATE1;
                    end else begin
                        next_state = IDLE;
                    end
                end
                STATE1: begin
                    if (start) begin
                        next_state = STATE2;
                    end else begin
                        next_state = IDLE;
                    end
                end
                STATE2: begin
                    if (start) begin
                        next_state = STATE3;
                    end else begin
                        next_state = IDLE;
                    end
                end
                STATE3: begin
                    if (start) begin
                        next_state = IDLE;
                    end else begin
                        next_state = IDLE;
                    end
                end
            endcase
        end
    end

    // State update logic
    always @(posedge clk) begin
        if (start) begin
            current_state = IDLE;
        end else begin
            current_state <= next_state;
        end
    end

    // Direction output logic
    always @(*) begin
        case (current_state)
            IDLE: direction = 4'b0000;
            STATE1: direction = 4'b0001;
            STATE2: direction = 4'b0010;
            STATE3: direction = 4'b0011;
        endcase
    end

    // Ready output logic
    always @(*) begin
        ready = (current_state == IDLE);
    end

endmodule

