    output [0:2] mem_out,
    output [0:2] mem_outb
);

    // Declare flip-flops
    reg [0:0] ff1, ff2, ff3;

    // Assign initial values to flip-flops
    initial begin
        ff1 = 0;
        ff2 = 0;
        ff3 = 0;
    end

    // Sequential logic for the shift register
    always @(posedge prog_clk) begin
        ff1 <= ccff_head;
        ff2 <= ff1;
        ff3 <= ff2;
    end

    // Output assignments
    assign mem_out = {ff3, ff2, ff1};
    assign mem_outb = ~{ff3, ff2, ff1};

    // Assign ccff_tail as the output of the last flip-flop
    assign ccff_tail = ff3;

endmodule

module partsel_00215(
    input [3:0] ctrl,
    input [2:0] s0,
    input [2:0] s1,
    input [2:0] s2,
    input [2:0] s3,
    input signed [31:0] x0,
    input signed [31:0] x1,
    input signed [31:0] x2,
    input [31:0] x3,
    output [127:0] y
);

    // Local parameters
    localparam p0 = 16'h1234;
    localparam p1 = 16'h5678;
    localparam p2 = 16'h9ABC;
    localparam p3 = 16'hDEFG;

    // Intermediate wires
    wire [31:0] x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15;

    // Conditional logic and arithmetic operations
    always_comb begin
        case (ctrl)
            4'b0000: begin
                x4 = x0;
                x5 = x1;
                x6 = x2;
                x7 = x3;
            end
            4'b0001: begin
                x4 = x0 >> s0;
                x5 = x1 >> s1;
                x6 = x2 >> s2;
                x7 = x3 >> s3;
            end
            4'b0010: begin
                x4 = x0 << s0;
                x5 = x1 << s1;
                x6 = x2 << s2;
                x7 = x3 << s3;
            end
            4'b0011: begin
                x4 = x0 + x1;
                x5 = x2 + x3;
                x6 = x0 - x1;
                x7 = x2 - x3;
            end
            4'b0100: begin
                x4 = x0 * x1;
                x5 = x2 * x3;
                x6 = x0 / x1;
                x7 = x2 / x3;
            end
            4'b0101: begin
                x4 = x0 & x1;
                x5 = x2 & x3;
                x6 = x0 | x1;
                x7 = x2 | x3;
            end
            4'b0110: begin
                x4 = x0 ^ x1;
                x5 = x2 ^ x3;
                x6 = ~x0;
                x7 = ~x3;
            end
            4'b0111: begin
                x4 = x0 + p0;
                x5 = x1 + p1;
                x6 = x2 + p2;
                x7 = x3 + p3;
            end
            4'b1000: begin
                x4 = x0 - p0;
                x5 = x1 - p1;
                x6 = x2 - p2;
                x7 = x3 - p3;
            end
            4'b1001: begin
                x4 = x0 * p0;
                x5 = x1 * p1;
                x6 = x2 * p2;
                x7 = x3 * p3;
            end
            4'b1010: begin
                x4 = x0 / p0;
                x5 = x1 / p1;
                x6 = x2 / p2;
                x7 = x3 / p3;
            end
            4'b1011: begin
                x4 = x0 & p0;
                x5 = x1 & p1;
                x6 = x2 & p2;
                x7 = x3 & p3;
            end
            4'b1100: begin
                x4 = x0 | p0;
                x5 = x1 | p1;
                x6 = x2 | p2;
                x7 = x3 | p3;
            end
            4'b1101: begin
                x4 = x0 ^ p0;
                x5 = x1 ^ p1;
                x6 = ~p0;
                x7 = ~p3;
            end
            4'b1110: begin
                x4 = x0 + p0 + p1;
                x5 = x1 + p2 + p3;
                x6 = x2 + p0 + p2;
                x7 = x3 + p1 + p3;
            end
            4'b1111: begin
                x4 = x0 - p0 - p1;
                x5 = x1 - p2 - p3;
                x6 = x2 - p0 - p2;
                x7 = x3 - p1 - p3;
            end
            default: begin
                x4 = 0;
                x5 = 0;
                x6 = 0;
                x7 = 0;
            end
        endcase
    end

    // Concatenate intermediate results to form the output
    assign y = {x4, x5, x6, x7};

endmodule

module submulsub_0_stage_signed_14_bit(
	input signed [13:0] a,
	input signed [13:0] b,
	input signed [13:0] c,
	input signed [13:0] d,
	output [13:0] out
	);

	// Calculate (d - a) * b
	signed [26:0] intermediate1;
	intermediate1 = (d - a) * b;

	// Calculate (d - a) * b - c
	out = intermediate1 - c;

endmodule

