module sparc_ifu_esl_lfsr
(
    input               clk,
    input               rst_n,


    input [15:0]        lfsr_seed,
    input               lfsr_ld,


    input               lfsr_step,


    output reg [15:0]   lfsr_state_f,


    output reg          lfsr_out_f
);

    // Define the LFSR parameters
    localparam WIDTH = 16;
    localparam TAPS = 15; // Example taps, adjust as needed

    // Register to store the current state of the LFSR
    reg [WIDTH-1:0] lfsr_state;

    // Combinational logic to determine the next state
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            lfsr_state <= 16'b0; // Reset to zero state
        end else if (lfsr_ld) begin
            lfsr_state <= lfsr_seed; // Load from seed
        end else if (lfsr_step) begin
            // Calculate the next state using XOR operations on specific bits
            lfsr_state <= {lfsr_state[WIDTH-2:0], lfsr_state[TAPS]};
        end
    end

    // Output the current state and the most significant bit
    assign lfsr_state_f = lfsr_state;
    assign lfsr_out_f = lfsr_state[WIDTH-1];

endmodule

