module FFlr(
    input wire clk,
    input wire [31:0] f,
    output reg [31:0] g
);

    // Internal signals
    reg [31:0] len_raw;
    reg [31:0] x_mask;
    reg [31:0] f_masked;
    reg [31:0] f_incr;
    reg [31:0] f_out;
    reg [31:0] res;
    reg [31:0] g_reg;

    // Compute len_raw by subtracting 255 from bits 30:23
    assign len_raw = f[30:23] - 255;

    // Determine x_mask based on len_raw
    assign x_mask = len_raw[7:0];

    // Create f_masked by clearing bits beyond x_mask
    assign f_masked = f & ~({32{1'b1}} << x_mask);

    // Increment f_masked at the x_mask's first set bit
    assign f_incr = f_masked + 1;

    // Conditionally select between f_masked and f_incr based on f's value
    assign f_out = (f[31] == 1'b1) ? f_incr : f_masked;

    // Combine f's sign with modified lower bits
    assign res = {f[31], f_out[22:0]};

    // Pipeline res into g through two registers
    always @(posedge clk) begin
        g_reg <= res;
        g <= g_reg;
    end

endmodule

