module main (
    input X4,
    input X3,
    input X2,
    input X1,
    input X0,
    output F
);

    // Intermediate signals
    wire xor_result;
    wire and_result;
    wire not_result;
    wire intermediate1;
    wire intermediate2;

    // XOR operation on X0 and X1
    xor_result = X0 ^ X1;

    // AND operation on X0 and X1
    and_result = X0 & X1;

    // NOT operation on X0
    not_result = ~X0;

    // Intermediate signals based on XOR and AND results
    intermediate1 = xor_result | not_result;
    intermediate2 = and_result & X2;

    // Multiplexer to select the final output based on X3, X4, and intermediate signals
    always_comb begin
        case ({X3, X4})
            2'b00: F = intermediate1;
            2'b01: F = intermediate2;
            2'b10: F = X3;
            2'b11: F = X4;
            default: F = 1'b0; // Default case, should not occur
        endcase
    end

endmodule

