module FullAdder(
  input wire a, 
  input wire b,
  input wire carry_in,
  output wire sum,
  output wire carry_out
);

  // Sum is the XOR of a and b
  assign sum = a ^ b;

  // Carry_out is the OR of (a AND b) and (carry_in AND (a XOR b))
  assign carry_out = (a & b) | (carry_in & (a ^ b));

endmodule

