module p_adder #(parameter N=8) (
	input [N-1:0] A, B,
	input Cin,
	output [N-1:0] S,
	output Cout
	);

	// Initialize carry-out to 0
	wire [N-1:0] carry;

	// Compute the sum and carry for each bit position
	for (genvar i = 0; i < N; i++) begin
		assign carry[i] = A[i] & B[i] | A[i] & Cin | B[i] & Cin;
		assign S[i] = A[i] ^ B[i] ^ Cin;
	end

	// Assign the final carry-out
	assign Cout = carry[N-1];

endmodule

module mul8x7u_6PC (
