endmodule

module display(
    input sysclk,
    input [7:0] anodes,
    output reg shift = 0,
    output reg latch = 0,
    output reg data = 0
);

    reg [3:0] step_count = 0;

    always @(posedge sysclk) begin
        if (anodes != step_count[3:0]) begin
            step_count <= 0;
            shift <= 1;
            latch <= 0;
        end else begin
            step_count <= step_count + 1;
            if (step_count[1:0] == 2'b00) begin
                data <= anodes[step_count[3:0]];
                shift <= 1;
                latch <= 0;
            end else if (step_count[1:0] == 2'b10) begin
                shift <= 0;
                latch <= 1;
            end
        end
    end

endmodule

