module ALU (
    output [31:0] ALU_o,
    input signed  [31:0] A, B,
    input  [3:0]  ALUSel
);

    // Define the ALU operations
    wire [31:0] add_result;
    wire [31:0] sub_result;
    wire [31:0] sll_result;
    wire [31:0] srl_result;
    wire [31:0] sra_result;
    wire [31:0] xor_result;
    wire [31:0] and_result;
    wire [31:0] or_result;
    wire [31:0] comp_result;

    // Adder
    adder #(.WIDTH(32)) adder_inst (
        .a(A),
        .b(B),
        .sum(add_result)
    );

    // Subtractor
    subtractor #(.WIDTH(32)) subtractor_inst (
        .a(A),
        .b(~B + 1),
        .sum(sub_result)
    );

    // Shift Left Logical
    shift_left_logical #(.WIDTH(32)) sll_inst (
        .a(A),
        .b(B[4:0]),
        .sum(sll_result)
    );

    // Shift Right Logical
    shift_right_logical #(.WIDTH(32)) srl_inst (
        .a(A),
        .b(B[4:0]),
        .sum(srl_result)
    );

    // Shift Right Arithmetic
    shift_right_arithmetic #(.WIDTH(32)) sra_inst (
        .a(A),
        .b(B[4:0]),
        .sum(sra_result)
    );

    // XOR
    xor #(.WIDTH(32)) xor_inst (
        .a(A),
        .b(B),
        .sum(xor_result)
    );

    // AND
    and #(.WIDTH(32)) and_inst (
        .a(A),
        .b(B),
        .sum(and_result)
    );

    // OR
    or #(.WIDTH(32)) or_inst (
        .a(A),
        .b(B),
        .sum(or_result)
    );

    // Comparison (SLT)
    comp32b #(.WIDTH(32)) comp_inst (
        .a(A),
        .b(B),
        .slt(comp_result)
    );

    // Multiplexer to select the result based on ALUSel
    always_comb begin
        case (ALUSel)
            4'b0000: ALU_o = add_result;
            4'b0001: ALU_o = sub_result;
            4'b0010: ALU_o = sll_result;
            4'b0011: ALU_o = srl_result;
            4'b0100: ALU_o = sra_result;
            4'b0101: ALU_o = xor_result;
            4'b0110: ALU_o = and_result;
            4'b0111: ALU_o = or_result;
            4'b1000: ALU_o = comp_result; // SLT
            default: ALU_o = 32'b0; // Default case
        endcase
    end

endmodule

// Adder module
module adder (
    output [31:0] sum,
    input signed  [31:0] a,
    input signed  [31:0] b
);
    assign sum = a + b;
endmodule

// Subtractor module
module subtractor (
    output [31:0] sum,
    input signed  [31:0] a,
    input signed  [31:0] b
);
    assign sum = a - b;
endmodule

// Shift Left Logical module
module shift_left_logical (
    output [31:0] sum,
    input signed  [31:0] a,
    input  [4:0]  b
);
    assign sum = a << b;
endmodule

// Shift Right Logical module
module shift_right_logical (
    output [31:0] sum,
    input signed  [31:0] a,
    input  [4:0]  b
);
    assign sum = a >> b;
endmodule

// Shift Right Arithmetic module
module shift_right_arithmetic (
    output [31:0] sum,
    input signed  [31:0] a,
    input  [4:0]  b
);
    assign sum = a >>> b;
endmodule

// Comparison (SLT) module
module comp32b (
    output [31:0] slt,
    input signed  [31:0] a,
    input signed  [31:0] b
);
    assign slt = (a < b) ? 32'b1 : 32'b0;
endmodule

module button_pulse 
#(
    parameter MAX_COUNT = 8,    
    parameter DEC_COUNT = 2,    
    parameter MIN_COUNT = 1     
)(
    input wire clk,
    input wire clk_en,
    input wire button,
    input wire reset,
    output wire pulse
);

    reg [7:0] comp;
    reg [7:0] count;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            comp <= MAX_COUNT - 1;
            count <= 0;
            pulse <= 0;
        end else if (clk_en) begin
            if (button) begin
                count <= count + 1;
                if (count == MAX_COUNT) begin
                    comp <= MAX_COUNT - 1;
                end else if (count == comp) begin
                    comp <= comp - DEC_COUNT;
                end
            end else begin
                count <= 0;
                comp <= MAX_COUNT - 1;
            end
            if (count == 0 && button) begin
                pulse <= 1;
                count <= 0;
                comp <= MAX_COUNT - 1;
            end
        end
    end

endmodule

