            TWO: begin
                if (load_p1_from_p2) begin
                    data_p2 <= data_p1;
                    load_p1_from_p2 <= 0;
                    s_ready <= 1;
                    m_valid <= 1;
                end
            end
        endcase
    end
end

// Output signals
