module fsm_seq_10010_moore(
    input clk,
    input rst_n,
    input x,
    output z
);

    // Define the states of the FSM
    parameter S1 = 3'b000,
            S2 = 3'b001,
            S3 = 3'b010,
            S4 = 3'b011,
            S5 = 3'b100,
            S6 = 3'b101;

    // Declare the state and next state registers
    reg [2:0] state;
    reg [2:0] next;

    // Asynchronous reset to initialize the state to S1
    always @(posedge rst_n) begin
        state <= S1;
    end

    // Combinational logic to determine the next state
    always @(posedge clk) begin
        case (state)
            S1: begin
                if (x == 1'b0) begin
                    next <= S2;
                end else begin
                    next <= S3;
                end
            end
            S2: begin
                if (x == 1'b0) begin
                    next <= S3;
                end else begin
                    next <= S4;
                end
            end
            S3: begin
                if (x == 1'b0) begin
                    next <= S4;
                end else begin
                    next <= S5;
                end
            end
            S4: begin
                if (x == 1'b0) begin
                    next <= S5;
                end else begin
                    next <= S6;
                end
            end
            S5: begin
                if (x == 1'b0) begin
                    next <= S6;
                end else begin
                    next <= S1;
                end
            end
            S6: begin
                if (x == 1'b0) begin
                    next <= S1;
                end else begin
                    next <= S2;
                end
            end
        endcase
    end

    // Sequential logic to update the state register
    always @(posedge clk) begin
        state <= next;
    end

    // Output z when the FSM is in state S6
    assign z = (state == S6);

endmodule

module SRAM64x32(
    input CLK,
    input [3:0] WE,
    input EN,
    input [31:0] Di,
    output [31:0] Do,
    input [5:0] A
);

    // Define the size of the SRAM
    localparam WORD_SIZE = 32;
    localparam ADDR_SIZE = 6;
    localparam DATA_SIZE = 8;

    // Define the number of words and bytes
    localparam NUM_WORDS = 64;
    localparam NUM_BYTES = NUM_WORDS * DATA_SIZE;

    // Define the memory array
    reg [DATA_SIZE-1:0] memory[NUM_WORDS-1:0];

    // Define the address decoder
    wire [ADDR_SIZE-1:0] addr_decoded;

    // Address decoder logic
    always @(posedge CLK) begin
        addr_decoded <= A;
    end

    // Data input buffer
    reg [DATA_SIZE-1:0] di_buffer;

    // Data input buffer logic
    always @(posedge CLK) begin
        if (EN) begin
            di_buffer <= Di;
        end
    end

    // Data output buffer
    reg [DATA_SIZE-1:0] do_buffer;

    // Data output buffer logic
    always @(posedge CLK) begin
        if (EN) begin
            do_buffer <= memory[addr_decoded];
        end
    end

    // Write enable logic
    always @(posedge CLK) begin
        if (EN && WE[3]) begin
            memory[addr_decoded] <= di_buffer;
        end
    end

    // Output the data
    assign Do = do_buffer;

endmodule

