module bsg_fifo_1r1w_small_width_p109_els_p2_ready_THEN_valid_p1
(
  clk_i,
  reset_i,
  v_i,
  ready_o,
  data_i,
  v_o,
  data_o,
  yumi_i
);
  input [108:0] data_i;
  output [108:0] data_o;
  input clk_i;
  input reset_i;
  input v_i;
  input yumi_i;
  output ready_o;
  output v_o;

  // Internal signals
  reg [9:0] write_ptr;
  reg [9:0] read_ptr;
  reg full;
  reg empty;

  // Memory for FIFO
  reg [108:0] mem [0:108];

  // Reset
  always @(posedge reset_i or posedge clk_i) begin
    if (reset_i) begin
      write_ptr <= 0;
      read_ptr <= 0;
      full <= 0;
      empty <= 1;
    end else begin
      if (v_i && !full) begin
        mem[write_ptr] <= data_i;
        write_ptr <= write_ptr + 1;
        if (write_ptr == 109) write_ptr <= 0;
        full <= (write_ptr == read_ptr);
      end
      if (yumi_i && !empty) begin
        read_ptr <= read_ptr + 1;
        if (read_ptr == 109) read_ptr <= 0;
        empty <= (read_ptr == write_ptr);
      end
    end
  end

  // Outputs
  assign ready_o = ~full;
  assign v_o = ~empty;

  // Data output
  always @(posedge clk_i or posedge reset_i) begin
    if (reset_i) begin
      data_o <= 0;
    end else begin
      if (!empty) begin
        data_o <= mem[read_ptr];
        read_ptr <= read_ptr + 1;
        if (read_ptr == 109) read_ptr <= 0;
      end
    end
  end
endmodule

