module sound_dac8 (
    input        clk,
    input  [7:0] dac_in,
    input        speaker,
    output       audio_out
  );

  reg [9:0] dac_register;

  always @(posedge clk) begin
    // Shift the speaker control bit to the higher bit position
    reg [9:0] shifted_speaker = {speaker, 8'b0};

    // Add the current value of the register's lower 8 bits to the new dac_in value
    // and the shifted speaker control bit
    reg [9:0] new_value = dac_register[8:0] + dac_in + shifted_speaker;

    // Store the result back in the register
    dac_register <= new_value;

    // The audio output is determined by the value of the highest bit in the register
    audio_out <= dac_register[9];
  end

endmodule

