// Write and read pointers
reg [clog2_FIFO_DEPTH-1:0] wr_ptr;
reg [clog2_FIFO_DEPTH-1:0] rd_ptr;

// Status signals
always @(posedge clk or negedge arstn) begin
    if (!arstn) begin
        wr_ptr <= 0;
        rd_ptr <= 0;
        usedw <= 0;
        empty <= 1'b1;
        full <= 1'b0;
    end else begin
        if (wrreq && !full) begin
            mem[wr_ptr] <= data_in;
            wr_ptr <= (wr_ptr + 1) % FIFO_DEPTH;
            usedw <= usedw + 1;
            if (usedw == FIFO_DEPTH) begin
                full <= 1'b1;
            end
        end
        if (rdreq && !empty) begin
            data_out <= mem[rd_ptr];
            rd_ptr <= (rd_ptr + 1) % FIFO_DEPTH;
            usedw <= usedw - 1;
            if (usedw == 0) begin
                empty <= 1'b1;
            end
        end
    end
end

// Calculate usedw combinatorially
always @(*) begin
    if (wr_ptr >= rd_ptr) begin
        usedw = wr_ptr - rd_ptr;
    end else begin
        usedw = FIFO_DEPTH - (rd_ptr - wr_ptr);
    end
end

// Status signals
assign empty = (usedw == 0);
assign full = (usedw == FIFO_DEPTH);

endmodule

