and #10 #10 #10 #10 Q (Q, IN1, IN2, IN3, IN4);

// Specify timing for each input-to-output path
specify
    @(*) Q = 1'b1 when (IN1 == 1'b1 && IN2 == 1'b1 && IN3 == 1'b1 && IN4 == 1'b1);
    @(*) Q = 1'b0 when (IN1 == 1'b0 || IN2 == 1'b0 || IN3 == 1'b0 || IN4 == 1'b0);
endspecify

