module Data_CrossDomain(
    input clkA,
    input FlagIn_clkA, 
    input clkB,
    output FlagOut_clkB,
    input [7:0] dataA,
    output [7:0] dataB
);

    // Register to capture the state of FlagIn_clkA
    reg FlagToggle_clkA;

    // Register to synchronize the flag across clock domains
    reg [2:0] SyncA_clkB;

    // Registers to hold the data during the transfer process
    reg [7:0] clkA_data;
    reg [7:0] clkB_data;

    // Always block for handling sequential logic
    always @(posedge clkA or posedge clkB) begin
        if (clkA) begin
            // Capture the state of FlagIn_clkA
            FlagToggle_clkA <= FlagIn_clkA;

            // Synchronize the flag across clock domains
            if (SyncA_clkB == 3'b111) begin
                SyncA_clkB <= 3'b000;
                FlagOut_clkB <= FlagToggle_clkA;
            end else begin
                SyncA_clkB <= SyncA_clkB + 1'b1;
            end

            // Transfer data from clkA to clkB
            if (FlagToggle_clkA) begin
                clkA_data <= dataA;
            end
        end

        if (clkB) begin
            // Store the data received from clkA
            clkB_data <= clkA_data;

            // Output the synchronized data
            dataB <= clkB_data;
        end
    end

endmodule

module gh_delay_programmable_31(
    input wire CLK,
    input wire rst,
    input wire srst,
    input wire D,
    input wire [4:0] DELAY,
    output wire Q
);

    // Define the number of delay stages
    localparam NUM_STAGES = 5;

    // Array of delay stages
    gh_delay #(.DELAY(2)) delay_2(.CLK(CLK), .rst(rst), .srst(srst), .D(D), .Q(D_d1));
    gh_delay #(.DELAY(4)) delay_4(.CLK(CLK), .rst(rst), .srst(srst), .D(D_d1), .Q(D_d2));
    gh_delay #(.DELAY(8)) delay_8(.CLK(CLK), .rst(rst), .srst(srst), .D(D_d2), .Q(D_d3));
    gh_delay #(.DELAY(16)) delay_16(.CLK(CLK), .rst(rst), .srst(srst), .D(D_d3), .Q(D_d4));
    gh_delay #(.DELAY(32)) delay_32(.CLK(CLK), .rst(rst), .srst(srst), .D(D_d4), .Q(D_d5));

    // Register to handle single-cycle delays
    reg [4:0] D_d1;
    reg [4:0] D_d2;
    reg [4:0] D_d3;
    reg [4:0] D_d4;
    reg [4:0] D_d5;

    // Select the delayed output based on the DELAY input
    always @(posedge CLK or posedge rst or posedge srst) begin
        if (rst || srst) begin
            Q <= 1'b0;
            D_d1 <= 1'b0;
            D_d2 <= 1'b0;
            D_d3 <= 1'b0;
            D_d4 <= 1'b0;
            D_d5 <= 1'b0;
        end else begin
            case (DELAY)
                5'b00000: Q <= D;
                5'b00001: Q <= D_d1;
                5'b00010: Q <= D_d2;
                5'b00100: Q <= D_d3;
                5'b01000: Q <= D_d4;
                5'b10000: Q <= D_d5;
                default: Q <= 1'b0; // Default case, should not occur
            endcase
        end
    end

endmodule

