	input clk);

	// Intermediate registers
	reg [19:0] stage0;
	reg [19:0] stage1;
	reg [19:0] stage2;

	// Temporary register to hold the product
	reg [19:0] product;

	// Multiplication operation
	always @(posedge clk) begin
		product <= a * b;
	end

	// First stage: Multiply a and b
	always @(posedge clk) begin
		stage0 <= product;
	end

	// Second stage: Perform bitwise OR with c
	always @(posedge clk) begin
		stage1 <= stage0 | c;
	end

	// Third stage: Store the result in the output
