module countUD5L(
    input clk,
    input Up,
    input Dw,
    input reset,
    input LD,
    input [4:0] D,
    output [4:0] Q
);

    // Internal signals for the 5-bit counter
    reg [4:0] count;
    reg [4:0] next_count;

    // Reset the counter
    always @(posedge reset) begin
        count <= 5'b00000;
    end

    // Load the counter with the input D
    always @(posedge LD) begin
        count <= D;
    end

    // Update the counter based on the Up and Dw signals
    always @(posedge clk) begin
        if (reset) begin
            next_count <= 5'b00000;
        end else if (Up) begin
            next_count <= count + 1;
        end else if (Dw) begin
            next_count <= count - 1;
        end else begin
            next_count <= count;
        end
    end

    // Assign the next count to the current count
    assign Q = next_count;

    // Propagate carry signals
    assign UTC = (count == 5'b11111);
    assign DTC = (count == 5'b00000);

endmodule

