module xfcp_interface_uart
(
    input  wire         clk,
    input  wire         rst,

    input  wire         uart_rxd,
    output wire         uart_txd,

    input  wire [7:0]   down_xfcp_in_tdata,
    input  wire         down_xfcp_in_tvalid,
    output wire         down_xfcp_in_tready,
    input  wire         down_xfcp_in_tlast,
    input  wire         down_xfcp_in_tuser,

    output wire [7:0]   down_xfcp_out_tdata,
    output wire         down_xfcp_out_tvalid,
    input  wire         down_xfcp_out_tready,
    output wire         down_xfcp_out_tlast,
    output wire         down_xfcp_out_tuser,

    input  wire [15:0]  prescale
);

    // Parameters
    localparam FIFO_DEPTH = 1024;
    localparam DATA_WIDTH = 8;

    // FIFOs
    reg [DATA_WIDTH-1:0] tx_fifo [0:FIFO_DEPTH-1];
    reg [DATA_WIDTH-1:0] rx_fifo [0:FIFO_DEPTH-1];
    reg tx_fifo_full;
    reg tx_fifo_empty;
    reg rx_fifo_full;
    reg rx_fifo_empty;

    // COBS Encoder/Decoder
    reg [DATA_WIDTH-1:0] cobs_encoded;
    reg [DATA_WIDTH-1:0] cobs_decoded;
    reg cobs_encoded_valid;
    reg cobs_decoded_valid;

    // UART Core
    reg [DATA_WIDTH-1:0] uart_tx_data;
    reg uart_tx_valid;
    reg uart_tx_ready;
    reg uart_rx_data;
    reg uart_rx_valid;
    reg uart_rx_ready;

    // Control Signals
    reg tx_ready;
    reg rx_ready;
    reg tx_valid;
    reg rx_valid;
    reg tx_last;
    reg rx_last;
    reg tx_user;
    reg rx_user;

    // UART Core instantiation
    uart_core uart_core_inst (
        .clk(clk),
        .rst(rst),
        .rx(uart_rxd),
        .tx(uart_txd),
        .rx_data(uart_rx_data),
        .rx_valid(uart_rx_valid),
        .rx_ready(uart_rx_ready),
        .tx_data(uart_tx_data),
        .tx_valid(uart_tx_valid),
        .tx_ready(uart_tx_ready)
    );

    // FIFOs instantiation
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            tx_fifo_full <= 1'b0;
            tx_fifo_empty <= 1'b1;
            rx_fifo_full <= 1'b0;
            rx_fifo_empty <= 1'b1;
        end else begin
            if (!tx_fifo_full && down_xfcp_in_tvalid) begin
                tx_fifo[tx_fifo_write_index] <= down_xfcp_in_tdata;
                tx_fifo_write_index <= (tx_fifo_write_index + 1) % FIFO_DEPTH;
                tx_fifo_full <= (tx_fifo_write_index == tx_fifo_read_index);
                tx_fifo_empty <= 0;
            end
            if (!rx_fifo_full && uart_rx_valid) begin
                rx_fifo[rx_fifo_write_index] <= uart_rx_data;
                rx_fifo_write_index <= (rx_fifo_write_index + 1) % FIFO_DEPTH;
                rx_fifo_full <= (rx_fifo_write_index == rx_fifo_read_index);
                rx_fifo_empty <= 0;
            end
        end
    end

    reg [DATA_WIDTH-1:0] tx_fifo_read_data;
    reg [DATA_WIDTH-1:0] rx_fifo_read_data;
    reg tx_fifo_read_index;
    reg rx_fifo_read_index;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            tx_fifo_read_index <= 0;
            rx_fifo_read_index <= 0;
        end else begin
            if (!tx_fifo_empty) begin
                tx_fifo_read_data <= tx_fifo[tx_fifo_read_index];
                tx_fifo_read_index <= (tx_fifo_read_index + 1) % FIFO_DEPTH;
            end
            if (!rx_fifo_empty) begin
                rx_fifo_read_data <= rx_fifo[rx_fifo_read_index];
                rx_fifo_read_index <= (rx_fifo_read_index + 1) % FIFO_DEPTH;
            end
        end
    end

    // COBS Encoder/Decoder instantiation
    cobs_encoder cobs_encoder_inst (
        .data(tx_fifo_read_data),
        .valid(tx_fifo_valid),
        .encoded(cobs_encoded),
        .encoded_valid(cobs_encoded_valid)
    );

    cobs_decoder cobs_decoder_inst (
        .data(rx_fifo_read_data),
        .valid(rx_fifo_valid),
        .decoded(cobs_decoded),
        .decoded_valid(rx_decoded_valid)
    );

    // Data Flow Management
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            tx_ready <= 1'b0;
            rx_ready <= 1'b0;
            tx_valid <= 1'b0;
            rx_valid <= 1'b0;
            tx_last <= 1'b0;
            rx_last <= 1'b0;
            tx_user <= 1'b0;
            rx_user <= 1'b0;
        end else begin
            if (down_xfcp_in_tvalid && down_xfcp_in_tready) begin
                tx_ready <= 1'b1;
                tx_valid <= down_xfcp_in_tvalid;
                tx_last <= down_xfcp_in_tlast;
                tx_user <= down_xfcp_in_tuser;
            end else begin
                tx_ready <= 1'b0;
                tx_valid <= 1'b0;
                tx_last <= 1'b0;
                tx_user <= 1'b0;
            end

            if (uart_rx_valid && uart_rx_ready) begin
                rx_ready <= 1'b1;
                rx_valid <= uart_rx_valid;
                rx_last <= uart_rx_last;
                rx_user <= uart_rx_user;
            end else begin
                rx_ready <= 1'b0;
                rx_valid <= 1'b0;
                rx_last <= 1'b0;
                rx_user <= 1'b0;
            end
        end
    end

    // AXI Stream Interface
    assign down_xfcp_out_tdata = cobs_decoded;
    assign down_xfcp_out_tvalid = rx_valid;
    assign down_xfcp_out_tready = rx_ready;
    assign down_xfcp_out_tlast = rx_last;
    assign down_xfcp_out_tuser = rx_user;

    assign down_xfcp_in_tready = tx_ready;
    assign down_xfcp_in_tvalid = tx_valid;
    assign down_xfcp_in_tlast = tx_last;
    assign down_xfcp_in_tuser = tx_user;

endmodule

