module ltcdrw
  (
   input   [63:0] in_data,
   output  [63:0] out_data
   );

  // Split the 64-bit input into four 8-bit cells for each 32-bit half
  wire [7:0] cell0 = in_data[7:0];
  wire [7:0] cell1 = in_data[15:8];
  wire [7:0] cell2 = in_data[23:16];
  wire [7:0] cell3 = in_data[31:24];
  wire [7:0] cell4 = in_data[39:32];
  wire [7:0] cell5 = in_data[47:40];
  wire [7:0] cell6 = in_data[55:48];
  wire [7:0] cell7 = in_data[63:56];

  // Process each 8-bit cell using the ldrw module
  wire [31:0] result0;
  wire [31:0] result1;
  wire [31:0] result2;
  wire [31:0] result3;

  ldrw ldrw0 (.in_data(cell0), .out_data(result0));
  ldrw ldrw1 (.in_data(cell1), .out_data(result1));
  ldrw ldrw2 (.in_data(cell2), .out_data(result2));
  ldrw ldrw3 (.in_data(cell3), .out_data(result3));

  // Combine the 32-bit outputs into the 64-bit output
  assign out_data = {result3, result2, result1, result0};

endmodule

