module mul8u_13QR (
    input [7:0] A,
    input [7:0] B,
    output [15:0] O
);

// Initialize the output to zero
assign O = 16'h0000;

// Internal signals for the multiplication process
reg [15:0] product;
reg [15:0] temp;

// Iterate over each bit of A
for (genvar i = 0; i < 8; i++) begin
    // Shift B left by i bits
    temp = B << i;

    // Perform bitwise AND between temp and A
    product = product + (temp & A);
end

// Assign the product to the output
assign O = product;

endmodule

