module lfsr24(
    input wire Clk,
    input wire one,
    input wire tick,
    input wire [6:0] coreCount,
    output reg data
);

    // Internal registers to hold the current and next states of the LFSR
    reg [23:0] lfsr_p;
    reg [23:0] lfsr_n;

    // Initial state of the LFSR
    initial begin
        lfsr_p = 24'h020000;
    end

    // LFSR shift and rotation logic
    always @(posedge Clk) begin
        if (one) begin
            // Reset the LFSR to the initial state
            lfsr_p <= 24'h020000;
        end else if (tick) begin
            // Shift the LFSR
            lfsr_n <= {lfsr_p[23:1], lfsr_p[0]};

            // Apply feedback based on coreCount
            if (coreCount < 24) begin
                // Rotate the LFSR
                lfsr_n <= {lfsr_n[23:1], lfsr_n[0]};
            end
        end
    end

    // Output the selected bit from the LFSR
    always @(posedge Clk) begin
        if (coreCount == 0) begin
            data <= lfsr_p[0];
        end else if (coreCount == 1) begin
            data <= lfsr_p[1];
        end else if (coreCount == 2) begin
