module serial2parallel(
    input clk,
    input rst_n,
    input din_serial,
    input din_valid,
    output reg [7:0] dout_parallel,
    output reg dout_valid
);

    // Shift register to accumulate serial data
    reg [7:0] shift_reg;

    // Counter to track the number of bits received
    reg [3:0] bit_counter;

    // Register to hold the accumulated byte
    reg [7:0] accumulated_byte;

    // Register to hold the validity of the accumulated byte
    reg accumulated_byte_valid;

    // Process to handle serial data
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shift_reg <= 8'b0;
            bit_counter <= 4'b0;
            accumulated_byte <= 8'b0;
            accumulated_byte_valid <= 1'b0;
            dout_parallel <= 8'b0;
            dout_valid <= 1'b0;
        end else begin
            if (din_valid) begin
                // Shift the serial data into the shift register
                shift_reg <= {din_serial, shift_reg[7:1]};

                // Increment the bit counter
                bit_counter <= bit_counter + 1'b1;

                // Check if eight bits have been received
                if (bit_counter == 8'b1111) begin
                    // Accumulate the byte from the shift register
                    accumulated_byte <= shift_reg;

                    // Assert the validity of the accumulated byte
                    accumulated_byte_valid <= 1'b1;

                    // Reset the bit counter
                    bit_counter <= 4'b0;
                end
            end else begin
                // Reset the accumulated byte validity if din_valid is not asserted
                accumulated_byte_valid <= 1'b0;
            end

            // Output the accumulated byte and its validity
            dout_parallel <= accumulated_byte;
            dout_valid <= accumulated_byte_valid;
        end
    end

endmodule

module fa(sum, cout, a, b, cin);
    input a, b, cin;
    output sum, cout;

    wire w0, w1, w2;

    // Intermediate XOR operation
    w0 = a ^ b;

    // Intermediate AND operations
    w1 = a & b;
    w2 = w0 & cin;

    // Final sum and carry-out computation
    sum = w0 ^ cin;
    cout = w1 | w2;
endmodule

module pe(
