    // Combinational logic to compute the product of a and b
    assign product = a * b;

    // Sequential logic to accumulate the lower 32 bits of the product
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            c <= 32'b0; // Reset c to zero on reset
        end else begin
            c <= c + product[31:0]; // Accumulate the lower 32 bits of the product
        end
    end

endmodule

