module bsg_fifo_1rw_large_width_p62_els_p64_verbose_p0
(
  clk_i,
  reset_i,
  data_i,
  v_i,
  enq_not_deq_i,
  full_o,
  empty_o,
  data_o
);
  parameter WIDTH = 62;
  parameter DEPTH = 64;
  parameter VERBOSE = 0;

  input [WIDTH-1:0] data_i;
  output [WIDTH-1:0] data_o;
  input clk_i;
  input reset_i;
  input v_i;
  input enq_not_deq_i;
  output full_o;
  output empty_o;

  reg [WIDTH-1:0] mem[0:DEPTH-1];
  reg [5:0] read_ptr;
  reg [5:0] write_ptr;
  reg [1:0] last_op;

  // Sequential logic for FIFO operations
  always @(posedge clk_i or posedge reset_i) begin
    if (reset_i) begin
      read_ptr <= 0;
      write_ptr <= 0;
      last_op <= 2'b00;
      full_o <= 1'b0;
      empty_o <= 1'b1;
    end else begin
      if (v_i && enq_not_deq_i) begin // Enqueue operation
        if (write_ptr != read_ptr || last_op != 2'b01) begin
          mem[write_ptr] <= data_i;
          write_ptr <= write_ptr + 1'b1;
          if (write_ptr == DEPTH) write_ptr <= 0;
          last_op <= 2'b01;
        end else if (VERBOSE) $display("FIFO full, data dropped");
      end else if (v_i && !enq_not_deq_i) begin // Dequeue operation
        if (write_ptr != read_ptr || last_op != 2'b00) begin
          data_o <= mem[read_ptr];
          read_ptr <= read_ptr + 1'b1;
          if (read_ptr == DEPTH) read_ptr <= 0;
          last_op <= 2'b00;
        end else if (VERBOSE) $display("FIFO empty, no data to dequeue");
      end else if (write_ptr == read_ptr && last_op == 2'b01) begin // Full and last operation was enqueue
        if (VERBOSE) $display("FIFO full, data dropped");
      end else if (write_ptr == read_ptr && last_op == 2'b00) begin // Empty and last operation was dequeue
        if (VERBOSE) $display("FIFO empty, no data to dequeue");
      end
    end
  end

  // Combinational logic for status signals
  assign full_o = (write_ptr == read_ptr && last_op == 2'b01);
  assign empty_o = (write_ptr == read_ptr && last_op == 2'b00);

endmodule

module pn_gen_9 (
    input clk,
    input rst,
    input next,
    input [31:0] seed,
    output reg [31:0] num
  );

  // Internal registers
  reg [31:0] M_x, M_y, M_z, M_w;

  // Combinational logic to compute the next state
  always @(posedge clk or posedge rst) begin
    if (rst) begin
      // Initialize registers with a constant and seed
      M_x <= 32'h12345678;
      M_y <= 32'h87654321;
      M_z <= 32'h11223344;
      M_w <= 32'h55667788;
    end else if (next) begin
      // Compute the next state values
