module clock_divider(
    input wire clock,
    output wire clock_div
);

    // Parameters for input and output frequencies
    parameter INPUT_FREQ = 100000000; // 100 MHz
    parameter OUTPUT_FREQ = 20000000; // 20 MHz

    // Calculate the number of cycles for the output clock
    localparam COUNTER_LIMIT = INPUT_FREQ / OUTPUT_FREQ;

    // Internal registers
    reg [31:0] counter;
    reg clock_signal;

    // Always block triggered by the positive edge of the input clock
    always @(posedge clock) begin
        // Increment the counter
        counter <= counter + 1'b1;

        // Check if the counter has reached the limit
        if (counter == COUNTER_LIMIT) begin
            // Reset the counter
            counter <= 0;

            // Invert the clock signal
            clock_signal <= ~clock_signal;
        end
    end

    // Assign the output clock signal
    assign clock_div = clock_signal;

endmodule

