        .carry_in(tmp_carry[8]),
        .sum(adder2),
        .carry_out(tmp_carry[9])
    );

    adder8 #(.WIDTH(8)) adder3_inst (
        .a(a[23:16]),
        .b(b[23:16]),
        .carry_in(tmp_carry[9]),
        .sum(adder3),
        .carry_out(tmp_carry[10])
    );

    adder8 #(.WIDTH(8)) adder4_inst (
        .a(a[31:24]),
        .b(b[31:24]),
        .carry_in(tmp_carry[10]),
        .sum(adder4),
        .carry_out(tmp_carry[11])
    );

    // Combine the 8-bit sums to form the 32-bit sum
    assign sum = {adder4, adder3, adder2, adder1};

    // The final carry is the carry from the most significant byte adder
    assign carry_out = tmp_carry[11];

endmodule

// 8-bit adder module
module adder8 (
    input wire [7:0] a,
    input wire [7:0] b,
    input wire carry_in,
    output wire [7:0] sum,
    output wire carry_out
);

    // Define 4-bit adders
    wire [3:0] adder1, adder2, adder3, adder4;
    wire [4:0] tmp_carry;

    // Connect 4-bit adders
    adder4 #(.WIDTH(4)) adder1_inst (
        .a(a[3:0]),
        .b(b[3:0]),
        .carry_in(carry_in),
        .sum(adder1),
        .carry_out(tmp_carry[4])
    );

    adder4 #(.WIDTH(4)) adder2_inst (
        .a(a[7:4]),
        .b(b[7:4]),
        .carry_in(tmp_carry[4]),
        .sum(adder2),
        .carry_out(tmp_carry[5])
    );

    adder4 #(.WIDTH(4)) adder3_inst (
        .a(a[11:8]),
        .b(b[11:8]),
        .carry_in(tmp_carry[5]),
        .sum(adder3),
        .carry_out(tmp_carry[6])
    );

    adder4 #(.WIDTH(4)) adder4_inst (
        .a(a[15:12]),
        .b(b[15:12]),
        .carry_in(tmp_carry[6]),
        .sum(adder4),
        .carry_out(tmp_carry[7])
    );

    // Combine the 4-bit sums to form the 8-bit sum
    assign sum = {adder4, adder3, adder2, adder1};

    // The final carry is the carry from the most significant 4-bit adder
    assign carry_out = tmp_carry[7];

endmodule

