module gh_delay_programmable_63(
    input wire CLK,
    input wire rst,
    input wire srst,
    input wire D,
    input wire [5:0] DELAY,
    output wire Q
);

    // Define the number of delay stages
    localparam NUM_STAGES = 6;
    localparam DELAY_STAGES = {32, 16, 8, 4, 2, 1};

    // Instantiate the delay stages
    gh_delay gh_delay_32(.CLK(CLK), .D(D), .Q(Q_d32));
    gh_delay gh_delay_16(.CLK(CLK), .D(D), .Q(Q_d16));
    gh_delay gh_delay_8(.CLK(CLK), .D(D), .Q(Q_d8));
    gh_delay gh_delay_4(.CLK(CLK), .D(D), .Q(Q_d4));
    gh_delay gh_delay_2(.CLK(CLK), .D(D), .Q(Q_d2));
    gh_delay gh_delay_1(.CLK(CLK), .D(D), .Q(Q_d1));

    // Multiplexer to select the appropriate delayed version of D
    wire [5:0] delay_select;
    assign delay_select = DELAY;

    // Assign Q based on the DELAY value
    always @(posedge CLK or posedge rst or posedge srst) begin
        if (rst || srst) begin
            Q <= 1'b0;
            Q_d1 <= 1'b0;
            Q_d2 <= 1'b0;
            Q_d4 <= 1'b0;
            Q_d8 <= 1'b0;
            Q_d16 <= 1'b0;
            Q_d32 <= 1'b0;
        end else begin
            if (delay_select == 6'b000000) begin
                Q <= D;
            end else begin
                Q <= Q_d1;
                if (delay_select[5]) Q <= Q_d2;
                if (delay_select[4]) Q <= Q_d4;
                if (delay_select[3]) Q <= Q_d8;
                if (delay_select[2]) Q <= Q_d16;
                if (delay_select[1]) Q <= Q_d32;
            end
        end
    end

endmodule

