module fsm_trafic_light(clk, reset, red, yellow, green) {
    input clk, reset;
    output reg red, yellow, green;

    // Define the states of the FSM
    typedef enum {RED, YELLOW, GREEN, YELLOW2} state_t;
    state_t current_state, next_state;

    // Initial state
    initial begin
        current_state = RED;
    end

    // State transition logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= RED;
        end else begin
            current_state <= next_state;
        end
    end

    // Output logic based on the current state
    always @(*) begin
        case (current_state)
            RED: begin
                red = 1'b1;
                yellow = 1'b0;
                green = 1'b0;
            end
            YELLOW: begin
                red = 1'b0;
                yellow = 1'b1;
                green = 1'b0;
            end
            GREEN: begin
                red = 1'b0;
                yellow = 1'b0;
                green = 1'b1;
            end
            YELLOW2: begin
                red = 1'b0;
                yellow = 1'b1;
                green = 1'b0;
            end
        endcase
    end
}

