module B_8xBin2BCD(
    input  [7:0] numBin,
    output [9:0] numBCD
);

    // Define the number of 3-bit segments in the input binary number
    localparam NUM_SEGMENTS = 8;

    // Define the number of 4-bit BCD digits per segment
    localparam BCD_DIGITS_PER_SEGMENT = 4;

    // Define the number of BCD digits in the final output
    localparam NUM_BCD_DIGITS = NUM_SEGMENTS * BCD_DIGITS_PER_SEGMENT;

    // Define the number of carry signals
    localparam NUM_CARRIES = NUM_SEGMENTS - 1;

    // Declare the B_add3BCD module instances
    B_add3BCD b_add3BCD[NUM_SEGMENTS];

    // Declare the intermediate BCD digits and carry signals
    reg [3:0] bcdDigits[NUM_SEGMENTS];
    reg [3:0] carry[NUM_CARRIES];

    // Generate the B_add3BCD module instances
    generate
        for (genvar i = 0; i < NUM_SEGMENTS; i++) begin
            b_add3BCD[i] (
                .binIn(numBin[3*i+2:3*i]),
                .binIn1(numBin[3*i+1:3*i]),
                .binIn2(numBin[3*i:3*i-1]),
                .bcdOut(bcdDigits[i]),
                .carryOut(carry[i])
            );
        end
    endgenerate

    // Combine the intermediate BCD digits and carry signals to form the final BCD output
    assign numBCD = {carry[NUM_CARRIES-1], bcdDigits[NUM_SEGMENTS-1], bcdDigits[NUM_SEGMENTS-2], bcdDigits[NUM_SEGMENTS-3], bcdDigits[NUM_SEGMENTS-4], bcdDigits[NUM_SEGMENTS-5], bcdDigits[NUM_SEGMENTS-6], bcdDigits[NUM_SEGMENTS-7], bcdDigits[NUM_SEGMENTS-8]};

endmodule

