module B_add3BCD(
    input  [2:0] binIn,
    input  [2:0] binIn1,
    input  [2:0] binIn2,
    output reg [3:0] bcdOut,
    output reg [3:0] carryOut
);

    // Define the BCD digits for each 3-bit binary segment
    localparam BCD_DIGITS = 4;
    localparam BCD_TABLE[7:0] = {
        4'b0000, // 0
        4'b0001, // 1
        4'b0010, // 2
        4'b0011, // 3
        4'b0100, // 4
        4'b0101, // 5
        4'b0110, // 6
        4'b0111, // 7
        4'b1000, // 8
        4'b1001  // 9
    };

    // Calculate the BCD digits for each input segment
    reg [3:0] bcd1 = BCD_TABLE[binIn];
    reg [3:0] bcd2 = BCD_TABLE[binIn1];
    reg [3:0] bcd3 = BCD_TABLE[binIn2];

    // Calculate the BCD output and carry
    assign bcdOut = bcd1 + bcd2 + bcd3;
    assign carryOut = bcdOut[3];

endmodule

