module sum22bit(
    input [21:0] a,
    input [21:0] b,
    input [1:0] kIn,
    output [22:0] sum
);

    // Constants for the number of stages
    localparam STAGES = 11;

    // Generate array of carry generation instances
    generate
        for (genvar i = 0; i < STAGES; i++) begin
            // Generate carry generation instance
            carry_gen #(
                .WIDTH(22),
                .STAGE(i)
            ) gen_i (
                .a(a[i+1:0]),
                .b(b[i+1:0]),
                .kIn(kIn),
                .carryOut(gen_i.carryOut),
                .carryIn(gen_i.carryIn)
            );
        end
    endgenerate

    // Generate array of carry comparison instances
    generate
        for (genvar i = 0; i < STAGES; i++) begin
            // Generate carry comparison instance
            carry_cmp #(
                .WIDTH(22),
                .STAGE(i)
            ) cmp_i (
                .a(a[i+1:0]),
                .b(b[i+1:0]),
                .kIn(kIn),
                .carryOut(cmp_i.carryOut),
                .carryIn(cmp_i.carryIn)
            );
        end
    endgenerate

    // Combine carry signals to determine final carry and sum
    reg [22:0] sumReg;
    reg [22:0] carryReg;
    always @(posedge kIn) begin
        sumReg <= a + b + carryReg;
        carryReg <= gen_i.carryOut | cmp_i.carryOut;
    end

    // Output the sum
    assign sum = sumReg;

endmodule

