);

    // Generate carryOut using XOR and OR gates
    assign carryOut = (a & b) | (a & kIn) | (b & kIn);

    // Generate carryIn for the next stage
    assign carryIn = carryOut;

endmodule

module submuladd_1_stage_signed_16_bit(
