	// Internal 32-bit register to handle overflow
	reg [31:0] stage0;

	// Calculate the intermediate result
	always @(posedge clk) begin
		stage0 <= (d - a) * b + c;
	end

	// Output the 16-bit result by truncating the lower 16 bits
	assign out = stage0[31:16];

endmodule

module soundcodec(
    input clk,
    input pulse,
    output o_pwm
);

    reg [8:0] PWM_accumulator;
    reg [8:0] temp;

    always @(posedge clk) begin
        case (PWM_accumulator)
            8'b000000000: begin
                if (pulse) begin
                    temp = 8'b11111111;
                    PWM_accumulator <= temp;
                end
            end
            8'b111111111: begin
                if (pulse) begin
                    temp = 8'b00000000;
                    PWM_accumulator <= temp;
                end
            end
            default: begin
                if (pulse) begin
                    PWM_accumulator <= PWM_accumulator + 8'b11111111;
                end
            end
        endcase
    end

    assign o_pwm = PWM_accumulator[8];

endmodule

