module uart(
    input clk,
    input rst_n,
    input [7:0] data_in,
    input start,
    output reg [7:0] data_out,
    output reg done
);

    // Constants
    localparam IDLE = 0;
    localparam START_BIT = 1;
    localparam DATA_BITS = 2;
    localparam PARITY_BIT = 3;
    localparam STOP_BIT = 4;

    // State machine
    reg [3:0] state;
    reg [3:0] next_state;

    // Bit counter
    reg [3:0] bit_counter;

    // Shift register
    reg [7:0] shift_register;

    // Parity bit
    reg parity;

    // Clock enable
    reg clk_en;

    // Initial state
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            bit_counter <= 0;
            shift_register <= 0;
            parity <= 0;
            done <= 0;
        end else begin
            state <= next_state;
            bit_counter <= bit_counter + 1'b1;
            shift_register <= {shift_register[6:0], data_in[bit_counter]};
            if (bit_counter == 7) begin
                parity <= shift_register[7] ^ shift_register[6] ^ shift_register[5] ^ shift_register[4] ^ shift_register[3] ^ shift_register[2] ^ shift_register[1] ^ shift_register[0];
            end
        end
    end

    // Next state logic
    always @(*) begin
        case (state)
            IDLE: begin
                if (start) begin
                    next_state = START_BIT;
                end else begin
                    next_state = IDLE;
                end
            end
            START_BIT: begin
                next_state = DATA_BITS;
            end
            DATA_BITS: begin
                if (bit_counter == 7) begin
                    next_state = PARITY_BIT;
                end else begin
                    next_state = DATA_BITS;
                end
            end
            PARITY_BIT: begin
                next_state = STOP_BIT;
            end
            STOP_BIT: begin
                if (bit_counter == 3) begin
                    next_state = IDLE;
                    done <= 1;
                end else begin
                    next_state = STOP_BIT;
                end
            end
            default: begin
                next_state = IDLE;
            end
        endcase
    end

    // Clock enable logic
    always @(posedge clk) begin
        if (state == START_BIT || state == DATA_BITS || state == PARITY_BIT || state == STOP_BIT) begin
            clk_en <= 1;
        end else begin
            clk_en <= 0;
        end
    end

    // Data output logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            data_out <= 0;
        end else begin
            if (state == DATA_BITS) begin
                data_out <= shift_register;
            end
        end
    end

endmodule

module muladd_3_stage_signed_8_bit(
    input signed [7:0] a,
    input signed [7:0] b,
    input signed [7:0] c,
    output [7:0] out,
    input clk);

    // Internal registers to pipeline the operations
    reg [15:0] stage0;
    reg [15:0] stage1;
    reg [15:0] stage2;

    // Multiplication and addition in the first stage
    always @(posedge clk) begin
        stage0 <= (a * b) + c;
    end

    // Pass the result from stage0 to stage1
    always @(posedge clk) begin
        stage1 <= stage0;
    end

    // Pass the result from stage1 to stage2
    always @(posedge clk) begin
        stage2 <= stage1;
    end

    // Assign the final result to the output
    assign out = stage2[7:0];

endmodule

