    output [0:16] mem_out,
    output [0:16] mem_outb
);

    // Define the number of stages
    localparam STAGES = 16;

    // Declare the flip-flops
    reg [0:0] dffr[0:STAGES-1];

    // Initialize the flip-flops
    always @(posedge pReset) begin
        for (int i = 0; i < STAGES; i++) begin
            dffr[i] <= 1'b0;
        end
    end

    // Sequential logic for the shift register
    always @(posedge prog_clk) begin
        for (int i = 0; i < STAGES; i++) begin
