module key_filter(clk, rst_n, key_pin, key_status, key_event);
    input clk;
    input rst_n;
    input key_pin;
    output reg key_status;
    output reg key_event;

    // Internal signals
    reg [3:0] state;
    reg [3:0] prev_state;
    reg [3:0] edge_count;
    reg [3:0] stable_count;
    reg [3:0] debounce_count;
    reg [3:0] debounce_state;
    reg [3:0] debounce_prev_state;

    // FSM states
    typedef enum {IDLE, PRESS, STEADY, RELEASE} state_t;
    state_t current_state, next_state;

    // Shift register to track previous key states
    reg [3:0] key_shift_reg;

    // Debounce logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            debounce_state <= IDLE;
            debounce_prev_state <= IDLE;
            debounce_count <= 0;
        end else begin
            case (debounce_state)
                IDLE: begin
                    if (key_pin) begin
                        debounce_state <= PRESS;
                        debounce_count <= 0;
                    end
                end
                PRESS: begin
                    if (!key_pin) begin
                        debounce_state <= STEADY;
                        debounce_count <= 0;
                    end else if (debounce_count == 9) begin
                        debounce_state <= IDLE;
                        debounce_prev_state <= PRESS;
                    end else begin
                        debounce_count <= debounce_count + 1;
                    end
                end
                STEADY: begin
                    if (key_pin) begin
                        debounce_state <= RELEASE;
                        debounce_count <= 0;
                    end else if (debounce_count == 9) begin
                        debounce_state <= IDLE;
                        debounce_prev_state <= STEADY;
                    end else begin
                        debounce_count <= debounce_count + 1;
                    end
                end
                RELEASE: begin
                    if (!key_pin) begin
                        debounce_state <= IDLE;
                        debounce_prev_state <= RELEASE;
                    end else if (debounce_count == 9) begin
                        debounce_state <= IDLE;
                        debounce_prev_state <= RELEASE;
                    end else begin
                        debounce_count <= debounce_count + 1;
                    end
                end
            endcase
        end
    end

    // FSM logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            current_state <= IDLE;
            key_status <= 0;
            key_event <= 0;
            edge_count <= 0;
            stable_count <= 0;
            debounce_count <= 0;
            debounce_state <= IDLE;
            debounce_prev_state <= IDLE;
        end else begin
            current_state <= next_state;

            case (current_state)
                IDLE: begin
                    if (key_pin) begin
                        next_state <= PRESS;
                        edge_count <= 0;
                        stable_count <= 0;
                        debounce_count <= 0;
                        debounce_state <= IDLE;
                        debounce_prev_state <= IDLE;
                    end
                end
                PRESS: begin
                    if (edge_count == 9) begin
                        next_state <= STEADY;
                        edge_count <= 0;
                        stable_count <= 0;
                        debounce_count <= 0;
                        debounce_state <= IDLE;
                        debounce_prev_state <= PRESS;
                    end else begin
                        edge_count <= edge_count + 1;
                    end
                end
                STEADY: begin
                    if (edge_count == 9) begin
                        next_state <= RELEASE;
                        edge_count <= 0;
                        stable_count <= 0;
                        debounce_count <= 0;
                        debounce_state <= IDLE;
                        debounce_prev_state <= STEADY;
                    end else begin
                        edge_count <= edge_count + 1;
                    end
                end
                RELEASE: begin
                    if (edge_count == 9) begin
                        next_state <= IDLE;
                        edge_count <= 0;
                        stable_count <= 0;
                        debounce_count <= 0;
                        debounce_state <= IDLE;
                        debounce_prev_state <= RELEASE;
                    end else begin
                        edge_count <= edge_count + 1;
                    end
                end
            endcase

            // Update key_status and key_event
            case (current_state)
                IDLE: begin
                    key_status <= 0;
                    key_event <= 0;
                end
                PRESS: begin
                    key_status <= 1;
                    key_event <= 0;
                end
                STEADY: begin
                    key_status <= 1;
                    key_event <= 0;
                end
                RELEASE: begin
                    key_status <= 0;
                    key_event <= 1;
                end
            endcase
        end
    end

    // Shift register to track previous key states
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            key_shift_reg <= 4'b0000;
        end else begin
            key_shift_reg <= {key_pin, key_shift_reg[3:1]};
        end
    end

endmodule

module apb_master(
    input     [7:0]       addr,
    input                 data_valid,  
    input     [31:0]      data,
    input                 data_dir,
    output [31:0]      read_out_data,
    output            transaction_done,


    input                 apb_clk,
    input                 apb_reset,
    output                apb_write,
    output                apb_selx,
    output                apb_en,
    output   [31:0]       apb_wdata,
    input    [31:0]       apb_rdata,
    input                 apb_ready,
    output   [7:0]        apb_addr,
    output   				apb_tranerr
);

    // State definitions
    typedef enum {IDLE, SETUP, ACCESS} state_t;
    state_t current_state, next_state;

    // Register declarations
    reg [7:0] apb_addr_reg;
    reg [31:0] apb_wdata_reg;
    reg [31:0] apb_rdata_reg;
    reg [31:0] read_out_data_reg;
    reg [31:0] timeout_count;
    reg [31:0] timeout_max;
    reg transaction_done_reg;
    reg apb_write_reg;
    reg apb_selx_reg;
    reg apb_en_reg;
    reg apb_tranerr_reg;

    // Initial values
    initial begin
        current_state = IDLE;
        apb_addr_reg = 8'b0;
        apb_wdata_reg = 32'b0;
        apb_rdata_reg = 32'b0;
        read_out_data_reg = 32'b0;
        timeout_count = 0;
        timeout_max = 10000; // Example timeout value
        transaction_done_reg = 0;
        apb_write_reg = 0;
        apb_selx_reg = 0;
        apb_en_reg = 0;
        apb_tranerr_reg = 0;
    end

    // Combinational logic for next-state determination
    always @(posedge apb_clk or posedge apb_reset) begin
        if (apb_reset) begin
            current_state <= IDLE;
        end else begin
            current_state <= next_state;
        end
    end

    // Sequential logic for state updates and output handling
    always @(posedge apb_clk) begin
        if (current_state == IDLE) begin
            if (data_valid) begin
                next_state <= SETUP;
            end
        end else if (current_state == SETUP) begin
            apb_addr_reg <= addr;
            apb_wdata_reg <= data;
            apb_write_reg <= data_dir;
            apb_selx_reg <= 1'b1; // Assuming single slave
            apb_en_reg <= 1'b1;
            next_state <= ACCESS;
        end else if (current_state == ACCESS) begin
            if (apb_ready) begin
                if (apb_write_reg) begin
                    apb_wdata <= data;
                    apb_en <= 1'b1;
                end else begin
                    apb_en <= 1'b1;
                end
                timeout_count <= 0;
                next_state <= IDLE;
            end else begin
                timeout_count <= timeout_count + 1;
                if (timeout_count == timeout_max) begin
                    apb_tranerr_reg <= 1'b1;
                    next_state <= IDLE;
                end
            end
        end
    end

    // Output assignments
    assign read_out_data = read_out_data_reg;
    assign transaction_done = transaction_done_reg;
    assign apb_addr = apb_addr_reg;
    assign apb_wdata = apb_wdata_reg;
    assign apb_rdata = apb_rdata_reg;
    assign apb_write = apb_write_reg;
    assign apb_selx = apb_selx_reg;
    assign apb_en = apb_en_reg;
    assign apb_tranerr = apb_tranerr_reg;

endmodule

module data_path(
    output [31:0] IR_OUT,
    output MOC,
    output Cond,
    input SE,
    input [1:0] size,
    input FR_ld,
    input RF_ld,
    input IR_ld,
    input MAR_ld,
    input MDR_ld,
    input R_W,
    input MOV,
    input MA_1, MA_0, MB_1, MB_0, MC_2, MC_1, MC_0, MD, ME,
    input [4:0] OP,
    input clk, clr
    );

    // Constants
    localparam PC = 0;
    localparam LR = 1;
    localparam ZERO = 0;

    // Registers
    reg [31:0] IR, MAR, MDR, FR;

    // Multiplexers
    wire [31:0] mux_A, mux_B;
    wire [31:0] ALU_result;
    wire [31:0] shifter_result;
    wire [31:0] ram_result;

    // ALU
    always @(posedge clk or posedge clr) begin
        if (clr) begin
            ALU_result <= 0;
        end else begin
            case (OP)
                5'b00000: ALU_result <= FR + MDR; // ADD
                5'b00001: ALU_result <= FR - MDR; // SUB
                5'b00010: ALU_result <= FR & MDR; // AND
                5'b00011: ALU_result <= FR | MDR; // OR
                5'b00100: ALU_result <= FR ^ MDR; // XOR
                5'b00101: ALU_result <= FR << MDR; // SHL
                5'b00110: ALU_result <= FR >> MDR; // SHR
                5'b01000: ALU_result <= FR + 1; // INC
                5'b01001: ALU_result <= FR - 1; // DEC
                5'b01010: ALU_result <= FR & ~MDR; // NOT
                5'b01011: ALU_result <= FR | ~MDR; // NOT
                5'b01100: ALU_result <= FR ^ ~MDR; // NOT
                5'b01101: ALU_result <= FR << 1; // SHL
                5'b01110: ALU_result <= FR >> 1; // SHR
                default: ALU_result <= 0;
            endcase
        end
    end

    // Shifter
    always @(posedge clk or posedge clr) begin
        if (clr) begin
            shifter_result <= 0;
        end else begin
            case (OP)
                5'b00000: shifter_result <= FR + MDR; // ADD
                5'b00001: shifter_result <= FR - MDR; // SUB
                5'b00010: shifter_result <= FR & MDR; // AND
                5'b00011: shifter_result <= FR | MDR; // OR
                5'b00100: shifter_result <= FR ^ MDR; // XOR
                5'b00101: shifter_result <= FR << MDR; // SHL
                5'b00110: shifter_result <= FR >> MDR; // SHR
                5'b01000: shifter_result <= FR + 1; // INC
                5'b01001: shifter_result <= FR - 1; // DEC
                5'b01010: shifter_result <= FR & ~MDR; // NOT
                5'b01011: shifter_result <= FR | ~MDR; // NOT
                5'b01100: shifter_result <= FR ^ ~MDR; // NOT
                5'b01101: shifter_result <= FR << 1; // SHL
                5'b01110: shifter_result <= FR >> 1; // SHR
                default: shifter_result <= 0;
            endcase
        end
    end

    // RAM
    reg [255:0] ram_256;
    always @(posedge clk or posedge clr) begin
        if (clr) begin
            ram_256 <= 0;
        end else begin
            if (ME) begin
                ram_256[MA_1:MA_0] <= MDR;
            end
        end
    end

    // Sign Extender
    wire [31:0] sign_extender_result;
    assign sign_extender_result = {31{MDR[31]}} | MDR;

    // Multiplexers
    assign mux_A = (FR_ld) ? FR : (IR_ld) ? IR : (MAR_ld) ? MAR : (MDR_ld) ? MDR : 0;
    assign mux_B = (RF_ld) ? FR : (IR_ld) ? IR : (MAR_ld) ? MAR : (MDR_ld) ? MDR : 0;

    // Main logic
    always @(posedge clk or posedge clr) begin
        if (clr) begin
            IR <= 0;
            MAR <= 0;
            MDR <= 0;
            FR <= 0;
        end else begin
            if (IR_ld) begin
                IR <= sign_extender_result;
            end
            if (MAR_ld) begin
                MAR <= sign_extender_result;
            end
            if (MDR_ld) begin
                MDR <= sign_extender_result;
            end
            if (FR_ld) begin
                FR <= sign_extender_result;
            end
            if (ME) begin
                MDR <= ram_256[MA_1:MA_0];
            end
            if (R_W) begin
                MDR <= mux_A;
            end
            if (MOV) begin
                FR <= mux_B;
            end
            if (SE) begin
                IR <= sign_extender_result;
            end
            if (size == 2'b00) begin
                MDR <= mux_A;
            end else if (size == 2'b01) begin
                MDR <= mux_B;
            end else if (size == 2'b10) begin
                MDR <= ALU_result;
            end else if (size == 2'b11) begin
                MDR <= shifter_result;
            end
            if (OP == 5'b00000) begin
                MOC <= 1;
            end else begin
                MOC <= 0;
            end
            if (OP == 5'b00001) begin
                Cond <= (FR == MDR) ? 1 : 0;
            end else begin
                Cond <= 0;
            end
        end
    end

endmodule

