module tbl4p1 (
    input wire clk,
    input wire rst,
    input wire [2:0] sw,
    output reg [15:0] lr,
    output reg [6:0] h3,
    output reg [6:0] h2,
    output reg [6:0] h1,
    output reg [6:0] h0
);

    // Initialize the sw register
    initial begin
        sw = 3'b000;
    end

    // Testbench logic
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            sw = 3'b000;
            lr = 16'b0000000000000000;
            h3 = 7'b0000000;
            h2 = 7'b0000000;
            h1 = 7'b0000000;
            h0 = 7'b0000000;
        end else begin
            // Toggle sw[1] every iteration
            sw[1] = ~sw[1];

            // Set sw[2] to 0 at the start and then to 1 at the second iteration
            if (sw[2] == 0) begin
                sw[2] = 1;
            end

            // Apply test scenarios
            if (sw[0] == 0) begin
                // Test case 1: All outputs are 0
                lr = 16'b0000000000000000;
                h3 = 7'b0000000;
                h2 = 7'b0000000;
                h1 = 7'b0000000;
                h0 = 7'b0000000;
            end else if (sw[0] == 1) begin
                // Test case 2: All outputs are 1
                lr = 16'b1111111111111111;
                h3 = 7'b1111111;
                h2 = 7'b1111111;
                h1 = 7'b1111111;
                h0 = 7'b1111111;
            end else if (sw[0] == 2) begin
                // Test case 3: lr is 0, h3 is 1, h2 is 2, h1 is 3, h0 is 4
                lr = 16'b0000000000000000;
                h3 = 7'b0000001;
                h2 = 7'b0000010;
                h1 = 7'b0000011;
                h0 = 7'b0000100;
            end else if (sw[0] == 3) begin
                // Test case 4: lr is 1, h3 is 5, h2 is 6, h1 is 7, h0 is 8
                lr = 16'b1111111111111111;
                h3 = 7'b0000101;
                h2 = 7'b0000110;
                h1 = 7'b0000111;
                h0 = 7'b0001000;
            end

            // Delay between state changes
            #100;
        end
    end

    // Instantiate the lab04part02 module
    lab04part02 lab04part02_inst (
        .clk(clk),
        .rst(rst),
        .sw(sw),
        .lr(lr),
        .h3(h3),
        .h2(h2),
        .h1(h1),
        .h0(h0)
    );

endmodule

module VGA_Sig_Gen (
    input CLK,
    input RESET,
    input RE,
    input [15:0] CONFIG_COLOURS,
    output reg DPR_CLK,
    output reg [14:0] VGA_ADDR,
    input VGA_DATA,
    output reg VGA_HS,
    output reg VGA_VS,
    output reg [7:0] VGA_COLOUR
);

    // Define constants for VGA timing
    localparam H_ACTIVE = 640; // Horizontal active pixels
    localparam H_SYNC_PULSE = 96; // Horizontal sync pulse width
    localparam H_BACK_PORCH = 48; // Horizontal back porch width
    localparam H_FRONT_PORCH = 16; // Horizontal front porch width
    localparam V_ACTIVE = 480; // Vertical active lines
    localparam V_SYNC_PULSE = 2; // Vertical sync pulse width
    localparam V_BACK_PORCH = 10; // Vertical back porch width
    localparam V_FRONT_PORCH = 2; // Vertical front porch width

    // Define counters
    reg [14:0] h_counter;
    reg [9:0] v_counter;

    // Define state machine
    reg [1:0] state;

    // State machine states
    localparam IDLE = 2'b00;
    localparam H_SYNC = 2'b01;
    localparam V_SYNC = 2'b10;
    localparam ACTIVE = 2'b11;

    // Reset counter and state
    always @(posedge RESET) begin
        h_counter <= 0;
        v_counter <= 0;
        state <= IDLE;
    end

    // Clock edge process
    always @(posedge CLK) begin
        case (state)
            IDLE: begin
                if (RE) begin
                    state <= ACTIVE;
                    h_counter <= 0;
                    v_counter <= 0;
                end
            end
            H_SYNC: begin
                if (h_counter < H_SYNC_PULSE) begin
                    h_counter <= h_counter + 1;
                end else begin
                    state <= V_SYNC;
                    h_counter <= 0;
                end
            end
            V_SYNC: begin
                if (v_counter < V_SYNC_PULSE) begin
                    v_counter <= v_counter + 1;
                end else begin
                    state <= ACTIVE;
                    v_counter <= 0;
                end
            end
            ACTIVE: begin
                if (h_counter < H_ACTIVE) begin
                    h_counter <= h_counter + 1;
                end else begin
                    state <= H_SYNC;
                    h_counter <= 0;
                    v_counter <= v_counter + 1;
                end
            end
        endcase

        // Generate VGA signals
        case (state)
            IDLE: begin
                VGA_HS <= 1'b0;
                VGA_VS <= 1'b0;
                VGA_COLOUR <= 8'b0;
            end
            H_SYNC: begin
                VGA_HS <= 1'b1;
                VGA_VS <= 1'b0;
                VGA_COLOUR <= 8'b0;
            end
            V_SYNC: begin
                VGA_HS <= 1'b0;
                VGA_VS <= 1'b1;
                VGA_COLOUR <= 8'b0;
            end
            ACTIVE: begin
                VGA_HS <= 1'b0;
                VGA_VS <= 1'b0;
                VGA_COLOUR <= CONFIG_COLOURS;
            end
        endcase

        // Generate display clock
        if (state == ACTIVE) begin
            DPR_CLK <= 1'b1;
        end else begin
            DPR_CLK <= 1'b0;
        end
    end

endmodule

module APB_master(
    input Transfer,
    input Wr_Rd,
    input [4:0] Address,
    input [31:0] write_data,
    output reg [31:0] read_data,
    input PCLK,
    input PRESETn,
    input PREADY,
    input [31:0] PRDATA,
    input PSLVERR,
    output reg [4:0] PADDR,
    output reg PSELx,
    output reg PENABLE,
    output reg PWRITE,
    output reg [31:0] PWDATA
);

    // Define the states of the FSM
    typedef enum {IDLE, SETUP, ACCESS} state_t;
    state_t current_state, next_state;

    // Initialize the current state
    always @(posedge PCLK or posedge PRESETn) begin
        if (PRESETn == 1'b0) begin
            current_state <= IDLE;
        end else begin
            current_state <= next_state;
        end
    end

    // State transition logic
    always @(posedge PCLK or posedge PRESETn) begin
        if (PRESETn == 1'b0) begin
            next_state <= IDLE;
        end else begin
            case (current_state)
                IDLE: begin
                    if (Transfer) begin
                        next_state <= SETUP;
                    end else begin
                        next_state <= IDLE;
                    end
                end
                SETUP: begin
                    if (PREADY) begin
                        next_state <= ACCESS;
                    end else begin
                        next_state <= SETUP;
                    end
                end
                ACCESS: begin
                    if (PSLVERR) begin
                        next_state <= IDLE;
                    end else if (Wr_Rd) begin
                        if (PREADY) begin
                            next_state <= ACCESS;
                        end else begin
                            next_state <= SETUP;
                        end
                    end else begin
                        if (PREADY) begin
                            next_state <= ACCESS;
                        end else begin
                            next_state <= SETUP;
                        end
                    end
                end
            endcase
        end
    end

    // State action logic
    always @(posedge PCLK or posedge PRESETn) begin
        if (PRESETn == 1'b0) begin
            PADDR <= 5'b0;
            PSELx <= 1'b0;
            PENABLE <= 1'b0;
            PWRITE <= 1'b0;
            PWDATA <= 32'b0;
            read_data <= 32'b0;
        end else begin
            case (current_state)
                IDLE: begin
                    PADDR <= 5'b0;
                    PSELx <= 1'b0;
                    PENABLE <= 1'b0;
                    PWRITE <= 1'b0;
                    PWDATA <= 32'b0;
                    read_data <= 32'b0;
                end
                SETUP: begin
                    PADDR <= Address;
                    PSELx <= 1'b1;
                    PENABLE <= 1'b1;
                    PWRITE <= Wr_Rd;
                    PWDATA <= write_data;
                end
                ACCESS: begin
                    if (Wr_Rd) begin
                        read_data <= PRDATA;
                    end else begin
                        PWDATA <= read_data;
                    end
                end
            endcase
        end
    end

endmodule

module BBFASin(
    input  [63:0] in,
    output reg [63:0] out
);

    // Convert the 64-bit floating-point input to a real number
    real in_real;
    assign in_real = $bit2real(in);

    // Compute the arcsine of the real number
    real asin_real;
    assign asin_real = $asin(in_real);

    // Convert the result back to a 64-bit floating-point output
    assign out = $real2bit(asin_real);

endmodule

module mux_256x1 (in, sel, out);
