    input [7:0] sel;
    output out;

    // Intermediate 128-bit multiplexers
    wire [127:0] half1;
    wire [127:0] half2;

    // First level of multiplexing
    mux_128x1 mux1 (.in(in[127:0]), .sel(sel[6:0]), .out(half1));
    mux_128x1 mux2 (.in(in[255:128]), .sel(sel[6:0]), .out(half2));

    // Second level of multiplexing
    mux_2x1 mux3 (.in({half1, half2}), .sel(sel[7]), .out(out));
endmodule

