module mux_64x1 (in, sel, out);
    input [63:0] in;
    input [5:0] sel;
    output out;

    // Intermediate 32-bit multiplexers
    wire [31:0] half1;
    wire [31:0] half2;

    // First level of multiplexing
    mux_32x1 mux1 (.in(in[31:0]), .sel(sel[4:0]), .out(half1));
    mux_32x1 mux2 (.in(in[63:32]), .sel(sel[4:0]), .out(half2));

    // Second level of multiplexing
    mux_2x1 mux3 (.in({half1, half2}), .sel(sel[5]), .out(out));
endmodule

