module mux_32x1 (in, sel, out);
    input [31:0] in;
    input [4:0] sel;
    output out;

    // Intermediate 16-bit multiplexers
    wire [15:0] half1;
    wire [15:0] half2;

    // First level of multiplexing
    mux_16x1 mux1 (.in(in[15:0]), .sel(sel[3:0]), .out(half1));
    mux_16x1 mux2 (.in(in[31:16]), .sel(sel[3:0]), .out(half2));

    // Second level of multiplexing
    mux_2x1 mux3 (.in({half1, half2}), .sel(sel[4]), .out(out));
endmodule

