module mux_16x1 (in, sel, out);
    input [15:0] in;
    input [3:0] sel;
    output out;

    // Intermediate 8-bit multiplexers
    wire [7:0] half1;
    wire [7:0] half2;

    // First level of multiplexing
    mux_8x1 mux1 (.in(in[7:0]), .sel(sel[2:0]), .out(half1));
    mux_8x1 mux2 (.in(in[15:8]), .sel(sel[2:0]), .out(half2));

    // Second level of multiplexing
    mux_2x1 mux3 (.in({half1, half2}), .sel(sel[3]), .out(out));
