module FIFO_arp_server_arpTableInsertFifo_V_shiftReg (
    clk,
    data,
    ce,
    a,
    q);

    parameter DATA_WIDTH = 81;
    parameter ADDR_WIDTH = 3;
    parameter FIFO_DEPTH = 5;

    reg [DATA_WIDTH-1:0] SRL_SIG[FIFO_DEPTH-1:0];

    always @(posedge clk) begin
        if (ce) begin
            // Shift all data one position down
            for (int i = FIFO_DEPTH-2; i >= 0; i--) begin
                SRL_SIG[i+1] <= SRL_SIG[i];
            end
            // Insert new data at the beginning
            SRL_SIG[0] <= data;
        end
    end

    // Output the data at the specified address
    assign q = SRL_SIG[a];

endmodule

