module FIFO_toe_ackDelayFifoReadCount_V_V (
    clk,
    reset,
    if_empty_n,
    if_read_ce,
    if_read,
    if_dout,
    if_full_n,
    if_write_ce,
    if_write,
    if_din);

parameter DATA_WIDTH = 8;
parameter ADDR_WIDTH = 4;
parameter DEPTH = 16;

input clk;
input reset;
output if_empty_n;
input if_read_ce;
input if_read;
output [DATA_WIDTH - 1:0] if_dout;
output if_full_n;
input if_write_ce;
input if_write;
input [DATA_WIDTH - 1:0] if_din;

reg [ADDR_WIDTH - 1:0] read_ptr;
reg [ADDR_WIDTH - 1:0] write_ptr;
reg [DATA_WIDTH - 1:0] shift_reg[DEPTH - 1:0];
reg if_empty;
reg if_full;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        read_ptr <= 0;
        write_ptr <= 0;
        if_empty <= 1'b1;
        if_full <= 1'b0;
    end else begin
        if (if_write_ce && if_write && !if_full) begin
            shift_reg[write_ptr] <= if_din;
            write_ptr <= write_ptr + 1'b1;
            if (write_ptr == DEPTH - 1) begin
                write_ptr <= 0;
            end
            if_empty <= 1'b0;
        end
        if (if_read_ce && if_read && !if_empty) begin
            if_dout <= shift_reg[read_ptr];
            read_ptr <= read_ptr + 1'b1;
            if (read_ptr == DEPTH - 1) begin
                read_ptr <= 0;
            end
            if_full <= 1'b0;
        end
        if (write_ptr == read_ptr) begin
            if_empty <= 1'b1;
        end
        if (write_ptr == read_ptr + 1) begin
            if_full <= 1'b1;
        end
    end
end

assign if_empty_n = ~if_empty;
assign if_full_n = ~if_full;

endmodule

