module PulseCounter(
    input wire clk,
    output wire pulse
);

    // Parameter for the upper bound of the counter
    parameter UPPER_BOUND = 28'h123456789ABCDEF0;

    // Internal counter register
    reg [27:0] counter;

    // Combinational logic to generate the pulse
    always @(posedge clk) begin
        if (counter == UPPER_BOUND) begin
            pulse <= 1'b1;
        end else begin
            pulse <= 1'b0;
        end
    end

    // Sequential logic to increment the counter
    always @(posedge clk) begin
        if (counter == UPPER_BOUND) begin
            counter <= 28'h0;
        end else begin
            counter <= counter + 1'b1;
        end
    end

endmodule

