module Mux8to1GateLevel(
    input wire A,
    input wire B,
    input wire C,
    input wire D,
    input wire E,
    input wire F,
    input wire G,
    input wire H,
    input wire S0,
    input wire S1,
    input wire S2,
    output wire Y
);

    // Define the logic for the 8-to-1 multiplexer
    // Each data input is gated with a specific combination of the select signals
    // and the final output Y is computed by ORing the results of these AND operations

    // AND gates for each data input based on the select signals
    wire A_select = (S0 == 1'b0) & (S1 == 1'b0) & (S2 == 1'b0);
    wire B_select = (S0 == 1'b0) & (S1 == 1'b0) & (S2 == 1'b1);
    wire C_select = (S0 == 1'b0) & (S1 == 1'b1) & (S2 == 1'b0);
    wire D_select = (S0 == 1'b0) & (S1 == 1'b1) & (S2 == 1'b1);
    wire E_select = (S0 == 1'b1) & (S1 == 1'b0) & (S2 == 1'b0);
    wire F_select = (S0 == 1'b1) & (S1 == 1'b0) & (S2 == 1'b1);
    wire G_select = (S0 == 1'b1) & (S1 == 1'b1) & (S2 == 1'b0);
    wire H_select = (S0 == 1'b1) & (S1 == 1'b1) & (S2 == 1'b1);

    // OR gate to select the output based on the select signals
    Y = A_select & A | B_select & B | C_select & C | D_select & D |
        E_select & E | F_select & F | G_select & G | H_select & H;

endmodule

