endmodule

module CLA2 (
	input[1:0] a, b,
	input c_in,
	output g_out, p_out,
	output[1:0] s
	);

	// Submodule for generating individual bit-level carry and sum
	module ADD (
		input[1:0] a, b, c_in,
		output[1:0] s, c_out
	);
	assign s = a ^ b ^ c_in;
	assign c_out = (a & b) | (a & c_in) | (b & c_in);
	endmodule

	// Submodule for computing final carry and propagate outputs
	module G_P (
		input[1:0] c_out1, c_out2,
		output g_out, p_out
	);
	assign g_out = c_out1 | c_out2;
	assign p_out = c_out1 & c_out2;
	endmodule

	// Instantiate ADD submodules for each bit of the inputs
	ADD add1 (.a(a[0]), .b(b[0]), .c_in(c_in), .s(s[0]), .c_out(c_out1));
	ADD add2 (.a(a[1]), .b(b[1]), .c_in(c_out1), .s(s[1]), .c_out(c_out2));

	// Instantiate G_P submodule to compute final carry and propagate outputs
	G_P g_p (.c_out1(c_out1), .c_out2(c_out2), .g_out(g_out), .p_out(p_out));

endmodule

module CFGLUT5 (CDO, O5, O6, CDI, CE, CLK, I0, I1, I2, I3, I4);

    output CDO;
    output O5;
    output O6;

    input  I4, I3, I2, I1, I0;
    input  CDI, CE, CLK;

    reg [4:0] address;
    reg [7:0] data;
    reg [7:0] lut_data;
    reg [7:0] output_data;

    // Initial block to set the default data value
    initial begin
        data = 8'b00000000;
    end

    // Always block for handling clocked operations
    always @(posedge CLK or posedge CE) begin
        if (CE) begin
            // Update address based on input I0-I4
            address = {I4, I3, I2, I1, I0};

            // Load serial data into the data register
            if (CDI) begin
                data = data << 1;
                data[7] = CDI;
            end

            // Update the LUT data with the current data
            lut_data = data;
        end
    end

    // Assign statements for continuous output driving
    assign CDO = lut_data[7];
    assign O5 = lut_data[6];
    assign O6 = lut_data[5];

endmodule

module add8_271(A, B, O);
  input [7:0] A;
  input [7:0] B;
  output [8:0] O;

  wire [19:0] N;

  // Duplicating bits from A and B and assigning them to N
  assign N[19:12] = A;
  assign N[11:4] = A;
  assign N[3:0] = A;
  assign N[19:12] = B;
  assign N[11:4] = B;
  assign N[3:0] = B;

  // Half-adders for each bit
  wire [1:0] half_adder_0 = N[19] ^ N[18], carry_0 = N[19] & N[18];
  wire [1:0] half_adder_1 = N[17] ^ N[16], carry_1 = N[17] & N[16];
  wire [1:0] half_adder_2 = N[15] ^ N[14], carry_2 = N[15] & N[14];
  wire [1:0] half_adder_3 = N[13] ^ N[12], carry_3 = N[13] & N[12];
  wire [1:0] half_adder_4 = N[11] ^ N[10], carry_4 = N[11] & N[10];
  wire [1:0] half_adder_5 = N[9] ^ N[8], carry_5 = N[9] & N[8];
  wire [1:0] half_adder_6 = N[7] ^ N[6], carry_6 = N[7] & N[6];
  wire [1:0] half_adder_7 = N[5] ^ N[4], carry_7 = N[5] & N[4];
  wire [1:0] half_adder_8 = N[3] ^ N[2], carry_8 = N[3] & N[2];
  wire [1:0] half_adder_9 = N[1] ^ N[0], carry_9 = N[1] & N[0];

  // Full-adders for carry propagation
  wire [1:0] full_adder_0 = half_adder_0 + carry_0;
  wire [1:0] full_adder_1 = half_adder_1 + carry_1;
  wire [1:0] full_adder_2 = half_adder_2 + carry_2;
  wire [1:0] full_adder_3 = half_adder_3 + carry_3;
  wire [1:0] full_adder_4 = half_adder_4 + carry_4;
  wire [1:0] full_adder_5 = half_adder_5 + carry_5;
  wire [1:0] full_adder_6 = half_adder_6 + carry_6;
  wire [1:0] full_adder_7 = half_adder_7 + carry_7;
  wire [1:0] full_adder_8 = half_adder_8 + carry_8;
  wire [1:0] full_adder_9 = half_adder_9 + carry_9;

  // Assigning the final 9-bit output
  assign O[8] = full_adder_9[1];
  assign O[7:0] = full_adder_9[0] + full_adder_8[0];

endmodule

module bw_u1_oai222_4x (
    z,
    c1,
    c2,
    b1,
    b2,
    a1,
    a2 );
output z;
input  c1;
input  c2;
input  b1;
input  b2;
input  a1;
input  a2;

// Compute the OR of two inputs
wire or1 = c1 | c2;
wire or2 = b1 | b2;
wire or3 = a1 | a2;

