module tb_file_to_dvp
#(
	parameter FILE     = "in.bin",
	parameter BITS     = 8, 
	parameter H_FRONT  = 50,
	parameter H_PULSE  = 100,
	parameter H_BACK   = 50,
	parameter H_DISP   = 1280,
	parameter V_FRONT  = 10,
	parameter V_PULSE  = 20,
	parameter V_BACK   = 10,
	parameter V_DISP   = 960,
	parameter H_POL    = 0,
	parameter V_POL    = 1
)
(
	input             xclk,
	input             rst_n,
	output            pclk,
	output reg        href,
	output reg        hsync,
	output reg        vsync,
	output [BITS-1:0] data
);

// Internal parameters
localparam H_TOTAL = H_FRONT + H_PULSE + H_BACK + H_DISP;
localparam V_TOTAL = V_FRONT + V_PULSE + V_BACK + V_DISP;

// Internal registers
reg [BITS-1:0] raw_data;
reg [15:0] pix_cnt;
reg [15:0] line_cnt;
reg [15:0] data_cnt;

// File read buffer
reg [BITS-1:0] file_buffer[0:H_TOTAL*V_TOTAL-1];
reg [15:0] file_buffer_index = 0;

// File read process
always @(posedge xclk or negedge rst_n) begin
	if (!rst_n) begin
		file_buffer_index <= 0;
		for (int i = 0; i < H_TOTAL*V_TOTAL; i++) begin
			file_buffer[i] <= 0;
		end
	end else begin
		if (file_buffer_index < H_TOTAL*V_TOTAL) begin
			file_buffer[file_buffer_index] <= $freadnxtb(FILE, file_buffer_index, BITS);
			file_buffer_index <= file_buffer_index + 1;
		end
	end
end

// Pixel and line counters
always @(posedge xclk or negedge rst_n) begin
	if (!rst_n) begin
		pix_cnt <= 0;
		line_cnt <= 0;
		data_cnt <= 0;
	end else begin
		if (pix_cnt < H_TOTAL-1) begin
			pix_cnt <= pix_cnt + 1;
		end else begin
			pix_cnt <= 0;
			if (line_cnt < V_TOTAL-1) begin
				line_cnt <= line_cnt + 1;
			end else begin
				line_cnt <= 0;
			end
		end
	end
end

// Pixel data output
always @(posedge xclk or negedge rst_n) begin
	if (!rst_n) begin
		data <= 0;
		href <= 0;
		hsync <= 0;
		vsync <= 0;
	end else begin
		if (pix_cnt < H_FRONT) begin
			href <= 1;
		end else if (pix_cnt < H_FRONT + H_PULSE) begin
			href <= 0;
		end else if (pix_cnt < H_TOTAL) begin
			href <= 1;
			data <= file_buffer[data_cnt];
			data_cnt <= data_cnt + 1;
		end else begin
			href <= 0;
			data <= 0;
			data_cnt <= 0;
		end

		if (line_cnt < V_FRONT) begin
			vsync <= 1;
		end else if (line_cnt < V_FRONT + V_PULSE) begin
			vsync <= 0;
		end else if (line_cnt < V_TOTAL) begin
			vsync <= 1;
		end else begin
			vsync <= 0;
		end

		if (pix_cnt < H_FRONT + H_PULSE) begin
			hsync <= 1;
		end else if (pix_cnt < H_TOTAL) begin
			hsync <= 0;
		end else begin
			hsync <= 1;
		end
	end
end

// Clock assignment
assign pclk = xclk;

endmodule

