module uart_tx_tester (
    input clk_50M,
    input run_test_raw,
    input tx_busy,
    output reg [7:0] data_out,
    output reg trigger
);

    // Parameters
    parameter MSG_DELAY = 10000000; // 10000000 clock cycles = 200000 microseconds = 200 milliseconds
    parameter DATA_LENGTH = 13; // Length of the message "Hello World! " including the null terminator
    parameter STATE_IDLE = 0;
    parameter STATE_LOAD_DATA = 1;
    parameter STATE_TRIGGER_TX = 2;
    parameter STATE_POLL_BUSY = 3;
    parameter STATE_PAUSE = 4;

    // Internal registers
    reg [7:0] data_reg;
    reg [2:0] state;
    reg [31:0] delay_counter;
    reg [31:0] poll_counter;
    reg [31:0] pause_counter;

    // State machine
    always @(posedge clk_50M) begin
        case (state)
            STATE_IDLE: begin
                if (run_test_raw) begin
                    state <= STATE_LOAD_DATA;
                    data_reg <= 8'h20; // Start with a space
                    delay_counter <= MSG_DELAY;
                end
            end
            STATE_LOAD_DATA: begin
                if (delay_counter == 0) begin
                    state <= STATE_TRIGGER_TX;
                    data_reg <= 8'h48; // 'H'
                    delay_counter <= 1000000; // 1000000 clock cycles = 20000 microseconds = 200 milliseconds
                end else begin
                    delay_counter <= delay_counter - 1;
                end
            end
            STATE_TRIGGER_TX: begin
                if (delay_counter == 0) begin
                    state <= STATE_POLL_BUSY;
                    trigger <= 1'b1;
                    delay_counter <= 1000000; // 1000000 clock cycles = 20000 microseconds = 200 milliseconds
                end else begin
                    delay_counter <= delay_counter - 1;
                end
            end
            STATE_POLL_BUSY: begin
                if (tx_busy) begin
                    state <= STATE_POLL_BUSY;
                end else begin
                    state <= STATE_PAUSE;
                    poll_counter <= 1000000; // 1000000 clock cycles = 20000 microseconds = 200 milliseconds
                end
            end
            STATE_PAUSE: begin
                if (poll_counter == 0) begin
                    state <= STATE_LOAD_DATA;
                    data_reg <= 8'h20; // Start with a space
                    delay_counter <= MSG_DELAY;
                end else begin
                    poll_counter <= poll_counter - 1;
                end
            end
        endcase
    end

    // Data output
    always @(posedge clk_50M) begin
        if (state == STATE_LOAD_DATA) begin
            data_out <= data_reg;
        end
    end

    // Trigger output
    always @(posedge clk_50M) begin
        if (state == STATE_TRIGGER_TX) begin
            trigger <= 1'b0;
        end
    end

endmodule

