module maxFinder #(parameter numInput=10, parameter inputWidth=16)(
    input           i_clk,
    input [(numInput*inputWidth)-1:0]   i_data,
    input           i_valid,
    output reg [31:0] o_data,
    output reg     o_data_valid
) {
    reg [31:0] maxValue;
    reg [(numInput*inputWidth)-1:0] inDataBuffer;
    reg [31:0] counter;
    reg [31:0] maxIndex;

    always @(posedge i_clk) begin
        if (i_valid) begin
            // Store the new input data in the buffer
            inDataBuffer <= i_data;
            counter <= counter + 1;
            // Start a new search if all inputs have been processed
            if (counter == numInput) begin
                maxValue <= inDataBuffer[0];
                maxIndex <= 0;
                for (int i = 1; i < numInput; i++) begin
                    if (inDataBuffer[i] > maxValue) begin
                        maxValue <= inDataBuffer[i];
                        maxIndex <= i;
                    end
                end
                o_data_valid <= 1;
            end
        end else begin
            // Reset the counter and clear the valid output
            counter <= 0;
            o_data_valid <= 0;
        end
    end

    // Output the index of the maximum value
    assign o_data = maxIndex;
}

