module gtx_tx_reset_controller(
    input wire clk,
    input wire ref_clk,
    input wire powerup_channel,
    output reg tx_running,
    output reg txreset,
    output reg txuserrdy,
    output reg txpmareset,
    output reg txpcsreset,
    output reg pllpd,
    output reg pllreset,
    output reg plllocken,
    input wire plllock,
    output reg resetsel,
    input wire txresetdone
);

    // State machine states
    typedef enum {IDLE, PLL_RESET, PLL_LOCK, TX_RESET, TX_READY, TX_RUNNING} state_t;
    state_t current_state, next_state;

    // Counter for reference clock detection
    reg [15:0] ref_clk_counter;

    // Meta registers for synchronization
    reg [1:0] meta_reg;

    // Reset control signals
    reg txreset_internal;
    reg txuserrdy_internal;
    reg txpmareset_internal;
    reg txpcsreset_internal;
    reg pllpd_internal;
    reg pllreset_internal;
    reg plllocken_internal;
    reg resetsel_internal;

    // State machine logic
    always @(posedge clk or posedge powerup_channel) begin
        if (powerup_channel) begin
            current_state <= IDLE;
        end else begin
            current_state <= next_state;
        end
    end

    always @(posedge clk) begin
        // Update meta registers
        meta_reg <= {meta_reg[0], current_state};

        // Update internal reset control signals
        txreset_internal <= (current_state == TX_RUNNING) ? 1'b0 : txreset;
        txuserrdy_internal <= (current_state == TX_RUNNING) ? 1'b1 : txuserrdy;
        txpmareset_internal <= (current_state == TX_RUNNING) ? 1'b0 : txpmareset;
        txpcsreset_internal <= (current_state == TX_RUNNING) ? 1'b0 : txpcsreset;
        pllpd_internal <= (current_state == PLL_LOCK) ? 1'b1 : pllpd;
        pllreset_internal <= (current_state == PLL_LOCK) ? 1'b0 : pllreset;
        plllocken_internal <= (current_state == PLL_LOCK) ? 1'b1 : plllocken;
        resetsel_internal <= (current_state == PLL_LOCK) ? 1'b0 : resetsel;

        // Update output signals
        txreset <= txreset_internal;
        txuserrdy <= txuserrdy_internal;
        txpmareset <= txpmareset_internal;
        txpcsreset <= txpcsreset_internal;
        pllpd <= pllpd_internal;
        pllreset <= pllreset_internal;
        plllocken <= plllocken_internal;
        resetsel <= resetsel_internal;

        // Update reference clock counter
        if (ref_clk) begin
            ref_clk_counter <= ref_clk_counter + 1'b1;
        end else begin
            ref_clk_counter <= 16'b0;
        end

        // State transition logic
        case (current_state)
            IDLE: begin
                if (plllock) begin
                    next_state <= PLL_RESET;
                end else begin
                    next_state <= IDLE;
                end
            end
            PLL_RESET: begin
                if (pllresetdone) begin
                    next_state <= PLL_LOCK;
                end else begin
                    next_state <= PLL_RESET;
                end
            end
            PLL_LOCK: begin
                if (txresetdone) begin
                    next_state <= TX_RESET;
                end else begin
                    next_state <= PLL_LOCK;
                end
            end
            TX_RESET: begin
                if (txresetdone) begin
                    next_state <= TX_READY;
                end else begin
                    next_state <= TX_RESET;
                end
            end
            TX_READY: begin
                if (plllock) begin
                    next_state <= TX_RUNNING;
                end else begin
                    next_state <= TX_READY;
                end
            end
            TX_RUNNING: begin
                if (!plllock) begin
                    next_state <= TX_READY;
                end else begin
                    next_state <= TX_RUNNING;
                end
            end
            default: begin
                next_state <= IDLE;
            end
        endcase
    end

    // Output tx_running based on PLL lock and reset completion
    always @(posedge clk) begin
        if (plllock && txresetdone) begin
            tx_running <= 1'b1;
        end else begin
            tx_running <= 1'b0;
        end
    end

endmodule

