module RC_30_30(
    input [29:0] IN1,
    input [29:0] IN2,
    output [30:0] Out
);

// Define the number of bits for the lower and upper parts
localparam LOWER_BITS = 24;
localparam UPPER_BITS = 6;

// Instantiate the lower 24-bit adder using approx_fa_17_4
genvar i;
generate
    for (i = 0; i < LOWER_BITS; i = i + 1) begin
        approx_fa_17_4 lower_adder (
            .A(IN1[i]),
            .B(IN2[i]),
            .C(IN1[i + 1]),
            .D(IN2[i + 1]),
            .S(Out[i]),
            .C(Out[i + 1])
        );
    end
endgenerate

// Instantiate the upper 6-bit adder using FullAdder
FullAdder upper_adder (
    .A(IN1[LOWER_BITS]),
    .B(IN2[LOWER_BITS]),
    .C(Out[LOWER_BITS + 1]),
    .D(Out[LOWER_BITS + 1]),
    .S(Out[LOWER_BITS + 2]),
    .C(Out[LOWER_BITS + 3])
);

// Propagate the carry from the 29th bit addition to the 30th bit
assign Out[30] = Out[LOWER_BITS + 3];

endmodule

// FullAdder module definition
module FullAdder (
    input A,
    input B,
    input C,
    input D,
    output S,
    output C
);

    assign S = A ^ B ^ C ^ D;
    assign C = (A & B) | (A & C) | (B & C);

endmodule

