module datapath(clk, startGameEn, user_x, user_y, enemy_x, enemy_y, enem_grid, x, y, colour);
    input clk; 
    input startGameEn; 
    input [7:0]user_x; 
    input [6:0]user_y; 
    input [7:0]enemy_x; 
    input [6:0]enemy_y; 
    input [160*120-1:0] enem_grid; 
    output reg [7:0] x; 
    output reg [6:0] y; 
    output reg[2:0] colour;

    reg [7:0] x_reg;
    reg [6:0] y_reg;
    reg clear;

    always @(posedge clk) begin
        if (startGameEn) begin
            x_reg <= 0;
            y_reg <= 0;
            clear <= 1;
        end else if (!clear) begin
            if (x_reg < 160 && y_reg < 120) begin
                if (x_reg == user_x && y_reg == user_y) begin
                    colour <= 3'b001; // User position
                elsif (x_reg == enemy_x && y_reg == enemy_y) begin
                    colour <= 3'b010; // Enemy position
                elsif (enem_grid[(y_reg * 160) + x_reg] == 1) begin
                    colour <= 3'b100; // Grid-based element
                else begin
                    colour <= 3'b000; // Default color
                end
                x_reg <= x_reg + 1;
                if (x_reg == 160) begin
                    x_reg <= 0;
                    y_reg <= y_reg + 1;
                    if (y_reg == 120) begin
                        y_reg <= 0;
                        clear <= 1;
                    end
                end
            end
        end
    end
endmodule

module Start_UP_Handler(
    input wire i_CLK,
    output wire o_RST
);

    // Parameters for clock frequency and initial reset time
    parameter g_Clock_Frequency = 100000000; // 100 MHz
    parameter g_Initial_Reset_Time = 1000000; // 1 ms

    // Calculate the number of clock cycles for the initial reset
    localparam c_Initial_Reset_Clocks = g_Initial_Reset_Time / g_Clock_Frequency;

    // Register to hold the reset state
    reg r_RST;

    // Register to count clock cycles
    reg [31:0] r_RST_Counter;

    // Reset the counter and set the initial reset state
    always @(posedge i_CLK) begin
        if (r_RST_Counter == 0) begin
            r_RST <= 1'b1; // Initial reset
            r_RST_Counter <= c_Initial_Reset_Clocks - 1;
        end else begin
            r_RST <= 1'b0; // De-assert reset
            r_RST_Counter <= r_RST_Counter - 1;
        end
    end

    // Output the reset signal
    assign o_RST = r_RST;

endmodule

module sonar(
    input clk, rst_n,
    input do_measure,
    input sonar_pulse,
    output reg [7:0] inches,
    output reg sonar_trigger = 0,
    output reg READY = 0
);

    // State definitions
    typedef enum {STANDBY, START_MEASURE, WAIT_FOR_PULSE, COUNT_PULSE} state_t;
    state_t current_state, next_state;

    // Internal registers
    reg [15:0] timeCount;
    reg [15:0] timeoutCounter;

    // Initial state
    initial begin
        current_state = STANDBY;
    end

    // State machine
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            current_state <= STANDBY;
            timeCount <= 0;
            timeoutCounter <= 0;
            sonar_trigger <= 0;
            inches <= 0;
            READY <= 0;
        end else begin
            current_state <= next_state;

            case (current_state)
                STANDBY: begin
                    if (do_measure) begin
                        next_state = START_MEASURE;
                    end else begin
                        next_state = STANDBY;
                    end
                end

                START_MEASURE: begin
                    sonar_trigger <= 1;
                    next_state = WAIT_FOR_PULSE;
                end

                WAIT_FOR_PULSE: begin
                    if (sonar_pulse) begin
                        next_state = COUNT_PULSE;
                    end else begin
                        next_state = WAIT_FOR_PULSE;
                    end
                end

                COUNT_PULSE: begin
                    if (!sonar_pulse) begin
                        timeCount <= timeCount + 1;
                        next_state = STANDBY;
                    end else begin
                        next_state = COUNT_PULSE;
                    end
                end

                default: begin
                    next_state = STANDBY;
                end
            endcase

            // Timeout handling
            if (current_state != START_MEASURE && current_state != COUNT_PULSE) begin
                timeoutCounter <= timeoutCounter + 1;
                if (timeoutCounter == 10000) begin // 10000 clock cycles timeout
                    next_state = STANDBY;
                    timeCount <= 0;
                    timeoutCounter <= 0;
                end
            end
        end
    end

    // Distance calculation
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            inches <= 0;
        end else begin
            if (current_state == COUNT_PULSE) begin
                // Assuming a speed of 1125000000 Hz (11.25 MHz) for the sonar
                // and a pulse duration of 10 microseconds (10000 clock cycles)
                // Calculate distance in inches
                inches <= (timeCount * 1125000000 / 1000000000) / 2;
            end
        end
    end

    // READY output
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            READY <= 0;
        end else begin
            if (current_state == STANDBY) begin
                READY <= 1;
            end else begin
                READY <= 0;
            end
        end
    end

endmodule

