module voting (a0, a1, a2, a3, a4, out);

input    [2:0]   a0, a1, a2, a3, a4;
output reg [2:0]   out;

// Internal signals for sum calculation
reg [2:0] sum0, sum1, sum2;
reg [2:0] error0, error1, error2;

// Custom adder2 module for sum calculation
module adder2 (a, b, cin, sum, cout);
    input [2:0] a, b, cin;
    output [2:0] sum;
    output cout;

    assign sum = a + b + cin;
    assign cout = sum[3];
endmodule

// Sum calculation for each bit position
assign sum0 = a0[0] + a1[0] + a2[0] + a3[0] + a4[0];
assign sum1 = a0[1] + a1[1] + a2[1] + a3[1] + a4[1];
assign sum2 = a0[2] + a1[2] + a2[2] + a3[2] + a4[2];

// Error detection for each bit position
assign error0 = (sum0 > 2) | (sum0 < 0);
assign error1 = (sum1 > 2) | (sum1 < 0);
assign error2 = (sum2 > 2) | (sum2 < 0);

// Determine the majority vote or error
always @(*) begin
    if (error0) out = 3'b100; // Error in sum0
    else if (error1) out = 3'b010; // Error in sum1
    else if (error2) out = 3'b001; // Error in sum2
    else if (sum0 > sum1 && sum0 > sum2) out = 3'b000; // sum0 is the majority
    else if (sum1 > sum0 && sum1 > sum2) out = 3'b011; // sum1 is the majority
    else if (sum2 > sum0 && sum2 > sum1) out = 3'b101; // sum2 is the majority
    else out = 3'b111; // All sums are equal, error
end

endmodule

