module file_writer(
    input     clk,
    input     rst,
    input     [63:0] input_a,
    input     input_a_stb,
    output    input_a_ack
);

    // Parameters
    parameter DATA_WIDTH = 64;
    parameter FILE_NAME = "resp_z";

    // Internal signals
    reg [DATA_WIDTH-1:0] value;
    reg [DATA_WIDTH-1:0] part1;
    reg [DATA_WIDTH-1:0] part2;
    reg [1:0] state;
    reg s_input_a_ack;

    // File handle
    reg [31:0] file_handle;

    // FSM
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= 0;
            value <= 0;
            part1 <= 0;
            part2 <= 0;
            s_input_a_ack <= 0;
            file_handle <= 0;
        end else begin
            case (state)
                0: begin
                    if (input_a_stb) begin
                        value <= input_a;
                        state <= 1;
                        s_input_a_ack <= 1;
                    end
                end
                1: begin
                    part1 <= value[31:0];
                    part2 <= value[63:32];
                    state <= 2;
                    s_input_a_ack <= 1;
                end
                2: begin
