module CIRCUIT2(
    input [31:0] a, b, c,
    input Clk, Rst,
    output [31:0] x, z
);

    // Internal signals
    wire [31:0] sum_ab, sum_ac, diff_ab;
    wire [31:0] result_add, result_sub;
    wire [31:0] result_mux;
    wire [31:0] shift_result;
    wire [31:0] x_reg, z_reg;
    wire [31:0] compare_result;
    wire [31:0] shift_amount;

    // Comparator to determine shift amount
    always @(posedge Clk or posedge Rst) begin
        if (Rst) begin
            compare_result <= 0;
        end else begin
            compare_result <= (sum_ab > sum_ac) ? 1 : 0;
        end
    end

    // Adders
    adder #(.WIDTH(32)) adder_ab (.a(a), .b(b), .sum(sum_ab));
    adder #(.WIDTH(32)) adder_ac (.a(a), .b(c), .sum(sum_ac));
    subtractor #(.WIDTH(32)) subtractor_ab (.a(a), .b(b), .diff(diff_ab));

    // Multiplexers
    always @(posedge Clk or posedge Rst) begin
        if (Rst) begin
            result_mux <= 0;
        end else begin
            result_mux <= (compare_result) ? sum_ab : sum_ac;
        end
    end

    // Shifters
    always @(posedge Clk or posedge Rst) begin
        if (Rst) begin
            shift_amount <= 0;
        end else begin
            shift_amount <= (compare_result) ? 1 : 0;
        end
    end

    shifter #(.WIDTH(32)) shifter_left (.data(result_mux), .amount(shift_amount), .shifted_data(shift_result));
    shifter #(.WIDTH(32)) shifter_right (.data(result_mux), .amount(~shift_amount), .shifted_data(shift_result));

    // Registers
    always @(posedge Clk or posedge Rst) begin
        if (Rst) begin
            x_reg <= 0;
            z_reg <= 0;
        end else begin
            x_reg <= shift_result;
            z_reg <= shift_result;
        end
    end

    // Outputs
    assign x = x_reg;
    assign z = z_reg;

endmodule

// Adder module
module adder #(parameter WIDTH = 32) (
    input [WIDTH-1:0] a,
    input [WIDTH-1:0] b,
    output reg [WIDTH-1:0] sum
);
    assign sum = a + b;
endmodule

// Subtractor module
module subtractor #(parameter WIDTH = 32) (
    input [WIDTH-1:0] a,
    input [WIDTH-1:0] b,
    output reg [WIDTH-1:0] diff
);
    assign diff = a - b;
endmodule

// Shifter module
module shifter #(parameter WIDTH = 32) (
    input [WIDTH-1:0] data,
    input [WIDTH-1:0] amount,
    output reg [WIDTH-1:0] shifted_data
);
    always @(*) begin
        shifted_data = {data[WIDTH-1:amount], data[amount-1:0]};
    end
endmodule

