module FPAddSub_d (
    input ZeroSum,
    input [8:0] NormE,
    input [22:0] NormM,
    input R,
    input S,
    input G,
    input Sa,
    input Sb,
    input Ctrl,
    input MaxAB,
    input NegE,
    input [4:0] InputExc,
    output [31:0] P,
    output [4:0] Flags
);

    // Constants
    localparam MAX_EXP = 127;
    localparam MIN_EXP = -126;
    localparam MAX_MANTISSA = 2047;
    localparam MIN_MANTISSA = 1;

    // Variables
    reg [8:0] E1, E2, E3;
    reg [22:0] M1, M2, M3;
    reg [31:0] Result;
    reg [4:0] Flags;

    // Helper functions
    function [8:0] addExponents(input [8:0] a, input [8:0] b);
        return a + b;
    endfunction

    function [22:0] addMantissas(input [22:0] a, input [22:0] b);
        return a + b;
    endfunction

    function [8:0] adjustExponent(input [8:0] e, input [22:0] m);
        if (e == MAX_EXP) begin
            return MAX_EXP;
        end else if (e == MIN_EXP) begin
            return MIN_EXP;
        end else if (m == 0) begin
            return MIN_EXP;
        end else begin
            return e;
        end
    endfunction

    function [22:0] normalizeMantissa(input [22:0] m);
        if (m == 0) begin
            return 0;
        end else begin
            return m;
        end
    endfunction

    function [4:0] setFlags(input [31:0] result, input [4:0] inputExc);
        if (result == 0) begin
            Flags = Flags | 1'b1; // ZeroSum
        end else if (result == MAX_MANTISSA) begin
            Flags = Flags | 1'b2; // Overflow
        end else if (result == MIN_MANTISSA) begin
            Flags = Flags | 1'b4; // Underflow
        end else if (inputExc != 5'b00000) begin
            Flags = Flags | 1'b8; // Invalid Operation
        end else if (result != 0 && result != MAX_MANTISSA && result != MIN_MANTISSA) begin
            Flags = Flags | 1'b16; // Inexact
        end else begin
            Flags = Flags | 1'b31; // All flags set
        end
        return Flags;
    endfunction

    // Main logic
    always @(*) begin
        if (ZeroSum) begin
            P = 0;
            Flags = 1'b1; // ZeroSum
        end else if (Ctrl == 2'b00) begin // Addition
            E1 = addExponents(NormE, NormE);
            M1 = addMantissas(NormM, NormM);
            E3 = adjustExponent(E1, M1);
            M3 = normalizeMantissa(M1);
            P = {E3, M3};
            Flags = setFlags(P, InputExc);
        end else if (Ctrl == 2'b01) begin // Subtraction
            E1 = addExponents(NormE, ~NormE + 1);
            M1 = addMantissas(NormM, ~NormM + 1);
            E3 = adjustExponent(E1, M1);
            M3 = normalizeMantissa(M1);
            P = {E3, M3};
            Flags = setFlags(P, InputExc);
        end else if (Ctrl == 2'b10) begin // Rounding
            E1 = addExponents(NormE, NormE);
            M1 = addMantissas(NormM, NormM);
            E3 = adjustExponent(E1, M1);
            M3 = normalizeMantissa(M1);
            P = {E3, M3};
            Flags = setFlags(P, InputExc);
        end else if (Ctrl == 2'b11) begin // MaxAB
            E1 = addExponents(NormE, NormE);
            M1 = addMantissas(NormM, NormM);
            E3 = adjustExponent(E1, M1);
            M3 = normalizeMantissa(M1);
            P = {E3, M3};
            Flags = setFlags(P, InputExc);
        end
    end

endmodule

