// Full adder module
module full_adder #(parameter N = 1)
  (
  input [N-1:0] a,
  input [N-1:0] b,
  input cin,
  output [N-1:0] sum,
  output cout
  );

  wire [N:0] sum_internal;
  wire [N:0] carry_internal;

  // Sum calculation
  assign sum_internal = a ^ b ^ cin;

  // Carry calculation
  assign carry_internal = (a & b) | (a & cin) | (b & cin);

  // Output
  assign sum = sum_internal[N-1:0];
  assign cout = carry_internal[N];

endmodule

