        rco3 <= 1'b0;
        c_out0 <= 1'b0;
        c_out1 <= 1'b0;
        c_out2 <= 1'b0;
        c_out3 <= 1'b0;
    end

    // Ripple-carry adder for each digit
    always @(posedge clk) begin
        if (grst) begin
            rco0 <= 1'b0;
            rco1 <= 1'b0;
            rco2 <= 1'b0;
            rco3 <= 1'b0;
            c_out0 <= 1'b0;
            c_out1 <= 1'b0;
            c_out2 <= 1'b0;
            c_out3 <= 1'b0;
        end else begin
            // Digit 0
            rco0 <= enable & c_out0;
            c_out0 <= digit0 + 1'b1;
            digit0 <= digit0 + 1'b1;

            // Digit 1
            rco1 <= enable & c_out1;
            c_out1 <= digit1 + 1'b1;
            digit1 <= digit1 + 1'b1;

            // Digit 2
            rco2 <= enable & c_out2;
            c_out2 <= digit2 + 1'b1;
            digit2 <= digit2 + 1'b1;

            // Digit 3
            rco3 <= enable & c_out3;
            c_out3 <= digit3 + 1'b1;
            digit3 <= digit3 + 1'b1;
        end
    end

    // Concatenate the four digits to form the 16-bit count
    assign count = {digit3, digit2, digit1, digit0};

    // Calculate the carryout
    assign cout = c_out3;

