reg [15:0] carry;
reg [15:0] temp;

// Partial product generation
always @(*) begin
    sum = 0;
    carry = 0;
    for (int i = 0; i < 8; i++) begin
        temp = IN1[i] * IN2;
        sum = sum + temp;
        carry = carry + (temp >> 8);
    end
end

// Digit tree reduction
always @(*) begin
    Out = sum;
    for (int i = 0; i < 7; i++) begin
        Out = Out + (carry >> (7 - i));
        carry = carry << 1;
    end
end

endmodule

