module full_adder (i_a, i_b, i_carry, o_sum, o_carry);
    input [1:0] i_a;
    input [1:0] i_b;
    input i_carry;
    output [1:0] o_sum;
    output o_carry;

    // Intermediate wires for each bit position
    wire [1:0] sum0, sum1;
    wire carry0, carry1;

    // Lower bit (bit 0) calculation
    sum0 = i_a[0] ^ i_b[0] ^ i_carry;
    carry0 = (i_a[0] & i_b[0]) | (i_a[0] & i_carry) | (i_b[0] & i_carry);

    // Higher bit (bit 1) calculation
    sum1 = i_a[1] ^ i_b[1] ^ carry0;
    carry1 = (i_a[1] & i_b[1]) | (i_a[1] & carry0) | (i_b[1] & carry0);

    // Output the sum and carry
    o_sum = {sum1, sum0};
    o_carry = carry1;
endmodule

