module tb_ALU();
    // Parameters
    parameter CLOCK_PERIOD = 10;
    parameter RESET_ASSERT_TIME = 27;
    parameter TEST_VECTOR_SIZE = 27;
    parameter TEST_VECTOR_COUNT = 10001;

    // Inputs
    reg clk;
    reg reset;
    reg [TEST_VECTOR_SIZE-1:0] testvectors;

    // Outputs
    wire [TEST_VECTOR_SIZE-1:0] Result;
    wire zeroflag;
    wire [TEST_VECTOR_SIZE-1:0] error;

    // Instantiate the ALU
    ALU alu(
        .clk(clk),
        .reset(reset),
        .A(testvectors[TEST_VECTOR_SIZE-1:TEST_VECTOR_SIZE-16]),
        .B(testvectors[TEST_VECTOR_SIZE-16:TEST_VECTOR_SIZE-8]),
        .opcode(testvectors[TEST_VECTOR_SIZE-8:TEST_VECTOR_SIZE-4]),
        .Result(Result),
        .zeroflag(zeroflag),
        .error(error)
    );

    // Clock generation
    always begin
        clk = 1'b0;
        #CLOCK_PERIOD;
        clk = 1'b1;
        #CLOCK_PERIOD;
    end

    // Reset generation
    reg [RESET_ASSERT_TIME-1:0] reset_counter;
    always begin
        reset = 1'b1;
        reset_counter = RESET_ASSERT_TIME;
        forever begin
            #1;
            reset_counter = reset_counter - 1;
            if (reset_counter == 0) begin
                reset = 1'b0;
            end
        end
    end

    // Test vector generation
    reg [TEST_VECTOR_SIZE-1:0] current_testvector;
    reg [TEST_VECTOR_SIZE-1:0] expected_result;
    reg [TEST_VECTOR_SIZE-1:0] expected_zeroflag;
    reg [TEST_VECTOR_SIZE-1:0] expected_error;
    reg [TEST_VECTOR_SIZE-1:0] actual_result;
    reg [TEST_VECTOR_SIZE-1:0] actual_zeroflag;
    reg [TEST_VECTOR_SIZE-1:0] actual_error;
    reg [TEST_VECTOR_SIZE-1:0] test_vector_index;
    reg [TEST_VECTOR_SIZE-1:0] test_vector_count;
    reg [TEST_VECTOR_SIZE-1:0] test_vector_error_count;

    initial begin
        test_vector_index = 0;
        test_vector_count = TEST_VECTOR_COUNT;
        test_vector_error_count = 0;

        // Read test vectors from a file
        $readmemb("test_vectors.mem", testvectors);

        // Start the test
        while (test_vector_index < test_vector_count) begin
            // Extract current test vector
            current_testvector = testvectors[test_vector_index];

            // Extract expected results
            expected_result = current_testvector[TEST_VECTOR_SIZE-1:TEST_VECTOR_SIZE-16];
            expected_zeroflag = current_testvector[TEST_VECTOR_SIZE-16:TEST_VECTOR_SIZE-8];
            expected_error = current_testvector[TEST_VECTOR_SIZE-8:TEST_VECTOR_SIZE-4];

            // Apply inputs to the ALU
            alu.A = current_testvector[TEST_VECTOR_SIZE-1:TEST_VECTOR_SIZE-16];
            alu.B = current_testvector[TEST_VECTOR_SIZE-16:TEST_VECTOR_SIZE-8];
            alu.opcode = current_testvector[TEST_VECTOR_SIZE-8:TEST_VECTOR_SIZE-4];

            // Wait for the ALU to complete
            #CLOCK_PERIOD;

            // Read actual results
            actual_result = Result;
            actual_zeroflag = zeroflag;
            actual_error = error;

            // Compare actual results with expected results
            if (actual_result != expected_result) begin
                $display("Test vector %d failed: Result mismatch (expected %h, got %h)", test_vector_index, expected_result, actual_result);
                test_vector_error_count = test_vector_error_count + 1;
            end
            if (actual_zeroflag != expected_zeroflag) begin
                $display("Test vector %d failed: Zero flag mismatch (expected %b, got %b)", test_vector_index, expected_zeroflag, actual_zeroflag);
                test_vector_error_count = test_vector_error_count + 1;
            end
            if (actual_error != expected_error) begin
                $display("Test vector %d failed: Error mismatch (expected %b, got %b)", test_vector_index, expected_error, actual_error);
                test_vector_error_count = test_vector_error_count + 1;
            end

            // Move to the next test vector
            test_vector_index = test_vector_index + 1;
        end

        // Report test results
        $display("Test completed: %d tests passed, %d tests failed", test_vector_count - test_vector_error_count, test_vector_error_count);
    end
endmodule

