module preaddmul_3_stage_unsigned_10_bit(
    input  [9:0] a,
    input  [9:0] b,
    input  [9:0] d,
    output [9:0] out,
    input clk);

    // Internal registers to hold intermediate results
    reg [19:0] stage0;
    reg [19:0] stage1;
    reg [19:0] stage2;

    // First stage: compute (d + a) * b
    always @(posedge clk) begin
        stage0 <= (d + a) * b;
    end

    // Second stage: hold the result from the first stage
    always @(posedge clk) begin
        stage1 <= stage0;
    end

    // Third stage: pass the result to the output
    always @(posedge clk) begin
        out <= stage1;
    end

endmodule

