module lfsr (
    output reg [7:0] out,
    input wire enable,
    input wire clk,
    input wire reset
);

    // Internal register for the LFSR
    reg [7:0] lfsr_reg;

    // Feedback calculation
    wire feedback = lfsr_reg[7] ^ lfsr_reg[3];

    // Asynchronous reset
    always @(posedge reset) begin
        lfsr_reg <= 8'b00000000;
    end

    // Synchronous operation on the clock edge
    always @(posedge clk) begin
        if (reset) begin
            lfsr_reg <= 8'b00000000;
        end else if (enable) begin
            // Shift the register left by one bit
            lfsr_reg[7] <= lfsr_reg[6];
            lfsr_reg[6] <= lfsr_reg[5];
            lfsr_reg[5] <= lfsr_reg[4];
            lfsr_reg[4] <= lfsr_reg[3];
            lfsr_reg[3] <= lfsr_reg[2];
            lfsr_reg[2] <= lfsr_reg[1];
            lfsr_reg[1] <= lfsr_reg[0];
            // Apply feedback
            lfsr_reg[0] <= feedback;
        end
    end

    // Output the current state of the LFSR
    assign out = lfsr_reg;

endmodule

module submod (a, b, c);

   input a, b;
   output c;

   // Instantiate two copies of subsub module
   subsub subsub1 (.a(a), .b(b), .c1(c1));
   subsub subsub2 (.a(a), .b(b), .c2(c2));

   // Compute the final output c using XOR of c1 and c2
   assign c = c1 ^ c2;

endmodule

// Submodule definition
module subsub (a, b, c);

   input a, b;
   output c;

   // Compute c1 as the result of AND operation on a and b
   assign c1 = a & b;

   // Compute c2 as the result of OR operation on a and b
   assign c2 = a | b;

endmodule

module BaudTickGen (
    input clk,
    input enable,
    output reg tick
);

    // Parameters
    parameter ClkFrequency = 100000000; // Input clock frequency in Hz
    parameter Baud = 9600; // Desired baud rate in bits per second
    parameter Oversampling = 10; // Oversampling factor for accuracy

    // Calculate the number of bits needed for the accumulator
    localparam log2Acc = $clog2(Oversampling * Baud);

    // Internal registers
    reg [log2Acc-1:0] Acc;
    reg Inc;

    // Calculate the increment value for the accumulator
    always @(posedge clk) begin
        if (enable) begin
            Inc <= 1'b1;
        end else begin
            Inc <= 1'b0;
        end
    end

    // Accumulator logic
    always @(posedge clk) begin
        if (enable) begin
            Acc <= Acc + Inc;
        end
    end

    // Generate the tick signal when the accumulator overflows
    always @(posedge clk) begin
        if (Acc == (Oversampling * Baud - 1)) begin
            tick <= 1'b1;
        end else begin
            tick <= 1'b0;
        end
    end

endmodule

module submuladd_2_stage_unsigned_8_bit(
