    // Internal 16-bit registers to store intermediate results
    reg [15:0] stage0;
    reg [15:0] stage1;

    // Calculate the intermediate result for the first stage
    always @(posedge clk) begin
        stage0 <= (d - a) * b + c;
    end

    // Calculate the final result for the second stage
    always @(posedge clk) begin
        out <= stage0;
    end

endmodule

module vga_sync_pulse
(
    input   i_clk,
    output  o_hsync,
    output  o_vsync,
    output reg [9:0] o_col_count = 0,
    output reg [9:0] o_row_count = 0
);

parameter COLS = 640;
parameter ROWS = 480;
parameter ACTIVE_COLS = 640;
parameter ACTIVE_ROWS = 480;
parameter HSYNC_WIDTH = 8;
parameter VSYNC_WIDTH = 8;

reg [9:0] col_count;
reg [9:0] row_count;
reg [HSYNC_WIDTH-1:0] hsync_counter;
reg [VSYNC_WIDTH-1:0] vsync_counter;

always @(posedge i_clk) begin
    if (col_count == COLS - 1) begin
        col_count <= 0;
    end else begin
        col_count <= col_count + 1;
    end

    if (row_count == ROWS - 1) begin
        row_count <= 0;
    end else begin
        row_count <= row_count + 1;
    end

    if (col_count < ACTIVE_COLS) begin
        hsync_counter <= hsync_counter + 1;
        if (hsync_counter == HSYNC_WIDTH - 1) begin
            hsync_counter <= 0;
            o_hsync <= 1'b0;
        end else begin
            o_hsync <= 1'b1;
        end
    end else begin
        hsync_counter <= 0;
        o_hsync <= 1'b0;
    end

    if (row_count < ACTIVE_ROWS) begin
        vsync_counter <= vsync_counter + 1;
        if (vsync_counter == VSYNC_WIDTH - 1) begin
            vsync_counter <= 0;
            o_vsync <= 1'b0;
        end else begin
            o_vsync <= 1'b1;
        end
    end else begin
        vsync_counter <= 0;
        o_vsync <= 1'b0;
    end
end

endmodule

