module bridge_1x2(
    input                           clk,          
    input                           resetn,       
    input                           cpu_data_en,      
    input  [3                   :0] cpu_data_wen,     
    input  [31                  :0] cpu_data_addr,    
    input  [31                  :0] cpu_data_wdata,   
    output [31                  :0] cpu_data_rdata,   
    output                          data_sram_en,     
    output [3                   :0] data_sram_wen,    
    output [31                  :0] data_sram_addr,   
    output [31                  :0] data_sram_wdata,  
    input  [31                  :0] data_sram_rdata,  
    output                          conf_en,          
    output [3                   :0] conf_wen,         
    output [31                  :0] conf_addr,        
    output [31                  :0] conf_wdata,       
    input  [31                  :0] conf_rdata        
);

    // Parameters
    parameter CONF_ADDR_BASE = 32'h80000000;
    parameter CONF_ADDR_MASK = 32'h7FFFFFFF;

    // Signals
    reg [3                   :0] sel_sram;
    reg [3                   :0] sel_conf;
    reg [31                  :0] data_sram_addr;
    reg [31                  :0] data_sram_wdata;
    reg [31                  :0] conf_addr;
    reg [31                  :0] conf_wdata;

    // Register for sel_sram and sel_conf
    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            sel_sram <= 4'b0;
            sel_conf <= 4'b0;
        end else begin
            sel_sram <= cpu_data_addr[31:28];
            sel_conf <= cpu_data_addr[31:28];
        end
    end

    // Control signals for memories
    assign data_sram_en = cpu_data_en & (sel_sram == 4'b0);
    assign data_sram_wen = cpu_data_en & (sel_sram == 4'b0) & cpu_data_wen;
    assign data_sram_addr = cpu_data_addr[31:0];
    assign data_sram_wdata = cpu_data_wdata;

    assign conf_en = cpu_data_en & (sel_conf == 4'b1);
    assign conf_wen = cpu_data_en & (sel_conf == 4'b1) & cpu_data_wen;
    assign conf_addr = cpu_data_addr[31:0];
    assign conf_wdata = cpu_data_wdata;

    // CPU data read data
    assign cpu_data_rdata = (sel_sram == 4'b0) ? data_sram_rdata : conf_rdata;

endmodule

module rggen_apb_bridge #(
  parameter ADDRESS_WIDTH = 8,
  parameter BUS_WIDTH     = 32
)(
  input                             i_clk,
  input                             i_rst_n,
  input                             i_bus_valid,
  input   [1:0]                     i_bus_access,
  input   [ADDRESS_WIDTH-1:0]       i_bus_address,
  input   [BUS_WIDTH-1:0]           i_bus_write_data,
  input   [BUS_WIDTH/8-1:0]         i_bus_strobe,
  output                            o_bus_ready,
  output  [1:0]                     o_bus_status,
  output  [BUS_WIDTH-1:0]           o_bus_read_data,
  output                            o_psel,
  output                            o_penable,
  output  [ADDRESS_WIDTH-1:0]       o_paddr,
  output  [2:0]                     o_pprot,
  output                            o_pwrite,
  output  [BUS_WIDTH/8-1:0]         o_pstrb,
  output  [BUS_WIDTH-1:0]           o_pwdata,
  input                             i_pready,
  input   [BUS_WIDTH-1:0]           i_prdata,
  input                             i_pslverr
);

  // Parameters
  localparam NUM_STAGES = 2; // Number of stages in the state machine

  // Internal signals
  reg [NUM_STAGES-1:0] state;
  reg [NUM_STAGES-1:0] next_state;
  reg [BUS_WIDTH-1:0] read_data;
  reg [BUS_WIDTH-1:0] write_data;
  reg [ADDRESS_WIDTH-1:0] address;
  reg [BUS_WIDTH/8-1:0] strobe;
  reg [1:0] status;
  reg busy;

  // State machine
  always @(posedge i_clk or negedge i_rst_n) begin
    if (!i_rst_n) begin
      state <= 2'b00; // Reset to idle state
      busy <= 1'b0;
    end else begin
      state <= next_state;
      busy <= state[0];
    end
  end

  // State transitions
  always @(*) begin
    case (state)
      2'b00: begin // Idle
        if (i_bus_valid) begin
          next_state = 2'b01; // Start read/write
        end else begin
          next_state = 2'b00; // Stay idle
        end
      end
      2'b01: begin // Read/Write
        if (i_pready) begin
          next_state = 2'b02; // Wait for read/write completion
        end else begin
          next_state = 2'b01; // Stay in read/write
        end
      end
      2'b02: begin // Read/Write completion
        if (i_bus_valid) begin
          next_state = 2'b01; // Start next read/write
        end else begin
          next_state = 2'b00; // Return to idle
        end
      end
      default: begin
        next_state = 2'b00; // Invalid state, return to idle
      end
    endcase
  end

  // Control signals
  assign o_psel = state[0];
  assign o_penable = state[1];
  assign o_paddr = address;
  assign o_pprot = 3'b000; // Default protection
  assign o_pwrite = (i_bus_access == 2'b01); // Write access
  assign o_pstrb = strobe;
  assign o_pwdata = write_data;

  // Read/write logic
  always @(posedge i_clk or negedge i_rst_n) begin
    if (!i_rst_n) begin
      read_data <= 0;
      write_data <= 0;
      address <= 0;
      strobe <= 0;
      status <= 2'b00;
    end else begin
      if (state == 2'b01) begin
        if (i_bus_access == 2'b00) begin // Read
          read_data <= i_prdata;
          status <= 2'b01; // Read successful
        end else if (i_bus_access == 2'b01) begin // Write
          write_data <= i_bus_write_data;
          address <= i_bus_address;
          strobe <= i_bus_strobe;
          status <= 2'b00; // Write successful
        end
      end
    end
  end

  // Output signals
  assign o_bus_ready = state[0];
  assign o_bus_status = status;
  assign o_bus_read_data = read_data;

endmodule

module preaddmul_2_stage_unsigned_10_bit(
    input  [9:0] a,
    input  [9:0] b,
    input  [9:0] d,
    output [9:0] out,
