    output reg[31:0] ex32
);
    always @(*) begin
        // Extract the sign bit of ex16
        reg[15] sign_bit = ex16[15];

        // Create a 16-bit mask with all bits set to 1
        reg[15:0] mask = 16'hFFFF;

        // Create a 32-bit mask with the sign bit replicated 16 times
        reg[31:0] sign_extended_mask = {sign_bit, mask};

        // Perform the sign extension by shifting the sign bit 16 places to the left
        // and then ORing it with the original 16-bit value
        ex32 = {sign_extended_mask, ex16};
    end
endmodule

