module FIFO(
    input clock,
    input sclr,
    input rdreq,
    input wrreq,
    output reg full,
    output reg empty,
    input [7 : 0] data,
    output [7 : 0] q
);

    // Register declarations
    reg [15 : 0] mem [0 : 15];
    reg [3 : 0] wp;
    reg [3 : 0] rp;
    reg w_flag;
    reg r_flag;

    // Always block for sequential operations
    always @(posedge clock or posedge sclr) begin
        if (sclr) begin
            wp <= 4'b0000;
            rp <= 4'b0000;
            w_flag <= 1'b0;
            r_flag <= 1'b0;
            full <= 1'b0;
            empty <= 1'b1;
        end else begin
            if (wrreq && !full) begin
                mem[wp] <= data;
                wp <= wp + 1'b1;
                w_flag <= 1'b1;
            end
            if (rdreq && !empty) begin
                q <= mem[rp];
                rp <= rp + 1'b1;
                r_flag <= 1'b1;
            end
            // Update full and empty flags
            if (wp == rp) begin
                full <= 1'b1;
                empty <= 1'b0;
            end else begin
                full <= 1'b0;
                empty <= 1'b1;
            end
        end
    end

endmodule

