module AdderTreePipelined
#(
    parameter DATA_WIDTH=32,
    parameter LENGTH=8,
    parameter OUT_WIDTH=DATA_WIDTH+$clog2(LENGTH),
    parameter DELAT_STAGES=$clog2(LENGTH)
)
(
    input rst,
    input clk,
    input in_advance,
    input signed [LENGTH*DATA_WIDTH-1:0] in_addends,
    output signed [OUT_WIDTH-1:0] out_sum
);

// Helper function to calculate the sum of two numbers
function signed add_two_numbers(signed a, signed b);
    add_two_numbers = a + b;
endfunction

// Recursive function to process the addends
function void process_addends(signed [LENGTH*DATA_WIDTH-1:0] addends, output signed [OUT_WIDTH-1:0] sum);
    if (LENGTH == 1) begin
        sum = add_two_numbers(addends[0:DATA_WIDTH-1], addends[DATA_WIDTH:2*DATA_WIDTH-1]);
    end else begin
        signed [LENGTH/2*DATA_WIDTH-1:0] left_addends;
        signed [LENGTH/2*DATA_WIDTH-1:0] right_addends;
        signed [LENGTH/2*DATA_WIDTH-1:0] left_sum;
        signed [LENGTH/2*DATA_WIDTH-1:0] right_sum;

        // Split the addends into two halves
        left_addends = addends[0:LENGTH/2*DATA_WIDTH-1];
        right_addends = addends[LENGTH/2*DATA_WIDTH:LENGTH*DATA_WIDTH-1];

        // Process each half recursively
        process_addends(left_addends, left_sum);
        process_addends(right_addends, right_sum);

        // Combine the results
        sum = add_two_numbers(left_sum, right_sum);
    end
endfunction

// Main module logic
always @(posedge clk or posedge rst) begin
    if (rst) begin
        out_sum <= 0;
    end else if (in_advance) begin
        process_addends(in_addends, out_sum);
    end
end

endmodule

