module Test_ShiftLoadRegister(
    input wire clk,
    input wire rst,
    input wire load,
    input wire we,
    input wire [7:0] data_in,
    output reg [7:0] data_out
);

    // Instantiate the shift-load register
    ShiftLoadRegister #(.WIDTH(8)) shift_load_reg (
        .clk(clk),
        .rst(rst),
        .load(load),
        .we(we),
        .data_in(data_in),
        .data_out(data_out)
    );

    // Test sequence
    initial begin
        // Initialize the register
        data_out = 8'b00000000;

        // Apply a clock signal
        clk = 1'b0;
        #10;
        clk = 1'b1;
        #10;

        // Load data into the register
        load = 1'b1;
        data_in = 8'b11110000;
        #10;
        load = 1'b0;

        // Write enable to shift the register
        we = 1'b1;
        #10;
        we = 1'b0;

        // Apply another clock signal
        clk = 1'b0;
        #10;
        clk = 1'b1;
        #10;

        // Load data into the register again
        load = 1'b1;
        data_in = 8'b00001111;
        #10;
        load = 1'b0;

        // Write enable to shift the register again
        we = 1'b1;
        #10;
        we = 1'b0;

        // Apply another clock signal
        clk = 1'b0;
        #10;
        clk = 1'b1;
        #10;

        // Check the final state of the register
        $display("Final data_out: %b", data_out);
    end

endmodule

module Combination(a, b, c, out);
    input a, b, c;
    output out;

    wire w1, w2;

