module multi_seven_seg_6 (
    input clk,
    input rst,
    input [15:0] value,
    output reg [6:0] segs,
    output reg [3:0] sel
  );

  // Parameters
  parameter NUM_DIGITS = 4;
  parameter DIV_1 = 1;
  parameter DIV_2 = 2;
  parameter DIV_3 = 4;
  parameter DIV_4 = 8;
  parameter BIT_WIDTH = 16;

  // Internal signals
  reg [3:0] digit_counter;
  reg [3:0] digit_index;
  reg [6:0] segs_temp;
  reg [3:0] sel_temp;

  // Seven-segment decoder
  always @(posedge clk or posedge rst) begin
    if (rst) begin
      segs_temp <= 7'b1111111;
      sel_temp <= 4'b0000;
    end else begin
      case (digit_index)
        0: segs_temp <= 7'b1111110; // 0
        1: segs_temp <= 7'b0110000; // 1
        2: segs_temp <= 7'b1101101; // 2
        3: segs_temp <= 7'b1111001; // 3
        4: segs_temp <= 7'b0110011; // 4
        5: segs_temp <= 7'b1011011; // 5
        6: segs_temp <= 7'b1011111; // 6
        7: segs_temp <= 7'b1110001; // 7
        8: segs_temp <= 7'b1111111; // 8
        9: segs_temp <= 7'b1111011; // 9
        default: segs_temp <= 7'b1111111;
      endcase
      sel_temp <= digit_index;
    end
  end

  // Digit decoder
  always @(posedge clk or posedge rst) begin
    if (rst) begin
      digit_counter <= 0;
    end else begin
      digit_counter <= digit_counter + 1;
    end
  end

  // Combinational logic
  always @(*) begin
    if (digit_counter < NUM_DIGITS) begin
      segs <= segs_temp;
      sel <= sel_temp;
    end else begin
      segs <= 7'b1111111;
      sel <= 4'b0000;
    end
  end

endmodule

