module timer_variable(
    input wire zedboard_clk,
    input wire enable,
    input wire reset,
    output reg timerOutput
);

    // Define the timer value register
    reg [31:0] timer_value;

    // Reset the timer when reset is asserted
    always @(posedge reset) begin
        timer_value <= 32'b0;
        timerOutput <= 1'b0;
    end

    // Increment the timer value on each rising edge of the clock
    always @(posedge zedboard_clk) begin
        if (reset) begin
            timer_value <= 32'b0;
            timerOutput <= 1'b0;
        end else begin
            timer_value <= timer_value + 1'b1;
            if (timer_value == 32'd100000) begin
                timerOutput <= 1'b1;
                timer_value <= 32'b0;
            end else begin
                timerOutput <= 1'b0;
            end
        end
    end

endmodule

