module sr_latch(NQ, Q, S, R);
    output Q, NQ;
    input S, R;

    reg state;

    always @(posedge S or posedge R) begin
        if (S) begin
            state <= 1'b1;
        end else if (R) begin
            state <= 1'b0;
        end
    end

    assign Q = state;
    assign NQ = ~state;

    // Continuous assignments with a 5-time unit delay
    always @(posedge S or posedge R) begin
        #5 Q <= state;
        #5 NQ <= ~state;
    end
endmodule

