    output  logic [BE_WIDTH-1:0]              data_be_o,
    output  logic [ID_WIDTH-1:0]              data_ID_o,
    output  logic [AUX_WIDTH-1:0]             data_aux_o,
    input   logic                             data_gnt_i,

    input   logic                             clk,
    input   logic                             rst_n
)
{
    // Internal signals
    logic [1:0] current_channel;
    logic [1:0] next_channel;
    logic [1:0] rr_flag;
    logic [1:0] sel;

    // Reset logic
    always_ff @(posedge rst_n or negedge clk) begin
        if (!rst_n) begin
            current_channel <= 2'b00;
            next_channel <= 2'b00;
            rr_flag <= 2'b00;
        end else begin
            if (data_gnt_i) begin
                current_channel <= next_channel;
                rr_flag <= ~rr_flag;
            end
        end
    end

    // Next channel selection logic
    always_comb begin
        if (data_req_CH0_i && !data_req_CH1_i) begin
            next_channel = 2'b01;
        end else if (data_req_CH1_i && !data_req_CH0_i) begin
            next_channel = 2'b10;
        end else if (data_req_CH0_i && data_req_CH1_i) begin
            next_channel = rr_flag;
        end else begin
            next_channel = current_channel;
        end
    end

    // Selection signal
    always_comb begin
        sel = current_channel;
    end

    // Output signals
    assign data_req_o = data_req_CH0_i || data_req_CH1_i;
    assign data_add_o = (sel == 2'b00) ? data_add_CH0_i : data_add_CH1_i;
    assign data_wen_o = (sel == 2'b00) ? data_wen_CH0_i : data_wen_CH1_i;
    assign data_wdata_o = (sel == 2'b00) ? data_wdata_CH0_i : data_wdata_CH1_i;
    assign data_be_o = (sel == 2'b00) ? data_be_CH0_i : data_be_CH1_i;
    assign data_ID_o = (sel == 2'b00) ? data_ID_CH0_i : data_ID_CH1_i;
    assign data_aux_o = (sel == 2'b00) ? data_aux_CH0_i : data_aux_CH1_i;

    // Grant signals
    assign data_gnt_CH0_o = (sel == 2'b00) ? data_gnt_i : 1'b0;
    assign data_gnt_CH1_o = (sel == 2'b01) ? data_gnt_i : 1'b0;
}

