module Multiplication(
    input wire [7:0] Input1,
    input wire [7:0] Input2,
    input wire Op,
    output wire [7:0] Output1,
    output wire [7:0] Output2,
    output wire N
);

    // Perform signed multiplication
    wire [15:0] SignedMult;
    signed [15:0] signedInput1 = Input1;
    signed [15:0] signedInput2 = Input2;
    SignedMult = signedInput1 * signedInput2;

    // Perform unsigned multiplication
    wire [15:0] UnsignedMult;
    UnsignedMult = Input1 * Input2;

    // Select the appropriate result based on Op
    wire [15:0] MultAns;
    assign MultAns = Op ? UnsignedMult : SignedMult;

    // Assign the lower and upper 8 bits of the result
    assign Output1 = MultAns[7:0];
    assign Output2 = MultAns[15:8];

    // Assign the sign bit N
    assign N = Op ? MultAns[15] : 0;

endmodule

module fft2 (
