    wire [31:0] x1_re_tmp;
    wire [31:0] x1_img_tmp;

    // Multipliers to scale inputs
    assign a_re_scaled = a_re * 2; // Assuming scaling factor is 2 for simplicity
    assign a_img_scaled = a_img * 2;
    assign b_re_scaled = b_re * 2;
    assign b_img_scaled = b_img * 2;

    // buf11 module to manage data preparation
    buf11 #(.WIDTH(32)) buf1 (
        .in(a_re_scaled),
        .out(x0_re_tmp)
    );

    buf11 #(.WIDTH(32)) buf2 (
        .in(a_img_scaled),
        .out(x0_img_tmp)
    );

    buf11 #(.WIDTH(32)) buf3 (
        .in(b_re_scaled),
        .out(x1_re_tmp)
    );

    buf11 #(.WIDTH(32)) buf4 (
        .in(b_img_scaled),
        .out(x1_img_tmp)
    );

