    complex_adder #(.WIDTH(32)) adder1 (
        .a(x0_re_tmp),
        .b(x1_re_tmp),
        .c(x0_re),
        .d(x1_re)
    );

    complex_adder #(.WIDTH(32)) adder2 (
        .a(x0_img_tmp),
        .b(x1_img_tmp),
        .c(x0_img),
        .d(x1_img)
    );

