    end

    // Pulse count detection
    always @(posedge clk) begin
        if (motor_rot_pulse && !last_scan_value) begin
            pulse_count_qty = pulse_count_qty + 1;
        end
        last_scan_value = motor_rot_pulse;
    end

    // Output calculation
    always @(posedge clk) begin
        if (pulse_count_qty > 0) begin
            output_count_qty = pulse_count_qty;
        end
    end

    // Output assignment
    assign rpm_output = output_count_qty;

endmodule

module edge_detect (
  input clk,
  input rst_n,
  input a,
  output reg rise,
  output reg down
);

  reg [1:0] a_prev;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      a_prev <= 2'b00;
      rise <= 0;
      down <= 0;
    end else begin
      if (a != a_prev) begin
        if (a_prev == 2'b00) begin
          rise <= 1;
        end else begin
          down <= 1;
        end
        a_prev <= a;
      end
    end
  end

endmodule

