module I_SQRT_2(
    input wire [31:0] n,
    input wire CLK,
    input wire RST_n,
    input wire EN,
    input wire SEL,
    output wire VAL,
    output wire Z,
    output wire [31:0] out_sqrt
);

    // Initial guess for the square root in floating-point format
    reg [31:0] x_0 = 32'h100000000; // 1.0 in IEEE 754 single-precision

    // Current iteration value
    reg [31:0] x_i;

    // Next guess for the square root
    reg [31:0] x_next;

    // Final result
    reg [31:0] sqrt;

    // Register to store the final result
    reg [31:0] out_sqrt_reg;

    // Control signals
    reg val_comb;
    reg z_comb;

    // Flip-flops to synchronize control signals
    always @(posedge CLK or negedge RST_n) begin
        if (!RST_n) begin
            val_ff <= 0;
            z_ff <= 0;
        end else begin
            val_ff <= val_comb;
            z_ff <= z_comb;
        end
    end

    // Multiplexed input for x_i
    reg [31:0] x_i_mux;
    always @(posedge CLK or negedge RST_n) begin
        if (!RST_n) begin
            x_i_mux <= x_0;
        end else begin
            if (SEL) begin
                x_i_mux <= x_i;
            end else begin
                x_i_mux <= x_0;
            end
        end
    end

    // Compute the next guess
    always @(posedge CLK or negedge RST_n) begin
        if (!RST_n) begin
            x_next <= 0;
        end else begin
            x_next <= x_i_mux + (n >> 1);
        end
    end

    // Update the current guess
    always @(posedge CLK or negedge RST_n) begin
        if (!RST_n) begin
            x_i <= 0;
        end else begin
            x_i <= x_next;
        end
    end

    // Compute the final result
    always @(posedge CLK or negedge RST_n) begin
        if (!RST_n) begin
            sqrt <= 0;
        end else begin
            if (x_next >= x_i) begin
                sqrt <= x_i;
                val_comb <= 1;
                z_comb <= 0;
            end else begin
                val_comb <= 0;
                z_comb <= 0;
            end
        end
    end

    // Output the final result
    always @(posedge CLK or negedge RST_n) begin
        if (!RST_n) begin
            out_sqrt_reg <= 0;
        end else begin
            if (EN) begin
                out_sqrt_reg <= sqrt;
            end
        end
    end

    // Assign the output signals
    assign out_sqrt = out_sqrt_reg;
    assign VAL = val_ff;
    assign Z = z_ff;

endmodule

