module serial2parallel(
    input clk,
    input rst_n,
    input din_serial,
    input din_valid,
    output reg [7:0] dout_parallel,
    output reg dout_valid
);

    // Internal signals
    reg [7:0] shift_register;
    reg [3:0] bit_counter;

    // Reset the shift register and counter
    always @(posedge rst_n or negedge clk) begin
        if (!rst_n) begin
            shift_register <= 8'b0;
            bit_counter <= 4'b0;
            dout_parallel <= 8'b0;
            dout_valid <= 1'b0;
        end
    end

    // Shift register and bit counter logic
    always @(posedge clk) begin
        if (din_valid) begin
            // Shift the incoming serial bit into the shift register
            shift_register <= {din_serial, shift_register[7:1]};
            // Increment the bit counter
            bit_counter <= bit_counter + 1'b1;
        end

        // Output the parallel data when 8 bits have been received
        if (bit_counter == 8) begin
            dout_parallel <= shift_register;
            dout_valid <= 1'b1;
        end else begin
            dout_valid <= 1'b0;
        end
    end

endmodule

module NV_NVDLA_HLS_shiftrightsatsu (
   input [IN_WIDTH-1:0] data_in,
   input [SHIFT_WIDTH-1:0] shift_num,
   output [OUT_WIDTH-1:0] data_out,
   output sat_out
);

parameter IN_WIDTH = 49;
parameter SHIFT_WIDTH = 6;
parameter OUT_WIDTH = 32;

reg [IN_WIDTH-1:0] shifted_data;
reg [OUT_WIDTH-1:0] rounded_data;
reg [OUT_WIDTH-1:0] saturated_data;
reg sat_out_reg;

always_comb begin
    // Calculate the shifted data
    shifted_data = data_in >> shift_num;

    // Determine the sign of the shifted data
    reg [IN_WIDTH-1:0] sign_shifted_data;
    sign_shifted_data = {shifted_data[IN_WIDTH-1], shifted_data[IN_WIDTH-2:0]};

    // Calculate the rounded data
    rounded_data = shifted_data;

    // Check for saturation
    if (shifted_data[IN_WIDTH-1] != sign_shifted_data[IN_WIDTH-1]) begin
        // Saturation occurred
        if (sign_shifted_data[IN_WIDTH-1]) begin
            // Negative saturation
            saturated_data = {OUT_WIDTH{1'b1}};
        end else begin
            // Positive saturation
            saturated_data = {OUT_WIDTH{1'b0}};
        end
        sat_out_reg = 1'b1;
    end else begin
        // No saturation
        saturated_data = rounded_data;
        sat_out_reg = 1'b0;
    end

    // Output the data_out and sat_out
    data_out = saturated_data;
    sat_out = sat_out_reg;
end

endmodule

