module p2(i,s0,s1,s2,class3,cs,os0,os1,os2,ml,aluout);

input [31:0]i;
input [4:0]s0;
input [4:0]s1;
input [4:0]s2;

output reg [2:0]class3;
output reg [4:0]cs;
output reg [4:0]os0;
output reg [4:0]os1;
output reg [4:0]os2;
output reg [15:0]ml;
output reg [15:0]aluout;

always @(i or s0 or s1 or s2) begin
    class3 = 3'b000; // Default class3 value
    cs = 5'b00000; // Default control signal
    os0 = 5'b00000; // Default operand output
    os1 = 5'b00000; // Default operand output
    os2 = 5'b00000; // Default operand output
    ml = 16'b0000000000000000; // Default memory address
    aluout = 16'b0000000000000000; // Default ALU result

    // Decode the instruction
    if (i[31:26] == 5'b00000) begin // Load Immediate (LI)
        class3 = 3'b001;
        cs = 5'b00001;
        os0 = 5'b00000; // Immediate value
        ml = 16'b0000000000000000; // Default memory address
        aluout = i[25:0]; // Immediate value
    end else if (i[31:26] == 5'b00001) begin // Add (ADD)
        class3 = 3'b001;
        cs = 5'b00010;
        os0 = s0;
        os1 = s1;
        ml = 16'b0000000000000000; // Default memory address
        aluout = s0 + s1; // Add operation
    end else if (i[31:26] == 5'b00010) begin // Subtract (SUB)
        class3 = 3'b001;
        cs = 5'b00011;
        os0 = s0;
        os1 = s1;
        ml = 16'b0000000000000000; // Default memory address
