module delay (
    input clk,
    input reset,
    input [3:0] variable_pulse_index,
    output slow_pulse,
    output fast_pulse,
    output variable_pulse
);

    // Define the base value for the variable pulse threshold
    localparam BASE_VALUE = 2000000;
    localparam MAX_VALUE = 24000000;

    // Calculate the threshold for the variable pulse
    reg [23:0] variable_pulse_threshold;
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            variable_pulse_threshold <= 0;
        end else begin
            variable_pulse_threshold <= BASE_VALUE * (variable_pulse_index + 1);
        end
    end

    // Define the fixed intervals for the slow and fast pulses
    localparam SLOW_INTERVAL = 18000000;
    localparam FAST_INTERVAL = 4800000;

    // Define the counter register
    reg [31:0] counter;

    // Increment the counter on each positive edge of the clock
    always @(posedge clk) begin
        if (!reset) begin
            counter <= counter + 1;
        end
    end

    // Generate the slow pulse when the counter reaches the slow interval
    assign slow_pulse = (counter >= SLOW_INTERVAL) ? 1'b1 : 1'b0;

    // Generate the fast pulse when the counter reaches the fast interval
    assign fast_pulse = (counter >= FAST_INTERVAL) ? 1'b1 : 1'b0;

    // Generate the variable pulse when the counter reaches the variable pulse threshold
    assign variable_pulse = (counter >= variable_pulse_threshold) ? 1'b1 : 1'b0;

endmodule

