module FSM_game(
    input wire iRST,
    input wire iCLK,
    input wire [1:0] iA,
    input wire [1:0] iB,
    output wire oA,
    output wire oB
);

    // Define the states
    typedef enum {DRAW, B_LEAD, B_WIN, A_LEAD, A_WIN} state_t;
    state_t sSTATE, sNEXT_STATE;

    // Initial state
    initial begin
        sSTATE = DRAW;
    end

    // Combinational logic to determine the next state
    always_comb begin
        case (sSTATE)
            DRAW: begin
                if (iA == iB) begin
                    sNEXT_STATE = DRAW;
                end else if (iA > iB) begin
                    sNEXT_STATE = A_LEAD;
                end else begin
                    sNEXT_STATE = B_LEAD;
                end
            end
            B_LEAD: begin
                if (iA > iB) begin
                    sNEXT_STATE = A_LEAD;
                end else if (iA == iB) begin
                    sNEXT_STATE = DRAW;
                end else begin
                    sNEXT_STATE = B_WIN;
                end
            end
            B_WIN: begin
                sNEXT_STATE = B_WIN;
            end
            A_LEAD: begin
                if (iA < iB) begin
                    sNEXT_STATE = B_LEAD;
                end else if (iA == iB) begin
                    sNEXT_STATE = DRAW;
                end else begin
                    sNEXT_STATE = A_WIN;
                end
            end
            A_WIN: begin
                sNEXT_STATE = A_WIN;
            end
        endcase
    end

    // Synchronous logic to update the current state
    always_ff @(posedge iCLK or posedge iRST) begin
        if (iRST) begin
            sSTATE <= DRAW;
        end else begin
            sSTATE <= sNEXT_STATE;
        end
    end

    // Decode the current state to determine the winner
    always_comb begin
        case (sSTATE)
            DRAW: begin
                oA = 2'b00;
                oB = 2'b00;
            end
            B_LEAD: begin
                oA = 2'b00;
                oB = 2'b01;
            end
            B_WIN: begin
                oA = 2'b00;
                oB = 2'b10;
            end
            A_LEAD: begin
                oA = 2'b10;
                oB = 2'b00;
            end
            A_WIN: begin
                oA = 2'b10;
                oB = 2'b10;
            end
        endcase
    end

endmodule

