module array_mul4bit(a, b, prod);
    input [3:0] a;
    input [3:0] b;
    output [7:0] prod;

    // Generate all 16 possible AND products between bits of a and b
    wire [15:0] _and;
    generate
        for (genvar i = 0; i < 4; i++) begin
            for (genvar j = 0; j < 4; j++) begin
                _and[i*4+j] = a[i] & b[j];
            end
        end
    endgenerate

    // Initialize the product output to zero
    reg [7:0] prod_reg = 8'b0;

    // Add each bit of the product using a series of adders
    generate
        for (genvar i = 0; i < 8; i++) begin
            wire [3:0] sum;
            wire carry;
            assign sum = _and[i*4] + _and[i*4+1] + _and[i*4+2] + _and[i*4+3];
            assign carry = sum[4];
            assign prod_reg[i] = sum[3:0];
        end
    endgenerate

    // Output the final product
    assign prod = prod_reg;
endmodule

module isqrt
(
    input      [31:0] x,
    output reg [15:0] y
);

    // Internal registers
    reg [15:0] result;
    reg [15:0] temp;
    reg [15:0] mask;

    // Initialize the result register
    assign result = 16'h0000;

    // Iterate through each bit of the input
    for (int i = 0; i < 32; i++) begin
        // Shift the result left by 1
        result = result << 1;

        // Check if the current bit of the input is set
        if (x & (1 << i)) begin
            // Subtract the current bit of the input from the result
            result = result - (1 << i);
        end

        // Update the mask to track the current bit
        mask = mask << 1;
        mask = mask | 1;
    end

    // Assign the lower 16 bits of the result to the output
    assign y = result;

endmodule

module gf180mcu_fd_sc_mcu9t5v0__oai31_4(
