    wire A1_inv = ~A1;
    wire A2_inv = ~A2;
    wire A3_inv = ~A3;

    // Invert the B input
    wire B_inv = ~B;

    // Compute the logical AND of the inverted A signals
    wire ZN_row1 = A1_inv & A2_inv & A3_inv;

    // Compute the final output ZN by taking the logical OR of ZN_row1 and the inverted B signal
    assign ZN = ZN_row1 | B_inv;

endmodule

