module mii_if(
    input aclk,
    input aresetn,

    output reg [7:0] tx_tdata,
    output reg tx_tvalid,
    output reg tx_tlast,
    input tx_tready,

    input [7:0] rx_tdata,
    input rx_tvalid,
    input rx_tlast,
    output reg rx_tready,

    output mii_tx_clk,
    input mii_tx_en,
    input mii_tx_er,
    input [3:0] mii_tx_data,

    output mii_rx_clk,
    output reg mii_rx_dv,
    output reg mii_rx_er,
    output reg [3:0] mii_rx_data,

    output mii_crs,
    output mii_col
);

    // Internal registers
    reg [7:0] tx_data_reg;
    reg tx_tvalid_reg;
    reg tx_tlast_reg;
    reg [7:0] rx_data_reg;
    reg rx_tvalid_reg;
    reg rx_tlast_reg;
    reg [3:0] mii_tx_data_reg;
    reg mii_rx_dv_reg;
    reg mii_rx_er_reg;
    reg [3:0] mii_rx_data_reg;
    reg mii_crs_reg;
    reg mii_col_reg;
    reg [31:0] timer;
    reg timer_done;

    // FSM states
    typedef enum logic [2:0] {
        IDLE,
        STROBE,
        INTER_FRAME_GAP,
        UNDERFLOW,
        RECOVERY
    } state_t;
    state_t current_state, next_state;

    // Timer configuration
    parameter TIMER_PERIOD = 1000; // 1000 cycles = 100ns

    // Clock divider for MII clock generation
    always @(posedge aclk or posedge aresetn) begin
        if (aresetn) begin
            mii_tx_clk <= 0;
            mii_rx_clk <= 0;
        end else begin
            if (timer_done) begin
                mii_tx_clk <= ~mii_tx_clk;
                mii_rx_clk <= ~mii_rx_clk;
                timer <= 0;
                timer_done <= 0;
            end else begin
                timer <= timer + 1;
                if (timer == TIMER_PERIOD) begin
                    timer_done <= 1;
                end
            end
        end
    end

    // FSM
    always @(posedge aclk or posedge aresetn) begin
        if (aresetn) begin
            current_state <= IDLE;
            tx_tvalid_reg <= 0;
            tx_tlast_reg <= 0;
            rx_tvalid_reg <= 0;
            rx_tlast_reg <= 0;
            mii_tx_data_reg <= 0;
            mii_rx_dv_reg <= 0;
            mii_rx_er_reg <= 0;
            mii_rx_data_reg <= 0;
            mii_crs_reg <= 0;
            mii_col_reg <= 0;
        end else begin
            current_state <= next_state;

            case (current_state)
                IDLE: begin
                    if (rx_tvalid && rx_tready) begin
                        next_state <= STROBE;
                        rx_tvalid_reg <= 1;
                        rx_tlast_reg <= rx_tlast;
                        mii_rx_dv_reg <= 1;
                        mii_rx_er_reg <= 0;
                        mii_rx_data_reg <= rx_tdata;
                    end
                end
                STROBE: begin
                    if (mii_rx_dv) begin
                        next_state <= INTER_FRAME_GAP;
                        mii_rx_dv_reg <= 0;
                    end
                end
                INTER_FRAME_GAP: begin
                    if (timer_done) begin
                        next_state <= UNDERFLOW;
                        timer_done <= 0;
                    end
                end
                UNDERFLOW: begin
                    if (rx_tvalid && rx_tready) begin
                        next_state <= STROBE;
                        rx_tvalid_reg <= 1;
                        rx_tlast_reg <= rx_tlast;
                        mii_rx_dv_reg <= 1;
                        mii_rx_er_reg <= 0;
                        mii_rx_data_reg <= rx_tdata;
                    end
                end
                RECOVERY: begin
                    if (timer_done) begin
                        next_state <= IDLE;
                        timer_done <= 0;
                    end
                end
            endcase
        end
    end

    // Data processing
    always @(posedge aclk or posedge aresetn) begin
        if (aresetn) begin
            tx_data_reg <= 0;
            tx_tvalid_reg <= 0;
            tx_tlast_reg <= 0;
        end else begin
            if (current_state == IDLE && tx_tvalid && tx_tready) begin
                tx_data_reg <= tx_tdata;
                tx_tvalid_reg <= 1;
                tx_tlast_reg <= tx_tlast;
            end
        end
