module UART_rx(
    input wire clk,
    input wire reset,
    input wire rx_data_in,
    output reg [7:0] rx_data_out
);

parameter BAUD_RATE = 9600; // Baud rate in bits per second
parameter OVERSAMPLE_RATE = 16; // Oversampling rate
parameter BIT_WIDTH = 8; // Number of bits in a byte

// Calculate the number of clock cycles per bit
localparam CYCLES_PER_BIT = (OVERSAMPLE_RATE / BAUD_RATE);

// State machine for UART receiver
typedef enum {IDLE, START, DATA, STOP} state_t;
state_t current_state, next_state;

// Variables to store received data and bit counter
reg [7:0] received_data;
reg [3:0] bit_counter;

// Clock divider to generate a clock signal for data processing
reg [15:0] clock_divider;
always @(posedge clk) begin
    if (reset) begin
        clock_divider <= 0;
    end else begin
        clock_divider <= clock_divider + 1;
    end
end

// State machine logic
always @(posedge clk) begin
    if (reset) begin
        current_state <= IDLE;
        received_data <= 8'b0;
        bit_counter <= 0;
    end else begin
        current_state <= next_state;
        case (current_state)
            IDLE: begin
                if (rx_data_in) begin
                    next_state <= START;
                end
            end
            START: begin
                if (clock_divider == (CYCLES_PER_BIT - 1)) begin
                    next_state <= DATA;
                    bit_counter <= 0;
                end
            end
            DATA: begin
                if (clock_divider == (CYCLES_PER_BIT - 1)) begin
                    received_data[bit_counter] <= rx_data_in;
                    bit_counter <= bit_counter + 1;
                    if (bit_counter == BIT_WIDTH - 1) begin
                        next_state <= STOP;
                    end
                end
            end
            STOP: begin
                if (clock_divider == (CYCLES_PER_BIT - 1)) begin
                    next_state <= IDLE;
                    rx_data_out <= received_data;
                end
            end
        endcase
    end
end

endmodule

module serial(clk, reset, rxD, sout, signal, counter);
    parameter n = 30;
    parameter count = 4;

    input clk;
    input reset;
    input rxD;

    output reg [n-1:0] sout;
    output reg signal;
    output reg [31:0] counter;

    reg [31:0] delay;
    reg [7:0] s_in;
    reg [31:0] counter_reg;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            sout <= 0;
            signal <= 0;
            counter <= 0;
            delay <= 0;
            counter_reg <= 0;
        end else begin
            if (counter_reg == count - 1) begin
                signal <= 1;
                counter_reg <= 0;
            end else begin
                signal <= 0;
                counter_reg <= counter_reg + 1;
            end

            if (counter_reg == count - 1) begin
                delay <= delay + 1;
            end else begin
                delay <= delay;
            end

            if (delay == 1) begin
                sout <= rxD;
                delay <= 0;
            end else begin
                sout <= sout;
            end
        end
    end
endmodule

