module blackcell(
    input g_in1,
    input p_in1,
    input g_in2,
    input p_in2,
    output g_out,
    output p_out
);

    // Intermediate wire for computation
    wire w;

    // Logic operations
    assign w = p_in1 & g_in2; // w is the AND of p_in1 and g_in2
    assign g_out = w | g_in1; // g_out is the OR of w and g_in1
    assign p_out = p_in1 & p_in2; // p_out is the AND of p_in1 and p_in2

endmodule

module uart_regs_tb;
  reg clk = 0, rst = 0;
