  reg [2:0] addr_i;
  reg [7:0] din_i;

  reg rx_overrun_err, rx_parity_err, rx_framing_err, rx_break_int;
  wire tx_fifo_push;
  wire rx_fifo_pop;
  wire baud_pulse_out;
  wire tx_fifo_reset, rx_fifo_reset;
  wire [3:0] rx_fifo_threshold;
  wire [7:0] data_out;

  uart_regs uut (clk, rst, wr_i, rd_i, rx_fifo_empty_i, rx_overrun_err, rx_parity_err, rx_framing_err, rx_break_int, addr_i, din_i, rx_fifo_data_in, tx_fifo_push, rx_fifo_pop, baud_pulse_out, tx_fifo_reset, rx_fifo_reset, rx_fifo_threshold, data_out);

  initial begin
    clk = 0;
    forever #5 clk = ~clk;
  end

  initial begin
    rst = 1;
    #10 rst = 0;
  end

  initial begin
    // Write to the divisor latch register (address 0)
    wr_i = 1;
    addr_i = 0;
    din_i = 12; // Example divisor value for 9600 baud
    #10 wr_i = 0;

    // Read from the divisor latch register (address 0)
    rd_i = 1;
    addr_i = 0;
    #10 rd_i = 0;
