    // Write to the interrupt enable register (address 1)
    wr_i = 1;
    addr_i = 1;
    din_i = 7; // Enable all interrupts
    #10 wr_i = 0;

    // Read from the interrupt enable register (address 1)
    rd_i = 1;
    addr_i = 1;
    #10 rd_i = 0;
    #10 $display("Read from interrupt enable: %b", data_out);

    // Write to the receive FIFO threshold register (address 2)
    wr_i = 1;
    addr_i = 2;
    din_i = 4; // Set threshold to 4
    #10 wr_i = 0;

    // Read from the receive FIFO threshold register (address 2)
    rd_i = 1;
    addr_i = 2;
    #10 rd_i = 0;
    #10 $display("Read from receive FIFO threshold: %b", data_out);

    // Write to the transmit FIFO reset register (address 3)
    wr_i = 1;
    addr_i = 3;
    din_i = 1;
    #10 wr_i = 0;

    // Write to the receive FIFO reset register (address 3)
    wr_i = 1;
    addr_i = 3;
    din_i = 0;
    #10 wr_i = 0;

    // Write to the transmit FIFO push register (address 4)
    wr_i = 1;
    addr_i = 4;
    din_i = 123; // Example data to transmit
    #10 wr_i = 0;

    // Read from the transmit FIFO push register (address 4)
    rd_i = 1;
    addr_i = 4;
    #10 rd_i = 0;
    #10 $display("Read from transmit FIFO push: %b", data_out);

    // Write to the receive FIFO pop register (address 5)
    wr_i = 1;
    addr_i = 5;
    din_i = 1;
    #10 wr_i = 0;

    // Read from the receive FIFO pop register (address 5)
    rd_i = 1;
    addr_i = 5;
    #10 rd_i = 0;
    #10 $display("Read from receive FIFO pop: %b", data_out);

    // Write to the baud pulse output register (address 6)
    wr_i = 1;
    addr_i = 6;
