module arbiter (
    input wire clock,
    input wire reset,
    input wire req_0,
    input wire req_1,
    output reg gnt_0,
    output reg gnt_1
);

always @(posedge clock or posedge reset) begin
    if (reset) begin
        gnt_0 <= 0;
        gnt_1 <= 0;
    end else begin
        if (req_0 && !req_1) begin
            gnt_0 <= 1;
            gnt_1 <= 0;
        end else if (!req_0 && req_1) begin
            gnt_0 <= 0;
            gnt_1 <= 1;
        end else begin
            gnt_0 <= 0;
            gnt_1 <= 0;
        end
    end
end

endmodule

module NAND3C(Y, A, B, C);
    input A, B, C;
    output Y;

    // Invert inputs A and B
    wire notA = ~A;
    wire notB = ~B;

    // Combine inverted A and B using an AND gate
    wire andAB = notA & notB;

    // Combine the result of the AND gate with the inverted C using a NAND gate
    Y = ~andAB & ~C;
endmodule

