module pcm(set, clk, q1, q2, q3);
    input set, clk;
    output q1, q2, q3;

    reg [4:0] count;

    always @(posedge clk) begin
        if (set) begin
            count <= 9;
        end else if (count > 0) begin
            count <= count - 1;
        end
    end

    assign q1 = (count >= 7) & (count <= 9);
    assign q2 = (count >= 4) & (count <= 6);
    assign q3 = (count >= 1) & (count <= 3);
endmodule

