    assign MGM_WB_0 = EN & I_inv_for_gf180mcu_fd_sc_mcu7t5v0__invz_12;

    // Generate the enable control for the buffer
    assign MGM_WB_1 = ~MGM_WB_0;

    // Buffer to drive the output ZN conditionally
    assign ZN = MGM_WB_1 ? I_inv_for_gf180mcu_fd_sc_mcu7t5v0__invz_12 : 1'bZ;

