module ControlUnit(
    input [5:0] opcode,
    input [5:0] funct,
    output reg reg_dst,
    output reg reg_write,
    output reg [1:0] alu_src,
    output reg [3:0] alu_op,
    output reg branch,
    output reg mem_write,
    output reg mem_to_reg,
    output reg zero_sign_ext,
    output reg mult_op,
    output reg mfhi,
    output reg mflo
);

always @(*) begin
    // Default values for control signals
    reg_dst = 2'b00;
    reg_write = 1'b0;
    alu_src = 2'b00;
    alu_op = 4'b0000;
    branch = 1'b0;
    mem_write = 1'b0;
    mem_to_reg = 1'b0;
    zero_sign_ext = 1'b0;
    mult_op = 1'b0;
    mfhi = 1'b0;
    mflo = 1'b0;

    // Decode R-type instructions
    if (opcode == 6'b000000) begin
        reg_dst = 2'b01;
        reg_write = 1'b1;
        alu_src = 2'b00;
        alu_op = 4'b1000; // Add
        branch = 1'b0;
        mem_write = 1'b0;
        mem_to_reg = 1'b0;
        zero_sign_ext = 1'b0;
        mult_op = 1'b0;
        mfhi = 1'b0;
        mflo = 1'b0;
    end

    // Decode I-type instructions
    else if (opcode == 6'b001000) begin // lw
        reg_dst = 2'b01;
        reg_write = 1'b1;
        alu_src = 2'b01;
        alu_op = 4'b1000; // Add
        branch = 1'b0;
        mem_write = 1'b0;
        mem_to_reg = 1'b1;
        zero_sign_ext = 1'b1;
        mult_op = 1'b0;
        mfhi = 1'b0;
        mflo = 1'b0;
    end
    else if (opcode == 6'b001010) begin // sw
        reg_dst = 2'b00;
        reg_write = 1'b0;
        alu_src = 2'b01;
        alu_op = 4'b1000; // Add
        branch = 1'b0;
        mem_write = 1'b1;
        mem_to_reg = 1'b0;
        zero_sign_ext = 1'b0;
        mult_op = 1'b0;
        mfhi = 1'b0;
        mflo = 1'b0;
    end
    else if (opcode == 6'b000100) begin // beq
        reg_dst = 2'b00;
        reg_write = 1'b0;
        alu_src = 2'b00;
        alu_op = 4'b0000; // Add
        branch = 1'b1;
        mem_write = 1'b0;
        mem_to_reg = 1'b0;
        zero_sign_ext = 1'b0;
        mult_op = 1'b0;
        mfhi = 1'b0;
        mflo = 1'b0;
    end

    // Decode special operations
    else if (opcode == 6'b000010) begin // mult
        mult_op = 1'b1;
        mfhi = 1'b1;
        mflo = 1'b1;
    end
    else if (opcode == 6'b000011) begin // div
        mult_op = 1'b1;
        mfhi = 1'b1;
        mflo = 1'b1;
    end
    else if (opcode == 6'b000111) begin // mfhi
        mfhi = 1'b1;
    end
    else if (opcode == 6'b000110) begin // mflo
        mflo = 1'b1;
    end
end

endmodule

module BranchLogic (zf, cf, nf, sel, branch, branch_out, flag_reg);
    input zf, cf, nf, branch;
    input [1:0] sel;
    output branch_out;
    output [2:0] flag_reg;

    // Determine the selected flag based on the sel input
    wire [2:0] selected_flag;
    assign selected_flag = (sel == 2'b00) ? zf : (sel == 2'b01) ? cf : nf;

    // Compute the branch_out based on the selected flag and branch input
    assign branch_out = (branch && selected_flag) || (!branch && !selected_flag);

    // Update the flag_reg based on the selected flag
    assign flag_reg = selected_flag;
endmodule

