module zmc2_dot (
    input CLK_12M,
    input EVEN,
    input LOAD,
    input H,
    input [31:0] CR,
    output reg [3:0] GAD, GBD,
    output reg DOTA, DOTB
);

    // Internal register to hold the control register value
    reg [31:0] SR;

    // Temporary register to hold the shifted and combined bits
    reg [31:0] temp;

    // Combinational logic to update SR based on LOAD
    always @(posedge CLK_12M or posedge LOAD) begin
        if (LOAD) begin
            SR <= CR;
        end
    end

    // Sequential logic to shift and combine bits based on EVEN and H
    always @(posedge CLK_12M) begin
        if (H) begin
            // Shift SR right by 1 bit and OR with the least significant bit
            temp = {SR[30:0], SR[31]};
        end else begin
            // Shift SR left by 1 bit and OR with the most significant bit
            temp = {SR[0], SR[31:1]};
        end

        // Assign GAD and GBD based on the shifted bits
        GAD = temp[3:0];
        GBD = temp[7:4];

        // Calculate DOTA and DOTB as the OR of GAD and GBD
        DOTA = GAD | GBD;
        DOTB = GAD | GBD;
    end

endmodule

