module Bin2BCDConverter_4
#(
	parameter INPUT_BIT_WIDTH  = 8
)
(
    input [(INPUT_BIT_WIDTH-1):0] Input,
    output reg [3:0] Digit3,
    output reg [3:0] Digit2,
    output reg [3:0] Digit1,
    output reg [3:0] Digit0
);

reg [3:0] BCD3, BCD2, BCD1, BCD0;

always @(*) begin
    BCD3 = 4'b0000;
    BCD2 = 4'b0000;
    BCD1 = 4'b0000;
    BCD0 = 4'b0000;

    for (int i = INPUT_BIT_WIDTH - 1; i >= 0; i--) begin
        if (Input[i] == 1) begin
            if (BCD3 == 9) begin
                BCD3 = 4'b0000;
                BCD2 = BCD2 + 1;
            end else if (BCD2 == 9) begin
                BCD2 = 4'b0000;
                BCD1 = BCD1 + 1;
            end else if (BCD1 == 9) begin
                BCD1 = 4'b0000;
                BCD0 = BCD0 + 1;
            end else begin
                BCD3 = BCD3 + 1;
            end
        end
        BCD3 = BCD3 << 1;
        BCD2 = BCD2 << 1;
        BCD1 = BCD1 << 1;
        BCD0 = BCD0 << 1;
        BCD0[3] = Input[i];
    end

    Digit3 = BCD3;
    Digit2 = BCD2;
    Digit1 = BCD1;
    Digit0 = BCD0;
end

endmodule

module half_adder_tb;
