    half_adder ha (
        .a(a),
        .b(b),
        .sum(sum),
        .carry(carry)
    );

    // Test signals
    reg t_a;
    reg t_b;
    reg [1:0] test_cases = 2'b00; // Start with 00

    // Initial block to initialize test signals and control simulation flow
    initial begin
        // Initialize test signals
        t_a = 0;
        t_b = 0;

        // Test all possible combinations of t_a and t_b
        while (test_cases < 4) begin
            // Drive test signals
            t_a = test_cases[0];
            t_b = test_cases[1];

            // Wait for 5 units
            #5;

            // Monitor outputs
            $display("t_a = %b, t_b = %b, sum = %b, carry = %b", t_a, t_b, sum, carry);

            // Increment test cases
            test_cases = test_cases + 1;
        end

        // End of simulation
        $finish;
    end
endmodule

