module bufferDatapointMemoryAccess(
  input         clock,
  input         reset,
  input         io_wrEna,
  input  [9:0]  io_Addr,
  input  [15:0] io_dataIn,
  output [15:0] io_rdData
);

  // Memory array declaration
  reg [15:0] memory [0:1023];

  // Internal registers for pipelining
  reg [15:0] dataInReg;
  reg [9:0] addrReg;

  // Conditional initializations for randomization
  initial begin
    if (reset) begin
      for (int i = 0; i < 1024; i++) begin
        memory[i] = $random;
      end
    end
  end

  // Sequential write operation
  always @(posedge clock or posedge reset) begin
    if (reset) begin
      dataInReg <= 16'h0;
      addrReg <= 10'h0;
    end else if (io_wrEna) begin
      dataInReg <= io_dataIn;
      addrReg <= io_Addr;
      memory[addrReg] <= dataInReg;
    end
  end

  // Read operation
  always @(posedge clock or posedge reset) begin
    if (reset) begin
      io_rdData <= 16'h0;
    end else if (!io_wrEna) begin
      io_rdData <= memory[addrReg];
    end
  end

endmodule

