// Comparator4 module
module comparator4(
    input [3:0] N,
    input [3:0] mic,
    output egal,
    output mare
);

    // Fixed patterns for comparison
    wire [3:0] pattern1 = 4'b0000;
    wire [3:0] pattern2 = 4'b0001;
    wire [3:0] pattern3 = 4'b0010;
    wire [3:0] pattern4 = 4'b0011;
    wire [3:0] pattern5 = 4'b0100;
    wire [3:0] pattern6 = 4'b0101;
    wire [3:0] pattern7 = 4'b0110;
    wire [3:0] pattern8 = 4'b0111;
    wire [3:0] pattern9 = 4'b1000;
    wire [3:0] pattern10 = 4'b1001;
    wire [3:0] pattern11 = 4'b1010;
    wire [3:0] pattern12 = 4'b1011;
    wire [3:0] pattern13 = 4'b1100;
    wire [3:0] pattern14 = 4'b1101;
    wire [3:0] pattern15 = 4'b1110;
    wire [3:0] pattern16 = 4'b1111;

    // Compare N with each pattern
    assign egal = (N == pattern1) | (N == pattern2) | (N == pattern3) | (N == pattern4) |
                  (N == pattern5) | (N == pattern6) | (N == pattern7) | (N == pattern8) |
                  (N == pattern9) | (N == pattern10) | (N == pattern11) | (N == pattern12) |
                  (N == pattern13) | (N == pattern14) | (N == pattern15) | (N == pattern16);

    assign mare = (N > pattern1) | (N > pattern2) | (N > pattern3) | (N > pattern4) |
                  (N > pattern5) | (N > pattern6) | (N > pattern7) | (N > pattern8) |
                  (N > pattern9) | (N > pattern10) | (N > pattern11) | (N > pattern12) |
                  (N > pattern13) | (N > pattern14) | (N > pattern15) | (N > pattern16);

endmodule

