    parameter DIVISOR = 1024; // Example divisor, can be changed

    // Define the counter width
    localparam COUNTER_WIDTH = 28;

    // Declare the counter register
    reg [COUNTER_WIDTH-1:0] counter;

    // Reset the counter on the first positive edge of clock_in
    always @(posedge clock_in) begin
        if (!counter) begin
            counter <= DIVISOR - 1;
        end
    end

    // Generate the output clock_out
    always @(posedge clock_in) begin
        if (counter < DIVISOR / 2) begin
            clock_out <= 1'b1;
        end else begin
            clock_out <= 1'b0;
        end
        counter <= counter - 1;
    end

endmodule

