module noise(
  input i_clk,
  output reg signed [15:0] o_data
);

  // Initialize the LFSR register
  reg [15:0] r_shift16 = 16'hDEAD;

  // LFSR feedback taps
  wire [3:0] feedback = {r_shift16[15], r_shift16[14], r_shift16[12], r_shift16[3]};

  // LFSR shift operation
  always @(posedge i_clk) begin
    // Shift the LFSR to the left
    r_shift16 <= {r_shift16[14:0], feedback};

    // Check if the LFSR state is 0x8000
    if (r_shift16 == 16'h8000) begin
      // Modify the output to 0x8001 when the state is 0x8000
      o_data <= 16'h8001;
    } else begin
      // Otherwise, output the current state of the LFSR
      o_data <= r_shift16;
    end
  end

endmodule

