module NBitCounterChain #(
   parameter counterSize   = 16,
   parameter numOfCounters = 3054
) (
   input  wire                   clk,
   input  wire                   reset,
   output wire [counterSize-1:0] outCount
);

// Array to store the current count values of all counters
reg [counterSize-1:0] counts[numOfCounters];

// Array to track when each counter reaches its maximum value
reg [counterSize-1:0] terminalCounts[numOfCounters];

// Generate loop to instantiate multiple counters
generate
   for (genvar i = 0; i < numOfCounters; i++) begin
      // Instantiate a counter
      NBitCounter #(
         .counterSize(counterSize)
      ) counter (
         .clk(clk),
         .reset(reset),
         .count(counts[i]),
         .terminalCount(terminalCounts[i])
      );

      // Connect the enable signal for each counter
      if (i > 0) begin
         assign counter.enable = terminalCounts[i - 1];
      end else begin
         // The first counter is always enabled
         assign counter.enable = 1'b1;
      end
   end
endgenerate

// Compute the final output as the count value of the last counter
assign outCount = counts[numOfCounters - 1];

endmodule

// NBitCounter module definition
module NBitCounter #(
   parameter counterSize = 16
) (
   input  wire                   clk,
   input  wire                   reset,
   output reg [counterSize-1:0] count,
   output reg [counterSize-1:0] terminalCount
);

always @(posedge clk or posedge reset) begin
   if (reset) begin
      count <= 0;
      terminalCount <= 0;
   end else begin
      count <= count + 1;
      if (count == (2**counterSize) - 1) begin
         terminalCount <= 1;
      end else begin
         terminalCount <= 0;
      end
   end
end

endmodule

