module division(A, B, Res);
    input [15:0] A;
    input [15:0] B;
    output reg [15:0] Res = 0;

    reg [16:0] a1;
    reg [16:0] b1;
    reg [16:0] p1;

    always @(posedge A or posedge B) begin
        a1 <= A;
        b1 <= B;
        p1 <= 0;

        for (int i = 0; i < 16; i++) begin
            if (p1 >= b1) begin
                p1 <= p1 - b1;
                Res <= Res + 1'b1;
            end
            p1 <= p1 << 1;
        end
    end
endmodule

