            end
            // Load operation
            if (MemRead) begin
                mem_addr <= addr;
                mem_write_data <= 32'h0;
                mem_write_enable <= 1'b0;
                data_out <= mem_write_data; // Read data from ram
                mem_done <= 1'b1; // Set mem_done for load operation
            end
        end
    end

endmodule

