module vga_sync(
    input wire clk,
    input wire rst,
    output reg active,
    output reg hsync,
    output reg vsync,
    output wire [9:0] xaddr,
    output wire [9:0] yaddr
);

    // Parameters for VGA display
    parameter H_ACTIVE = 640; // Horizontal active pixels
    parameter H_SYNC = 96;  // Horizontal sync pixels
    parameter H_BACK = 48;   // Horizontal back porch pixels
    parameter H_RETRACE = 16; // Horizontal retrace pixels
    parameter V_ACTIVE = 480; // Vertical active lines
    parameter V_SYNC = 2;    // Vertical sync lines
    parameter V_BACK = 33;   // Vertical back porch lines
    parameter V_RETRACE = 2;  // Vertical retrace lines

    // Internal counters
    reg [9:0] h_count_reg;
    reg [9:0] v_count_reg;

    // Counter reset
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            h_count_reg <= 0;
            v_count_reg <= 0;
        end else begin
            if (h_count_reg == H_ACTIVE + H_SYNC + H_BACK + H_RETRACE - 1) begin
                h_count_reg <= 0;
            end else begin
                h_count_reg <= h_count_reg + 1;
            end
            if (v_count_reg == V_ACTIVE + V_SYNC + V_BACK + V_RETRACE - 1) begin
                v_count_reg <= 0;
            end else begin
                v_count_reg <= v_count_reg + 1;
            end
        end
    end

    // Synchronization signals
    always @(posedge clk) begin
        if (h_count_reg < H_ACTIVE + H_SYNC + H_BACK) begin
            hsync <= 1'b0;
        end else if (h_count_reg < H_ACTIVE + H_SYNC + H_BACK + H_RETRACE) begin
            hsync <= 1'b1;
        end else begin
            hsync <= 1'b0;
        end

        if (v_count_reg < V_ACTIVE + V_SYNC + V_BACK) begin
            vsync <= 1'b0;
        end else if (v_count_reg < V_ACTIVE + V_SYNC + V_BACK + V_RETRACE) begin
            vsync <= 1'b1;
        end else begin
            vsync <= 1'b0;
        end
    end

    // Active video signal
    always @(posedge clk) begin
        active <= (h_count_reg >= H_BACK) && (h_count_reg < H_ACTIVE + H_BACK + H_RETRACE) && (v_count_reg >= V_BACK) && (v_count_reg < V_ACTIVE + V_BACK + V_RETRACE);
    end

    // Address outputs
    assign xaddr = h_count_reg;
    assign yaddr = v_count_reg;

endmodule

module slink_demet_reset
  (
   input  wire   clk,
   input  wire   reset,
   input  wire   sig_in,
   output wire   sig_out
  );

  // Two-bit register to store the intermediate values
  reg [1:0] demet_flops;

  // Asynchronous reset to clear the register
  always @(posedge reset) begin
    demet_flops <= 2'b00;
  end

  // Synchronous update of the register
  always @(posedge clk) begin
    if (reset) begin
      demet_flops <= 2'b00; // Clear the register on reset
    end else begin
      demet_flops <= {demet_flops[0], sig_in}; // Shift bits to the right
    end
  end

  // Output the least significant bit of the register
  assign sig_out = demet_flops[0];

endmodule

