module lfsr #( parameter WIDTH = 10, parameter SEED = 10'h2aa, parameter TAPS = 10'h2C2 ) ( input wire clk_i, input wire rst_i, input wire next_i, output wire [WIDTH-1:0] output_o );

    // Register to hold the current state of the LFSR
    reg [WIDTH-1:0] lfsr_reg;

    // Initialize the LFSR register with the seed value
    initial begin
        lfsr_reg = SEED;
    end

    // Always block to handle the LFSR logic
    always @(posedge clk_i or posedge rst_i) begin
        if (rst_i) begin
            // Reset the LFSR to the seed value
            lfsr_reg = SEED;
        end else if (next_i) begin
            // Compute the feedback bit using the taps configuration
            reg feedback_bit;
            feedback_bit = lfsr_reg[TAPS];

            // Shift the register and update the feedback bit
            lfsr_reg = {feedback_bit, lfsr_reg[WIDTH-2:0]};
        end
    end

    // Output the current state of the LFSR
    assign output_o = lfsr_reg;

endmodule

