);

    reg Qold;

    always @(posedge clk) begin
        Qold <= Q;
        if (j == 1'b1) begin
            Q <= 1'b1;
        end else if (k == 1'b1) begin
            Q <= 1'b0;
        end else begin
            Q <= ~Qold;
