    wire [29:0] concatenated_input;
    assign concatenated_input = {a, b, c, d, e, f};

    // Split the concatenated input vector into four 8-bit output vectors
    assign w = concatenated_input[29:22];
    assign x = concatenated_input[21:14];
    assign y = concatenated_input[13:6];
    assign z = concatenated_input[5:0];

    // Add two 1-bit outputs at the LSB positions
    assign w[0] = 1'b1;
