module TopModule (
    input  clk,
    input  reset,
    output reg [2:0] ena,
    output reg [15:0] q
);

    // Internal signals
    reg [3:0] ones;
    reg [3:0] tens;
    reg [3:0] hundreds;
    reg [3:0] thousands;

    // BCD counter logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            ones <= 4'b0000;
            tens <= 4'b0000;
            hundreds <= 4'b0000;
            thousands <= 4'b0000;
            ena <= 3'b000;
        end else begin
            if (ones == 9) begin
                ones <= 4'b0000;
                if (tens == 9) begin
                    tens <= 4'b0000;
                    if (hundreds == 9) begin
                        hundreds <= 4'b0000;
                        thousands <= thousands + 1'b01;
                    end else begin
                        hundreds <= hundreds + 1'b01;
                    end
                end else begin
                    tens <= tens + 1'b01;
                end
            end else begin
                ones <= ones + 1'b01;
            end

            // Enable signals
            ena[0] = (ones == 9);
            ena[1] = (tens == 9);
            ena[2] = (hundreds == 9);
        end
    end

    // Output the BCD digits
    assign q[15:12] = thousands;
    assign q[11:8] = hundreds;
    assign q[7:4] = tens;
    assign q[3:0] = ones;

endmodule

