module TopModule (
    input  a,
    input  b,
    input  c,
    input  d,
    output out_sop,
    output out_pos
);

    // Define the truth tables for out_sop and out_pos
    // out_sop is 1 when 2, 7, or 15 appear on the inputs
    // out_pos is 1 when 0, 1, 4, 5, 6, 9, 10, 13, or 14 appear

    // out_sop
    assign out_sop = (a & b & c & d) | (a & b & c & ~d) | (a & b & ~c & d) | (a & b & ~c & ~d) |
                     (a & ~b & c & d) | (a & ~b & c & ~d) | (a & ~b & ~c & d) | (a & ~b & ~c & ~d) |
                     (~a & b & c & d) | (~a & b & c & ~d) | (~a & b & ~c & d) | (~a & b & ~c & ~d) |
                     (~a & ~b & c & d) | (~a & ~b & c & ~d) | (~a & ~b & ~c & d) | (~a & ~b & ~c & ~d);

    // out_pos
    assign out_pos = ~(a & b & c & d) & ~(a & b & c & ~d) & ~(a & b & ~c & d) & ~(a & b & ~c & ~d) &
                     ~(a & ~b & c & d) & ~(a & ~b & c & ~d) & ~(a & ~b & ~c & d) & ~(a & ~b & ~c & ~d) &
                     ~(~a & b & c & d) & ~(~a & b & c & ~d) & ~(~a & b & ~c & d) & ~(~a & b & ~c & ~d) &
                     ~(~a & ~b & c & d) & ~(~a & ~b & c & ~d) & ~(~a & ~b & ~c & d) & ~(~a & ~b & ~c & ~d);

endmodule

