module TopModule (
    input  clk,
    input  reset,
    output reg [31:0] q
);

    // Initialize the LFSR with a seed value of 32'h1
    reg [31:0] lfsr = 32'h1;

    // Define the taps for the Galois LFSR
    localparam TAP_32 = 32'h80000000; // Bit 32
    localparam TAP_22 = 32'h40000000; // Bit 22
    localparam TAP_2 = 32'h00000004;  // Bit 2
    localparam TAP_1 = 32'h00000001;  // Bit 1

    // Shift the LFSR on the positive edge of the clock
    always @(posedge clk) begin
        if (reset) begin
            lfsr <= 32'h1; // Reset the LFSR to 32'h1
        end else begin
            // Calculate the next state of the LFSR
            lfsr <= {lfsr[31:2], lfsr[30:2] ^ lfsr[1], lfsr[29:1] ^ lfsr[0]};
        end
    end

    // Assign the output q to the current state of the LFSR
    assign q = lfsr;

endmodule

