    reg [7:0] Q;

    // Multiplexer
    reg [2:0] MUX_IN;
    wire [7:0] MUX_OUT;

    // Assign inputs to multiplexer
    assign MUX_IN[0] = Q[0];
    assign MUX_IN[1] = Q[1];
    assign MUX_IN[2] = Q[2];
    assign MUX_IN[3] = Q[3];
    assign MUX_IN[4] = Q[4];
    assign MUX_IN[5] = Q[5];
    assign MUX_IN[6] = Q[6];
    assign MUX_IN[7] = Q[7];

    // Multiplexer logic
    always @(posedge clk) begin
        if (enable) begin
            case ({A, B, C})
                3'b000: MUX_OUT = Q[0];
                3'b001: MUX_OUT = Q[1];
                3'b010: MUX_OUT = Q[2];
                3'b011: MUX_OUT = Q[3];
                3'b100: MUX_OUT = Q[4];
                3'b101: MUX_OUT = Q[5];
                3'b110: MUX_OUT = Q[6];
                3'b111: MUX_OUT = Q[7];
                default: MUX_OUT = Q[0];
            endcase
        end else begin
            MUX_OUT = Q;
        end
    end

    // Shift register logic
    always @(posedge clk) begin
        if (enable) begin
            Q <= {Q[6:0], S};
        end
    end

    // Output
    assign Z = MUX_OUT;

endmodule

