    // Internal signal for the LFSR
    reg [4:0] lfsr;

    // Reset the LFSR on a rising edge of the clock
    always @(posedge clk) begin
        if (reset) begin
            lfsr <= 5'b11111; // Initial state for a 5-bit LFSR
        end else begin
            // Calculate the next state of the LFSR
            lfsr <= {lfsr[4:0], lfsr[TAP_5] ^ lfsr[TAP_3]};
