    typedef enum { A, B } state_t;
    state_t current_state, next_state;

    // Register to hold the current state
    reg [1:0] state_reg;

    // Assign the current state to the register
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= A;
            state_reg <= 2'b00;
        end else begin
            current_state <= next_state;
            state_reg <= state_reg;
        end
    end

    // Determine the next state based on the current state and input x
    always @(*) begin
        case (current_state)
            A: begin
                if (x == 0) begin
                    next_state = A;
                    z = 0;
                end else begin
                    next_state = B;
                    z = 1;
                end
            end
            B: begin
                if (x == 0) begin
                    next_state = B;
                    z = 1;
                end else begin
                    next_state = B;
                    z = 0;
                end
            end
        endcase
    end

