    wire [1:0] mux_2to1_4;

    // Implement the 2-to-1 multiplexers
    assign mux_2to1_1 = {c, d};
    assign mux_2to1_2 = {c, d};
    assign mux_2to1_3 = {c, d};
    assign mux_2to1_4 = {c, d};

    // Assign the outputs of the 2-to-1 multiplexers to mux_in
    assign mux_in[0] = mux_2to1_1[0];
    assign mux_in[1] = mux_2to1_2[1];
    assign mux_in[2] = mux_2to1_3[2];
