module TopModule (
    input  [3:0] in,
    output [3:0] out_both,
    output [3:0] out_any,
    output [3:0] out_different
);

    // out_both: Each bit indicates if both the corresponding input bit and its left neighbour are '1'
    assign out_both[0] = in[0] & in[1];
    assign out_both[1] = in[1] & in[2];
    assign out_both[2] = in[2] & in[3];
    assign out_both[3] = in[3] & in[0];

    // out_any: Each bit indicates if any of the corresponding input bit and its right neighbour are '1'
    assign out_any[0] = in[0] | in[1];
    assign out_any[1] = in[1] | in[2];
    assign out_any[2] = in[2] | in[3];
    assign out_any[3] = in[3] | in[0];

    // out_different: Each bit indicates if the corresponding input bit is different from its left neighbour
    assign out_different[0] = in[0] ^ in[1];
    assign out_different[1] = in[1] ^ in[2];
    assign out_different[2] = in[2] ^ in[3];
    assign out_different[3] = in[3] ^ in[0];

endmodule

