module TopModule (
    input  clk,
    input  reset,
    input  data,
    output reg start_shifting
);

    // Define the states of the finite-state machine
    typedef enum {IDLE, FIND_1, FIND_11, FIND_110, FIND_1101} state_t;
    state_t current_state, next_state;

    // Register to hold the current state
    reg [3:0] state_reg;

    // Register to hold the last four bits of the input stream
    reg [3:0] last_four_bits;

    // Initial state
    initial begin
        current_state = IDLE;
        state_reg = 4'b0000;
        start_shifting = 0;
    end

    // State transition logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= IDLE;
            state_reg <= 4'b0000;
            start_shifting <= 0;
        end else begin
            current_state <= next_state;
            state_reg <= {state_reg[2:0], data};
        end
    end

    // Next state logic
    always @(*) begin
        case (current_state)
            IDLE: begin
                if (data == 1'b1) begin
                    next_state = FIND_1;
                end else begin
                    next_state = IDLE;
                end
            end
            FIND_1: begin
                if (data == 1'b1) begin
                    next_state = FIND_11;
                end else begin
                    next_state = IDLE;
                end
            end
            FIND_11: begin
                if (data == 1'b0) begin
                    next_state = FIND_110;
                end else begin
                    next_state = IDLE;
                end
            end
            FIND_110: begin
                if (data == 1'b1) begin
                    next_state = FIND_1101;
                end else begin
                    next_state = IDLE;
                end
            end
            FIND_1101: begin
                if (data == 1'b1) begin
                    next_state = FIND_1101;
                end else begin
                    next_state = IDLE;
                end
            end
            default: begin
                next_state = IDLE;
            end
        endcase
    end

    // Output logic
    always @(*) begin
        case (current_state)
            FIND_1101: begin
                start_shifting = 1'b1;
            end
            default: begin
                start_shifting = 1'b0;
            end
        endcase
    end

endmodule

