module TopModule (
    input  y[5:0],  // 6-bit input
    input  w,       // 1-bit input
    output Y1,      // 1-bit output
    output Y3       // 1-bit output
);

    // Define the states
    typedef enum { A, B, C, D, E, F } state_t;
    state_t current_state, next_state;

    // Assign states to y[5:0]
    always_comb begin
        case (y[5:0])
            6'b000001: current_state = A;
            6'b000010: current_state = B;
            6'b000100: current_state = C;
            6'b001000: current_state = D;
            6'b010000: current_state = E;
            6'b100000: current_state = F;
            default: current_state = A;
        endcase
    end

    // Next-state logic
    always_comb begin
        case (current_state)
            A: next_state = (w == 1'b0) ? B : A;
            B: next_state = (w == 1'b0) ? C : D;
            C: next_state = (w == 1'b0) ? E : D;
            D: next_state = (w == 1'b0) ? F : A;
            E: next_state = (w == 1'b1) ? E : D;
            F: next_state = (w == 1'b1) ? C : D;
            default: next_state = A;
        endcase
    end

    // Output logic
    always_comb begin
        Y1 = y[1];
        Y3 = y[3];
    end

endmodule

