                if (in == 0) begin
                    next_state = A;
                end else begin
                    next_state = B;
                end
            end
            A: begin
                if (in == 0) begin
                    next_state = B;
                end else begin
                    next_state = A;
                end
            end
        endcase
    end

    // Output logic
    assign out = current_state == B ? 1'b1 : 1'b0;

