module TopModule (
    input  clk,
    input  load,
    input  [511:0] data,
    output [511:0] q
);

    // Initialize the q register with the initial data
    reg [511:0] q_reg = 0;

    // Rule 90 logic
    always @(posedge clk) begin
        if (load) begin
            q_reg <= data;
        end else begin
            // Create a temporary register to hold the next state
            reg [511:0] next_q_reg;

            // Apply Rule 90 to each cell
            for (int i = 0; i < 512; i++) begin
                // Handle the boundary conditions
                reg left = (i == 0) ? 0 : q_reg[i - 1];
                reg center = q_reg[i];
                reg right = (i == 511) ? 0 : q_reg[i + 1];

                // Apply Rule 90
                next_q_reg[i] = (left ^ center ^ right);
            end

            // Update the q register with the next state
            q_reg <= next_q_reg;
        end
    end

    // Output the q register
    assign q = q_reg;

endmodule

