    localparam [7:0] SCANCODE_1 = 8'h16;
    localparam [7:0] SCANCODE_2 = 8'h1e;
    localparam [7:0] SCANCODE_3 = 8'h26;
    localparam [7:0] SCANCODE_4 = 8'h25;
    localparam [7:0] SCANCODE_5 = 8'h2e;
    localparam [7:0] SCANCODE_6 = 8'h36;
    localparam [7:0] SCANCODE_7 = 8'h3d;
    localparam [7:0] SCANCODE_8 = 8'h3e;
    localparam [7:0] SCANCODE_9 = 8'h46;

    // Assign the output based on the recognized scancode
    always_comb begin
        out = 4'b0;
        valid = 1'b0;

        if (code == SCANCODE_0) begin
            out = 4'b0000;
            valid = 1'b1;
        end else if (code == SCANCODE_1) begin
            out = 4'b0001;
            valid = 1'b1;
        end else if (code == SCANCODE_2) begin
            out = 4'b0010;
            valid = 1'b1;
        end else if (code == SCANCODE_3) begin
            out = 4'b0011;
            valid = 1'b1;
        end else if (code == SCANCODE_4) begin
            out = 4'b0100;
            valid = 1'b1;
        end else if (code == SCANCODE_5) begin
            out = 4'b0101;
