        end else if (code == SCANCODE_6) begin
            out = 4'b0110;
            valid = 1'b1;
        end else if (code == SCANCODE_7) begin
            out = 4'b0111;
            valid = 1'b1;
        end else if (code == SCANCODE_8) begin
            out = 4'b1000;
            valid = 1'b1;
        end else if (code == SCANCODE_9) begin
            out = 4'b1001;
