);

    // Internal register
    reg [63:0] shift_reg;

    // Process to handle the shift operation
    always @(posedge clk or posedge load) begin
        if (load) begin
            // Load the data into the shift register
            shift_reg <= data;
        end else if (ena) begin
            case (amount)
                2'b00: // Shift left by 1 bit
                    shift_reg <= {shift_reg[62:0], shift_reg[63]};
                2'b01: // Shift left by 8 bits
                    shift_reg <= {shift_reg[55:0], shift_reg[63:56]};
                2'b10: // Shift right by 1 bit
                    shift_reg <= {shift_reg[1:0], shift_reg[63:1]};
                2'b11: // Shift right by 8 bits
                    shift_reg <= {shift_reg[63:56], shift_reg[55:0]};
                default: // Invalid amount, do nothing
                    shift_reg <= shift_reg;
            endcase
        end
    end

    // Output the shift register contents
    assign q = shift_reg;

endmodule

