module TopModule (
    input  clk,
    input  load,
    input  [511:0] data,
    output [511:0] q
);

    // Initialize the state of the 512-cell system
    reg [511:0] q_reg = 0;

    // Temporary register to hold the next state of the system
    reg [511:0] q_next;

    // Rule 110 table
    always @(posedge clk) begin
        if (load) begin
            // Load the data into the system
            q_reg <= data;
        end else begin
            // Calculate the next state of the system
            for (int i = 0; i < 512; i++) begin
                // Get the left, center, and right neighbors
                reg left = (i == 0) ? 0 : q_reg[i - 1];
                reg center = q_reg[i];
                reg right = (i == 511) ? 0 : q_reg[i + 1];

                // Determine the next state based on Rule 110
                case ({right, center, left})
                    4'b000: q_next[i] = 0;
                    4'b001: q_next[i] = 1;
                    4'b010: q_next[i] = 1;
                    4'b011: q_next[i] = 0;
                    4'b100: q_next[i] = 1;
                    4'b101: q_next[i] = 1;
                    4'b110: q_next[i] = 1;
                    4'b111: q_next[i] = 0;
                    default: q_next[i] = 0;
                endcase
            end

            // Update the system state
            q_reg <= q_next;
        end
    end

    // Output the current state of the system
    assign q = q_reg;

endmodule

