    state_t current_state, next_state;

    // Initialize the FSM state
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= IDLE;
            done <= 0;
        end else begin
            current_state <= next_state;
        end
    end

    // Next state logic
    always @(*) begin
        case (current_state)
            IDLE: begin
                if (in[3]) begin
                    next_state <= BYTE1;
                end else begin
                    next_state <= IDLE;
                end
            end
            BYTE1: begin
                if (in[3]) begin
                    next_state <= BYTE2;
                end else begin
                    next_state <= IDLE;
                end
            end
            BYTE2: begin
                if (in[3]) begin
                    next_state <= BYTE3;
                end else begin
                    next_state <= IDLE;
                end
            end
            BYTE3: begin
                if (in[3]) begin
                    next_state <= IDLE;
                    done <= 1;
                end else begin
                    next_state <= IDLE;
                end
            end
            default: begin
                next_state <= IDLE;
            end
        endcase
    end

endmodule

module TopModule (
    input  clk,
    input  aresetn,
    input  x,
    output z
);

    // Define the states
    typedef enum logic [1:0] {
        IDLE,
        WAIT_1,
        WAIT_0
    } state_t;

    // State register
    state_t current_state, next_state;

    // Output register
    reg z_reg;

    // Initial state
    initial begin
        current_state = IDLE;
        z_reg = 0;
    end

    // State transition logic
    always @(posedge clk or negedge aresetn) begin
        if (!aresetn) begin
            current_state <= IDLE;
            z_reg <= 0;
        end else begin
            current_state <= next_state;
            z_reg <= (current_state == WAIT_0 && x == 1'b1);
        end
    end

    // Next state logic
    always @(*) begin
        case (current_state)
            IDLE: begin
                if (x == 1'b1) begin
                    next_state = WAIT_1;
                end else begin
                    next_state = IDLE;
                end
            end
            WAIT_1: begin
                if (x == 1'b0) begin
                    next_state = WAIT_0;
                end else begin
                    next_state = IDLE;
                end
            end
            WAIT_0: begin
                if (x == 1'b1) begin
                    next_state = WAIT_1;
                end else begin
                    next_state = IDLE;
                end
            end
        endcase
    end

    // Output assignment
    assign z = z_reg;

endmodule

