module top_module (
    input x,
    input y,
    output z
);

    // Instantiate four A submodules
    A a1 (x, y, z);
    A a2 (x, y, z);
    A a3 (x, y, z);
    A a4 (x, y, z);

    // Instantiate two B submodules
    B b1 (x, y, z);
    B b2 (x, y, z);

    // Connect the outputs of the first A submodule to the first OR
    wire a1_out = a1.z;
    wire b1_out = b1.z;
    wire or_out = a1_out | b1_out;

    // Connect the outputs of the second A submodule to the second AND
    wire a2_out = a2.z;
    wire b2_out = b2.z;
    wire and_out = a2_out & b2_out;

    // Connect the outputs of the OR and AND to the XOR
    wire xor_out = or_out ^ and_out;

    // Assign the XOR output to the z output
    assign z = xor_out;

endmodule

// A submodule implementing the boolean function z = (x^y) & x
module A (
    input x,
    input y,
    output z
);
    assign z = (x ^ y) & x;
endmodule

// B submodule implementing the boolean function z = (x^y) & x
module B (
    input x,
    input y,
    output z
);
    assign z = (x ^ y) & x;
endmodule

