module TopModule (
    input  clk,
    input  reset,
    input  s,
    input  w,
    output z
);

    // Define the states
    typedef enum { A, B } state_t;
    state_t current_state, next_state;

    // Register to hold the current state
    reg [1:0] state_reg;

    // Register to hold the count of w = 1 in the last three clock cycles
    reg [2:0] w_count;

    // Register to hold the output z
    reg z_reg;

    // Always block to handle state transitions
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= A;
            state_reg <= A;
            w_count <= 0;
            z_reg <= 0;
        end else begin
            current_state <= next_state;
            state_reg <= current_state;
            w_count <= w_count + (w ? 1 : 0);
            z_reg <= (w_count == 2) ? 1 : 0;
        end
    end

    // Next state logic
