module TopModule (
    input  clk,
    input  reset,
    input  ena,
    output pm,
    output [7:0] hh,
    output [7:0] mm,
    output [7:0] ss
);

    // Constants for BCD encoding
    localparam BCD_0 = 4'b0000;
    localparam BCD_1 = 4'b0001;
    localparam BCD_2 = 4'b0010;
    localparam BCD_3 = 4'b0011;
    localparam BCD_4 = 4'b0100;
    localparam BCD_5 = 4'b0101;
    localparam BCD_6 = 4'b0110;
    localparam BCD_7 = 4'b0111;
    localparam BCD_8 = 4'b1000;
    localparam BCD_9 = 4'b1001;

    // Counter for hours (0-11)
    reg [3:0] hour_counter;
    reg [3:0] hour_bcd;

    // Counter for minutes (0-59)
    reg [5:0] minute_counter;
    reg [7:0] minute_bcd;

    // Counter for seconds (0-59)
    reg [5:0] second_counter;
    reg [7:0] second_bcd;

    // AM/PM indicator
    reg pm_flag;

    // Reset logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            hour_counter <= 4'b0000;
            minute_counter <= 6'b000000;
            second_counter <= 6'b000000;
            pm_flag <= 1'b0;
        end else begin
            if (ena) begin
                if (second_counter == 59) begin
                    second_counter <= 6'b000000;
                    if (minute_counter == 59) begin
                        minute_counter <= 6'b000000;
                        if (hour_counter == 11) begin
                            hour_counter <= 4'b0000;
                            pm_flag <= ~pm_flag;
                        end else begin
                            hour_counter <= hour_counter + 1'b1;
                        end
                    end else begin
                        minute_counter <= minute_counter + 1'b1;
                    end
                end else begin
                    second_counter <= second_counter + 1'b1;
                end
            end
        end
    end

    // BCD encoding for hours
    assign hour_bcd = BCD_0 + hour_counter;

    // BCD encoding for minutes
    assign minute_bcd = BCD_0 + minute_counter;

    // BCD encoding for seconds
    assign second_bcd = BCD_0 + second_counter;

    // Output the BCD encoded values
    assign hh = hour_bcd;
    assign mm = minute_bcd;
    assign ss = second_bcd;

    // Output the AM/PM indicator
    assign pm = pm_flag;

endmodule

module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    output walk_left,
    output walk_right,
    output aaah
);

    // Define the states
    typedef enum {WALK_LEFT, WALK_RIGHT, FALL} state_t;
    state_t current_state, next_state;

    // Initial state
    initial begin
        current_state = WALK_LEFT;
    end

    // State machine logic
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= WALK_LEFT;
        end else begin
            current_state <= next_state;
        end
    end

    // Next state logic
    always @(*) begin
        case (current_state)
            WALK_LEFT: begin
                if (bump_right) begin
                    next_state = WALK_RIGHT;
                end else if (ground) begin
                    next_state = WALK_LEFT;
                end else begin
                    next_state = FALL;
                end
            end
            WALK_RIGHT: begin
                if (bump_left) begin
                    next_state = WALK_LEFT;
                end else if (ground) begin
                    next_state = WALK_RIGHT;
                end else begin
                    next_state = FALL;
                end
            end
            FALL: begin
                if (ground) begin
                    next_state = WALK_LEFT;
                end else begin
                    next_state = FALL;
                end
            end
        endcase
    end

    // Output logic
    always @(*) begin
        walk_left = (current_state == WALK_LEFT);
        walk_right = (current_state == WALK_RIGHT);
        aaah = (current_state == FALL);
    end

endmodule

