module TopModule (
    input  clk,
    input  reset,
    input  data,
    input  done_counting,
    input  ack,
    output shift_ena,
    output counting,
    output done
);

    // Define the states of the finite-state machine
    typedef enum logic [2:0] {
        IDLE,
        WAIT_PATTERN,
        SHIFT_DATA,
        COUNTING,
        NOTIFY_USER,
        WAIT_ACK
    } state_t;

    // Declare the state variable
    state_t current_state, next_state;

    // Declare the state register
    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= IDLE;
        end else begin
            current_state <= next_state;
        end
    end

    // Declare the state transition logic
    always_comb begin
        next_state = current_state;

        case (current_state)
            IDLE: begin
                if (data == 4'b1101) begin
                    next_state = WAIT_PATTERN;
                end
            end
            WAIT_PATTERN: begin
                if (data == 4'b1101) begin
                    next_state = SHIFT_DATA;
                end else begin
                    next_state = IDLE;
                end
            end
            SHIFT_DATA: begin
                if (data == 4'b1101) begin
                    next_state = WAIT_PATTERN;
                end else begin
                    next_state = COUNTING;
                end
            end
            COUNTING: begin
                if (done_counting) begin
                    next_state = NOTIFY_USER;
                end
            end
            NOTIFY_USER: begin
                if (ack) begin
                    next_state = IDLE;
                end
            end
            WAIT_ACK: begin
                if (ack) begin
                    next_state = IDLE;
                end
            end
        endcase
    end

    // Declare the output logic
    assign shift_ena = (current_state == SHIFT_DATA);
    assign counting = (current_state == COUNTING);
    assign done = (current_state == NOTIFY_USER);

endmodule

