    output aaah,
    output digging
);

    // Define states
    typedef enum {WALK_LEFT, WALK_RIGHT, FALLING, DIGGING} state_t;
    state_t current_state, next_state;

    // Initial state
    initial begin
        current_state = WALK_LEFT;
    end

    // State machine logic
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= WALK_LEFT;
        end else begin
            current_state <= next_state;
        end
    end

    // Next state logic
    always @(*) begin
        case (current_state)
            WALK_LEFT: begin
                if (bump_right) begin
                    next_state = WALK_RIGHT;
                end else if (ground && !dig) begin
                    next_state = WALK_LEFT;
                end else if (ground && dig) begin
                    next_state = DIGGING;
                end else if (!ground) begin
                    next_state = FALLING;
                end else begin
                    next_state = WALK_LEFT;
                end
            end
            WALK_RIGHT: begin
                if (bump_left) begin
                    next_state = WALK_LEFT;
                end else if (ground && !dig) begin
                    next_state = WALK_RIGHT;
                end else if (ground && dig) begin
                    next_state = DIGGING;
                end else if (!ground) begin
                    next_state = FALLING;
                end else begin
                    next_state = WALK_RIGHT;
                end
            end
            FALLING: begin
                if (ground) begin
                    next_state = WALK_LEFT;
                end else begin
                    next_state = FALLING;
                end
            end
            DIGGING: begin
                if (ground) begin
                    next_state = WALK_LEFT;
                end else begin
                    next_state = DIGGING;
                end
            end
        endcase
    end

    // Output logic
    always @(*) begin
        walk_left = (current_state == WALK_LEFT);
        walk_right = (current_state == WALK_RIGHT);
        aaah = (current_state == FALLING);
        digging = (current_state == DIGGING);
