    input  reset,
    input  in,
    output out_bytes,
    output done
);

    // State machine states
    typedef enum {IDLE, WAIT_1, WAIT_2, WAIT_3, DONE} state_t;
    state_t current_state, next_state;

    // State register
    reg [2:0] state_reg;

    // Byte buffer
    reg [7:0] byte_buffer [0:2];
    reg [23:0] out_bytes_reg;

    // Byte counter
    reg [1:0] byte_counter;

    // FSM logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= IDLE;
            state_reg <= IDLE;
            byte_buffer <= {8{8'b0}};
            out_bytes_reg <= 24'b0;
            byte_counter <= 2'b0;
            done <= 0;
        end else begin
            current_state <= next_state;
            state_reg <= current_state;

            case (current_state)
                IDLE: begin
                    if (in[3]) begin
                        next_state <= WAIT_1;
                        byte_counter <= 2'b0;
                    end else begin
                        next_state <= IDLE;
                    end
                end
                WAIT_1: begin
                    if (in[3]) begin
                        byte_buffer[0] <= in;
                        next_state <= WAIT_2;
                    end else begin
                        next_state <= IDLE;
                    end
                end
                WAIT_2: begin
                    if (in[3]) begin
                        byte_buffer[1] <= in;
                        next_state <= WAIT_3;
                    end else begin
                        next_state <= IDLE;
                    end
                end
                WAIT_3: begin
                    if (in[3]) begin
                        byte_buffer[2] <= in;
                        next_state <= DONE;
                    end else begin
                        next_state <= IDLE;
                    end
                end
                DONE: begin
                    out_bytes_reg <= {byte_buffer[2], byte_buffer[1], byte_buffer[0]};
                    done <= 1;
                    next_state <= IDLE;
                end
            endcase
        end
    end

    // Output assignment
    assign out_bytes = out_bytes_reg;

