                if (ground) begin
                    next_state = WALK_LEFT;
                end else if (dig) begin
                    next_state = DIGGING;
                end else begin
                    next_state = FALLING;
                end
            end
            SPLATTERED: begin
                next_state = SPLATTERED;
            end
        endcase
    end

    // Output logic
    always @(*) begin
        case (current_state)
            WALK_LEFT: begin
                walk_left = 1;
