  full_adder fa0 (.a(x[0]), .b(y[0]), .cin(carry_in[0]), .sum(sum_out[0]), .cout(carry_out[0]));
  full_adder fa1 (.a(x[1]), .b(y[1]), .cin(carry_in[1]), .sum(sum_out[1]), .cout(carry_out[1]));
  full_adder fa2 (.a(x[2]), .b(y[2]), .cin(carry_in[2]), .sum(sum_out[2]), .cout(carry_out[2]));
  full_adder fa3 (.a(x[3]), .b(y[3]), .cin(carry_in[3]), .sum(sum_out[3]), .cout(carry_out[3]));

