  input reset,
  output reg [7:0] q
);

  // Instantiate 8 D flip-flops
  reg [7:0] dffs [0:7];

  // Synchronous reset for all D flip-flops
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      for (int i = 0; i < 8; i++) begin
        dffs[i] <= 8'b0;
      end
    end else begin
      for (int i = 0; i < 8; i++) begin
        dffs[i] <= d[i];
      end
    end
  end

  // Assign the output of the last D flip-flop to q
  assign q = dffs[7];

endmodule

