  // Extract the sign bit of the input
  wire sign_bit = in[7];

  // Create 24 copies of the sign bit
  wire [23:0] sign_extension = {sign_bit, sign_bit, sign_bit, sign_bit, sign_bit, sign_bit, sign_bit, sign_bit, sign_bit, sign_bit, sign_bit, sign_bit, sign_bit, sign_bit, sign_bit, sign_bit, sign_bit, sign_bit, sign_bit, sign_bit, sign_bit, sign_bit, sign_bit};

  // Concatenate the sign extension with the input
  assign out = {sign_extension, in};

