module TopModule (
  input clk,
  input [7:0] in,
  output reg [7:0] anyedge
);

  // Internal signals to track the previous state of each bit
  reg [7:0] prev_in;

  // Process to detect any edge
  always @(posedge clk) begin
    // Update the previous state of each bit
    prev_in <= in;

    // Check for any edge and set anyedge accordingly
    for (int i = 0; i < 8; i++) begin
      if (in[i] != prev_in[i]) begin
        anyedge[i] <= 1'b1;
      end else begin
        anyedge[i] <= 1'b0;
      end
    end
  end

endmodule

module TopModule (
  input clk,
  input [7:0] d,
  input reset,
  output reg [7:0] q
);

  // Instantiate 8 D flip-flops
  reg [7:0] dffs [0:7];

  // Reset the D flip-flops to 0x34
  initial begin
    for (int i = 0; i < 8; i++) begin
      dffs[i] = 8'h34;
    end
  end

  // Synchronous reset
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      for (int i = 0; i < 8; i++) begin
        dffs[i] <= 8'h34;
      end
    end else begin
      for (int i = 0; i < 8; i++) begin
        dffs[i] <= d[i];
      end
    end
  end

  // Output the current state of the D flip-flops
  assign q = dffs;

endmodule

