  reg [7:0] dffs [0:7];

  // Reset all D flip-flops on areset
  always @(posedge clk or posedge areset) begin
    if (areset) begin
      for (int i = 0; i < 8; i++) begin
        dffs[i] <= 8'b0;
      end
    end else begin
      for (int i = 0; i < 8; i++) begin
        dffs[i] <= d[i];
      end
    end
  end

  // Assign the output q to the last D flip-flop
  assign q = dffs[7];

endmodule

