  input p2d,
  output p2y
);

  // Define the 7420 chip with two 4-input NAND gates
  wire nand1a, nand1b, nand1c, nand1d;
  wire nand2a, nand2b, nand2c, nand2d;

  // Implement the first 4-input NAND gate
  assign nand1a = ~p1a & ~p1b & ~p1c & ~p1d;
  assign nand1b = ~p1a & ~p1b & ~p1c & p1d;
  assign nand1c = ~p1a & ~p1b & p1c & ~p1d;
  assign nand1d = ~p1a & ~p1b & p1c & p1d;

  // Implement the second 4-input NAND gate
  assign nand2a = ~p2a & ~p2b & ~p2c & ~p2d;
  assign nand2b = ~p2a & ~p2b & ~p2c & p2d;
  assign nand2c = ~p2a & ~p2b & p2c & ~p2d;
  assign nand2d = ~p2a & ~p2b & p2c & p2d;

  // Assign the outputs of the 7420 chip to the module's output ports
  assign p1y = nand1a | nand1b | nand1c | nand1d;
  assign p2y = nand2a | nand2b | nand2c | nand2d;

endmodule

