module TopModule (
  input clk,
  input reset,
  output [3:1] ena,
  output reg [15:0] q
);

  // Define the BCD counter state
  typedef enum {ZERO, ONE, TWO, THREE, FOUR, FIVE, SIX, SEVEN, EIGHT, NINE} BCDState;

  // State variable
  BCDState state;

  // Internal signals
  reg [3:0] digit;
  reg [3:0] next_digit;

  // Enable signals for each digit
  reg [3:0] digit_ena;

  // Initial state
  initial begin
    state = ZERO;
    digit = 4'b0000;
    digit_ena = 4'b0000;
  end

  // Clock edge sensitive logic
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      state <= ZERO;
      digit <= 4'b0000;
      digit_ena <= 4'b0000;
    end else begin
      // Update the state based on the current digit
      case (state)
        ZERO: begin
          if (digit == 9) begin
            state <= ONE;
            digit <= 4'b0000;
          end else begin
            state <= ZERO;
            digit <= digit + 1;
          end
        end
        ONE: begin
          if (digit == 9) begin
            state <= TWO;
            digit <= 4'b0000;
          end else begin
            state <= ONE;
            digit <= digit + 1;
          end
        end
        TWO: begin
          if (digit == 9) begin
            state <= THREE;
            digit <= 4'b0000;
          end else begin
            state <= TWO;
            digit <= digit + 1;
          end
        end
        THREE: begin
          if (digit == 9) begin
            state <= FOUR;
            digit <= 4'b0000;
          end else begin
            state <= THREE;
            digit <= digit + 1;
          end
        end
        FOUR: begin
          if (digit == 9) begin
            state <= FIVE;
            digit <= 4'b0000;
          end else begin
            state <= FOUR;
            digit <= digit + 1;
          end
        end
        FIVE: begin
          if (digit == 9) begin
            state <= SIX;
            digit <= 4'b0000;
          end else begin
            state <= FIVE;
            digit <= digit + 1;
          end
        end
        SIX: begin
          if (digit == 9) begin
            state <= SEVEN;
            digit <= 4'b0000;
          end else begin
            state <= SIX;
            digit <= digit + 1;
          end
        end
        SEVEN: begin
          if (digit == 9) begin
            state <= EIGHT;
            digit <= 4'b0000;
          end else begin
            state <= SEVEN;
            digit <= digit + 1;
          end
        end
        EIGHT: begin
          if (digit == 9) begin
            state <= NINE;
            digit <= 4'b0000;
          end else begin
            state <= EIGHT;
            digit <= digit + 1;
          end
        end
        NINE: begin
          state <= ZERO;
          digit <= 4'b0000;
        end
      endcase

      // Update the enable signals
      digit_ena = {digit_ena[2:0], digit == 9};

      // Assign the output
      q = {digit_ena, digit};
    end
  end

endmodule

module TopModule (
