module TopModule (
  input clk,
  input resetn,
  input [1:0] byteena,
  input [15:0] d,
  output reg [15:0] q
);

  // Array of 16 D flip-flops
  reg [15:0] dffs [0:15];

  // Synchronous reset
  always @(posedge clk or negedge resetn) begin
    if (!resetn) begin
      for (int i = 0; i < 16; i++) begin
        dffs[i] <= 16'h0;
      end
    end
  end

  // Write to D flip-flops based on byteena
  always @(posedge clk) begin
    for (int i = 0; i < 16; i++) begin
      if (byteena[1] && (i >= 8)) begin
        dffs[i] <= d[15:8];
      end else if (byteena[0] && (i < 8)) begin
        dffs[i] <= d[7:0];
      end
    end
  end

  // Output the value of the D flip-flops
  assign q = dffs;

endmodule

module TopModule (
  input clk,
  input x,
  output z
);

  // Define the states of the finite state machine
  typedef enum {STATE_XOR, STATE_AND, STATE_OR} state_t;
  state_t current_state, next_state;

  // Define the D flip-flops
  reg q_xor, q_and, q_or;

  // Initial values for the D flip-flops
  initial begin
    q_xor = 0;
    q_and = 0;
    q_or = 0;
  end

  // State machine logic
  always @(posedge clk) begin
    current_state <= next_state;

    case (current_state)
      STATE_XOR: begin
        q_xor <= x;
        next_state <= STATE_AND;
      end
      STATE_AND: begin
        q_and <= ~q_xor;
        next_state <= STATE_OR;
      end
      STATE_OR: begin
        q_or <= ~q_xor & ~q_and;
        next_state <= STATE_XOR;
      end
    endcase
  end

  // Output the result of the NOR gate
  assign z = ~q_xor & ~q_and & ~q_or;

endmodule

module TopModule (
  input clk,
  input areset,
  input train_valid,
  input train_taken,
  output logic [1:0] state
);

  // Internal signal to hold the counter value
  logic [1:0] counter;

  // Asynchronous reset
  always_ff @(posedge areset) begin
    counter <= 2'b01; // Reset to weakly not-taken
  end

  // Saturating counter logic
  always_ff @(posedge clk) begin
    if (areset) begin
      counter <= 2'b01; // Reset on positive edge of areset
    end else if (train_valid && train_taken) begin
      // Increment counter if train_valid and train_taken are both 1
      if (counter < 3) begin
        counter <= counter + 1;
      end
    end else if (train_valid && !train_taken) begin
      // Decrement counter if train_valid and train_taken are both 0
      if (counter > 0) begin
        counter <= counter - 1;
      end
    end
  end

  // Output the counter value
  assign state = counter;

endmodule

