  reg q_next;
  reg q_prev;

  // Clock edge detector
  always @(posedge clk or negedge clk) begin
    if (clk) begin
      q_prev <= q;
    end
  end

  // Single-edge triggered flip-flop
  always @(posedge clk) begin
    if (q_prev != d) begin
      q_next <= d;
    end
  end

  // Output assignment
  assign q = q_next;

endmodule

module TopModule (
  input in,
  input [3:0] state,
  output reg [3:0] next_state,
  output out
);

  // State transition logic
  always @(*) begin
    case (state)
      4'b0001: next_state = in ? 4'b0010 : 4'b0001;
      4'b0010: next_state = in ? 4'b0100 : 4'b0010;
      4'b0100: next_state = in ? 4'b0001 : 4'b1000;
      4'b1000: next_state = in ? 4'b0010 : 4'b0100;
      default: next_state = 4'b0001; // Default case, should not happen
    endcase
  end

  // Output logic
  always @(*) begin
    case (state)
      4'b0001: out = 0;
      4'b0010: out = 0;
      4'b0100: out = 0;
      4'b1000: out = 1;
      default: out = 0; // Default case, should not happen
    endcase
  end

endmodule

