module TopModule (
  input clk,
  input reset,
  output reg [31:0] q
);

  // Initialize the shift register with 32'h1
  reg [31:0] lfsr = 32'h1;

  // Define the taps for the Galois LFSR
  parameter TAP_32 = 32'h80000000;
  parameter TAP_22 = 32'h4000000;
  parameter TAP_2 = 32'h4;
  parameter TAP_1 = 32'h1;

  // Reset the shift register on a rising edge of the clock
  always @(posedge clk) begin
    if (reset) begin
      lfsr <= 32'h1;
    end else begin
      // Calculate the next state of the shift register
      lfsr <= {lfsr[31:1], lfsr[31] ^ lfsr[TAP_32] ^ lfsr[TAP_22] ^ lfsr[TAP_2] ^ lfsr[TAP_1]};
    end
  end

  // Assign the output q to the current state of the shift register
  assign q = lfsr;

endmodule

