module TopModule (
  input clk,
  input reset,
  input data,
  output start_shifting
);

  // Define the state type
  typedef enum {IDLE, FIND_1, FIND_11, FIND_110, FIND_1101} state_t;

  // Declare the state variable
  state_t current_state, next_state;

  // Declare the shift register
  reg [3:0] shift_reg;

  // Initial state
  initial begin
    current_state = IDLE;
    start_shifting = 0;
  end

  // State machine process
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      current_state <= IDLE;
      start_shifting <= 0;
    end else begin
      current_state <= next_state;
      case (current_state)
        IDLE: begin
          if (data) begin
            shift_reg <= {data, shift_reg[3:1]};
            next_state <= FIND_1;
          end else begin
            next_state <= IDLE;
          end
        end
        FIND_1: begin
          if (data) begin
            shift_reg <= {data, shift_reg[3:1]};
            next_state <= FIND_11;
          end else begin
            next_state <= IDLE;
          end
        end
        FIND_11: begin
          if (data) begin
            shift_reg <= {data, shift_reg[3:1]};
            next_state <= FIND_110;
          end else begin
            next_state <= IDLE;
          end
        end
        FIND_110: begin
          if (data) begin
            shift_reg <= {data, shift_reg[3:1]};
            next_state <= FIND_1101;
          end else begin
            next_state <= IDLE;
          end
        end
        FIND_1101: begin
          if (data) begin
            shift_reg <= {data, shift_reg[3:1]};
            next_state <= FIND_1101;
          end else begin
            start_shifting <= 1;
            next_state <= IDLE;
          end
        end
      endcase
    end
  end

endmodule

