  always @(posedge clk or posedge reset) begin
    if (reset) begin
      current_state <= B;
    end else begin
      current_state <= next_state;
    end
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      B: begin
        if (in == 0) begin
          next_state = A;
        end else begin
          next_state = B;
        end
      end
      A: begin
        if (in == 0) begin
          next_state = B;
