module TopModule (
  input clk,
  input load,
  input [511:0] data,
  output reg [511:0] q
);

  // Initialize q with the initial state
  initial begin
    q = 512'b0;
  end

  // Rule 90 implementation
  always @(posedge clk) begin
    if (load) begin
      q = data;
    end else begin
      // Create a temporary array to hold the next state
      reg [511:0] next_q;
      next_q = 512'b0;

      // Apply Rule 90 to each cell
      for (int i = 0; i < 512; i++) begin
        // Handle boundary conditions
        reg left, center, right;
        left = (i == 0) ? 0 : q[i - 1];
        center = q[i];
        right = (i == 511) ? 0 : q[i + 1];

        // Apply Rule 90
        next_q[i] = (left ^ center ^ right);
      end

      // Update q with the next state
      q = next_q;
    end
  end

endmodule

