module TopModule (
  input clk,
  input load,
  input [511:0] data,
  output reg [511:0] q
);

  // Initialize q with the initial state
  always @(posedge clk) begin
    if (load) begin
      q <= data;
    end
  end

  // Rule 110 implementation
  always @(posedge clk) begin
    reg [511:0] next_q;
    for (int i = 0; i < 512; i++) begin
      // Handle the boundary conditions
      reg left = (i == 0) ? 0 : q[i - 1];
      reg center = q[i];
      reg right = (i == 511) ? 0 : q[i + 1];

      // Apply Rule 110
      case ({left, center, right})
        4'b000: next_q[i] = 0;
        4'b001: next_q[i] = 1;
        4'b010: next_q[i] = 1;
        4'b011: next_q[i] = 0;
        4'b100: next_q[i] = 1;
        4'b101: next_q[i] = 1;
        4'b110: next_q[i] = 1;
        4'b111: next_q[i] = 0;
      endcase
    end
    q <= next_q;
  end

endmodule

