module TopModule (
  input clk,
  input reset,
  input s,
  input w,
  output reg z
);

  // Define the states
  typedef enum {A, B} state_t;
  state_t current_state, next_state;

  // Register to hold the current state
  reg [1:0] state_reg;

  // Counter to track the number of w cycles
  reg [2:0] w_counter;

  // Register to hold the count of w = 1 in the last three cycles
  reg [1:0] w_count;

  // Always block for state machine logic
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      current_state <= A;
      state_reg <= 2'b00;
      w_counter <= 3'b000;
      w_count <= 2'b00;
      z <= 1'b0;
    end else begin
      // Update the current state
      current_state <= next_state;

      // Update the state register
      state_reg <= current_state;

      // Update the w_counter
      if (current_state == B) begin
        w_counter <= w_counter + 1'b1;
      end else begin
        w_counter <= 3'b000;
      end

      // Update the w_count
      if (current_state == B) begin
        if (w) begin
          w_count <= w_count + 1'b1;
        end else begin
          w_count <= 2'b00;
        end
      end else begin
        w_count <= 2'b00;
      end

      // Determine the next state
      case (current_state)
        A: begin
          if (s) begin
            next_state <= B;
          end else begin
            next_state <= A;
          end
        end
        B: begin
          if (w_counter == 3'b111) begin
            if (w_count == 2'b10) begin
              z <= 1'b1;
            end else begin
              z <= 1'b0;
            end
            next_state <= A;
          end else begin
            next_state <= B;
          end
        end
      endcase
    end
  end

endmodule

