  typedef enum {STATE_000, STATE_001, STATE_010, STATE_011, STATE_100} state_t;
  state_t current_state, next_state;

  // Initial state
  initial begin
    current_state = STATE_000;
  end

  // Next state logic
  always @(posedge clk) begin
    current_state <= next_state;
  end

  // Output logic
  always @(current_state, x, y) begin
    case (current_state)
      STATE_000: begin
        if (x == 0) begin
          next_state = (y == 3'b000) ? STATE_000 : STATE_001;
          Y0 = y[0];
          z = 0;
        end else begin
          next_state = (y == 3'b000) ? STATE_001 : STATE_010;
          Y0 = y[0];
          z = 1;
        end
