          next_state = (y == 3'b100) ? STATE_011 : STATE_100;
          Y0 = y[0];
          z = 1;
        end
      end
      STATE_010: begin
        if (x == 0) begin
          next_state = (y == 3'b010) ? STATE_010 : STATE_011;
          Y0 = y[0];
