        end else begin
          next_state = (y == 3'b001) ? STATE_001 : STATE_010;
          Y0 = y[0];
          z = 1;
        end
      end
      STATE_011: begin
        if (x == 0) begin
          next_state = (y == 3'b001) ? STATE_001 : STATE_010;
          Y0 = y[0];
          z = 0;
        end else begin
          next_state = (y == 3'b010) ? STATE_011 : STATE_100;
          Y0 = y[0];
          z = 1;
        end
      end
      STATE_100: begin
        if (x == 0) begin
          next_state = (y == 3'b011) ? STATE_011 : STATE_100;
          Y0 = y[0];
          z = 0;
        end else begin
          next_state = (y == 3'b100) ? STATE_011 : STATE_100;
          Y0 = y[0];
          z = 1;
