      current_state <= A;
    end else begin
      current_state <= next_state;
    end
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      A: begin
        if (w) begin
          next_state = A;
        end else begin
          next_state = B;
        end
      end
      B: begin
        if (w) begin
          next_state = C;
        end else begin
          next_state = D;
        end
      end
      C: begin
        if (w) begin
          next_state = D;
        end else begin
          next_state = E;
        end
      end
      D: begin
        if (w) begin
          next_state = A;
        end else begin
          next_state = F;
        end
      end
      E: begin
        if (w) begin
          next_state = E;
        end else begin
          next_state = D;
        end
      end
      F: begin
        if (w) begin
          next_state = C;
        end else begin
          next_state = D;
        end
      end
    endcase
  end

  // Output logic
  always @(*) begin
    case (current_state)
      A: z <= 0;
      B: z <= 0;
      C: z <= 0;
      D: z <= 0;
      E: z <= 1;
      F: z <= 1;
    endcase
  end

