module TopModule (
  input clk,
  input load,
  input [255:0] data,
  output reg [255:0] q
);

  // Constants for the grid size
  localparam GRID_WIDTH = 16;
  localparam GRID_HEIGHT = 16;
  localparam GRID_SIZE = GRID_WIDTH * GRID_HEIGHT;

  // Helper function to get the index of a cell in the 1D array
  function int get_index(int x, int y);
    get_index = x + y * GRID_WIDTH;
  endfunction

  // Helper function to get the number of live neighbours of a cell
  function int get_live_neighbours(int x, int y);
    int live_neighbours = 0;

    // Check all 8 possible neighbours
    for (int dx = -1; dx <= 1; dx++) begin
      for (int dy = -1; dy <= 1; dy++) begin
        if (dx == 0 && dy == 0) continue; // Skip the cell itself

        int nx = (x + dx + GRID_WIDTH) % GRID_WIDTH;
        int ny = (y + dy + GRID_HEIGHT) % GRID_HEIGHT;
        live_neighbours += q[get_index(nx, ny)];
      end
    end

    return live_neighbours;
  endfunction

  // Sequential logic to update the grid
  always @(posedge clk) begin
    if (load) begin
      q <= data;
    end else begin
      reg [255:0] new_q;
      for (int i = 0; i < GRID_SIZE; i++) begin
        int x = i % GRID_WIDTH;
        int y = i / GRID_WIDTH;
        int live_neighbours = get_live_neighbours(x, y);

        if (live_neighbours == 3) begin
          new_q[i] = 1;
        end else if (live_neighbours == 2) begin
          new_q[i] = q[i];
        end else begin
          new_q[i] = 0;
        end
      end
      q <= new_q;
    end
  end

endmodule

