module TopModule (
  input clk,
  input reset,
  input data,
  output reg shift_ena,
  output reg counting,
  input done_counting,
  output reg done,
  input ack
);

  // Define the states of the finite-state machine
  typedef enum {IDLE, START, COUNT, DONE} state_t;
  state_t current_state, next_state;

  // State register
  reg [3:0] state_reg;

  // Internal signals
  reg [3:0] counter;
  reg [3:0] pattern = 4'b1101;

  // State transition logic
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      current_state <= IDLE;
      state_reg <= IDLE;
      counter <= 4'b0;
      shift_ena <= 1'b0;
      counting <= 1'b0;
      done <= 1'b0;
    end else begin
      current_state <= next_state;
      state_reg <= current_state;
      counter <= counter;
      shift_ena <= shift_ena;
      counting <= counting;
      done <= done;
    end
  end

  // State transition conditions
  always @(*) begin
    case (current_state)
      IDLE: begin
        if (data == pattern) begin
          next_state = START;
        end else begin
          next_state = IDLE;
        end
      end
      START: begin
        if (data == pattern) begin
          next_state = COUNT;
        end else begin
          next_state = IDLE;
        end
      end
      COUNT: begin
        if (done_counting) begin
          next_state = DONE;
        end else begin
          next_state = COUNT;
        end
      end
      DONE: begin
        if (ack) begin
          next_state = IDLE;
        end else begin
          next_state = DONE;
        end
      end
      default: begin
        next_state = IDLE;
      end
    endcase
  end

  // Output logic
  always @(*) begin
    case (current_state)
      IDLE: begin
        shift_ena <= 1'b0;
        counting <= 1'b0;
        done <= 1'b0;
      end
      START: begin
        shift_ena <= 1'b1;
        counting <= 1'b0;
        done <= 1'b0;
      end
      COUNT: begin
        shift_ena <= 1'b0;
        counting <= 1'b1;
        done <= 1'b0;
      end
      DONE: begin
        shift_ena <= 1'b0;
        counting <= 1'b0;
        done <= 1'b1;
      end
      default: begin
        shift_ena <= 1'b0;
        counting <= 1'b0;
        done <= 1'b0;
      end
    endcase
  end

endmodule

module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  input ground,
  input dig,
  output walk_left,
  output walk_right,
  output aaah,
  output digging
);

  // Define states
  typedef enum {IDLE, WALK_LEFT, WALK_RIGHT, FALLING, DIGGING} state_t;
  state_t current_state, next_state;

  // State variables
  reg walk_left_reg, walk_right_reg, aaah_reg, digging_reg;

  // Initial state
  initial begin
    current_state = IDLE;
    walk_left_reg = 1'b0;
    walk_right_reg = 1'b0;
    aaah_reg = 1'b0;
    digging_reg = 1'b0;
  end

  // State machine
  always @(posedge clk or posedge areset) begin
    if (areset) begin
      current_state <= IDLE;
      walk_left_reg <= 1'b0;
      walk_right_reg <= 1'b0;
      aaah_reg <= 1'b0;
      digging_reg <= 1'b0;
    end else begin
      current_state <= next_state;

      // Update state variables
      walk_left_reg <= (current_state == WALK_LEFT || current_state == DIGGING);
      walk_right_reg <= (current_state == WALK_RIGHT || current_state == DIGGING);
      aaah_reg <= (current_state == FALLING);
      digging_reg <= (current_state == DIGGING);
    end
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      IDLE: begin
        if (dig) begin
          next_state = DIGGING;
        end else if (bump_left) begin
          next_state = WALK_RIGHT;
        end else if (bump_right) begin
          next_state = WALK_LEFT;
        end else begin
          next_state = WALK_LEFT;
        end
      end
      WALK_LEFT: begin
        if (bump_right) begin
          next_state = WALK_RIGHT;
        end else if (ground) begin
          next_state = IDLE;
        end else begin
          next_state = FALLING;
        end
      end
      WALK_RIGHT: begin
        if (bump_left) begin
          next_state = WALK_LEFT;
        end else if (ground) begin
          next_state = IDLE;
        end else begin
          next_state = FALLING;
        end
      end
      FALLING: begin
        if (ground) begin
          next_state = IDLE;
        end else begin
          next_state = FALLING;
        end
      end
      DIGGING: begin
        if (ground) begin
          next_state = IDLE;
        end else begin
          next_state = DIGGING;
        end
      end
    endcase
  end

  // Output assignments
  assign walk_left = walk_left_reg;
  assign walk_right = walk_right_reg;
  assign aaah = aaah_reg;
  assign digging = digging_reg;

endmodule

module TopModule (
  input clk,
  input areset,

  input predict_valid,
  input [6:0] predict_pc,
  output predict_taken,
  output [6:0] predict_history,

  input train_valid,
  input train_taken,
  input train_mispredicted,
  input [6:0] train_history,
  input [6:0] train_pc
);

  // Constants
  localparam PHT_SIZE = 128;
  localparam HISTORY_SIZE = 7;

  // Global branch history register
  reg [HISTORY_SIZE-1:0] global_history;

  // PHT (Pattern History Table)
  reg [1:0] pht[PHT_SIZE-1:0];

  // Function to calculate the index for the PHT
  function [6:0] calculate_index(input [6:0] pc, input [HISTORY_SIZE-1:0] history);
    calculate_index = pc ^ history;
  endfunction

  // Function to saturate a counter
  function [1:0] saturate_counter(input [1:0] counter);
    if (counter == 2'b11) begin
      saturate_counter = 2'b11;
    end else if (counter == 2'b10) begin
      saturate_counter = 2'b11;
    end else if (counter == 2'b01) begin
      saturate_counter = 2'b10;
    end else if (counter == 2'b00) begin
      saturate_counter = 2'b01;
    end else begin
      saturate_counter = counter;
    end
  endfunction

  // Function to update the PHT
  function void update_pht(input [6:0] pc, input [HISTORY_SIZE-1:0] history, input [1:0] outcome, input [1:0] mispredict);
    reg [6:0] index = calculate_index(pc, history);
    if (mispredict) begin
      pht[index] = 2'b00;
    end else begin
      pht[index] = saturate_counter(pht[index] + outcome);
    end
  endfunction

  // Main logic
  always @(posedge clk or posedge areset) begin
    if (areset) begin
      global_history <= 7'b0;
      for (int i = 0; i < PHT_SIZE; i++) begin
        pht[i] <= 2'b00;
      end
    end else begin
      if (predict_valid) begin
        reg [1:0] prediction;
        reg [6:0] index = calculate_index(predict_pc, global_history);
        prediction = pht[index];
        predict_taken <= prediction[1];
        predict_history <= global_history;
      end

      if (train_valid) begin
        update_pht(train_pc, train_history, train_taken, train_mispredicted);
        if (train_mispredicted) begin
          global_history <= train_history;
        end
      end
    end
  end

endmodule

module TopModule (
  input clk,
  input [7:0] in,
  input reset,
  output [23:0] out_bytes,
  output done
);

  // State machine states
  typedef enum {IDLE, WAIT_1, WAIT_2, WAIT_3, DONE} state_t;
  state_t current_state, next_state;

  // State register
  reg [3:0] state_reg;

  // Byte buffer
  reg [7:0] byte_buffer [0:2];

  // Byte counter
  reg [2:0] byte_count;

  // Output byte buffer
  reg [23:0] output_byte_buffer;

  // Output byte counter
  reg [2:0] output_byte_count;

  // Output byte valid flag
  reg output_byte_valid;

  // State machine logic
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      current_state <= IDLE;
      state_reg <= IDLE;
      byte_buffer <= {8{8'b0}};
      byte_count <= 0;
      output_byte_buffer <= 24'b0;
      output_byte_count <= 0;
      output_byte_valid <= 0;
    end else begin
      current_state <= next_state;
      state_reg <= current_state;

      case (current_state)
        IDLE: begin
          if (in[3]) begin
            next_state <= WAIT_1;
            byte_buffer[0] <= in;
            byte_count <= 1;
          end else begin
            next_state <= IDLE;
          end
        end

        WAIT_1: begin
          if (in[3]) begin
            next_state <= WAIT_2;
            byte_buffer[1] <= in;
            byte_count <= 2;
          end else begin
            next_state <= IDLE;
          end
        end

        WAIT_2: begin
          if (in[3]) begin
            next_state <= WAIT_3;
            byte_buffer[2] <= in;
            byte_count <= 3;
          end else begin
            next_state <= IDLE;
          end
        end

        WAIT_3: begin
          if (in[3]) begin
            next_state <= DONE;
            output_byte_buffer <= {byte_buffer[2], byte_buffer[1], byte_buffer[0]};
            output_byte_count <= 3;
            output_byte_valid <= 1;
          end else begin
            next_state <= IDLE;
          end
        end

        DONE: begin
          if (output_byte_count == 0) begin
            next_state <= IDLE;
            output_byte_valid <= 0;
          end else begin
            next_state <= DONE;
            output_byte_count <= output_byte_count - 1;
          end
        end
      endcase
    end
  end

  // Output logic
  assign out_bytes = output_byte_buffer;
  assign done = output_byte_valid;

endmodule

module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  input ground,
  input dig,
  output walk_left,
  output walk_right,
  output aaah,
  output digging
);

  // State definitions
  typedef enum {WALK_LEFT, WALK_RIGHT, FALLING, DIGGING, SPLATTERED} state_t;
  state_t current_state, next_state;

  // State variables
  reg [19:0] fall_counter;
  reg [1:0] dig_counter;

  // Reset logic
  always @(posedge areset) begin
    current_state <= WALK_LEFT;
    walk_left <= 1'b1;
    walk_right <= 1'b0;
    aaah <= 1'b0;
    digging <= 1'b0;
    fall_counter <= 20'd0;
    dig_counter <= 2'd0;
  end

  // State transition logic
  always @(posedge clk) begin
    current_state <= next_state;

    // Determine next state based on current state and inputs
    case (current_state)
      WALK_LEFT: begin
        if (bump_right) begin
          next_state = WALK_RIGHT;
        end else if (ground) begin
          next_state = WALK_LEFT;
        end else begin
          next_state = FALLING;
        end
      end
      WALK_RIGHT: begin
        if (bump_left) begin
          next_state = WALK_LEFT;
        end else if (ground) begin
          next_state = WALK_RIGHT;
        end else begin
          next_state = FALLING;
        end
      end
      FALLING: begin
        if (ground) begin
          next_state = WALK_LEFT;
        end else if (dig) begin
          next_state = DIGGING;
        end else if (fall_counter == 20'd0) begin
          next_state = SPLATTERED;
        end else begin
          next_state = FALLING;
        end
      end
      DIGGING: begin
        if (ground) begin
          next_state = WALK_LEFT;
        end else if (dig) begin
          next_state = DIGGING;
        end else if (fall_counter == 20'd0) begin
          next_state = SPLATTERED;
        end else begin
          next_state = FALLING;
        end
      end
      SPLATTERED: begin
        next_state = SPLATTERED;
      end
    endcase
  end

  // Output logic
  always @(current_state) begin
    case (current_state)
      WALK_LEFT: begin
        walk_left <= 1'b1;
        walk_right <= 1'b0;
        aaah <= 1'b0;
        digging <= 1'b0;
      end
      WALK_RIGHT: begin
        walk_left <= 1'b0;
        walk_right <= 1'b1;
        aaah <= 1'b0;
        digging <= 1'b0;
      end
      FALLING: begin
        walk_left <= 1'b0;
        walk_right <= 1'b0;
        aaah <= 1'b1;
        digging <= 1'b0;
      end
      DIGGING: begin
        walk_left <= 1'b0;
        walk_right <= 1'b0;
        aaah <= 1'b0;
        digging <= 1'b1;
      end
      SPLATTERED: begin
        walk_left <= 1'b0;
        walk_right <= 1'b0;
        aaah <= 1'b0;
        digging <= 1'b0;
      end
    endcase
  end

  // Counter logic
  always @(posedge clk) begin
    if (current_state == FALLING) begin
      if (fall_counter < 20'd20) begin
        fall_counter <= fall_counter + 1'd1;
      end
    end
    if (current_state == DIGGING) begin
      if (dig_counter < 2'd2) begin
        dig_counter <= dig_counter + 1'd1;
      end
    end
  end

endmodule

